/*
 * dowel theme - the token vocabulary every product of the lacodda line shares.
 *
 * The vocabulary comes from the products themselves: kilna and kasl-server
 * already ship the same token names (bg / raise / soft / line / text / dim /
 * accent / good / warn / bad / info) and differ only in values. That is the
 * contract this file freezes. Names are the mockup's own words rather than
 * stock component-library names, so a screen can be checked against a mockup
 * in the mockup's words.
 *
 * Two things are parametric, and everything else is derived from them:
 *
 *   --accent-base   the product's hue from the brand-line registry
 *   --neutral-base  the hue the greys are tinted with (the accent, by default)
 *
 * Tinting the neutrals is not decoration - it is what the two live products do
 * by hand: kilna's greys lean magenta, kasl-server's lean gold. Here that lean
 * is one declaration instead of thirty hand-picked hex values.
 *
 * Soft variants are mixed from their own base with `color-mix`, so a product
 * that overrides `--accent-base` gets a matching `--accent-soft` for free and
 * cannot pick one that disagrees with it.
 *
 * Theme selection: no class on the root element follows the operating system,
 * an explicit `light` or `dark` class pins the theme. Components never use
 * `dark:` utilities - every colour goes through a token, and the theme swaps
 * the token underneath.
 */

:root {
  /* The two parameters. `--accent-base` is overridden per product by an accent
   * file; `--neutral-base` follows it unless a product says otherwise. */
  --accent-base: #e8862d;
  --neutral-base: var(--accent-base);

  /* Ink and ground of the dark theme, before the neutral tint is mixed in.
   * Kept as their own tokens so the tint amount is the only thing that
   * changes when a product wants greyer or warmer chrome. */
  --ground: #131316;
  --ink: #ece9ef;

  /* How much of `--neutral-base` bleeds into the greys. The live products sit
   * at roughly this much: enough that the chrome belongs to the product,
   * little enough that it still reads as grey. */
  --neutral-tint: 6%;
  --neutral-tint-strong: 9%;

  color-scheme: dark;

  --bg: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), var(--ground));
  --raise: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), #1c1c21);

  /* Surfaces that lift by translucency rather than by their own colour: they
   * must work over `--bg` and over `--raise` alike. */
  --soft: rgb(255 255 255 / 0.045);
  --softer: rgb(255 255 255 / 0.025);
  --line: rgb(255 255 255 / 0.08);
  --line-2: rgb(255 255 255 / 0.15);

  --text: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), var(--ink));
  --dim: color-mix(in oklab, var(--neutral-base) var(--neutral-tint-strong), #a7a2ad);
  --faint: color-mix(in oklab, var(--neutral-base) var(--neutral-tint-strong), #6e6a76);

  --accent: var(--accent-base);
  /* The hover/active partner: lighter on dark, where the ground is what the
   * accent has to separate from. */
  --accent-2: color-mix(in oklab, white 22%, var(--accent-base));
  --accent-soft: color-mix(in oklab, var(--accent-base) 16%, transparent);

  /* Status hues are the line's own and do not follow the product accent: a
   * green that shifted per product would stop meaning "good". Meaning never
   * rests on colour alone - a badge carries an icon and a word - so these
   * exist for emphasis, not as the message. */
  --good: #45d18f;
  --warn: #e8b13f;
  --bad: #ef6a6a;
  --info: #4cc4e0;
  --good-soft: color-mix(in oklab, var(--good) 14%, transparent);
  --warn-soft: color-mix(in oklab, var(--warn) 14%, transparent);
  --bad-soft: color-mix(in oklab, var(--bad) 14%, transparent);
  --info-soft: color-mix(in oklab, var(--info) 15%, transparent);

  /* Series colours, for charts.
   *
   * Like the status hues and unlike everything else here, these do NOT follow
   * the product accent - and that is the whole decision. A series is a
   * property of the data, not of the product showing it; a palette derived
   * from the accent would paint the same series differently in kilna and in
   * kasl-server, which is the one thing a series colour must never do.
   *
   * Deriving them from the accent was measured, not guessed: rotating the hue
   * by fixed angles put the best candidate at Delta-E 12.1 from the product's
   * own accent with adjacent pairs at 9.8, and threw 46 of 152 colours outside
   * sRGB. The fixed palette does better on both counts.
   *
   * The cost of fixing them is stated plainly: 13 of the line's 19 accents sit
   * within Delta-E 8 of some slot (lyrid 2.7, atlas 3.1, turnout 3.2). A chart
   * shows one accent, so this is survivable - but it is exactly why identity is
   * carried by the legend and by direct labels, never by hue on its own. The
   * components of this block enforce that; it is not advice.
   *
   * Assigned in order, 1..8, and never cycled: a ninth series folds into
   * "other", or the chart becomes small multiples. The order is the
   * colour-blind-safety mechanism - the worst adjacent pair is Delta-E 8.4
   * under simulated protanopia - so re-ordering these breaks a gate.
   *
   * Slot 8 is the line's own value rather than the reference palette's. The
   * reference red sat Delta-E 1.9 from `--bad`, which would have let a series
   * impersonate a status; this one clears every status by 15 and costs
   * nothing, the worst adjacent pair being unchanged.
   *
   * Some slots sit below 3:1 against the surface. That is allowed only because
   * the relief ships with them: visible values, or the table view.
   */
  --series-1: #3987e5;
  --series-2: #d95926;
  --series-3: #199e70;
  --series-4: #c98500;
  --series-5: #d55181;
  --series-6: #008300;
  --series-7: #9085e9;
  --series-8: #a3215a;

  /* Magnitude rather than identity: one hue, light to dark. A heatmap cell
   * reads this. The lightest step is allowed to recede toward the surface,
   * because "near zero" should; an ordered-but-discrete scale (tiers, funnel
   * stages) starts at 300 instead, where the contrast still holds. */
  --scale-100: #0d366b;
  --scale-200: #184f95;
  --scale-300: #256abf;
  --scale-400: #2a78d6;
  --scale-500: #3987e5;
  --scale-600: #5598e7;
  --scale-700: #86b6ef;

  /* The chart's own furniture. A gridline that competes with the data is drawn
   * wrong, so it is quieter than `--line`; the axis is the one that may be
   * seen. */
  --chart-grid: rgb(255 255 255 / 0.06);
  --chart-axis: rgb(255 255 255 / 0.14);

  /* Heat, for a grid of cells where colour is the only thing carrying the
   * value - a year of activity, a month of a team's hours.
   *
   * Five discrete steps rather than the seven of `--scale-*`, and a separate
   * set rather than a slice of them, because the two answer different
   * questions. `--scale-*` is sequential: a continuous magnitude, where the
   * lightest step means "near zero" and may recede toward the surface.
   * Heat is ordinal: five shades a reader tells apart at a glance and matches
   * against a legend, which needs wider gaps between them (no slice of
   * `--scale-*` clears the 0.06 lightness step - they sit 0.047 apart) and a
   * bottom step that stays distinct from an empty cell.
   *
   * That last one is the whole point. A heatmap cell has more meanings than a
   * number: nothing recorded, a day still running, a day outside the data, and
   * a value. If the faintest value looks like the empty cell, the grid says
   * somebody did nothing on a day nobody reported - and `--heat-1` clears the
   * empty square by 2.1:1 so it cannot.
   *
   * Fixed, like the series and unlike almost everything else here. Derived
   * from the accent - as the first consumer did - the faintest step sat 1.3:1
   * from the empty cell for half the line, and pinning lightness instead ran
   * out of sRGB: the darkest accents cannot reach the top of the ramp at their
   * own chroma.
   */
  --heat-1: #28528e;
  --heat-2: #3a65a3;
  --heat-3: #4d78b7;
  --heat-4: #608ccd;
  --heat-5: #73a0e2;

  /* Syntax, for code shown inside a product.
   *
   * Eight kinds rather than the fifty a highlighter's theme names, because
   * these are the distinctions that survive across languages: a keyword, a
   * literal string, a number, a comment, an identifier, a type, punctuation,
   * and the metadata around the code (a decorator, an attribute, a prompt).
   * Anything finer is a grammar's own vocabulary and does not travel.
   *
   * Fixed, like the series and the heat ramps, and for the same reason: code
   * is not a property of the product showing it, and `if` should not be
   * magenta in kilna and cobalt in kasl-server.
   *
   * Chosen against the surface code actually sits on - `--soft` over `--bg`,
   * which is what CodeBlock and `.prose pre` draw - and every slot clears
   * 4.5:1 AS TEXT in both themes. That threshold, not the 3:1 the series are
   * held to, is the whole reason these exist separately: the series palette
   * was measured here first and five of its eight light values sat under 3:1,
   * one at 1.90:1. A filled bar can be pale; a 12px glyph cannot.
   *
   * These are deliberately NOT held to the colour-blind floor the series are.
   * A series colour is the identity of its mark - lose the hue and the data is
   * gone. Syntax colour is a second reading of what the text already says in
   * full: a keyword is a keyword by its spelling, and CodeBlock's default
   * renders no colour at all and stays readable. `syntax.test.ts` says so in
   * place, so the omission is not mistaken for an oversight.
   *
   * `comment` is the quietest on purpose - it is the one kind a reader is
   * meant to be able to skip - and still clears the threshold.
   */
  --syntax-keyword: #c792ea;
  --syntax-string: #9ccc65;
  --syntax-number: #f78c6c;
  --syntax-comment: #9e99a6;
  --syntax-name: #82aaff;
  --syntax-type: #4dd0b1;
  --syntax-punctuation: #c4bfcb;
  --syntax-meta: #f0a868;

  /* Elevation, three steps. The products had one shadow and used it for
   * everything that leaves the flow - a toast, a dropdown and a modal all
   * floated by the same amount, so a modal never felt further away than the
   * menu it covered. The three are the steps.
   *
   * Two layers each, and that is what makes them read as depth on a dark
   * surface rather than as a stain. One big soft blur at high opacity is what
   * these were - `0 24px 60px` of 55% black - and against a near-black page
   * the wide skirt never resolves into shade: it just darkens a ring of
   * background around the panel, which a pilot photographed and called an ugly
   * dark contour. Depth is read from the CONTACT shadow, the tight one right
   * under the edge; the ambient layer only has to hint that there is room
   * under the thing. So each step is a tight, slightly stronger layer plus a
   * wider, much weaker one, and the totals come down. */
  --shadow-lift: 0 1px 2px rgb(0 0 0 / 0.4), 0 2px 6px rgb(0 0 0 / 0.22);
  --shadow-raise: 0 2px 4px rgb(0 0 0 / 0.36), 0 8px 20px rgb(0 0 0 / 0.26);
  --shadow-float: 0 4px 8px rgb(0 0 0 / 0.36), 0 18px 44px rgb(0 0 0 / 0.32);
}

/*
 * Light theme, twice: once for the operating system's preference, once for the
 * explicit `light` class. The declarations are identical - only the selector
 * differs - so that a product can pin a theme against the system setting.
 */
@media (prefers-color-scheme: light) {
  :root:not(.dark) {
    color-scheme: light;

    --ground: #f6f5f7;
    --ink: #232027;

    --bg: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), var(--ground));
    --raise: #ffffff;

    /* Tinted, and translucent - which took two goes to get right.
     *
     * `color-mix` mixes the alpha along with the colour, so mixing 60% of an
     * opaque accent into a 5%-opaque grey gives a surface 62% opaque: twelve
     * times denser than the hairline it was meant to be. It went unnoticed for
     * ten versions because `bg-soft` was only ever used for a hover, where a
     * flash of colour reads as feedback rather than as a mistake. The first
     * component to sit on it permanently - Alert - made it obvious.
     *
     * `oklch(from … / alpha)` keeps the alpha out of the mix: the hue comes
     * from the tinted colour, the transparency is stated. */
    --soft: oklch(from color-mix(in oklab, var(--neutral-base) 45%, #181420) l c h / 0.05);
    --softer: oklch(from color-mix(in oklab, var(--neutral-base) 45%, #181420) l c h / 0.03);
    --line: oklch(from color-mix(in oklab, var(--neutral-base) 30%, #181420) l c h / 0.11);
    --line-2: oklch(from color-mix(in oklab, var(--neutral-base) 30%, #181420) l c h / 0.2);

    --text: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), var(--ink));
    --dim: color-mix(in oklab, var(--neutral-base) var(--neutral-tint-strong), #63606b);
    --faint: color-mix(in oklab, var(--neutral-base) var(--neutral-tint-strong), #8a8692);

    /* On a light ground the accent has to darken to stay legible as text and
     * as a fill. It darkens *to* a lightness rather than *by* an amount: how
     * far a hue has to travel depends on where it starts, and a fixed step
     * that suits magenta leaves lime and gold short. Pinning the lightness and
     * keeping the hue and chroma clears 5:1 for every accent in the line. */
    --accent: oklch(from var(--accent-base) 0.5 c h);
    --accent-2: oklch(from var(--accent-base) 0.4 c h);
    --accent-soft: color-mix(in oklab, var(--accent-base) 12%, transparent);

    --good: #0c8554;
    --warn: #9a6b0c;
    --bad: #c93b3b;
    --info: #0d7f9c;
    --good-soft: color-mix(in oklab, var(--good) 12%, transparent);
    --warn-soft: color-mix(in oklab, var(--warn) 14%, transparent);
    --bad-soft: color-mix(in oklab, var(--bad) 12%, transparent);
    --info-soft: color-mix(in oklab, var(--info) 11%, transparent);

    /* Series and scale, stepped for the light surface - the same eight hues
     * chosen again against this ground, not the dark values lightened. The dark
     * block says why these do not follow the product accent. */
    --series-1: #2a78d6;
    --series-2: #eb6834;
    --series-3: #1baf7a;
    --series-4: #eda100;
    --series-5: #e87ba4;
    --series-6: #008300;
    --series-7: #4a3aa7;
    --series-8: #85284d;

    --scale-100: #cde2fb;
    --scale-200: #9ec5f4;
    --scale-300: #6da7ec;
    --scale-400: #3987e5;
    --scale-500: #2a78d6;
    --scale-600: #1c5cab;
    --scale-700: #104281;

    --chart-grid: oklch(from color-mix(in oklab, var(--neutral-base) 30%, #181420) l c h / 0.08);
    --chart-axis: oklch(from color-mix(in oklab, var(--neutral-base) 30%, #181420) l c h / 0.18);

    /* The same five steps chosen again for the light ground, running the other
     * way: here "more" is darker. See the dark block for why heat is its own
     * ramp and not a slice of `--scale-*`. */
    --heat-1: #84a8fd;
    --heat-2: #7193e7;
    --heat-3: #5e7fd1;
    --heat-4: #4c6cbb;
    --heat-5: #3b58a6;

    /* The same eight kinds chosen again for the light ground - not the dark
     * values darkened. Each clears 4.5:1 as text against `--soft` over this
     * theme's `--bg`; the dark block says why syntax is its own palette and
     * why it is not held to the colour-blind floor. */
    --syntax-keyword: #7c3aad;
    --syntax-string: #276c2b;
    --syntax-number: #b5451b;
    --syntax-comment: #6f6b78;
    --syntax-name: #1a5fb4;
    --syntax-type: #00695c;
    --syntax-punctuation: #4a4753;
    --syntax-meta: #9c4a00;

    --shadow-lift: 0 2px 8px rgb(30 24 38 / 0.08);
    --shadow-raise: 0 10px 30px rgb(30 24 38 / 0.14);
    --shadow-float: 0 24px 60px rgb(30 24 38 / 0.18);
  }
}

:root.light {
  color-scheme: light;

  --ground: #f6f5f7;
  --ink: #232027;

  --bg: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), var(--ground));
  --raise: #ffffff;

  /* The same surfaces as above; see the note there. */
  --soft: oklch(from color-mix(in oklab, var(--neutral-base) 45%, #181420) l c h / 0.05);
  --softer: oklch(from color-mix(in oklab, var(--neutral-base) 45%, #181420) l c h / 0.03);
  --line: oklch(from color-mix(in oklab, var(--neutral-base) 30%, #181420) l c h / 0.11);
  --line-2: oklch(from color-mix(in oklab, var(--neutral-base) 30%, #181420) l c h / 0.2);

  --text: color-mix(in oklab, var(--neutral-base) var(--neutral-tint), var(--ink));
  --dim: color-mix(in oklab, var(--neutral-base) var(--neutral-tint-strong), #63606b);
  --faint: color-mix(in oklab, var(--neutral-base) var(--neutral-tint-strong), #8a8692);

  /* Darkened to a lightness, not by an amount - see the note above. */
  --accent: oklch(from var(--accent-base) 0.5 c h);
  --accent-2: oklch(from var(--accent-base) 0.4 c h);
  --accent-soft: color-mix(in oklab, var(--accent-base) 12%, transparent);

  --good: #0c8554;
  --warn: #9a6b0c;
  --bad: #c93b3b;
  --info: #0d7f9c;
  --good-soft: color-mix(in oklab, var(--good) 12%, transparent);
  --warn-soft: color-mix(in oklab, var(--warn) 14%, transparent);
  --bad-soft: color-mix(in oklab, var(--bad) 12%, transparent);
  --info-soft: color-mix(in oklab, var(--info) 11%, transparent);

  /* Series and scale, stepped for the light surface - the same eight hues
   * chosen again against this ground, not the dark values lightened. The dark
   * block says why these do not follow the product accent. */
  --series-1: #2a78d6;
  --series-2: #eb6834;
  --series-3: #1baf7a;
  --series-4: #eda100;
  --series-5: #e87ba4;
  --series-6: #008300;
  --series-7: #4a3aa7;
  --series-8: #85284d;

  --scale-100: #cde2fb;
  --scale-200: #9ec5f4;
  --scale-300: #6da7ec;
  --scale-400: #3987e5;
  --scale-500: #2a78d6;
  --scale-600: #1c5cab;
  --scale-700: #104281;

  --chart-grid: oklch(from color-mix(in oklab, var(--neutral-base) 30%, #181420) l c h / 0.08);
  --chart-axis: oklch(from color-mix(in oklab, var(--neutral-base) 30%, #181420) l c h / 0.18);

  /* The same five steps chosen again for the light ground, running the other
   * way: here "more" is darker. See the dark block for why heat is its own
   * ramp and not a slice of `--scale-*`. */
  --heat-1: #84a8fd;
  --heat-2: #7193e7;
  --heat-3: #5e7fd1;
  --heat-4: #4c6cbb;
  --heat-5: #3b58a6;

  /* The same eight kinds chosen again for the light ground - not the dark
   * values darkened. Each clears 4.5:1 as text against `--soft` over this
   * theme's `--bg`; the dark block says why syntax is its own palette and
   * why it is not held to the colour-blind floor. */
  --syntax-keyword: #7c3aad;
  --syntax-string: #276c2b;
  --syntax-number: #b5451b;
  --syntax-comment: #6f6b78;
  --syntax-name: #1a5fb4;
  --syntax-type: #00695c;
  --syntax-punctuation: #4a4753;
  --syntax-meta: #9c4a00;

  --shadow-lift: 0 2px 8px rgb(30 24 38 / 0.08);
  --shadow-raise: 0 10px 30px rgb(30 24 38 / 0.14);
  --shadow-float: 0 24px 60px rgb(30 24 38 / 0.18);
}

/*
 * `--on-accent` - what sits on top of an accent fill.
 *
 * A light accent (gold, lime, amber) needs dark glyphs; a dark one needs
 * white. The live products picked this by hand and wrote the answer into the
 * theme; here the theme works it out, by the same rule the brand-line S tile
 * uses.
 *
 * `contrast-color()` is the direct way to say it and is used where supported.
 * The fallback covers browsers that lack it. Relative colour syntax exposes
 * the accent's own lightness as `l`; `clamp()` turns that into a hard switch,
 * because the multiplication drives the middle term far past either bound
 * everywhere except within a hair of the threshold. Below it the accent is
 * dark and the result is 1 (white); above it, 0 (black). Chroma is dropped to
 * zero, so what comes out is neutral rather than a tinted grey.
 *
 * The threshold is 0.58, and it is deliberately far below the midpoint an eye
 * would guess. Contrast is not symmetric about it: a mid-lightness colour is
 * still much closer to white than to black in luminance, so black wins well
 * before the colour looks light. Checked against all fourteen accents of the
 * line - every one of them reads better with dark glyphs, the closest being
 * cobalt at 4.86:1 against 4.32:1 for white. A higher threshold is what puts
 * white text on magenta at 3.6:1, which is the defect this rule exists to
 * prevent.
 */
:root {
  --on-accent: oklch(from var(--accent) clamp(0, (0.58 - l) * 1000, 1) 0 0);

  /*
   * The same question for the status fills, and it has to be asked separately:
   * `--on-accent` is derived from the accent, so using it on a `--warn` fill
   * is only ever right by coincidence. The line's first consumer did exactly
   * that - a count on a yellow badge, drawn in white at 1.95:1 - and it read
   * as correct for as long as the product happened to pin white.
   *
   * The status hues do not follow the product accent, so these four are the
   * same for every product; they are still derived rather than written down,
   * because the status colours themselves change between the themes.
   */
  --on-good: oklch(from var(--good) clamp(0, (0.58 - l) * 1000, 1) 0 0);
  --on-warn: oklch(from var(--warn) clamp(0, (0.58 - l) * 1000, 1) 0 0);
  --on-bad: oklch(from var(--bad) clamp(0, (0.58 - l) * 1000, 1) 0 0);
  --on-info: oklch(from var(--info) clamp(0, (0.58 - l) * 1000, 1) 0 0);
}

@supports (color: contrast-color(red)) {
  :root {
    --on-accent: contrast-color(var(--accent));
    --on-good: contrast-color(var(--good));
    --on-warn: contrast-color(var(--warn));
    --on-bad: contrast-color(var(--bad));
    --on-info: contrast-color(var(--info));
  }
}

/*
 * The Tailwind 4 surface. `--color-*: initial` drops the stock palette on
 * purpose: a raw `bg-zinc-800` in a product should not compile, because the
 * only colours that exist here are the line's own.
 */
@theme inline {
  --color-*: initial;
  --color-bg: var(--bg);
  --color-raise: var(--raise);
  --color-soft: var(--soft);
  --color-softer: var(--softer);
  --color-line: var(--line);
  --color-line-2: var(--line-2);
  --color-text: var(--text);
  --color-dim: var(--dim);
  --color-faint: var(--faint);
  --color-accent: var(--accent);
  --color-accent-2: var(--accent-2);
  --color-accent-soft: var(--accent-soft);
  --color-on-accent: var(--on-accent);
  --color-on-good: var(--on-good);
  --color-on-warn: var(--on-warn);
  --color-on-bad: var(--on-bad);
  --color-on-info: var(--on-info);
  --color-good: var(--good);
  --color-good-soft: var(--good-soft);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-bad: var(--bad);
  --color-bad-soft: var(--bad-soft);
  --color-info: var(--info);
  --color-info-soft: var(--info-soft);

  /* Charts. `bg-series-3`, `fill-series-3`, `stroke-scale-500` - the same
   * utilities the rest of the vocabulary gets, so a chart is written in
   * tokens like everything else and `dowel/no-raw-color` can hold it to
   * that. */
  --color-series-1: var(--series-1);
  --color-series-2: var(--series-2);
  --color-series-3: var(--series-3);
  --color-series-4: var(--series-4);
  --color-series-5: var(--series-5);
  --color-series-6: var(--series-6);
  --color-series-7: var(--series-7);
  --color-series-8: var(--series-8);
  --color-scale-100: var(--scale-100);
  --color-scale-200: var(--scale-200);
  --color-scale-300: var(--scale-300);
  --color-scale-400: var(--scale-400);
  --color-scale-500: var(--scale-500);
  --color-scale-600: var(--scale-600);
  --color-scale-700: var(--scale-700);
  --color-chart-grid: var(--chart-grid);
  --color-chart-axis: var(--chart-axis);
  --color-heat-1: var(--heat-1);
  --color-heat-2: var(--heat-2);
  --color-heat-3: var(--heat-3);
  --color-heat-4: var(--heat-4);
  --color-heat-5: var(--heat-5);

  /* Syntax, so a highlighted token is written `text-syntax-keyword` like every
   * other colour in the system, and `dowel/no-raw-color` can hold it to that.
   * A highlighter's own stylesheet - which writes hex values into class names
   * of its own choosing - is what this replaces. */
  --color-syntax-keyword: var(--syntax-keyword);
  --color-syntax-string: var(--syntax-string);
  --color-syntax-number: var(--syntax-number);
  --color-syntax-comment: var(--syntax-comment);
  --color-syntax-name: var(--syntax-name);
  --color-syntax-type: var(--syntax-type);
  --color-syntax-punctuation: var(--syntax-punctuation);
  --color-syntax-meta: var(--syntax-meta);

  /* Kept because they are not palette choices: a hairline is `transparent`,
   * an SVG follows `currentColor`, and pure black and white are what an
   * overlay scrim and a print sheet are made of. */
  --color-transparent: transparent;
  --color-current: currentColor;
  --color-white: #fff;
  --color-black: #000;

  /*
   * Type. System stacks on purpose: a downloaded face costs a network round
   * trip before the first word appears, and the line's products are desktop
   * tools where the operating system's own face is the one the user already
   * reads everything else in.
   */
  --font-sans: 'Segoe UI Variable Text', 'Segoe UI', system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, 'Cascadia Code', 'SF Mono', Consolas, monospace;

  /*
   * Radius. Taken from what the products actually draw, not from a ratio:
   * `rounded-[9px]` appears twenty times and `rounded-[10px]` twelve, because
   * a control and the primary button were tuned by eye and then copied. The
   * scale keeps the cluster they landed in and gives it names.
   *
   * `md` is the control radius - inputs, buttons, list rows. That the primary
   * button was one pixel rounder than every other variant is not preserved:
   * the products differ from themselves there, and buttons of the same size
   * sitting side by side should not have mismatched corners.
   */
  --radius-xs: 4px;
  --radius-sm: 6px;
  --radius-md: 9px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 20px;

  /*
   * A radius nested inside another has to be smaller by the gap between them,
   * or the inner corner looks wrong against the outer one. The products did
   * this by hand once - 18px outside, 17px inside - and nowhere else.
   */
  --radius-inner: calc(var(--radius-lg) - 1px);

  /*
   * Type scale. The products live between 10px and 14px: `text-sm` and
   * `text-xs` together account for nine tenths of every size in both, and the
   * rest scattered across 9, 9.5, 10, 10.5, 11, 11.5, 12.5 and 13 - nine steps
   * inside four pixels, which no eye distinguishes and no reason justifies.
   * This is the same range with the noise removed.
   */
  --text-2xs: 10px;
  --text-2xs--line-height: 14px;
  --text-xs: 11px;
  --text-xs--line-height: 15px;
  --text-sm: 12px;
  --text-sm--line-height: 16px;
  --text-base: 14px;
  --text-base--line-height: 20px;
  --text-lg: 16px;
  --text-lg--line-height: 22px;
  --text-xl: 18px;
  --text-xl--line-height: 24px;
  --text-2xl: 21px;
  --text-2xl--line-height: 28px;

  /* Weights. `semibold` is what both products use for anything emphasised;
   * `bold` appears in neither, and the one `font-[650]` in a page title is the
   * kind of value a scale exists to absorb. */
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Tracking. The uppercase caption is the only place the products track at
   * all - and they do it at 0.08em in six files and 0.09em in three, a
   * difference nobody can see. One name settles it. */
  --tracking-caption: 0.085em;
  --tracking-tight: -0.01em;

  /*
   * A step between the steps.
   *
   * The spacing scale runs in fours - 2, 4, 6, 8 - and four different
   * primitives independently reached past it for three pixels: the gap
   * between segments of a rating and of an axis, the gap between cells of a
   * heatmap, and how far a tooltip's arrow tucks under its popup. Four hands
   * arriving at the same number is not four accidents; it is a step the scale
   * was missing, and each of them wrote `[3px]` because there was nothing to
   * name.
   *
   * It exists for hairline gaps between things that are themselves small -
   * where two pixels reads as touching and four as separate objects. Nothing
   * larger belongs here: this is the bottom of the scale, not a licence to
   * measure by eye.
   */
  --spacing-hair: 3px;

  /*
  /* Easing. `out` for anything the user asked for - it arrives fast and
   * settles, which reads as responsive. `in-out` for something moving on its
   * own. `in` is deliberately absent: it starts slowly, which on a control
   * reads as lag. */
  --ease-out: cubic-bezier(0.2, 0, 0, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);

  /*
   * Elevation. Three steps, because the products had one and used it for a
   * toast, a dropdown and a modal alike - so a modal never sat further from
   * the page than the menu it covered.
   */
  --shadow-lift: var(--shadow-lift);
  --shadow-raise: var(--shadow-raise);
  --shadow-float: var(--shadow-float);

  /*
   * The smallest a pointer target may be.
   *
   * 24 CSS pixels, which is WCAG 2.2's 2.5.8 at AA. Not a matter of taste, and
   * measured rather than assumed: a live run of the stand found four different
   * answers to the same question in one set - a chip's cross at 16, Copyable
   * at 19, CopyButton at 21, a search field's clear at 24. Three of the four
   * fail, and the failure is silent. A cross missed by a thumb on a tablet, or
   * by anyone whose hand is not steady, does not delete the tag and does not
   * say anything either.
   *
   * It is a size token rather than a spacing step because it is a floor, not a
   * rhythm: nothing is ever `--target-min` tall on purpose, things are at
   * least that big. `size-target` and `min-size-target` come free from the
   * namespace, but the way a primitive usually reaches it is `target-min`
   * below, which grows the hit area without growing the glyph.
   */
  --size-target: 24px;

  /*
   * The window's own chrome: the strip at the top, the rail at the left, and
   * the buttons that close the window.
   *
   * Four products of the line draw their own title bar - the trade is that a
   * system bar over an application bar costs a strip of every laptop screen
   * for nothing - and by the time the fourth one did it, the strip was 40px
   * in one and 2.4rem in another. Neither number is wrong; having two is. A
   * window's chrome is the part of a product that is supposed to look like
   * the operating system rather than like the product, so it is the last
   * place where two of them should differ.
   *
   * 40px is not a taste either. The window buttons have to clear the pointer
   * target floor with room for the hover fill to read as a button, and the
   * strip has to hold a mark, a trail and a search box at one line of text
   * without the trail wrapping. 40 is where both stop being tight.
   *
   * `--spacing-window-button` is 46px because that is what Windows draws, and
   * a bar whose buttons are narrower than the system's has a gap the pointer
   * falls into on the way to the corner. It is deliberately wider than it is
   * tall: the close button is the one that must be hit without aiming, and on
   * a maximised window it is the screen's corner.
   *
   * These are in the spacing namespace rather than beside `--size-target`,
   * and the reason is mechanical rather than tidy. `--size-*` yields exactly
   * one utility, `size-*`, which sets both axes - so `w-window-button` off a
   * `--size-` token compiles to NOTHING, and a button written that way loses
   * its width with no error anywhere. Every measurement here is one axis: the
   * bar has a height, the rail a width, the button a width unequal to its
   * height. `--spacing-*` is the namespace that feeds `w-`, `h-`, `min-h-`
   * and the padding utilities, so it is the one that can say so. Caught by
   * compiling the utility rather than by reading the stylesheet, which is
   * what `tailwind.test.ts` exists for.
   */
  --spacing-titlebar: 40px;
  --spacing-rail: 216px;
  --spacing-window-button: 46px;

  /*
   * How much of a frameless window's edge can be grabbed to resize it.
   *
   * The system used to own this and gave about 4 pixels plus whatever the
   * border was; a frameless window has no border, so the whole of it has to
   * be put back by hand. Five is the smallest that can be hit reliably with a
   * mouse and the largest that does not steal a click meant for the first
   * line of text - the strips sit above everything, so anything they cover
   * they cover completely.
   *
   * The corner is double, because a corner is aimed at less precisely than an
   * edge and is the one that resizes both axes at once.
   */
  --spacing-resize-edge: 5px;
  --spacing-resize-corner: 10px;
}

/*
 * `target-min` - visually smaller, clickably larger.
 *
 * The obvious fix for a 16px cross is to make it 24px, and it is the wrong
 * one: a chip is a small thing by design and a cross a third of its height
 * reads as a button with a chip around it. The set's appearance is a
 * decision, and an accessibility floor should not overturn it.
 *
 * So the target grows and the glyph does not. The pseudo-element is centred on
 * the control, takes its size, and refuses to go under the floor - so a
 * control already large enough is untouched, and a smaller one gains an
 * invisible margin of hit area on every side.
 *
 * `position: relative` comes with it rather than being left to the caller: a
 * target that silently does nothing because its parent forgot to establish a
 * containing block is exactly the failure this exists to prevent.
 *
 * Not `padding`, which was the other candidate: padding moves the glyph inside
 * its box and changes how the control sits in a flex row, so every call site
 * would need a compensating negative margin. This changes nothing about
 * layout.
 */
@utility target-min {
  position: relative;

  &::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    translate: -50% -50%;
    width: 100%;
    height: 100%;
    min-width: var(--size-target);
    min-height: var(--size-target);
  }
}

/*
 * How tall a control is, and how much room a screen gives each row.
 *
 * `h-9` appeared in nine primitives - every field the set has - each spelling
 * it out, which is why `Input` could not be made compact without editing
 * `Input`. One decision made nine times gets one name.
 *
 * **Not in `@theme`, and that is the whole mechanism.** A token declared there
 * is inlined by the compiler: `h-control` came out as `height: 36px`, the
 * override on a container had nothing to bind to, and the density attribute
 * did exactly nothing. Measured in the browser rather than assumed - the
 * container's `--row-control` read 32px while the field it contained stayed
 * 36. Tailwind also writes a fallback for any `var()` it recognises from the
 * theme, so the name has to live outside the theme's namespaces entirely.
 *
 * Declared here as plain custom properties and turned into utilities by hand
 * below, the reference survives, and an override on an ancestor reaches every
 * control under it - which is what makes density a property of a region
 * rather than of a component.
 */
:root {
  --row-control: 36px;
  --row-control-sm: 32px;
  --row-control-lg: 40px;

  /* The same question for a table, whose rows are sized by what is above and
   * below the text rather than by a height. `Table` had its own `density`
   * prop for this, with its own words - `base` and `dense` - which meant the
   * set used one word for two mechanisms and a product had to set both. */
  --row-cell: 10px;
}

@utility h-control {
  height: var(--row-control);
}

@utility py-row {
  padding-block: var(--row-cell);
}

@utility h-control-sm {
  height: var(--row-control-sm);
}

@utility h-control-lg {
  height: var(--row-control-lg);
}

/*
 * Density.
 *
 * Two answers to one question, and the set had neither: a product wanting a
 * tighter table wrote `h-8` at every call site, which is the drift the scale
 * exists to stop, one screen at a time.
 *
 * **It is an attribute on a container, not a prop on a component.** A prop
 * would have to be added to every primitive, threaded through every wrapper a
 * product writes, and passed by hand at each call site - and a primitive
 * written next year would not have it. An attribute is inherited:
 *
 *     <form data-density="compact">   …every field inside it…
 *
 * That reaches components which did not exist when the product was built, and
 * a product's own components too, as long as they measure in `h-control` like
 * everything else.
 *
 * The floor does not move with it. `--size-target` stays 24px at every
 * density, because WCAG does not care how tight a table is - which is exactly
 * why `target-min` grows the hit area rather than the control: a compact row
 * is still one a hand can hit.
 */
[data-density='compact'] {
  --row-control: 32px;
  --row-control-sm: 28px;
  --row-control-lg: 36px;
  --row-cell: 6px;
}

[data-density='comfortable'] {
  --row-control: 40px;
  --row-control-sm: 36px;
  --row-control-lg: 44px;
  --row-cell: 14px;
}

/*
 * Stacking order.
 *
 * Not in `@theme`: Tailwind has no z-index namespace, so `z-50` is a literal
 * fifty and a named step would not compile. These are custom properties a
 * component reads directly - `z-index: var(--z-modal)`.
 *
 * The order is the products' own, with the gaps closed. They ran 10 for an
 * in-flow popup, 20 sticky, 30 menu, 40 for a floating button, 50 for modals
 * and drawers, then jumped to 70 and 80 for the command palette - which had to
 * clear the modal layer and had no name to do it with.
 */
:root {
  /*
   * Motion. One duration existed before this - 160ms on a route change - and
   * everything else rode Tailwind's default. These are the steps around it:
   * `quick` for a colour or an opacity that should feel immediate, `base` for
   * something that moves, `slow` for something arriving from off-screen.
   *
   * Not in `@theme`: Tailwind's `duration-*` utility takes a literal number,
   * not a named step, so these are read directly - `transition-duration:
   * var(--duration-base)`. The easing curves opposite them ARE a namespace,
   * so `ease-out` is a class.
   *
   * Every duration here is for people who want motion: `prefers-reduced-
   * motion` cuts them to nothing further down.
   */
  --duration-quick: 120ms;
  --duration-base: 160ms;
  --duration-slow: 240ms;

  --z-popup: 10;
  --z-sticky: 20;
  --z-menu: 30;
  --z-floating: 40;
  --z-overlay: 50;
  --z-modal: 60;
  --z-palette: 70;
  --z-toast: 80;
}

/*
 * Base layer: what every product would otherwise write again. Scoped to
 * elements and to `:focus-visible`, never to a class, so nothing here can
 * collide with a component.
 */
body {
  margin: 0;
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

/*
 * In `@layer base`, so a component can turn it off.
 *
 * Unlayered, this rule has the same specificity as `focus-visible:outline-none`
 * from Tailwind - both are one pseudo-class - and wins on source order alone,
 * because the theme is imported before the utilities. Every component that
 * draws its own focus ring got this one on top of it: the command palette's
 * field had an accent outline it had explicitly opted out of, and a combobox
 * with chips drew two rings, one around the box and one around the input
 * inside it.
 *
 * A layered rule loses to any unlayered one regardless of specificity, which
 * is the whole point of cascade layers - the base layer states a default and
 * a component overrides it by saying so.
 */
@layer base {
  :focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
  }
}

/*
 * Scrollbars. A browser's default bar is a piece of someone else's chrome
 * sitting in the middle of the product - full width, with step arrows. These
 * are the line's own: thin, in the palette, drawn only where something
 * actually scrolls.
 */
* {
  scrollbar-width: thin;
  scrollbar-color: var(--line-2) transparent;
}

*::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

*::-webkit-scrollbar-track {
  background: transparent;
}

*::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 999px;
  background: var(--line-2);
  background-clip: content-box;
  /* The thumb is drawn proportional to how much of the document fits on
   * screen, so a long one collapses it to a few pixels: still visible, no
   * longer catchable by a pointer. This is the floor below which it stops
   * being a control. */
  min-height: 2.5rem;
}

*::-webkit-scrollbar-thumb:hover {
  background: var(--dim);
  background-clip: content-box;
}

*::-webkit-scrollbar-corner {
  background: transparent;
}

*::-webkit-scrollbar-button {
  display: none;
}

