import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Columns over a baseline: one period, one bar.
 *
 * Bars rather than a line, and the distinction is the data's not the
 * drawing's: a line says the value exists between the points, a column says
 * each period is its own sum. Hours worked in a week is a sum - there is no
 * "Wednesday afternoon" reading between two weeks - so it is a column.
 *
 * **The chart owns its height in pixels.** That is not a style choice, it is
 * the defect this component exists to prevent. The first consumer drew its
 * bars as a percentage of the parent, inside a flex row sized from its own
 * content: the child had no base to be a percentage of, every bar computed to
 * zero, and the chart shipped as a row of bare axis labels. No test and no API
 * check could see it - the owner found it by looking, and it cost a patch
 * release. Here the plot is a stated number of pixels and a bar is a
 * percentage of *that*.
 *
 * **An absent period is not a short one.** A week with nothing recorded and a
 * week of twenty minutes are different facts, and a bar of no height says
 * neither - it reads as a bar that failed to render. So a gap keeps its place
 * in the row and is drawn as a mark of its own.
 *
 * Interaction is one `title` per column rather than a tooltip layer: this is a
 * small chart that sits inside a panel, and the numbers it holds also belong
 * in the list beside it. A reader who needs them exactly should not have to
 * hover to find out.
 */

export const barChartVariants = cva('flex items-end gap-1 border-b border-chart-axis', {
  variants: {
    size: {
      /* Inside a panel, beside other things. */
      sm: '[--plot:72px]',
      /* On its own, where the shape is the subject. */
      md: '[--plot:112px]',
    },
  },
  defaultVariants: { size: 'md' },
})

export const barVariants = cva('mx-auto w-3/5 max-w-6 rounded-t-[4px]', {
  variants: {
    tone: {
      accent: 'bg-accent',
      /* For a bar that is one of several series, or one the caller is
       * highlighting against the rest. */
      series: 'bg-series-1',
      good: 'bg-good',
      warn: 'bg-warn',
      bad: 'bg-bad',
      /* The rest of the field, when one bar is the story: emphasis is the
       * most underused form in a chart of eight equal colours. */
      muted: 'bg-line-2',
    },
  },
  defaultVariants: { tone: 'accent' },
})

export interface BarDatum {
  /** Distinguishes this column from its neighbours. */
  key: string
  /** The period's own sum. `null` is a period with nothing recorded, which is
   * not the same as a sum of zero and is not drawn as a bar. */
  value: number | null
  /** What goes under the column. Kept short - these labels sit at a width the
   * chart does not control. */
  label: ReactNode
  tone?: NonNullable<VariantProps<typeof barVariants>['tone']>
  /** What the column says, for a reader hovering it and for a screen reader.
   * Required per bar, because a rectangle announces nothing. */
  title: string
}

export interface BarChartProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>,
    VariantProps<typeof barChartVariants> {
  bars: BarDatum[]
  /** The top of the scale. Defaults to the tallest bar present; state it to
   * compare two charts, or to hold a scale still while the data moves. */
  max?: number
  /** What the whole chart is, in words. */
  label: string
}

/** The shortest a bar may be drawn, as a percentage of the plot.
 *
 * A twenty-minute week against a forty-hour one is half a percent, which
 * rounds to nothing: the period was recorded and would simply not be there. */
const MIN_BAR = 3

export function BarChart({ bars, max, label, size, className, ...props }: BarChartProps) {
  const values = bars.map((bar) => bar.value).filter((value): value is number => value !== null)
  /* A ceiling of at least one, so a chart of nothing but zeroes divides
   * safely and draws a row of floors rather than nothing at all. */
  const ceiling = Math.max(max ?? 0, ...values, 1)

  return (
    <div className={cn(barChartVariants({ size }), className)} role="img" aria-label={label} {...props}>
      {bars.map((bar) => (
        <div key={bar.key} className="flex min-w-0 flex-1 flex-col items-center gap-1.5">
          {/* The track carries the height itself. See the note above: a
            * percentage against a parent that has no height of its own
            * resolves to zero, and the chart disappears without failing. */}
          <div className="flex h-[var(--plot)] w-full items-end" title={bar.title}>
            {bar.value === null ? (
              /* A gap, drawn as one. A bar of no height is indistinguishable
               * from a bar that did not render, and closing the gap up would
               * turn an absence into continuity - the one thing a trend must
               * not do. */
              <div className="mx-auto h-1 w-3/5 max-w-6 rounded-t-[4px] border-x border-t border-line-2" />
            ) : (
              <div
                className={cn(barVariants({ tone: bar.tone }))}
                style={{ height: `${Math.max((bar.value / ceiling) * 100, MIN_BAR)}%` }}
              />
            )}
          </div>
          <span className="w-full truncate text-center text-[10px] text-faint tabular-nums">
            {bar.label}
          </span>
        </div>
      ))}
    </div>
  )
}

/*
 * A line across the plot, at a value on the same scale.
 *
 * For the number every bar is read against - a median, a target, an agreed
 * norm. A chart without its baseline invites the reader to invent one, and the
 * one they invent is usually the tallest bar.
 *
 * Drawn as a solid hairline rather than a dash: a dashed rule reads as
 * "projected" or "threshold" when it is neither, and the doctrine is explicit
 * that grid and axis lines are solid.
 */
export interface BaselineProps extends HTMLAttributes<HTMLDivElement> {
  /** Where it sits, on the same scale as the bars. */
  value: number
  /** The same ceiling the chart is drawn against. */
  max: number
  /** What the line is, beside it. */
  children?: ReactNode
}

export function Baseline({ value, max, children, className, ...props }: BaselineProps) {
  if (!(max > 0) || value < 0 || value > max) return null

  return (
    <div
      className={cn('pointer-events-none absolute inset-x-0 flex items-center gap-2', className)}
      style={{ bottom: `${(value / max) * 100}%` }}
      {...props}
    >
      {/* The rule stops short of the label rather than running under it: a
        * hairline crossing its own caption reads as a strikethrough. */}
      <div className="h-px flex-1 bg-chart-grid" />
      {children !== undefined && (
        <span className="shrink-0 text-[10px] leading-none text-faint tabular-nums">{children}</span>
      )}
    </div>
  )
}

/*
 * The box a chart and its baseline share.
 *
 * Two things it does, and both are the component's job rather than the
 * caller's. It establishes the positioning context the baseline needs - left
 * to the caller that is a `relative` remembered or forgotten, and forgotten it
 * puts the rule at the bottom of the page. And it keeps a gutter on the right
 * for the baseline's label, which otherwise sits on top of the last columns:
 * the label is outside the plot, so the plot has to end before it starts.
 */
export interface ChartFrameProps extends HTMLAttributes<HTMLDivElement> {
  /** Room on the right for the baseline's label. Omit it where there is no
   * baseline, or where the label is short enough to live in the panel's own
   * padding. */
  gutter?: boolean
  children: ReactNode
}

export function ChartFrame({ gutter = true, className, ...props }: ChartFrameProps) {
  return <div className={cn('relative', gutter && 'pr-16', className)} {...props} />
}

import { Fragment, type HTMLAttributes, type ReactNode } from 'react'
import { useRender } from '@base-ui/react/use-render'
import { cn } from 'dowel-ui'

/*
 * Breadcrumbs.
 *
 * Where you are, as a trail rather than as a word. On a list screen the
 * screen's own name is enough; on something opened from it, it is not -
 * "Works" says nothing about which work, and the way back to the list is
 * otherwise the browser's back button alone, which a desktop window does not
 * visibly have.
 *
 * The last crumb is where you stand and is not a link. That is not styling:
 * it carries `aria-current="page"`, so a reader hears which of the four is
 * the destination rather than a list of four places to go. Everything before
 * it is the product's own link element, given through `render` for the reason
 * the rest of the set gives it - the registry has no business installing a
 * router.
 *
 * The trail truncates from the middle when it is longer than it is wide: the
 * first crumb and the last are the two that matter, and dropping the middle
 * into an ellipsis keeps the way home and the place you are. Letting it wrap
 * onto a second line would change the height of a title bar.
 */

export interface Crumb {
  id: string
  label: ReactNode
}

export interface BreadcrumbsProps extends Omit<HTMLAttributes<HTMLElement>, 'children' | 'onSelect'> {
  /** What the trail is called for a reader - "Breadcrumb" by convention, but
   * a product with two of them on one screen should say which. */
  label: string
  items: readonly Crumb[]
  /** The element a crumb before the last is drawn as. Without it a crumb is a
   * button and `onSelect` says which was pressed. */
  render?: (item: Crumb) => useRender.RenderProp
  onSelect?: (id: string) => void
  /**
   * How many crumbs are drawn before the middle is folded away. The first and
   * the last are always kept, so this is a floor of three.
   *
   * The default is four, which is one more than any screen in the line
   * actually reaches: a trail deeper than that is a sign the screens are
   * nested more deeply than anyone will navigate.
   */
  max?: number
}

/** The trail with its middle folded away, and where the fold happened.
 *
 * The first crumb is kept because it is the way out, and the last because it
 * is where you are; the ellipsis stands for everything between. It is not a
 * menu: a product whose trail is regularly too long has a navigation problem
 * that a disclosure on a crumb would only hide. */
function fold(items: readonly Crumb[], max: number): (Crumb | 'ellipsis')[] {
  if (items.length <= max) return [...items]
  // `max - 2` for the first crumb and the ellipsis, so the count the caller
  // asked for is the count that is drawn.
  return [items[0]!, 'ellipsis', ...items.slice(items.length - (max - 2))]
}

export function Breadcrumbs({
  label,
  items,
  render,
  onSelect,
  max = 4,
  className,
  ...props
}: BreadcrumbsProps) {
  const shown = fold(items, Math.max(3, max))

  return (
    <nav aria-label={label} className={cn('flex min-w-0 items-center', className)} {...props}>
      {/* An ordered list, because the order is the meaning: a reader is told
          "list, 3 items" and then hears them from the root inwards. */}
      <ol className="flex min-w-0 items-center gap-1.5 text-sm">
        {shown.map((entry, index) => (
          <Fragment key={entry === 'ellipsis' ? 'ellipsis' : entry.id}>
            {index === 0 ? null : (
              // Hidden from a reader: the separator is punctuation drawn
              // between list items that are already announced as a list, and
              // read aloud it becomes "Works, greater than, Harbour lights".
              <li aria-hidden className="shrink-0 text-faint" role="presentation">
                ›
              </li>
            )}
            {entry === 'ellipsis' ? (
              <li className="shrink-0 text-faint">…</li>
            ) : (
              <BreadcrumbItem
                item={entry}
                last={index === shown.length - 1}
                render={index === shown.length - 1 ? undefined : render?.(entry)}
                onSelect={onSelect}
              />
            )}
          </Fragment>
        ))}
      </ol>
    </nav>
  )
}

function BreadcrumbItem({
  item,
  last,
  render,
  onSelect,
}: {
  item: Crumb
  last: boolean
  render?: useRender.RenderProp
  onSelect?: (id: string) => void
}) {
  const crumb = useRender({
    render,
    // Where you stand is not somewhere to go: the last crumb is text, not a
    // control, so it is neither focusable nor announced as a link.
    defaultTagName: last ? 'span' : 'button',
    props: {
      ...(render === undefined && !last ? { type: 'button' } : {}),
      'aria-current': last ? ('page' as const) : undefined,
      onClick: last ? undefined : () => onSelect?.(item.id),
      className: cn(
        'block truncate rounded-xs no-underline',
        'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        last
          ? 'font-semibold text-text'
          : 'cursor-pointer text-dim transition-colors hover:text-text',
      ),
      children: item.label,
    },
  })

  return (
    // The crumbs before the last keep their width; the last is the one that
    // gives, because it is the one that is a title and may be a sentence
    // long. `min-w-0` on it so `truncate` inside has something to shrink to.
    <li className={last ? 'min-w-0' : 'shrink-0'}>{crumb}</li>
  )
}

import type { ButtonHTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { useRender } from '@base-ui/react/use-render'
// `cn` comes from the package rather than being copied in beside the
// component (ADR 0002): a helper every primitive shares should update
// centrally, and a project installing a component already has the package for
// the theme. shadcn's own components import it from `@/lib/utils`; that is a
// per-project alias, and a copied file cannot know what it points at.
import { cn } from 'dowel-ui'

/*
 * Button.
 *
 * Five variants, because that is what the line's products actually reach for:
 * one primary action per screen, a quiet default, a soft accent for something
 * selected, a destructive one, and an icon-only.
 *
 * Every colour and every size is a token. There are no `dark:` utilities and
 * no raw values - the theme swaps underneath, so the same class list is
 * correct in both themes and in every product's accent.
 */
export const buttonVariants = cva(
  [
    'inline-flex cursor-pointer items-center justify-center gap-1.5 whitespace-nowrap',
    'font-medium transition-colors',
    // Disabled is a state, not a colour: the button keeps its own hue and
    // loses contact instead, which reads the same whatever the accent is.
    'disabled:pointer-events-none disabled:opacity-50',
    '[&_svg]:shrink-0',
  ],
  {
    variants: {
      variant: {
        primary: 'rounded-md bg-accent font-semibold text-on-accent hover:bg-accent-2',
        ghost: 'rounded-md border border-line text-dim hover:border-line-2 hover:text-text',
        soft: 'rounded-md bg-accent-soft text-accent hover:bg-accent-soft/60',
        danger: 'rounded-md text-bad hover:bg-bad-soft',
        icon: 'rounded-md text-dim hover:bg-soft hover:text-text',
      },
      size: {
        sm: 'h-7 px-2.5 text-xs',
        md: 'h-9 px-3.5 text-sm',
        'icon-sm': 'size-7 [&_svg]:size-3.5',
        'icon-md': 'size-8 [&_svg]:size-4',
      },
    },
    defaultVariants: { variant: 'ghost', size: 'md' },
  },
)

export interface ButtonProps
  extends ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  /**
   * Render something else with the button's clothes on - a link, most often.
   *
   * Takes the element itself rather than a boolean: `render={<a href="…" />}`.
   * A function is also accepted, for the rare case that needs the props
   * before deciding what to build with them.
   */
  render?: useRender.RenderProp
}

export function Button({ variant, size, render, className, type, ...props }: ButtonProps) {
  return useRender({
    render,
    defaultTagName: 'button',
    props: {
      // A `<button>` inside a form submits it unless told otherwise, which
      // surprises everyone once. When rendering as something else the
      // attribute is meaningless and would land on an `<a>`, so it is only
      // set for the element that has it - `render` is what says which.
      ...(render === undefined && type === undefined ? { type: 'button' } : { type }),
      className: cn(buttonVariants({ variant, size }), className),
      ...props,
    },
  })
}

/*
 * The arithmetic a calendar runs on, with no React in it.
 *
 * Split out of the Calendar because the size gate asked the right question:
 * the file was two and a half times over its ceiling, and the reason was that
 * it held two things - the sums, and the grid that draws them. These are the
 * sums, and they are what DatePicker, DateRangePicker and any product doing
 * its own date work import.
 *
 * Everything here takes and returns `YYYY-MM-DD`, and never a `Date`. A
 * birthday has no timezone; a release date has no hour. Put one in a `Date`
 * and it becomes a moment - and moments cross midnight when they are
 * serialised, which is how a date reaches a server a day early. The string is
 * what a database column holds and what JSON carries.
 *
 * `Date` appears inside, in two places only: to ask `Intl` for a name, and to
 * add days. Both are wrapped here, so no caller ever holds one.
 *
 * No date library, deliberately. `react-day-picker` is good and would bring
 * `date-fns` and `@date-fns/tz` behind it - the first heavy dependency in a
 * set that is otherwise Base UI or nothing. `Intl` already knows the part a
 * library would be consulted for: which day the week starts on here, and what
 * the months are called. The rest is the arithmetic below, and it is only
 * hard when a date is stored as a moment.
 */

/** A calendar date: `2026-09-02`. Not a moment - no time, no zone. */
export type IsoDate = string

/** Whether a string is a calendar date this component can work with, and one
 * that actually exists. `2026-02-31` parses arithmetically and is not a day. */
export function isIsoDate(value: string): value is IsoDate {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false
  const [year, month, day] = value.split('-').map(Number) as [number, number, number]
  if (month < 1 || month > 12 || day < 1) return false
  return day <= daysInMonth(year, month)
}

/** How many days that month has. The leap rule in full, because the
 * hundred-year exception is the part that gets left out. */
export function daysInMonth(year: number, month: number): number {
  if (month === 2) {
    const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0
    return leap ? 29 : 28
  }
  return [4, 6, 9, 11].includes(month) ? 30 : 31
}

/** Today, as a calendar date in the reader's own timezone.
 *
 * Deliberately not `new Date().toISOString().slice(0, 10)`, which is the
 * common spelling and is wrong: that converts to UTC first, so anyone east of
 * Greenwich late in the evening gets tomorrow. */
export function today(): IsoDate {
  const now = new Date()
  return format(now.getFullYear(), now.getMonth() + 1, now.getDate())
}

function format(year: number, month: number, day: number): IsoDate {
  return `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
}

interface Parts {
  year: number
  month: number
  day: number
}

export function parts(date: IsoDate): Parts {
  const [year, month, day] = date.split('-').map(Number) as [number, number, number]
  return { year, month, day }
}

/** The same date shifted by whole days. Goes through a `Date` at noon rather
 * than midnight: a shift over a daylight-saving boundary at midnight can land
 * on the same calendar day it started from. */
export function addDays(date: IsoDate, days: number): IsoDate {
  const { year, month, day } = parts(date)
  const moved = new Date(year, month - 1, day, 12)
  moved.setDate(moved.getDate() + days)
  return format(moved.getFullYear(), moved.getMonth() + 1, moved.getDate())
}

/** The same day-of-month in another month, clamped when it does not exist
 * there: a step back from 31 March lands on 28 February, not on 3 March. */
export function addMonths(date: IsoDate, months: number): IsoDate {
  const { year, month, day } = parts(date)
  const zero = year * 12 + (month - 1) + months
  const nextYear = Math.floor(zero / 12)
  const nextMonth = (zero % 12) + 1
  return format(nextYear, nextMonth, Math.min(day, daysInMonth(nextYear, nextMonth)))
}

/** Which weekday a date falls on, as `Intl` numbers them: 1 is Monday, 7 is
 * Sunday. `Date` numbers Sunday 0, which does not sort and does not match
 * what `getWeekInfo` returns. */
export function weekday(date: IsoDate): number {
  const { year, month, day } = parts(date)
  const js = new Date(year, month - 1, day, 12).getDay()
  return js === 0 ? 7 : js
}

/** Which day the week starts on here: 1 Monday, 7 Sunday.
 *
 * `getWeekInfo` is the current spelling and `weekInfo` the older one; some
 * engines have neither, and Monday is the majority answer worldwide. */
export function firstDayOfWeek(locale: string): number {
  try {
    const info = new Intl.Locale(locale) as Intl.Locale & {
      getWeekInfo?: () => { firstDay: number }
      weekInfo?: { firstDay: number }
    }
    return info.getWeekInfo?.().firstDay ?? info.weekInfo?.firstDay ?? 1
  } catch {
    return 1
  }
}

/** The grid of a month: whole weeks, starting on the locale's first day, with
 * the days either side included so every row has seven.
 *
 * Returned as dates rather than as numbers, so a cell never has to be told
 * which month it belongs to - it knows, and a click on a trailing day works
 * without a special case. */
export function monthGrid(month: IsoDate, locale: string): IsoDate[][] {
  const { year, month: monthNumber } = parts(month)
  const first = format(year, monthNumber, 1)
  const start = firstDayOfWeek(locale)

  // How far back the grid starts: the distance from the first of the month
  // back to the most recent week start.
  const lead = (weekday(first) - start + 7) % 7
  const origin = addDays(first, -lead)

  const weeks: IsoDate[][] = []
  let cursor = origin
  // Six rows always, so the calendar does not change height between months -
  // a popup that resizes as you page through it is one that moves under the
  // pointer.
  for (let week = 0; week < 6; week += 1) {
    const row: IsoDate[] = []
    for (let day = 0; day < 7; day += 1) {
      row.push(cursor)
      cursor = addDays(cursor, 1)
    }
    weeks.push(row)
  }
  return weeks
}

/** The weekday initials, in the order this locale lays them out. */
export function weekdayNames(locale: string, start: number): string[] {
  const names = new Intl.DateTimeFormat(locale, { weekday: 'short' })
  // Any week works; this one begins on a Monday.
  const monday = Date.UTC(2024, 0, 1)
  return Array.from({ length: 7 }, (_, index) => {
    const offset = (start - 1 + index) % 7
    return names.format(new Date(monday + offset * 86_400_000))
  })
}

import { useMemo, useState, type KeyboardEvent } from 'react'
import { cn, useLocale } from 'dowel-ui'
import {
  addDays,
  addMonths,
  firstDayOfWeek,
  monthGrid,
  parts,
  today,
  weekday,
  weekdayNames,
  type IsoDate,
} from './calendar-math'

/*
 * Calendar - a month of days.
 *
 * The sums live next door in `calendar-math`, which has no React in it; this
 * is the grid that draws them and the keyboard that moves around it.
 *
 * One tab stop for the whole grid, arrows within - the arrangement a radio
 * group has, and the reason a calendar is usable at all: forty-two tab stops
 * is not a control. Arrows move a cursor and only Enter chooses, so a product
 * listening for a change does not receive five dates on the way to the sixth.
 */

export interface CalendarProps {
  /** The selected day, or `undefined` for none. */
  value?: IsoDate
  onValueChange?: (value: IsoDate) => void
  /** Which month is shown. Uncontrolled unless given. */
  month?: IsoDate
  onMonthChange?: (month: IsoDate) => void
  /** Bounds, inclusive. A day outside them cannot be chosen. */
  min?: IsoDate
  max?: IsoDate
  /** For a range: the other end, so the days between can be shaded. */
  rangeEnd?: IsoDate
  /** Formats the names. The application's language by default - see `useLocale`. */
  locale?: string
  /** What the grid is called, for a screen reader. */
  'aria-label'?: string
  /** Names the buttons that page the months. Required: they are icons, and an
   * icon with no name is a button that announces nothing. */
  previousMonthLabel: string
  nextMonthLabel: string
  className?: string
}

export function Calendar({
  value,
  onValueChange,
  month,
  onMonthChange,
  min,
  max,
  rangeEnd,
  locale,
  previousMonthLabel,
  nextMonthLabel,
  className,
  'aria-label': ariaLabel,
}: CalendarProps) {
  const [ownMonth, setOwnMonth] = useState<IsoDate>(() => value ?? today())
  const shown = month ?? ownMonth

  /* Which day the keyboard is on. It is not the selection: arrowing around a
   * calendar moves a cursor, and only Enter chooses - otherwise every arrow
   * key would fire `onValueChange` and a product listening for it would save
   * five dates on the way to the sixth. */
  const [focused, setFocused] = useState<IsoDate>(() => value ?? today())

  const language = useLocale(locale)
  const weeks = useMemo(() => monthGrid(shown, language), [shown, language])
  const start = firstDayOfWeek(language)
  const names = useMemo(() => weekdayNames(language, start), [language, start])
  const heading = useMemo(
    () => new Intl.DateTimeFormat(language, { month: 'long', year: 'numeric' }).format(
      new Date(parts(shown).year, parts(shown).month - 1, 1),
    ),
    [shown, language],
  )
  const dayNumber = useMemo(() => new Intl.DateTimeFormat(language, { day: 'numeric' }), [language])
  const fullDate = useMemo(
    () => new Intl.DateTimeFormat(language, { dateStyle: 'long' }),
    [language],
  )

  const outOfBounds = (date: IsoDate) =>
    (min !== undefined && date < min) || (max !== undefined && date > max)

  const goToMonth = (next: IsoDate) => {
    if (month === undefined) setOwnMonth(next)
    onMonthChange?.(next)
  }

  const moveFocus = (next: IsoDate) => {
    setFocused(next)
    // Paging follows the cursor: arrowing off the end of a month shows the
    // next one rather than moving to a day nobody can see.
    if (parts(next).month !== parts(shown).month || parts(next).year !== parts(shown).year) {
      goToMonth(next)
    }
  }

  const onKeyDown = (event: KeyboardEvent) => {
    const jump: Record<string, () => IsoDate> = {
      ArrowRight: () => addDays(focused, 1),
      ArrowLeft: () => addDays(focused, -1),
      ArrowDown: () => addDays(focused, 7),
      ArrowUp: () => addDays(focused, -7),
      PageDown: () => addMonths(focused, 1),
      PageUp: () => addMonths(focused, -1),
      Home: () => addDays(focused, -((weekday(focused) - start + 7) % 7)),
      End: () => addDays(focused, 6 - ((weekday(focused) - start + 7) % 7)),
    }

    const move = jump[event.key]
    if (move) {
      event.preventDefault()
      moveFocus(move())
      return
    }

    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      if (!outOfBounds(focused)) onValueChange?.(focused)
    }
  }

  const now = today()

  return (
    <div className={cn('w-64 select-none', className)}>
      <div className="mb-2 flex items-center justify-between gap-1">
        <button
          type="button"
          aria-label={previousMonthLabel}
          onClick={() => goToMonth(addMonths(shown, -1))}
          className={cn(
            'flex size-7 items-center justify-center rounded-md text-dim',
            'transition-colors hover:bg-soft hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
          )}
        >
          <svg viewBox="0 0 16 16" className="size-4" aria-hidden>
            <path
              d="M10 3L5 8l5 5"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.75"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>

        {/* The month is announced when it changes, so paging with the arrows
          * says where you have arrived rather than moving silently. */}
        <div aria-live="polite" className="text-sm font-medium text-text">
          {heading}
        </div>

        <button
          type="button"
          aria-label={nextMonthLabel}
          onClick={() => goToMonth(addMonths(shown, 1))}
          className={cn(
            'flex size-7 items-center justify-center rounded-md text-dim',
            'transition-colors hover:bg-soft hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
          )}
        >
          <svg viewBox="0 0 16 16" className="size-4" aria-hidden>
            <path
              d="M6 3l5 5-5 5"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.75"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
      </div>

      {/* One tab stop for the whole grid, and the arrows move within it - the
        * arrangement a radio group has, and the reason a calendar is usable at
        * all: forty-two tab stops is not a control. */}
      <div
        role="grid"
        aria-label={ariaLabel}
        tabIndex={0}
        onKeyDown={onKeyDown}
        className={cn(
          'rounded-md',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        )}
      >
        <div role="row" className="mb-1 grid grid-cols-7">
          {names.map((name) => (
            <div
              key={name}
              role="columnheader"
              aria-label={name}
              className="py-1 text-center text-2xs uppercase tracking-caption text-faint"
            >
              {name}
            </div>
          ))}
        </div>

        {weeks.map((week) => (
          <div role="row" key={week[0]} className="grid grid-cols-7">
            {week.map((date) => {
              const outside = parts(date).month !== parts(shown).month
              const disabled = outOfBounds(date)
              const selected =
                value !== undefined &&
                (rangeEnd === undefined
                  ? date === value
                  : date === value || date === rangeEnd)
              const inRange =
                value !== undefined && rangeEnd !== undefined && date > value && date < rangeEnd

              return (
                <div role="gridcell" key={date} aria-selected={selected || undefined}>
                  <button
                    type="button"
                    // Not a tab stop: the grid is the control. Announced with
                    // its full date, because "14" on its own is not a date.
                    tabIndex={-1}
                    disabled={disabled}
                    aria-label={fullDate.format(new Date(parts(date).year, parts(date).month - 1, parts(date).day))}
                    aria-current={date === now ? 'date' : undefined}
                    onClick={() => {
                      setFocused(date)
                      if (!disabled) onValueChange?.(date)
                    }}
                    className={cn(
                      'flex h-8 w-full items-center justify-center rounded-md text-sm tabular-nums',
                      'transition-colors',
                      outside ? 'text-faint' : 'text-text',
                      inRange && 'bg-accent-soft',
                      selected && 'bg-accent font-medium text-on-accent',
                      !selected && !disabled && 'hover:bg-soft',
                      date === now && !selected && 'font-medium text-accent',
                      date === focused && 'ring-1 ring-line-2',
                      disabled && 'cursor-not-allowed opacity-40',
                    )}
                  >
                    {dayNumber.format(new Date(parts(date).year, parts(date).month - 1, parts(date).day))}
                  </button>
                </div>
              )
            })}
          </div>
        ))}
      </div>
    </div>
  )
}

import type { HTMLAttributes, MouseEvent } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Chip.
 *
 * A badge you can act on: a filter that can be removed, a tag with a count, a
 * selected value in a field. The difference from a Badge is entirely about
 * whether something happens when you click it - and if something does, that
 * part is a real `<button>` with a real label, not a decorative cross.
 *
 * `onRemove` is the reason this exists separately. Every product wrote the
 * same removable tag and every one of them made the cross a `<span>`, which
 * the keyboard cannot reach and a screen reader does not announce.
 */
export const chipVariants = cva(
  'inline-flex items-center gap-1 rounded-full border py-0.5 pl-2.5 text-xs whitespace-nowrap transition-colors',
  {
    variants: {
      variant: {
        outline: 'border-line text-dim',
        accent: 'border-transparent bg-accent-soft text-accent',
        soft: 'border-transparent bg-soft text-dim',
      },
      /** Padding on the right depends on whether a remove button sits there. */
      removable: {
        true: 'pr-1',
        false: 'pr-2.5',
      },
    },
    defaultVariants: { variant: 'outline', removable: false },
  },
)

export interface ChipProps
  extends Omit<HTMLAttributes<HTMLSpanElement>, 'onSelect'>,
    Omit<VariantProps<typeof chipVariants>, 'removable'> {
  /** Shown after the label, for a count. */
  count?: number
}

/*
 * Removable, or not - and if removable, named.
 *
 * The two props travel together as a union rather than as two optionals, so
 * the type says what the component means: a remove button exists only when
 * there is a word for it. There is no default word on purpose. A string the
 * component invents is a string the product cannot translate, and it would
 * ship in English to every reader who does not read English.
 */
type Removable =
  | { onRemove: () => void; removeLabel: string }
  | { onRemove?: never; removeLabel?: never }

export function Chip({
  variant,
  count,
  onRemove,
  removeLabel,
  className,
  children,
  ...props
}: ChipProps & Removable) {
  return (
    <span className={cn(chipVariants({ variant, removable: Boolean(onRemove) }), className)} {...props}>
      {children}

      {count !== undefined && <span className="text-faint tabular-nums">{count}</span>}

      {onRemove && (
        <button
          type="button"
          aria-label={removeLabel}
          onClick={(event: MouseEvent<HTMLButtonElement>) => {
            // A chip is often inside something else that is also clickable.
            event.stopPropagation()
            onRemove()
          }}
          className={cn(
            // `target-min` keeps the cross the size it looks - a chip is a
            // small thing and a cross a third of its height reads as a button
            // with a chip around it - while the area a pointer has to find
            // grows to the floor the theme sets.
            'grid size-4 place-items-center rounded-full text-faint transition-colors target-min',
            'hover:bg-line hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
          )}
        >
          <svg viewBox="0 0 16 16" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
            <path d="M4 4l8 8M12 4l-8 8" strokeLinecap="round" />
          </svg>
        </button>
      )}
    </span>
  )
}

import type { HTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { CopyButton } from './copy-button'

/*
 * Code, shown inside a product.
 *
 * The frame around a piece of code is the same everywhere and is written again
 * in every product: the scroll that must not wrap, the gutter of line numbers
 * that must not be selectable, the copy button, the caption saying which file
 * this is, and the marking of the lines the reader was sent here to look at.
 * All of that is here.
 *
 * WHAT IS DELIBERATELY NOT HERE IS THE HIGHLIGHTER. A registry component is
 * copied into a product and becomes its file, so whatever this imports becomes
 * that product's dependency for good. Shiki is over a megabyte of grammars
 * before a language is chosen and resolves asynchronously, which would give
 * this component a loading state for text already in memory; Prism is
 * synchronous and mutates globals. Either one decides, on the product's
 * behalf, which languages it ships - which is not a primitive's decision to
 * make.
 *
 * So the split is: this draws, the product colours. `tokens` takes lines of
 * `{ text, kind }` from any highlighter - a mapping is about twenty lines -
 * and the eight kinds are the ones that mean the same thing in every language.
 * Without `tokens` the block renders the plain string and is completely
 * usable, which is the honest default: most code in an interface is four lines
 * of a command, where colour adds nothing.
 *
 * The colours are `--syntax-*`, fixed like the series palette: `if` should not
 * be magenta in one product and cobalt in another. They are measured as TEXT,
 * against the hardest surface a block sits on rather than the typical one -
 * every one clears 4.5:1 in both themes. That is why they are not the series
 * palette, whose light values sink to 1.90:1 at this size.
 */

export const codeBlockVariants = cva(
  // `group` so the copy button reveals on hover of the whole block rather than
  // only once the pointer has found a button it cannot see; `relative` because
  // a block with no caption has nowhere to put that button but over the code.
  'group relative overflow-hidden rounded-md border border-line bg-soft font-mono',
  {
    variants: {
      size: {
        sm: 'text-2xs',
        md: 'text-sm',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The eight distinctions worth drawing in every language. A highlighter's own
 * theme names fifty; the rest are one grammar's vocabulary and do not travel,
 * so they fold into the nearest of these. */
export type TokenKind =
  | 'keyword'
  | 'string'
  | 'number'
  | 'comment'
  /** An identifier: a variable, a function, a property. */
  | 'name'
  /** A type name, a class, a constructor. */
  | 'type'
  | 'punctuation'
  /** What surrounds the code rather than being it: a decorator, an attribute,
   * a shell prompt, a diff marker. */
  | 'meta'

export interface CodeToken {
  text: string
  /** Left out for text that takes the ordinary foreground - whitespace,
   * anything the highlighter had no opinion about. */
  kind?: TokenKind
}

/* A record rather than a template string, because Tailwind reads class names
 * out of the source: `text-syntax-${kind}` compiles to nothing, and the block
 * would render in the default colour with no error anywhere. */
const tokenColor: Record<TokenKind, string> = {
  keyword: 'text-syntax-keyword',
  string: 'text-syntax-string',
  number: 'text-syntax-number',
  comment: 'text-syntax-comment',
  name: 'text-syntax-name',
  type: 'text-syntax-type',
  punctuation: 'text-syntax-punctuation',
  meta: 'text-syntax-meta',
}

export interface CodeBlockProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'onCopy'>,
    VariantProps<typeof codeBlockVariants> {
  /** The code, as it should land on the clipboard. Always required, even when
   * `tokens` is given: what is copied is the text, not a reassembly of the
   * highlighting. */
  code: string
  /** The same code, coloured. Lines of tokens - one array per line, and the
   * newlines are the array boundaries rather than characters in the text.
   * Left out, the block draws `code` in one colour. */
  tokens?: CodeToken[][]
  /** Shown above the code: a file name, a path, a language. It is what brings
   * the header; without one the copy button floats over the code instead,
   * because a strip holding nothing but a button that hides until hover is
   * empty furniture. */
  caption?: string
  /** Numbers down the left. Off by default: they are for code a reader is
   * meant to refer to, and on a two-line command they are furniture. */
  numbered?: boolean
  /** Where the numbering starts, for an excerpt lifted out of a file. */
  firstLine?: number
  /** Lines to mark, in the same numbering the reader sees. */
  highlight?: readonly number[]
  /** Brings the copy button, and names it for a screen reader. Required to
   * have one, and deliberately without a default: a string this component
   * invents is a string the product cannot translate. */
  copyLabel?: string
  /** Announced after a successful copy. Required alongside `copyLabel`. */
  copiedLabel?: string
  /** Told what happened, for a product that wants its own toast. */
  onCopy?: (ok: boolean) => void
  /**
   * Let long lines wrap instead of scrolling.
   *
   * Off by default, and that is the right default for code: a wrapped line
   * lies about where it ends, and indentation is how code is read. It exists
   * for the case where the "code" is really a long single-line value - a URL,
   * a token, a stack frame - which scrolls forever and reads no better for it.
   */
  wrap?: boolean
}

export function CodeBlock({
  code,
  tokens,
  caption,
  numbered = false,
  firstLine = 1,
  highlight,
  copyLabel,
  copiedLabel,
  onCopy,
  wrap = false,
  size,
  className,
  ...props
}: CodeBlockProps) {
  /* The trailing newline almost every file ends with would draw an empty final
   * row - and, with numbering on, a number against nothing. It is stripped for
   * drawing only; `code` is what gets copied, unchanged. */
  const lines: CodeToken[][] =
    tokens ?? code.replace(/\n$/, '').split('\n').map((text) => [{ text }])
  const marked = new Set(highlight ?? [])

  /* Built once. Where it lands is the only thing that differs: inside the
   * header when there is one, and over the code when there is not - which is
   * why the block is `relative`. */
  const copy =
    copyLabel === undefined ? null : (
      <CopyButton
        value={code}
        label={copyLabel}
        copiedLabel={copiedLabel ?? copyLabel}
        onCopy={onCopy}
        className={caption === undefined ? 'absolute right-1.5 top-1.5 z-10 bg-raise' : undefined}
      />
    )

  return (
    <div className={cn(codeBlockVariants({ size }), className)} {...props}>
      {/*
       * The header exists for the caption. The copy button goes in it when
       * there is one, and over the code when there is not.
       *
       * The first version drew a header whenever there was EITHER, and a live
       * run showed what that is: a block holding a command, with no caption,
       * got a 34px strip containing one button that is invisible until hover.
       * Empty furniture on the commonest shape there is.
       *
       * Not `<figcaption>`: this is a div, and a caption claiming to be one
       * without a `<figure>` around it is a lie to a screen reader.
       */}
      {caption === undefined ? (
        copy
      ) : (
        <div className="flex items-center gap-2 border-b border-line bg-softer px-3 py-1.5">
          <span className="grow truncate text-2xs text-dim">{caption}</span>
          {copy}
        </div>
      )}

      {/*
       * `<pre>` inside the scroller rather than around it, so the horizontal
       * scrollbar belongs to the code and the header stays put above it.
       *
       * `tabIndex={0}` is not decoration: a region that scrolls has to be
       * reachable by the keyboard, or a reader who does not use a pointer
       * cannot see the right-hand end of a long line. It carries a role and a
       * label for the same reason.
       */}
      <pre
        tabIndex={0}
        className={cn(
          'overflow-x-auto py-2 leading-relaxed',
          // Restored here because a product's shell usually turns selection
          // off - and code that cannot be selected cannot be taken away.
          'select-text',
          'focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent',
        )}
      >
        <code className="block">
          {lines.map((line, index) => {
            const number = firstLine + index
            return (
              <span
                key={number}
                className={cn(
                  'flex px-3',
                  /* A left rule as well as a tint: a marked line that says so
                   * only by a wash of accent is a line nobody notices, and one
                   * that a reader who does not see the hue never notices at
                   * all. */
                  marked.has(number) &&
                    'border-l-2 border-accent bg-accent-soft pl-[calc(0.75rem-2px)]',
                )}
              >
                {numbered && (
                  /*
                   * `user-select: none` is the whole reason the numbers are
                   * drawn here rather than in a counter or a background: a
                   * reader who selects the block to copy it must not get "1"
                   * welded to the front of every line. That is the defect this
                   * gutter exists to avoid, and it is invisible until someone
                   * pastes.
                   */
                  <span
                    className="mr-3 shrink-0 select-none text-right tabular-nums text-faint"
                    style={{ width: `${String(firstLine + lines.length - 1).length}ch` }}
                    aria-hidden
                  >
                    {number}
                  </span>
                )}
                {/* `break-words` alongside the wrapping, not instead of it.
                  * `pre-wrap` breaks at spaces, and the case `wrap` exists for
                  * - a URL, a token, a stack frame - has none: a live run
                  * showed a JWT sitting 320px outside a block that had asked
                  * to wrap. Only `overflow-wrap` breaks inside a word. */}
                <span
                  className={cn(
                    'min-w-0',
                    wrap ? 'whitespace-pre-wrap break-words' : 'whitespace-pre',
                  )}
                >
                  {/* A line with nothing on it still needs its height, or a
                    * blank line between two paragraphs of code closes up and
                    * the numbering drifts away from the file. */}
                  {line.length === 0 ? (
                    '\n'
                  ) : (
                    line.map((token, at) => (
                      <span
                        key={at}
                        className={token.kind === undefined ? undefined : tokenColor[token.kind]}
                      >
                        {token.text}
                      </span>
                    ))
                  )}
                </span>
              </span>
            )
          })}
        </code>
      </pre>
    </div>
  )
}

import { useId, useState, type ReactNode } from 'react'
import { cn, lineProducts } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * ColorField.
 *
 * Picking a colour for something the product stores: a tag, a project, a
 * calendar. Note what that is *not* - it is not choosing the appearance of the
 * interface. The theme decides that, from one accent, and a field that let a
 * reader repaint the chrome would undo the argument the whole system rests on.
 *
 * So the palette comes first and the free field second. The swatches are the
 * line's own fourteen accents plus the four semantic tokens, which is the
 * vocabulary a product already speaks; a value picked there is a *name*
 * (`kilna`, `good`), not a hex, and it keeps meaning the right thing when the
 * theme changes underneath it.
 *
 * Free hex is available because the owner asked for it, and it is worth
 * saying why that does not contradict "no raw colours in components": the rule
 * is about a component hardcoding its own appearance. A colour the reader
 * chose for their own tag is the product's *data* - the same kind of thing as
 * the tag's name - and data does not come from a token vocabulary.
 *
 * The swatch is a real `<input type="radio">` per colour, in a `radiogroup`.
 * That is what makes the arrows walk the palette, what makes the choice
 * announce itself, and what makes the whole group one tab stop.
 */

/** The four semantic colours, which mean the same thing in every product. */
const SEMANTIC = ['good', 'warn', 'bad', 'info'] as const

/** Whether a string is a colour this field would accept as free input. Six
 * digits or three, with the hash - the two forms a reader actually types. */
export function isHexColor(value: string): boolean {
  return /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(value)
}

export interface ColorFieldProps {
  /** The chosen colour: a token name, or a hex string. */
  value: string
  onValueChange: (value: string) => void
  /** Whether the reader may type a colour of their own. */
  allowCustom?: boolean
  /** Names the palette for a screen reader. */
  'aria-label'?: string
  'aria-labelledby'?: string
  /** How a swatch is named. Takes the colour's name, so the product can say
   * "Lime" in its own language rather than shipping ours. */
  swatchLabel?: (name: string) => string
  /** The label on the free-entry box, when `allowCustom` is on. */
  customLabel?: ReactNode
  disabled?: boolean
  className?: string
}

export function ColorField({
  value,
  onValueChange,
  allowCustom,
  swatchLabel,
  customLabel,
  disabled,
  className,
  ...aria
}: ColorFieldProps) {
  const name = useId()
  const customId = useId()

  /* What is in the free box while it is being typed.
   *
   * It is not `value`: half of `#3fa9` is not a colour, and pushing every
   * keystroke up would either reject the reader mid-word or paint the product
   * a colour they were passing through. The box commits when what is in it is
   * a colour. */
  const [draft, setDraft] = useState(isHexColor(value) ? value : '')

  const swatches = [
    ...lineProducts.map((product) => ({ token: product.name, css: product.accent })),
    ...SEMANTIC.map((token) => ({ token, css: `var(--${token})` })),
  ]

  return (
    <div className={cn('flex flex-col gap-2', disabled && 'pointer-events-none opacity-50', className)}>
      <div role="radiogroup" {...aria} className="flex flex-wrap gap-1.5">
        {swatches.map((swatch) => {
          const chosen = value === swatch.token
          return (
            <label
              key={swatch.token}
              className={cn(
                'relative grid size-7 cursor-pointer place-items-center rounded-md border transition-colors',
                chosen ? 'border-accent' : 'border-line hover:border-dim',
                // The ring has to be on the label: the input itself is hidden,
                // so `focus-visible` on it would never be seen.
                'focus-within:outline-2 focus-within:outline-offset-1 focus-within:outline-accent',
              )}
            >
              <input
                type="radio"
                name={name}
                value={swatch.token}
                checked={chosen}
                disabled={disabled}
                onChange={() => onValueChange(swatch.token)}
                className="sr-only"
              />
              <span
                aria-hidden
                className="size-5 rounded"
                /* The one place a colour is set from a value rather than a
                 * class, because the value *is* the colour - a palette that
                 * could not show its own colours would be a list of words. */
                style={{ background: swatch.css }}
              />
              <span className="sr-only">{swatchLabel?.(swatch.token) ?? swatch.token}</span>
            </label>
          )
        })}
      </div>

      {allowCustom && (
        <div className="flex items-center gap-2">
          <label htmlFor={customId} className="text-xs text-dim">
            {customLabel}
          </label>
          <input
            id={customId}
            value={draft}
            disabled={disabled}
            /* No placeholder of its own.
             *
             * The obvious one is a specimen hex, and the lint rule that
             * forbids raw colours flags it - correctly, by the letter. Rather
             * than widen a gate that catches real violations for the sake of
             * one string, the format is shown by the monospace box and named
             * by `customLabel`, which is the product's word anyway. */
            spellCheck={false}
            onChange={(event) => {
              const next = event.target.value
              setDraft(next)
              // Committed only once it is a colour. Anything else is a word in
              // progress, and the product should not be repainted by one.
              if (isHexColor(next)) onValueChange(next)
            }}
            className={cn(fieldClasses, 'h-8 w-28 font-mono text-xs')}
          />
          <span
            aria-hidden
            className="size-5 shrink-0 rounded border border-line"
            style={{ background: isHexColor(draft) ? draft : 'transparent' }}
          />
        </div>
      )}
    </div>
  )
}

import { useCallback, useRef, useState, type PointerEvent as ReactPointerEvent } from 'react'
import { cn } from 'dowel-ui'

/*
 * The strip on a header cell's right edge that a column is dragged wider or narrower by.
 *
 * The handle, and the hook that keeps the widths it produces. Pointer events
 * rather than HTML5 drag-and-drop: a desktop shell that takes file drops for
 * itself never lets a `dragstart` reach the page, so the native API is a
 * handle that does nothing there; pointer capture on the handle also keeps
 * the drag alive when the pointer runs ahead of the cell, which at any speed
 * above a crawl it does.
 *
 * The starting width is measured from the cell rather than taken as a prop:
 * on pointerdown the handle reads its parent's box, and every move reports
 * that width plus the distance travelled. So the handle has no `width` to be
 * handed and cannot disagree with what is on screen. Double-click is the
 * reset, because a handle two pixels wide has no room for a second control.
 *
 * The widths themselves are the hook's, and there are two maps in it rather
 * than one. A table with any hand-set width has to switch to
 * `table-layout: fixed`, and under fixed layout every column needs a width
 * or the browser shares the free space equally between those without one -
 * which is how a date column ends up as wide as the title. So beside the
 * widths that were dragged, the hook keeps the widths every other column
 * measured the moment the first drag began, and `widthOf` answers from one
 * or the other. The caller draws one `<col>` per column from it and leaves
 * the one column meant to take the remaining space without a width.
 */

export interface ColumnResizeHandleProps {
  /** Names the column for assistive technology: "Resize the Tier column". */
  label: string
  /** Shown on hover: how to drag and how to reset. */
  hint?: string
  /** The width while dragging, and once more with `done` when the pointer is
   * let go - the moment to persist. */
  onResize: (width: number, done: boolean) => void
  /** Double-click: the column goes back to its natural width. */
  onReset: () => void
  /** Called on pointerdown, before the first `onResize` - the moment for the
   * caller to measure what every column is before the layout goes fixed. */
  onStart?: () => void
  /** Narrower than this and the column is a stripe with nothing in it. */
  minWidth?: number
  className?: string
}

export function ColumnResizeHandle({
  label,
  hint,
  onResize,
  onReset,
  onStart,
  minWidth = 56,
  className,
}: ColumnResizeHandleProps) {
  // Where the drag began, in both senses: the pointer's x and the cell's width.
  const origin = useRef<{ x: number; width: number } | null>(null)
  const [dragging, setDragging] = useState(false)

  const widthAt = (event: ReactPointerEvent<HTMLElement>): number | null => {
    const from = origin.current
    if (from === null) return null
    return Math.max(minWidth, Math.round(from.width + event.clientX - from.x))
  }

  const begin = (event: ReactPointerEvent<HTMLElement>) => {
    // The primary button only: a right-click on the edge is the context
    // menu's, and a middle one is nobody's.
    if (event.button !== 0) return
    const cell = event.currentTarget.parentElement
    if (cell === null) return
    event.preventDefault()
    event.stopPropagation()
    onStart?.()
    origin.current = { x: event.clientX, width: cell.getBoundingClientRect().width }
    event.currentTarget.setPointerCapture(event.pointerId)
    setDragging(true)
  }

  const move = (event: ReactPointerEvent<HTMLElement>) => {
    const width = widthAt(event)
    if (width !== null) onResize(width, false)
  }

  const end = (event: ReactPointerEvent<HTMLElement>) => {
    const width = widthAt(event)
    origin.current = null
    setDragging(false)
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId)
    }
    if (width !== null) onResize(width, true)
  }

  return (
    // A span, not a button: a button in a header cell would be one more tab
    // stop per column for something a keyboard cannot usefully drive. The
    // separator role says what it is; the label says which column.
    <span
      role="separator"
      aria-orientation="vertical"
      aria-label={label}
      title={hint}
      data-dragging={dragging ? '' : undefined}
      onPointerDown={begin}
      onPointerMove={move}
      onPointerUp={end}
      onPointerCancel={end}
      onDoubleClick={(event) => {
        event.stopPropagation()
        onReset()
      }}
      // The click after the drag must not reach the header: on a sortable
      // column it would flip the sort every time a width was set.
      onClick={(event) => event.stopPropagation()}
      className={cn(
        // Wider to hit than to see: the visible line is the inner pixel, the
        // grab zone is the whole strip. `touch-action: none` is what lets a
        // touch drag the column instead of scrolling the table.
        'absolute inset-y-0 right-0 z-10 w-2 cursor-col-resize touch-none select-none',
        'after:absolute after:inset-y-1.5 after:right-0.5 after:w-px after:bg-line after:transition-colors',
        'hover:after:bg-accent data-[dragging]:after:bg-accent',
        className,
      )}
    />
  )
}

/** The widths of the columns the hook is asked about, by column id. */
export type Widths<K extends string> = Partial<Record<K, number>>

/** What the hook is given. */
export interface ColumnWidthsOptions<K extends string> {
  /** What was dragged before - from storage, or nothing. A function is
   * called once, like `useState`'s. */
  initial: Widths<K> | (() => (Widths<K>))
  /** Told the hand-set widths whenever one settles: persist them here. */
  onChange?: (widths: Widths<K>) => void
  /** The width of a column that was not on screen when the others were
   * measured - one turned on after the first drag. */
  fallback?: (id: K) => number
  minWidth?: number
}

export interface ColumnWidths<K extends string> {
  /** True while any width is hand-set: the table is in fixed layout. */
  sized: boolean
  /** The widths that were dragged. */
  hand: Widths<K>
  /** Whether this column's width is the person's rather than measured. */
  isHandSized: (id: K) => boolean
  /** A width for the `<col>`: dragged, else measured, else the fallback. */
  widthOf: (id: K) => number | undefined
  /** A width from the handle; `done` on the last one persists. */
  resize: (id: K, width: number, done?: boolean) => void
  /** Back to the natural width; with nothing else hand-set, back to auto layout. */
  reset: (id: K) => void
  /** The natural widths, taken once before the layout goes fixed. Ignored
   * once it has, because what is measured then is the fixed width. */
  measure: (cells: Iterable<[K, number]>) => void
}

export function useColumnWidths<K extends string>({
  initial,
  onChange,
  fallback,
  minWidth = 56,
}: ColumnWidthsOptions<K>): ColumnWidths<K> {
  const [hand, setHand] = useState<Widths<K>>(initial)
  const [natural, setNatural] = useState<Widths<K>>({})
  // A mirror the callbacks read, so a resize that settles in the same tick as
  // its last move persists the value that was just set and not the one from
  // the render before.
  const held = useRef(hand)
  const sized = Object.keys(hand).length > 0

  const commit = useCallback(
    (next: Widths<K>, persist: boolean) => {
      held.current = next
      setHand(next)
      if (persist) onChange?.(next)
    },
    [onChange],
  )

  const resize = useCallback(
    (id: K, width: number, done = false) => {
      commit({ ...held.current, [id]: Math.max(minWidth, Math.round(width)) }, done)
    },
    [commit, minWidth],
  )

  const reset = useCallback(
    (id: K) => {
      const rest: Widths<K> = { ...held.current }
      delete rest[id]
      commit(rest, true)
      // With nothing hand-set the layout goes back to auto, and the next drag
      // measures afresh - the natural widths may have changed with the data.
      if (Object.keys(rest).length === 0) setNatural({})
    },
    [commit],
  )

  const measure = useCallback((cells: Iterable<[K, number]>) => {
    if (Object.keys(held.current).length > 0) return
    const measured: Widths<K> = {}
    for (const [id, width] of cells) measured[id] = Math.round(width)
    setNatural(measured)
  }, [])

  return {
    sized,
    hand,
    isHandSized: (id) => hand[id] !== undefined,
    widthOf: (id) => hand[id] ?? natural[id] ?? fallback?.(id),
    resize,
    reset,
    measure,
  }
}

/** The widths of a header row's cells, read off the screen.
 *
 * Each cell names its column in `data-column`; a cell without one - a
 * checkbox column, a row menu - is not a column the hook is asked about and
 * is skipped. Border-box widths, because that is what a `<col>` sets. */
export function measureColumns<K extends string>(row: HTMLElement, attribute = 'data-column'): [K, number][] {
  const measured: [K, number][] = []
  for (const cell of row.querySelectorAll<HTMLElement>(`[${attribute}]`)) {
    const id = cell.getAttribute(attribute)
    if (id !== null) measured.push([id as K, cell.getBoundingClientRect().width])
  }
  return measured
}

import type { Ref } from 'react'
import { Combobox as Base } from '@base-ui/react/combobox'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'
import { selectItemVariants, selectPopupVariants } from './select'

/*
 * Combobox.
 *
 * A Select you can type in. The list narrows as the query is typed, which is
 * the only difference that matters and the reason to reach for this one: a
 * Select stops being usable somewhere around thirty options, and a country
 * picker or a tag field is well past that.
 *
 * Everything the Select comment says about the native element applies here
 * too - there is no `<select>` under it, and the input is a real `<input
 * role="combobox">` so autofill, spellcheck and the phone keyboard still
 * work.
 *
 * Filtering is Base UI's: give the root an `items` array and it matches the
 * query against them with `Intl.Collator`, so accents and case behave the way
 * a reader in that language expects rather than the way `toLowerCase` does.
 * `filter` replaces the comparison; `filter={null}` turns it off for a list
 * that is filtered on a server.
 *
 * The chips are Base UI's too - Chips, Chip, ChipRemove - and that is worth
 * saying because inventing them is the obvious move and it goes wrong in one
 * specific way: hand-made chips end up as `<div>`s with an X that only a
 * pointer can reach, and the multi-select becomes keyboard-inaccessible at
 * exactly the point where it holds the most state. Base UI's are focusable,
 * walk with the arrows, and delete with Backspace.
 *
 * `Empty` renders only when nothing matched, and announces itself politely.
 * Its element stays mounted for that announcement to work, so it must not be
 * hidden with `display: none` or removed conditionally - which is why it is a
 * component here rather than a `{items.length === 0 && …}` in the product.
 */

/* Two bases, chosen by `bare`, rather than one base and an override.
 *
 * Inside `ComboboxChips` the container is the field, so the input has no
 * border, no background and no focus ring of its own - a bordered box inside a
 * bordered box reads as two controls, and two focus rings appear as one thick
 * one. The obvious way to write that is `fieldClasses` plus a few `-none`
 * classes, and it does not work: `tailwind-merge` does not treat
 * `focus-visible:outline-none` as conflicting with
 * `focus-visible:outline-2 … outline-accent`, so both survive and the later
 * one in the stylesheet wins. The same trap took `w-full` versus `w-auto`
 * earlier in this file.
 *
 * So the variant picks which set applies instead of trying to subtract from
 * one - nothing is left to a merge that has no opinion. */
export const comboboxInputVariants = cva('', {
  variants: {
    size: {
      sm: 'h-control-sm text-xs',
      md: 'h-control',
      lg: 'h-control-lg text-base',
    },
    bare: {
      true: 'h-7 w-auto min-w-24 flex-1 bg-transparent px-1 text-sm text-text placeholder:text-faint outline-none',
      false: fieldClasses,
    },
  },
  defaultVariants: { size: 'md', bare: false },
})

/** The list, and a row in it, are Select's - imported rather than copied.
 *
 * The two popups are the same object seen twice: a dropdown of options, one
 * of which can be chosen. A reader who uses both on one screen should not be
 * able to tell which is which until they type. Two `cva` calls that started
 * identical do not stay that way - one gets the padding fix - and then the
 * form has two dropdowns that are almost the same. */
export const comboboxPopupVariants = selectPopupVariants
export const comboboxItemVariants = selectItemVariants

/** The root. `items` is what gets filtered; `multiple` turns the value into an
 * array and makes the chips meaningful. */
export const Combobox = Base.Root

/** The wrapper for an input with something beside it - a clear button, an
 * icon, the chips. */
export const ComboboxInputGroup = Base.InputGroup

/** The button that opens the list without typing, for a reader who wants to
 * see everything there is. */
export const ComboboxTrigger = Base.Trigger

/** The chevron. Decorative. */
export const ComboboxIcon = Base.Icon

/** A labelled group of rows. */
export const ComboboxGroup = Base.Group

/** The rows of one group, as a render function over that group's items.
 *
 * A `List` is the listbox and there is one per combobox, so a grouped list is
 * a `List` over the groups with a `Collection` inside each - not a `List`
 * inside a `List`. Mapping by hand instead works, but the component then has
 * to be told how to match an item to a value, which is a second place for that
 * knowledge to live. */
export const ComboboxCollection = Base.Collection

/** The tick, drawn only on a chosen row. */
export const ComboboxItemIndicator = Base.ItemIndicator

/** A polite live region for the state of an asynchronous list. Stays mounted,
 * like `Empty`, so the announcement actually fires. */
export const ComboboxStatus = Base.Status

/** The container the chips sit in. Its children are plain nodes, not a render
 * function - the chosen values are mapped by `ComboboxValue` inside it.
 *
 * It wears the field's clothes and lays the chips out in a row that wraps,
 * which is the whole difference between a control and a list: unstyled, the
 * chips stack one per line and the box grows into a column of pills with the
 * input stranded underneath. The input sits on the same line as the last
 * chip and takes the rest of the width, so a half-filled field still looks
 * like a field. */
export function ComboboxChips({
  ref,
  className,
  ...props
}: Base.Chips.Props & { ref?: Ref<HTMLDivElement> }) {
  return (
    <Base.Chips
      // Taken out of `...props` and passed on deliberately: a product needs a
      // handle on this box to anchor the list to it, because the input inside
      // is only as wide as what has been typed.
      ref={ref}
      className={cn(
        fieldClasses,
        'flex min-h-9 flex-wrap items-center gap-1 py-1',
        'focus-within:outline-2 focus-within:outline-offset-0 focus-within:outline-accent',
        className,
      )}
      {...props}
    />
  )
}

/** The current value, as a render function of it. This is what turns a
 * `multiple` value into one chip per entry. */
export const ComboboxValue = Base.Value

/** `size` is taken from the native `<input size>` - a width in characters,
 * which nothing here wants - and given to the variant instead. */
export interface ComboboxInputProps
  extends Omit<Base.Input.Props, 'size'>,
    VariantProps<typeof comboboxInputVariants> {}

/** Where the query is typed. A real `<input role="combobox">`.
 *
 * Inside `ComboboxChips` it drops its own border and background: the
 * container is the field there, and a bordered input inside a bordered box
 * reads as two controls. */
export function ComboboxInput({ size, bare, className, ...props }: ComboboxInputProps) {
  // `bare` is pulled out and handed to `cva`. Left in `...props` it would be
  // spread onto the `<input>` as an unknown attribute and change nothing -
  // which is exactly what it did: the variant existed, the prop was passed,
  // and the class list came out without a trace of either.
  return <Base.Input className={cn(comboboxInputVariants({ size, bare }), className)} {...props} />
}

const iconButtonClasses = cn(
  'rounded-sm p-1 text-faint transition-colors hover:text-text',
  'focus-visible:outline-2 focus-visible:outline-accent',
  'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
)

/** Empties the value. Base UI hides it while there is nothing to clear. */
export function ComboboxClear({ className, ...props }: Base.Clear.Props) {
  return <Base.Clear className={cn(iconButtonClasses, className)} {...props} />
}

export interface ComboboxPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof comboboxPopupVariants> {
  /** Preferred side of the input. Base UI flips it when it does not fit. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. */
  align?: Base.Positioner.Props['align']
  /** Distance from the input, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /**
   * What to line the list up with. Defaults to the input that owns it.
   *
   * Pass the `ComboboxChips` box when there is one: with chips, the input is
   * only as wide as what has been typed - an empty one measured 214px inside
   * a 288px field - so a list anchored to it hangs short of the box a reader
   * sees. Base UI publishes the anchor's width as `--anchor-width`, which is
   * how the mismatch is visible from outside.
   */
  anchor?: Base.Positioner.Props['anchor']
  /** Where to portal to. Defaults to the document body. */
  container?: Base.Portal.Props['container']
}

/** The list. Portalled and positioned against the input, or the given anchor. */
export function ComboboxPopup({
  size,
  side,
  align,
  sideOffset = 4,
  anchor,
  container,
  className,
  children,
  ...props
}: ComboboxPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        anchor={anchor}
        className="[z-index:var(--z-menu)]"
      >
        <Base.Popup className={cn(comboboxPopupVariants({ size }), className)} {...props}>
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

/** The rows, as a list. Undressed: it is a wrapper, and the popup around it
 * already carries the border and the padding. */
export const ComboboxList = Base.List

/** A row. */
export function ComboboxItem({ className, ...props }: Base.Item.Props) {
  return <Base.Item className={cn(comboboxItemVariants(), className)} {...props} />
}

/** What is shown when nothing matched. The words are the product's. */
export function ComboboxEmpty({ className, ...props }: Base.Empty.Props) {
  return <Base.Empty className={cn('px-2 py-3 text-center text-sm text-faint', className)} {...props} />
}

/** One chosen value, in a multiple combobox. Focusable, so it can be reached
 * and removed without a pointer. */
export function ComboboxChip({ className, ...props }: Base.Chip.Props) {
  return (
    <Base.Chip
      className={cn(
        'flex items-center gap-1 rounded-sm bg-soft px-1.5 py-0.5 text-xs text-text',
        'outline-none data-[highlighted]:bg-accent-soft data-[highlighted]:text-accent',
        className,
      )}
      {...props}
    />
  )
}

/** The X on a chip. A real button, which is what makes Backspace and Enter
 * both work on it. */
export function ComboboxChipRemove({ className, ...props }: Base.ChipRemove.Props) {
  return <Base.ChipRemove className={cn(iconButtonClasses, 'p-0', className)} {...props} />
}

/** The caption above a group. */
export function ComboboxGroupLabel({ className, ...props }: Base.GroupLabel.Props) {
  return (
    <Base.GroupLabel
      className={cn('px-2 py-1.5 text-2xs uppercase tracking-caption text-faint', className)}
      {...props}
    />
  )
}

import type { ReactNode } from 'react'
import { Combobox as Base } from '@base-ui/react/combobox'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { comboboxItemVariants } from './combobox'
import { Kbd } from './kbd'

/*
 * CommandPalette.
 *
 * One box that finds anything: the shortcut opens it, typing narrows a list,
 * Enter runs what is highlighted.
 *
 * It is a Combobox rather than a Dialog with a field in it, and that is Base
 * UI's own arrangement rather than a shortcut taken here: put the input
 * *inside* the popup and the popup becomes `role="dialog"` on its own, with
 * the input still announced as the combobox that owns the list. The filtering,
 * the highlight, the arrow keys and the type-ahead are the ones Combobox
 * already has - there is no second implementation of any of it.
 *
 * What is left for the product is everything that makes a palette that
 * product's: what the items are, how they are grouped, what running one does.
 * `items` is deliberately `unknown[]` - a palette lists commands, works,
 * settings and recent files in the same box, and a type that admitted only
 * strings would push every product into the same stringly-typed workaround.
 */

export const commandPalettePopupVariants = cva(
  [
    'flex w-[min(36rem,calc(100vw-2rem))] flex-col overflow-hidden',
    'rounded-xl border border-line bg-raise text-text shadow-float',
    'focus-visible:outline-none',
    '[transition:opacity_var(--duration-quick)_var(--ease-out),transform_var(--duration-quick)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        md: 'max-h-[24rem]',
        lg: 'max-h-[32rem]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled by `open`/`onOpenChange`, because what opens a palette
 * is a shortcut somewhere else in the application. */
export const CommandPalette = Base.Root

/** A row. The same clothes as a Combobox row, on purpose: a palette is a list
 * of choices, and two lists of choices in one product should not differ.
 *
 * They did differ, for as long as this was a bare re-export: the comment said
 * "the same clothes" and the component wore none, so the rows inherited the
 * popup's 16px and stood a third taller than every other list in the set. A
 * live run caught it - the palette looked like a different product. */
export function CommandPaletteItem({ className, ...props }: Base.Item.Props) {
  return <Base.Item className={cn(comboboxItemVariants(), className)} {...props} />
}

/** The list. Takes a render function over the filtered items. */
export function CommandPaletteList({ className, ...props }: Base.List.Props) {
  return <Base.List className={cn('overflow-y-auto p-1', className)} {...props} />
}

/** Shown when nothing matches. The words are the product's.
 *
 * Base UI keeps it mounted so the announcement fires, which means its padding
 * is spent whether or not it has anything to say - and a palette with six
 * results had a 48px hole under the field. It collapses when empty instead. */
export function CommandPaletteEmpty({ className, ...props }: Base.Empty.Props) {
  return (
    <Base.Empty
      className={cn('px-2 py-3 text-center text-sm text-faint empty:hidden empty:p-0', className)}
      {...props}
    />
  )
}

/** A labelled group, for a palette that lists more than one kind of thing. */
export const CommandPaletteGroup = Base.Group

/** The caption above a group. */
export const CommandPaletteGroupLabel = Base.GroupLabel

/** The rows of one group, as a render function over that group's items.
 *
 * A palette that lists works, versions and notes together is a `List` over the
 * groups with a `Collection` inside each. Mapping a group's rows by hand also
 * works, but then the palette has to be told how to match an item to a value -
 * and for rows fetched fresh from a server, identity comparison never does. */
export const CommandPaletteCollection = Base.Collection

export interface CommandPalettePopupProps
  extends Omit<Base.Popup.Props, 'aria-label'>,
    VariantProps<typeof commandPalettePopupVariants> {
  /**
   * What the palette is called, for a screen reader. Required, and required
   * for a reason particular to this component: the popup is a dialog, and a
   * dialog is named by its own visible title - which a palette does not have,
   * because the field is the first thing in it.
   *
   * So the name has to come from outside, it has to be the product's word, and
   * nothing else can supply it. A palette without one is announced as "dialog"
   * and nothing more; making the prop required is what stops that shipping.
   */
  'aria-label': string
  /** Where to portal to. Defaults to the document body. */
  container?: Base.Portal.Props['container']
}

/** The palette itself: a dim over the page, and the box in the upper third of
 * it - where the eye already is, rather than dead centre. */
export function CommandPalettePopup({
  size,
  container,
  className,
  children,
  ...props
}: CommandPalettePopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Backdrop
        className={cn(
          'fixed inset-0 bg-black/55 backdrop-blur-[2px]',
          '[z-index:var(--z-overlay)]',
          '[transition:opacity_var(--duration-quick)_var(--ease-out)]',
          'data-[closed]:opacity-0 data-[starting-style]:opacity-0',
        )}
      />
      <Base.Positioner
        className="[z-index:var(--z-palette)]"
        /* The anchor is a point at the top of the viewport, given explicitly.
         *
         * A positioner places a popup against an anchor and hides itself with
         * an inline `opacity: 0` until it has measured one. A palette has no
         * trigger to point at - it is opened by a keystroke - so without this
         * the measure never resolves: the popup sits in the DOM at the right
         * size, fully transparent, rendering nothing and reporting no error.
         * Found by reading the computed style off the positioner rather than
         * the popup, which was opaque the whole time.
         *
         * A zero-height rectangle a fifth of the way down puts the palette
         * where the eye already is rather than dead centre. */
        anchor={{
          getBoundingClientRect: () => {
            const width = typeof window === 'undefined' ? 0 : window.innerWidth
            const top = typeof window === 'undefined' ? 0 : window.innerHeight * 0.18
            return new DOMRect(width / 2, top, 0, 0)
          },
        }}
        positionMethod="fixed"
        side="bottom"
        align="center"
        sideOffset={0}
        alignOffset={0}
      >
        <Base.Popup
          className={cn(commandPalettePopupVariants({ size }), className)}
          {...props}
        >
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

export interface CommandPaletteInputProps extends Base.Input.Props {
  /** Shown at the right of the field, as `['Esc']`. Decorative. */
  hint?: string[]
}

/** The field. Sits inside the popup, which is what makes the popup a dialog
 * and the field its combobox. */
export function CommandPaletteInput({ hint, className, ...props }: CommandPaletteInputProps) {
  return (
    <div className="flex items-center gap-2 border-b border-line px-3">
      <MagnifierIcon />
      <Base.Input
        className={cn(
          'h-11 w-full bg-transparent text-sm text-text placeholder:text-faint',
          'focus-visible:outline-none',
          className,
        )}
        {...props}
      />
      {hint && <Kbd keys={hint} aria-hidden className="shrink-0" />}
    </div>
  )
}

/** The row's own layout: an icon, what it is, and where it lives. */
export function CommandPaletteRow({
  icon,
  hint,
  className,
  children,
  ...props
}: {
  icon?: ReactNode
  hint?: ReactNode
  className?: string
  children: ReactNode
} & Omit<React.HTMLAttributes<HTMLDivElement>, 'children'>) {
  return (
    <div className={cn('flex w-full items-center gap-2.5', className)} {...props}>
      {icon}
      <span className="min-w-0 flex-1 truncate">{children}</span>
      {hint !== undefined && <span className="shrink-0 text-2xs text-faint">{hint}</span>}
    </div>
  )
}

export { comboboxItemVariants as commandPaletteItemVariants }

function MagnifierIcon() {
  return (
    <svg
      viewBox="0 0 16 16"
      width="15"
      height="15"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.6"
      aria-hidden
      className="shrink-0 text-faint"
    >
      <circle cx="7" cy="7" r="4.5" />
      <path d="M10.5 10.5L14 14" strokeLinecap="round" />
    </svg>
  )
}

import { AlertDialog as Base } from '@base-ui/react/alert-dialog'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * ConfirmDialog.
 *
 * The dialog for a choice that cannot be taken back - deleting, discarding,
 * revoking. It looks almost exactly like Dialog, and that is deliberate: the
 * difference is not clothes, it is what the popup is allowed to do.
 *
 * A Dialog is dismissed by clicking away, because a Dialog is a place the user
 * wandered into. This one is not: Base UI's `AlertDialog` announces itself as
 * `role="alertdialog"`, which tells a screen reader the popup is interrupting
 * rather than presenting, and it forces `modal` and `disablePointerDismissal`
 * on - `AlertDialog.Root` omits both from Dialog's props, so there is nothing
 * to turn off. A press outside does nothing at all.
 *
 * `Escape` still closes it, and that is deliberate rather than an oversight: a
 * popup with no keyboard way out is a trap. The difference is between a
 * deliberate keypress and clicking absentmindedly beside a dialog.
 *
 * So the rule for choosing between the two is not how important the content
 * feels. It is whether dismissing it by a stray click would be a loss.
 */

export const confirmDialogPopupVariants = cva(
  [
    'fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2',
    'rounded-xl border border-line bg-raise p-5 text-text shadow-float',
    'focus-visible:outline-none',
    // The enter and the leave. `duration-*` reads the token directly because
    // Tailwind's own utility takes a literal number.
    '[transition:opacity_var(--duration-base)_var(--ease-out),transform_var(--duration-base)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        sm: 'w-[min(22rem,calc(100vw-2rem))]',
        md: 'w-[min(26rem,calc(100vw-2rem))]',
        lg: 'w-[min(34rem,calc(100vw-2rem))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `ConfirmDialogTrigger`. */
export const ConfirmDialog = Base.Root

/** What opens it. Give it `render` to use your own button. */
export const ConfirmDialogTrigger = Base.Trigger

/** What closes it - and the only thing that does, which is why a confirm
 * dialog with no `ConfirmDialogClose` inside it is a trap. */
export const ConfirmDialogClose = Base.Close

/** The scrim. Darker than the Dialog's, because what is behind it is not just
 * out of reach for a moment - it is waiting on an answer. */
export function ConfirmDialogBackdrop({ className, ...props }: Base.Backdrop.Props) {
  return (
    <Base.Backdrop
      className={cn(
        'fixed inset-0 bg-black/60 backdrop-blur-[2px]',
        '[z-index:var(--z-overlay)]',
        '[transition:opacity_var(--duration-base)_var(--ease-out)]',
        'data-[closed]:opacity-0 data-[starting-style]:opacity-0',
        className,
      )}
      {...props}
    />
  )
}

export interface ConfirmDialogPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof confirmDialogPopupVariants> {
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by an ancestor. Pass an element to put it
   * somewhere else - inside an overlay that is already open, or into a
   * container being screenshotted. */
  container?: Base.Portal.Props['container']
  /** Whether to draw the scrim. On by default, and it should stay on for
   * anything a person actually uses: the dim is what says the page behind is
   * out of reach. Turn it off where the popup is shown alongside other things
   * on purpose - a component gallery, a screenshot - because a scrim is
   * `position: fixed` and covers everything, not only its own container. */
  backdrop?: boolean
}

/** The dialog itself, announced as `alertdialog`. Portalled, so it is not
 * clipped by whatever it was opened from. */
export function ConfirmDialogPopup({
  size,
  container,
  backdrop = true,
  className,
  children,
  ...props
}: ConfirmDialogPopupProps) {
  return (
    <Base.Portal container={container}>
      {backdrop && <ConfirmDialogBackdrop />}
      <Base.Popup
        className={cn(
          confirmDialogPopupVariants({ size }),
          '[z-index:var(--z-modal)]',
          className,
        )}
        {...props}
      >
        {children}
      </Base.Popup>
    </Base.Portal>
  )
}

/** The question. Base UI points the popup's `aria-labelledby` at it, so this
 * is what a screen reader reads out when the dialog interrupts. */
export function ConfirmDialogTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-base font-semibold', className)} {...props} />
}

/** What the answer costs, and the popup's `aria-describedby`. On this dialog
 * it is close to required: the title asks, the description says what happens. */
export function ConfirmDialogDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-1 text-sm text-dim', className)} {...props} />
}

/** Where the two answers go. Right-aligned, because the choice belongs where
 * the eye leaves the sentence. */
export function ConfirmDialogActions({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mt-5 flex justify-end gap-2', className)} {...props} />
}

import { ContextMenu as Base } from '@base-ui/react/context-menu'
import { menuItemVariants, menuPopupVariants } from './menu'
import { cn } from 'dowel-ui'

/*
 * ContextMenu.
 *
 * The same list of actions as Menu, opened the other way round: by right
 * click, or by a long press on a touch screen, over an *area* rather than
 * from a button. So the trigger is not a control - it is the region the menu
 * belongs to, a row, a canvas, a file tile - and it renders a `<div>`.
 *
 * That difference is the whole component. Everything below the Root is Menu's
 * own: Base UI re-exports the Portal, Positioner, Popup, Item and the rest
 * from the menu package, so the popup that opens here is literally the same
 * popup, with the same keyboard, the same type-ahead and the same submenus.
 *
 * Which is why the clothes are imported rather than copied. Two `cva` calls
 * that started identical drift within a release - one gets a padding fix, the
 * other does not - and then a product has two menus that are almost the same,
 * which is worse than two that differ on purpose.
 *
 * What Base UI does *not* give this one is `openOnHover`, `modal` or a
 * `handle`: a context menu is opened by a gesture over an anchor point, not
 * by a trigger element it can be attached to from elsewhere.
 */

/** The root. It positions against the pointer, so there is nothing to anchor
 * and nothing to control but `onOpenChange`. */
export const ContextMenu = Base.Root

/** The area that opens it. A `<div>`, not a button: give it `render` to make
 * it the row or the canvas it belongs to rather than a wrapper. */
export const ContextMenuTrigger = Base.Trigger

/** A labelled group of items, for a menu long enough to need headings. */
export const ContextMenuGroup = Base.Group

/** A submenu, opened from a `ContextMenuSubTrigger` inside the parent. */
export const ContextMenuSub = Base.SubmenuRoot

export interface ContextMenuPopupProps extends Base.Popup.Props {
  /** How wide the popup starts. The same three as Menu's. */
  size?: 'sm' | 'md' | 'lg'
  /** Where to portal to. Defaults to the document body, which keeps the menu
   * from being clipped by the very row it was opened over. */
  container?: Base.Portal.Props['container']
}

/** The panel. Portalled, and positioned against the point that was clicked
 * rather than against an element. */
export function ContextMenuPopup({
  size,
  container,
  className,
  children,
  ...props
}: ContextMenuPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner className="[z-index:var(--z-menu)]">
        <Base.Popup className={cn(menuPopupVariants({ size }), className)} {...props}>
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

export interface ContextMenuItemProps extends Base.Item.Props {
  /** `danger` draws the destructive one apart, in the colour of something
   * that cannot be undone. */
  tone?: 'default' | 'danger'
}

/** An action. */
export function ContextMenuItem({ tone, className, ...props }: ContextMenuItemProps) {
  return <Base.Item className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** An item that opens a submenu. Drawn like any other, because it is one. */
export function ContextMenuSubTrigger({ tone, className, ...props }: ContextMenuItemProps) {
  return <Base.SubmenuTrigger className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** An item that carries a tick. The state is the caller's. */
export function ContextMenuCheckboxItem({ tone, className, ...props }: ContextMenuItemProps) {
  return <Base.CheckboxItem className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** The tick itself, drawn only when the item is checked. */
export const ContextMenuCheckboxIndicator = Base.CheckboxItemIndicator

/** A line between groups of items. Decorative, and marked as such. */
export function ContextMenuSeparator({ className, ...props }: Base.Separator.Props) {
  return <Base.Separator className={cn('-mx-1 my-1 h-px bg-line', className)} {...props} />
}

/** The caption above a group. */
export function ContextMenuGroupLabel({ className, ...props }: Base.GroupLabel.Props) {
  return (
    <Base.GroupLabel
      className={cn('px-2 py-1.5 text-2xs uppercase tracking-caption text-faint', className)}
      {...props}
    />
  )
}

import { useCallback, useEffect, useRef, useState, type ButtonHTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * The copy affordance in the corner of a block.
 *
 * Whatever a product shows in a panel - code, a payload, a log, one side of a
 * comparison - somebody eventually wants to take it away, and the button that
 * lets them is written again every time with the same three things missed.
 *
 *   **It confirms only after the clipboard does.** The write can be refused:
 *   it needs a secure context and, in some browsers, a permission. A tick
 *   drawn on click is a lie in exactly the case the reader most needs the
 *   truth.
 *
 *   **It says so as well as showing it.** A tick that appears silently tells a
 *   sighted reader it worked and tells nobody else. The live region is the
 *   part that actually reports.
 *
 *   **It stays reachable without a pointer.** Revealed on hover, which is
 *   right - a permanent button in the corner of every block is clutter - and
 *   on its own that makes it unreachable by keyboard. It is visible whenever
 *   it has focus too, and that pairing is the whole trick.
 *
 * Copyable is the other shape of this, and the two are not interchangeable:
 * that one is a value sitting in a sentence - inline, truncating, showing the
 * text it copies - and this one is a control beside content already on screen,
 * so it carries an icon and no words.
 */

export interface CopyButtonProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'onCopy'> {
  /** What lands on the clipboard. */
  value: string
  /** What the button is called, for a screen reader. Required, and
   * deliberately without a default: a string this component invents is a
   * string the product cannot translate, and it would ship in English to
   * every reader who does not read English. */
  label: string
  /** What is announced after a successful copy. Required for the same
   * reason. */
  copiedLabel: string
  /** Told what happened, for a product that wants its own toast. `false` means
   * the clipboard refused. */
  onCopy?: (ok: boolean) => void
}

export function CopyButton({
  value,
  label,
  copiedLabel,
  onCopy,
  className,
  ...props
}: CopyButtonProps) {
  const [copied, setCopied] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)

  // A component that sets state on a timer has to stop when it goes away, or
  // it wakes up in a tree that no longer exists.
  useEffect(() => () => clearTimeout(timer.current), [])

  const copy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(value)
      setCopied(true)
      onCopy?.(true)
      clearTimeout(timer.current)
      timer.current = setTimeout(() => setCopied(false), 1600)
    } catch {
      onCopy?.(false)
    }
  }, [value, onCopy])

  return (
    <>
      <button
        type="button"
        onClick={copy}
        aria-label={copied ? copiedLabel : label}
        className={cn(
          'shrink-0 rounded-sm p-1 text-faint transition-colors target-min',
          'hover:bg-soft hover:text-text',
          /* `group-hover` rather than a hover of its own: the button is in the
           * corner of a block, and it has to appear when the pointer is
           * anywhere over that block rather than only once it has found the
           * button. The container carries `group`. */
          'opacity-0 group-hover:opacity-100 focus-visible:opacity-100',
          'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
          copied && 'text-good opacity-100',
          className,
        )}
        {...props}
      >
        {copied ? <Tick /> : <Clipboard />}
      </button>

      {/* The drawn tick is invisible to a screen reader; this is the part that
        * reports the copy. Outside the button, because its content changes and
        * a live region inside a labelled control is announced twice. */}
      <span role="status" aria-live="polite" className="sr-only">
        {copied ? copiedLabel : ''}
      </span>
    </>
  )
}

function Clipboard() {
  return (
    <svg viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="1.4" aria-hidden>
      <rect x="5.5" y="2.5" width="8" height="10" rx="1.5" />
      <path d="M10.5 2.5v-.5a1 1 0 0 0-1-1h-6a1 1 0 0 0-1 1v8a1 1 0 0 0 1 1h.5" />
    </svg>
  )
}

function Tick() {
  return (
    <svg viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
      <path d="M3 8.5l3.5 3.5L13 5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

import { useCallback, useEffect, useRef, useState, type HTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * Copyable.
 *
 * Any text that someone will eventually want to copy - an id, a path, a hash,
 * a token - copied with one click. The rule comes from nitid: if a value is
 * worth showing, it is worth being able to take away, and selecting a
 * monospaced id by hand is a small daily tax.
 *
 * Two things this gets right that the hand-written version usually does not.
 * It is a `<button>`, so the keyboard can reach it and a screen reader says
 * what it does. And the confirmation is announced, not only drawn: a tick that
 * appears silently tells a sighted user it worked and tells nobody else.
 *
 * The clipboard can refuse - it needs a secure context and, in some browsers,
 * a permission. A refusal is reported rather than swallowed, because a button
 * that looks like it worked and did not is worse than one that says it failed.
 */
export interface CopyableProps extends Omit<HTMLAttributes<HTMLButtonElement>, 'onCopy'> {
  /** What lands on the clipboard. Defaults to the visible text. */
  value?: string
  /** The visible text. */
  children: string
  /** What the button is called, for a screen reader. Required, and
   * deliberately without a default: a string the component invents is a
   * string the product cannot translate, and it would ship in English to
   * every reader who does not read English. */
  label: string
  /** What is announced after a successful copy. Required for the same
   * reason. */
  copiedLabel: string
  /** Told what happened, for a product that wants its own toast. */
  onCopy?: (ok: boolean) => void
}

export function Copyable({
  value,
  children,
  label,
  copiedLabel,
  onCopy,
  className,
  ...props
}: CopyableProps) {
  const [copied, setCopied] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)

  // A component that sets state on a timer has to stop when it goes away, or
  // it wakes up in a tree that no longer exists.
  useEffect(() => () => clearTimeout(timer.current), [])

  const copy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(value ?? children)
      setCopied(true)
      onCopy?.(true)
      clearTimeout(timer.current)
      timer.current = setTimeout(() => setCopied(false), 1600)
    } catch {
      // No secure context, or permission refused. Say so rather than pretend.
      onCopy?.(false)
    }
  }, [value, children, onCopy])

  return (
    <button
      type="button"
      onClick={copy}
      aria-label={copied ? copiedLabel : label}
      className={cn(
        'group inline-flex max-w-full items-center gap-1.5 rounded-sm px-1 py-0.5 text-left target-min',
        'font-mono text-xs text-dim transition-colors',
        'hover:bg-soft hover:text-text',
        'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
        className,
      )}
      {...props}
    >
      <span className="truncate">{children}</span>

      <span className={cn('shrink-0 transition-colors', copied ? 'text-good' : 'text-faint')} aria-hidden>
        {copied ? <Tick /> : <Clipboard />}
      </span>

      {/* Drawn confirmation is invisible to a screen reader; this is the part
          that actually says it worked. */}
      <span role="status" aria-live="polite" className="sr-only">
        {copied ? copiedLabel : ''}
      </span>
    </button>
  )
}

function Clipboard() {
  return (
    <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="1.4" aria-hidden>
      <rect x="5.5" y="2.5" width="8" height="10" rx="1.5" />
      <path d="M10.5 2.5v-.5a1 1 0 0 0-1-1h-6a1 1 0 0 0-1 1v8a1 1 0 0 0 1 1h.5" />
    </svg>
  )
}

function Tick() {
  return (
    <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
      <path d="M3 8.5l3.5 3.5L13 5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

import { useMemo, useState } from 'react'
import { cn, useLocale } from 'dowel-ui'
import { fieldClasses } from './input'
import { Popover, PopoverPopup, PopoverTrigger } from './popover'
import { Calendar } from './calendar'
import { isIsoDate, type IsoDate } from './calendar-math'

/*
 * DatePicker - a field that opens a month.
 *
 * The trigger is a button rather than a text input, and that is the decision
 * worth stating. A typable date field has to answer "what does `03/04/26`
 * mean" in a locale it cannot be sure of, and it answers wrong for half the
 * world; a button showing the date spelled out has no such question. Where
 * typing genuinely matters - a birth date, forty years back - the calendar is
 * the wrong control anyway and a product should reach for a plain field.
 *
 * The value is a calendar date as a string, `YYYY-MM-DD`, for the reasons the
 * Calendar states: a date with a timezone is a moment, and moments cross
 * midnight when they are serialised.
 *
 * What is shown is `Intl`'s own long form - "2 September 2026" here, "September
 * 2, 2026" in the United States - because a date written the reader's way is
 * one they do not have to decode.
 */

export interface DatePickerProps {
  /** The chosen day, or `undefined` for none. */
  value?: IsoDate
  onValueChange?: (value: IsoDate) => void
  /** Bounds, inclusive. */
  min?: IsoDate
  max?: IsoDate
  /** What the trigger says when nothing is chosen. The product's word, since
   * a default here would be English inside a primitive. */
  placeholder: string
  /** Names the two month-paging buttons inside the calendar. */
  previousMonthLabel: string
  nextMonthLabel: string
  /** How the date is written and which day starts the week. The
   * application's language unless stated - see `useLocale`. */
  locale?: string
  disabled?: boolean
  name?: string
  'aria-label'?: string
  className?: string
}

export function DatePicker({
  value,
  onValueChange,
  min,
  max,
  placeholder,
  previousMonthLabel,
  nextMonthLabel,
  locale,
  disabled = false,
  name,
  className,
  'aria-label': ariaLabel,
}: DatePickerProps) {
  const [open, setOpen] = useState(false)
  const language = useLocale(locale)

  const shown = useMemo(() => {
    if (value === undefined || !isIsoDate(value)) return undefined
    const [year, month, day] = value.split('-').map(Number) as [number, number, number]
    return new Intl.DateTimeFormat(language, { dateStyle: 'long' }).format(
      new Date(year, month - 1, day),
    )
  }, [value, language])

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        disabled={disabled}
        aria-label={ariaLabel}
        className={cn(
          fieldClasses,
          'flex h-control cursor-pointer items-center gap-2 text-left',
          'disabled:cursor-not-allowed',
          className,
        )}
      >
        <svg viewBox="0 0 16 16" className="size-4 shrink-0 text-faint" fill="none" aria-hidden>
          <rect x="2" y="3" width="12" height="11" rx="2" stroke="currentColor" strokeWidth="1.3" />
          <path d="M2 6.5h12M5.5 2v2M10.5 2v2" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
        </svg>
        <span className={cn('truncate', shown === undefined && 'text-faint')}>
          {shown ?? placeholder}
        </span>
      </PopoverTrigger>

      {/* The value also goes into a form, because a button is not a field and
        * a form submitting the screen would otherwise lose the date. */}
      {name !== undefined && <input type="hidden" name={name} value={value ?? ''} />}

      <PopoverPopup arrow={false} className="w-auto p-3">
        <Calendar
          value={value}
          min={min}
          max={max}
          locale={language}
          aria-label={ariaLabel ?? placeholder}
          previousMonthLabel={previousMonthLabel}
          nextMonthLabel={nextMonthLabel}
          onValueChange={(next) => {
            onValueChange?.(next)
            // Choosing a day is the whole errand: the popup closes rather
            // than waiting for a second dismissing click.
            setOpen(false)
          }}
        />
      </PopoverPopup>
    </Popover>
  )
}

import { useMemo, useState } from 'react'
import { cn, useLocale } from 'dowel-ui'
import { fieldClasses } from './input'
import { Popover, PopoverPopup, PopoverTrigger } from './popover'
import { Calendar } from './calendar'
import { isIsoDate, type IsoDate } from './calendar-math'

/*
 * DateRangePicker - two days, chosen in two clicks.
 *
 * The interesting part is the state between them. After the first click there
 * is a start and no end, and that is not an incomplete range to be hidden or
 * a range of one day - it is the normal middle of the interaction, and the
 * calendar has to show it: the first day marked, the days under the pointer
 * shading as the reader moves, the popup staying open. Products that skip it
 * end up with a picker that seems to do nothing until the second click.
 *
 * So the value is a pair where either end may be absent, and the component is
 * explicit about which half it is waiting for. `onValueChange` fires on both
 * clicks - a product watching it sees the half-made range, which is what lets
 * it show "from 2 September" while the reader is still deciding.
 *
 * The second click can land before the first. Clicking the 20th and then the
 * 10th means the 10th to the 20th, because that is plainly what was meant;
 * refusing it would be correct and unhelpful.
 */

export interface DateRange {
  /** The first day, inclusive. */
  start?: IsoDate
  /** The last day, inclusive. Absent while the range is half made. */
  end?: IsoDate
}

export interface DateRangePickerProps {
  value?: DateRange
  onValueChange?: (value: DateRange) => void
  min?: IsoDate
  max?: IsoDate
  /** What the trigger says when nothing is chosen. */
  placeholder: string
  /** Names the two month-paging buttons inside the calendar. */
  previousMonthLabel: string
  nextMonthLabel: string
  locale?: string
  disabled?: boolean
  'aria-label'?: string
  className?: string
}

export function DateRangePicker({
  value,
  onValueChange,
  min,
  max,
  placeholder,
  previousMonthLabel,
  nextMonthLabel,
  locale,
  disabled = false,
  className,
  'aria-label': ariaLabel,
}: DateRangePickerProps) {
  const [open, setOpen] = useState(false)
  const language = useLocale(locale)

  const range = value ?? {}
  const waitingForEnd = range.start !== undefined && range.end === undefined

  const shown = useMemo(() => {
    const write = (date: IsoDate) => {
      const [year, month, day] = date.split('-').map(Number) as [number, number, number]
      return new Intl.DateTimeFormat(language, { dateStyle: 'medium' }).format(
        new Date(year, month - 1, day),
      )
    }
    if (range.start === undefined || !isIsoDate(range.start)) return undefined
    if (range.end === undefined) return write(range.start)
    // An en dash rather than a hyphen: this is a span, and the two read
    // differently at a glance in a row of dates.
    return `${write(range.start)} – ${write(range.end)}`
  }, [range.start, range.end, language])

  const choose = (date: IsoDate) => {
    // A fresh click starts a new range whenever there is nothing waiting -
    // including right after a completed one, which is what a reader means by
    // clicking again.
    if (!waitingForEnd) {
      onValueChange?.({ start: date })
      return
    }

    const start = range.start!
    // Backwards is fine: the reader plainly meant the span between them.
    const next: DateRange = date < start ? { start: date, end: start } : { start, end: date }
    onValueChange?.(next)
    setOpen(false)
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        disabled={disabled}
        aria-label={ariaLabel}
        className={cn(
          fieldClasses,
          'flex h-control cursor-pointer items-center gap-2 text-left',
          'disabled:cursor-not-allowed',
          className,
        )}
      >
        <svg viewBox="0 0 16 16" className="size-4 shrink-0 text-faint" fill="none" aria-hidden>
          <rect x="2" y="3" width="12" height="11" rx="2" stroke="currentColor" strokeWidth="1.3" />
          <path d="M2 6.5h12M5.5 2v2M10.5 2v2" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
        </svg>
        <span className={cn('truncate', shown === undefined && 'text-faint')}>
          {shown ?? placeholder}
        </span>
      </PopoverTrigger>

      <PopoverPopup arrow={false} className="w-auto p-3">
        <Calendar
          value={range.start}
          rangeEnd={range.end}
          min={min}
          max={max}
          locale={language}
          aria-label={ariaLabel ?? placeholder}
          previousMonthLabel={previousMonthLabel}
          nextMonthLabel={nextMonthLabel}
          onValueChange={choose}
        />
      </PopoverPopup>
    </Popover>
  )
}

import { Dialog as Base } from '@base-ui/react/dialog'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Dialog.
 *
 * The parts are exposed rather than wrapped in one component with `title` and
 * `footer` props. The products that did it the other way ended up passing
 * `footer={<>…</>}` within a week, which is a slot with extra steps - and a
 * dialog that owns its own close button owns a word for it, which is a word
 * the product cannot translate.
 *
 * Behaviour is Base UI's: the focus trap, the return of focus to whatever
 * opened it, `Escape`, the scroll lock, and the `aria-labelledby` that ties
 * the popup to its own title. None of that is worth rewriting, and all of it
 * is wrong in the ways nobody notices until someone is navigating by keyboard.
 *
 * What is ours is the clothes, and the enter and leave: the popup arrives with
 * `data-open` and leaves with `data-closed`, both of which Base UI sets, so
 * the animation is a class list rather than a state machine.
 */

export const dialogPopupVariants = cva(
  [
    'fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2',
    'rounded-xl border border-line bg-raise p-5 text-text shadow-float',
    'focus-visible:outline-none',
    // The width was capped from the start and the height was not, so a dialog
    // with more in it than the window is tall centred itself and hung off both
    // ends - the top out of reach above the viewport, the buttons below it.
    // Found on a release editor in kilna, which is exactly the shape that does
    // it: half a dozen fields and a row of actions.
    'max-h-[calc(100dvh-2rem)] overflow-y-auto overscroll-contain',
    // The enter and the leave. `duration-*` reads the token directly because
    // Tailwind's own utility takes a literal number.
    '[transition:opacity_var(--duration-base)_var(--ease-out),transform_var(--duration-base)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        sm: 'w-[min(24rem,calc(100vw-2rem))]',
        md: 'w-[min(28rem,calc(100vw-2rem))]',
        lg: 'w-[min(40rem,calc(100vw-2rem))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `Dialog.Trigger`. */
export const Dialog = Base.Root

/** What opens it. Give it `render` to use your own button. */
export const DialogTrigger = Base.Trigger

/** What closes it - the same, for a cancel button or an X. */
export const DialogClose = Base.Close

/** The scrim. Dark because a modal is a modal: what is behind it is out of
 * reach, and saying so with contrast is the only thing that reads at a
 * glance. */
export function DialogBackdrop({ className, ...props }: Base.Backdrop.Props) {
  return (
    <Base.Backdrop
      className={cn(
        'fixed inset-0 bg-black/50 backdrop-blur-[2px]',
        '[z-index:var(--z-overlay)]',
        '[transition:opacity_var(--duration-base)_var(--ease-out)]',
        'data-[closed]:opacity-0 data-[starting-style]:opacity-0',
        className,
      )}
      {...props}
    />
  )
}

export interface DialogPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof dialogPopupVariants> {
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by whatever it was opened from. Pass an
   * element to put it somewhere else - inside a dialog that is already open,
   * or into a container being screenshotted. */
  container?: Base.Portal.Props['container']
  /** Whether to draw the scrim. On by default, and it should stay on for
   * anything a person actually uses: the dim is what says the page behind is
   * out of reach. Turn it off where the popup is shown alongside other things
   * on purpose - a component gallery, a screenshot - because a scrim is
   * `position: fixed` and covers everything, not only its own container. */
  backdrop?: boolean
}

/** The dialog itself. Portalled, so it is not clipped by whatever it was
 * opened from. */
export function DialogPopup({
  size,
  container,
  backdrop = true,
  className,
  children,
  ...props
}: DialogPopupProps) {
  return (
    <Base.Portal container={container}>
      {backdrop && <DialogBackdrop />}
      <Base.Popup
        className={cn(dialogPopupVariants({ size }), '[z-index:var(--z-modal)]', className)}
        {...props}
      >
        {children}
      </Base.Popup>
    </Base.Portal>
  )
}

/** The heading. Base UI points the popup's `aria-labelledby` at it, so a
 * dialog with one is named for a screen reader without anyone arranging it. */
export function DialogTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-base font-semibold', className)} {...props} />
}

/** The line under the heading, and the popup's `aria-describedby`. */
export function DialogDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-1 text-sm text-dim', className)} {...props} />
}

/** Where the actions go. Right-aligned, because the primary action of a
 * dialog belongs where the eye leaves the sentence. */
export function DialogActions({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mt-5 flex justify-end gap-2', className)} {...props} />
}

/*
 * The comparison behind DiffView, with no React in it.
 *
 * Split out like `line-scale` and `table-sort`: a product that wants to know
 * how much moved between two drafts - to put a number in a list, to decide
 * whether to offer the comparison at all - should not have to render a
 * component to find out.
 *
 * Lines rather than words, and that is a choice about the subject. The text
 * being compared here is prose someone wrote and revised - a draft, a note, a
 * configuration file - and prose is revised BY THE LINE. A word-level diff of
 * a rewritten paragraph is confetti: technically accurate, and it answers a
 * question nobody asked. Where the subject really is word-level - a title, a
 * single sentence - a product compares the two strings itself.
 *
 * Plain longest-common-subsequence. The bodies are a page or two, so the exact
 * O(n·m) answer costs nothing and there is no reason to reach for a heuristic.
 *
 * Taken from kilna, which had it first, with the arithmetic unchanged and the
 * pairing added: `rows` is the part the donor did not have, and its absence is
 * what made the donor's two columns drift out of step.
 */

/** One step through the comparison. */
export type Change =
  | { kind: 'same'; text: string }
  | { kind: 'added'; text: string }
  | { kind: 'removed'; text: string }

/**
 * One row of a side-by-side comparison: what stands on each side of it.
 *
 * `null` is a side with nothing there - the gap opposite an inserted line -
 * and it is deliberately not an empty string. An empty string is a line
 * somebody wrote that happens to have no characters on it, and a comparison
 * that cannot tell those apart draws a blank line as a deletion.
 */
export interface DiffRow {
  before: string | null
  after: string | null
  kind: Change['kind']
  /** Line numbers in each text, 1-based, for a gutter. `null` on the side that
   * has nothing. */
  beforeLine: number | null
  afterLine: number | null
}

/** How many lines each side may have before the comparison gives up. A table
 * of 2000×2000 is four million cells; past that the honest answer is "too long
 * to compare", not a frozen window. */
export const LIMIT = 2000

export function diffLines(before: string, after: string): Change[] {
  const a = before.split('\n')
  const b = after.split('\n')

  if (a.length > LIMIT || b.length > LIMIT) {
    return [
      { kind: 'removed', text: before },
      { kind: 'added', text: after },
    ]
  }

  // lcs[i][j] - the length of the longest common subsequence of a[i..] and
  // b[j..]. Filled backwards so the walk forwards can be greedy.
  const lcs: number[][] = Array.from({ length: a.length + 1 }, () =>
    Array.from({ length: b.length + 1 }, () => 0),
  )

  for (let i = a.length - 1; i >= 0; i -= 1) {
    for (let j = b.length - 1; j >= 0; j -= 1) {
      lcs[i]![j] = a[i] === b[j] ? lcs[i + 1]![j + 1]! + 1 : Math.max(lcs[i + 1]![j]!, lcs[i]![j + 1]!)
    }
  }

  const changes: Change[] = []
  let i = 0
  let j = 0

  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      changes.push({ kind: 'same', text: a[i]! })
      i += 1
      j += 1
    } else if (lcs[i + 1]![j]! >= lcs[i]![j + 1]!) {
      changes.push({ kind: 'removed', text: a[i]! })
      i += 1
    } else {
      changes.push({ kind: 'added', text: b[j]! })
      j += 1
    }
  }

  while (i < a.length) {
    changes.push({ kind: 'removed', text: a[i]! })
    i += 1
  }
  while (j < b.length) {
    changes.push({ kind: 'added', text: b[j]! })
    j += 1
  }

  return changes
}

/**
 * The changes as rows of two columns - the thing that makes side-by-side mean
 * anything.
 *
 * The obvious way to draw two columns is to filter the change list twice: keep
 * everything that is not `added` on the left, everything that is not `removed`
 * on the right. Both columns come out individually correct and they stop
 * lining up at the first insertion, because from there on they hold different
 * numbers of rows. The reader then compares line 4 against line 3 for the rest
 * of the screen, and nothing about the drawing looks wrong - which is why the
 * defect survived in the product this was taken from.
 *
 * Pairing instead makes the alignment structural: a row is one object with two
 * sides, so the columns are the same height by construction rather than by two
 * filters happening to agree.
 *
 * A removal immediately followed by an insertion is paired into ONE row rather
 * than two. That is the common shape of an edit - a line was rewritten - and
 * showing the old and the new opposite each other is the whole point of the
 * comparison. Left as separate rows, a rewritten line reads as a deletion
 * followed by an unrelated addition, with a gap opposite each.
 */
export function rows(changes: readonly Change[]): DiffRow[] {
  const out: DiffRow[] = []
  let beforeLine = 1
  let afterLine = 1

  for (let at = 0; at < changes.length; at += 1) {
    const change = changes[at]!

    if (change.kind === 'same') {
      out.push({
        before: change.text,
        after: change.text,
        kind: 'same',
        beforeLine: beforeLine++,
        afterLine: afterLine++,
      })
      continue
    }

    if (change.kind === 'removed') {
      // A removal with an insertion right behind it is a rewrite: pair them,
      // so the reader sees what the line became rather than two separate
      // events with a gap opposite each.
      const next = changes[at + 1]
      if (next?.kind === 'added') {
        out.push({
          before: change.text,
          after: next.text,
          kind: 'removed',
          beforeLine: beforeLine++,
          afterLine: afterLine++,
        })
        at += 1
        continue
      }
      out.push({
        before: change.text,
        after: null,
        kind: 'removed',
        beforeLine: beforeLine++,
        afterLine: null,
      })
      continue
    }

    out.push({
      before: null,
      after: change.text,
      kind: 'added',
      beforeLine: null,
      afterLine: afterLine++,
    })
  }

  return out
}

/** How much moved, for the one line above a comparison - or for a list that
 * wants to say "12 lines changed" without drawing anything. */
export function countChanges(changes: readonly Change[]): { added: number; removed: number } {
  let added = 0
  let removed = 0
  for (const change of changes) {
    if (change.kind === 'added') added += 1
    else if (change.kind === 'removed') removed += 1
  }
  return { added, removed }
}

import { useMemo, type HTMLAttributes, type ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { CopyButton } from './copy-button'
import { countChanges, diffLines, rows, type DiffRow } from './diff-lines'

/*
 * Two drafts of the same text, with what moved between them shown.
 *
 * The question this answers is "how did this read before, and how does it read
 * now" - a version against the one before it, a proposal against what is
 * there, a file against what is on disk. Not a code review: there is no
 * staging, no comment, nothing to accept. It is for looking.
 *
 * SIDE BY SIDE, AND THE ALIGNMENT IS THE WHOLE THING. The obvious way to draw
 * two columns is to filter the change list twice - keep what is not `added` on
 * the left, what is not `removed` on the right - and it is what the product
 * this came from did. Both columns come out individually correct, and they
 * stop lining up at the first insertion: from there the reader is comparing
 * line 4 against line 3, with nothing looking wrong. `rows` in `diff-lines`
 * pairs the changes instead, so the two sides are one list and cannot drift.
 *
 * The alignment has a second half, in the drawing rather than the data: ONE
 * scrolling region holds both columns, and a row is a single grid row spanning
 * them. Two scrollers - the shape this was first written with - come apart the
 * moment a reader touches one of them, which undoes the pairing at the point
 * it matters most. It also means a row is as tall as its taller side, so a
 * wrapped line on the left keeps its partner beside it instead of pushing the
 * two texts out of step.
 *
 * Below a certain width the pair stacks - the "after" line under the "before"
 * one - because two columns each too narrow to hold a line of text answer
 * nothing: every line wraps into three and the comparison is worse than one
 * column would have been. The breakpoint is on the component rather than the
 * viewport (`@container`), since a diff in a side panel is narrow on a wide
 * screen.
 *
 * STACKS, not hides. This drew `hidden @3xl:flex` on the after side for a
 * while, under a comment that said "stacked" - so a narrow reader saw a line
 * marked `~` as rewritten and nothing to compare it with, on a screen that
 * looked finished. Every test passed: they count cells in the DOM, and jsdom
 * does not resolve a container query. Half a comparison is worse than none.
 *
 * Colour is never the message. A changed line carries a marker glyph in the
 * gutter - `+`, `-`, `~` - so the comparison reads without hue, in a
 * screenshot, and for the eighth of men who would otherwise see two tinted
 * greys.
 */

export const diffViewVariants = cva('@container flex flex-col gap-2 text-sm', {
  variants: {
    size: {
      sm: '[--diff-max:16rem]',
      md: '[--diff-max:28rem]',
      /** No ceiling: the comparison is as tall as it is, and the page scrolls.
       * For a diff that IS the screen rather than sitting on one. */
      full: '[--diff-max:none]',
    },
  },
  defaultVariants: { size: 'md' },
})

export interface DiffViewProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'onCopy'>,
    VariantProps<typeof diffViewVariants> {
  before: string
  after: string
  /** What each side is called - a version name, a date, "on disk". */
  beforeLabel: string
  afterLabel: string
  /** The line above the comparison: how much moved. The component counts, the
   * product says it in words - a count is a plural, and a plural belongs to a
   * language the component does not know. Given the two numbers, and left out
   * entirely when there is nothing to say. */
  summary?: (counts: { added: number; removed: number }) => ReactNode
  /** Numbers down each side. On by default: a comparison is usually read in
   * order to go and change something, and the number is how the reader finds
   * the place. */
  numbered?: boolean
  /**
   * Brings a copy button to each side's header, and names it.
   *
   * A function of the side's label rather than a string, because the two
   * buttons need distinguishable names - "Copy" twice on one screen tells a
   * reader using them which is which only by where they are, which is what a
   * label exists to avoid. Sticking the two together here (`${copy}: ${side}`)
   * would invent a phrase in a grammar this component does not know.
   */
  copyLabel?: (side: string) => string
  /** Announced after a successful copy. Required alongside `copyLabel`. */
  copiedLabel?: string
  /** Told what happened, for a product that wants its own toast. */
  onCopy?: (ok: boolean) => void
}

export function DiffView({
  before,
  after,
  beforeLabel,
  afterLabel,
  summary,
  numbered = true,
  copyLabel,
  copiedLabel = '',
  onCopy,
  size,
  className,
  ...props
}: DiffViewProps) {
  const changes = useMemo(() => diffLines(before, after), [before, after])
  const paired = useMemo(() => rows(changes), [changes])
  const counts = useMemo(() => countChanges(changes), [changes])

  /* Wide enough for the largest number either side will show. Sized from the
   * row count rather than from each column's own last number, so the two
   * gutters are the same width and the texts start at the same offset. */
  const width = String(paired.length).length

  return (
    <div className={cn(diffViewVariants({ size }), className)} {...props}>
      {summary !== undefined && <p className="text-xs text-dim">{summary(counts)}</p>}

      <div className="overflow-hidden rounded-lg border border-line">
        {/*
         * The headers sit outside the scroller, in the same two tracks, so
         * they stay put while the text moves under them.
         *
         * In one column they sit side by side instead of stacking, with an
         * arrow between them: stacked, they would be two labels separated by
         * the whole of the left-hand text, which labels nothing. Both are
         * always drawn - a comparison that names one of its two sides is one
         * the reader has to guess at.
         */}
        <div className="group flex items-center gap-2 border-b border-line bg-softer px-3 py-1 text-2xs font-medium text-dim @3xl:grid @3xl:grid-cols-2 @3xl:gap-0 @3xl:px-0 @3xl:py-0">
          <span className="flex min-w-0 items-center gap-2 @3xl:grow @3xl:px-3 @3xl:py-1">
            <span className="truncate @3xl:grow">{beforeLabel}</span>
            {copyLabel !== undefined && (
              <CopyButton
                value={before}
                label={copyLabel(beforeLabel)}
                copiedLabel={copiedLabel}
                onCopy={onCopy}
              />
            )}
          </span>
          {/* Only while the two labels share a line. In two columns the tracks
            * say which is which. */}
          <span className="shrink-0 text-faint @3xl:hidden" aria-hidden>
            {'\u2192'}
          </span>
          <span className="flex min-w-0 items-center gap-2 @3xl:border-l @3xl:border-line @3xl:px-3 @3xl:py-1">
            <span className="truncate @3xl:grow">{afterLabel}</span>
            {copyLabel !== undefined && (
              <CopyButton
                value={after}
                label={copyLabel(afterLabel)}
                copiedLabel={copiedLabel}
                onCopy={onCopy}
              />
            )}
          </span>
        </div>

        <div
          /* The one scrolling region. Focusable because it scrolls: a region a
           * pointer can reach and a keyboard cannot is the usual way a long
           * diff hides its end. */
          tabIndex={0}
          className={cn(
            'max-h-[var(--diff-max)] overflow-auto py-1 font-mono text-xs leading-relaxed',
            // A desktop shell turns selection off; a comparison is read in
            // order to copy something out of it.
            'select-text',
            'focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent',
          )}
        >
          <div className="grid grid-cols-1 @3xl:grid-cols-2">
            {paired.map((row, index) => (
              // Lines repeat and reorder, so the text is not an identity; the
              // list is rebuilt whole whenever either side changes.
              <Row key={index} row={row} numbered={numbered} width={width} />
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}

/* The glyph in the gutter, per side. A deletion is only a deletion on the left
 * - on the right that same row is a gap - so the marker depends on which
 * column is being drawn, not on the change alone. `~` for a rewritten line,
 * which is one event with a side each. */
export function marker(row: DiffRow, side: 'before' | 'after'): string {
  const text = side === 'before' ? row.before : row.after
  if (row.kind === 'same' || text === null) return ' '
  if (row.kind === 'removed' && row.after !== null) return '~'
  return side === 'before' ? '-' : '+'
}

/*
 * One row, as its two cells.
 *
 * They are siblings in the grid rather than a wrapper holding both, because a
 * wrapper would become the grid item and the columns would stop being columns.
 * `display: contents` would do it too and is worse: it removes the element
 * from the accessibility tree in several browsers, taking any grouping with
 * it.
 */
function Row({ row, numbered, width }: { row: DiffRow; numbered: boolean; width: number }) {
  return (
    <>
      <Side row={row} side="before" numbered={numbered} width={width} />
      <Side row={row} side="after" numbered={numbered} width={width} />
    </>
  )
}

function Side({
  row,
  side,
  numbered,
  width,
}: {
  row: DiffRow
  side: 'before' | 'after'
  numbered: boolean
  width: number
}) {
  const text = side === 'before' ? row.before : row.after
  const line = side === 'before' ? row.beforeLine : row.afterLine
  const changed = row.kind !== 'same' && text !== null

  return (
    <div
      className={cn(
        'flex px-2',
        // The rule between the columns belongs to the right-hand cells, so it
        // runs the full height of the text rather than stopping at the last
        // row of a short column. Gone while stacked, where there is no second
        // column for it to divide.
        /*
         * On the right in two columns; UNDER its partner in one.
         *
         * Never hidden, and that is the whole note. This read `hidden
         * @3xl:flex` for a while, under a comment saying the comparison
         * "stacks" - it did not stack, it dropped the after side entirely, so
         * a narrow reader saw a line marked `~` and nothing to compare it
         * with. A screen that looks finished and withholds half the answer is
         * worse than one that admits it has no room.
         *
         * Stacking needs no rule of its own: the cells are already siblings of
         * a grid that is one column until `@3xl`, so they fall under each
         * other by themselves. What the narrow layout does need is the rule
         * BETWEEN the pair, which is a top border there and a left border in
         * two columns.
         */
        side === 'after' && 'border-t border-line @3xl:border-t-0 @3xl:border-l',
        changed && (side === 'before' ? 'bg-bad-soft text-bad' : 'bg-good-soft text-good'),
      )}
    >
      {numbered && (
        // Never part of a selection: a reader copying a column wants the text,
        // not the text with a number welded to the front of every line.
        <span
          className="mr-2 shrink-0 select-none text-right tabular-nums text-faint"
          style={{ width: `${width}ch` }}
          aria-hidden
        >
          {line ?? ''}
        </span>
      )}

      {/* The second channel, so the comparison reads without colour.
        * `aria-hidden` because a screen reader is told what changed by the
        * text itself; a spoken "minus" before every removed line is noise. */}
      <span className="mr-1.5 shrink-0 select-none" aria-hidden>
        {marker(row, side)}
      </span>

      <span className="min-w-0 whitespace-pre-wrap break-words">
        {/* A blank line still needs its height, or a gap opposite an insertion
          * collapses and the two columns come out of step by exactly the thing
          * the pairing prevented. */}
        {text === null || text === '' ? ' ' : text}
      </span>
    </div>
  )
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Divider.
 *
 * The line between one part of a screen and the next. The set already had
 * four of them - in the menu, the select, the context menu and the action bar
 * - and each was written inside the thing it divided, so a screen that wanted
 * a rule between two sections had nothing and reached for a bare `<hr>` or a
 * `div` with a background.
 *
 * Those two are not the same as this one, and the difference is the reason
 * this component is not a `<div className="h-px bg-line" />`. A rule between
 * sections is a semantic boundary: `role="separator"` is what tells a reader
 * that the content after it is a different thing, and a `div` tells them
 * nothing. A rule that is only decoration - a hairline inside a card, a tick
 * between two numbers - is the opposite case, and `decorative` takes it back
 * out of the accessibility tree, because a reader announcing "separator" six
 * times in one row is being read the styling.
 *
 * With a `label`, the line becomes a captioned break: the rule runs to the
 * caption, the caption sits in it, and the rule continues. It is a heading
 * for a run of content that does not deserve a heading - "Today", "Archived",
 * "or".
 *
 * A `div` of its own rather than Base UI's Separator, which was the obvious
 * dependency and does not do the one thing this is for: it renders a `div`
 * with `aria-orientation` and no `role`, so nothing is announced as a
 * separator at all - measured, not assumed, by rendering it. And there is no
 * way to take the role back off for a decorative rule, because there was
 * never one on. Two elements and two attributes are not worth borrowing
 * anyway; the decision here is which attributes, and that is the part a
 * dependency was not making.
 */

export const dividerVariants = cva('shrink-0 bg-line', {
  variants: {
    orientation: {
      horizontal: 'h-px w-full',
      /* `self-stretch` rather than `h-full`: a vertical rule in a flex row of
       * buttons has no height of its own to be a percentage of, and `h-full`
       * resolved to zero - a rule that was there in the markup and invisible
       * on the screen. */
      vertical: 'w-px self-stretch',
    },
    /* How much air it has. `none` is for a rule that is already inside
     * something padded - a list's rows, a table. */
    spacing: {
      none: '',
      sm: '',
      md: '',
      lg: '',
    },
  },
  compoundVariants: [
    { orientation: 'horizontal', spacing: 'sm', className: 'my-2' },
    { orientation: 'horizontal', spacing: 'md', className: 'my-4' },
    { orientation: 'horizontal', spacing: 'lg', className: 'my-8' },
    { orientation: 'vertical', spacing: 'sm', className: 'mx-2' },
    { orientation: 'vertical', spacing: 'md', className: 'mx-4' },
    { orientation: 'vertical', spacing: 'lg', className: 'mx-8' },
  ],
  defaultVariants: { orientation: 'horizontal', spacing: 'none' },
})

export interface DividerProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>,
    Omit<VariantProps<typeof dividerVariants>, 'orientation'> {
  /** Declared here rather than taken from the variants: cva types a variant
   * as nullable, and `aria-orientation` is not - a `null` passed through
   * would be a type error at the call site and an attribute React drops. */
  orientation?: 'horizontal' | 'vertical'
  /** A caption sitting in the line: "Today", "Archived", "or". Horizontal
   * only - there is no reading direction that puts a word inside a vertical
   * rule. */
  label?: ReactNode
  /** A rule that is styling rather than structure. Taken out of the
   * accessibility tree, so a reader is not told about it. */
  decorative?: boolean
}

export function Divider({
  orientation = 'horizontal',
  spacing,
  label,
  decorative = false,
  className,
  ...props
}: DividerProps) {
  if (label !== undefined && orientation === 'horizontal') {
    return (
      <div
        // The row is what carries the separator's meaning; the two rules
        // inside it are drawing. Without `aria-hidden` on them a reader hears
        // the break announced twice with a word in the middle.
        role={decorative ? 'presentation' : 'separator'}
        aria-orientation={decorative ? undefined : 'horizontal'}
        className={cn(
          'flex w-full items-center gap-3',
          dividerVariants({ orientation, spacing }),
          // The row is not itself the line: it holds two. The variant is
          // still asked for its spacing, so a captioned break sits in the
          // same rhythm as a plain one.
          'h-auto bg-transparent',
          className,
        )}
        {...props}
      >
        <span aria-hidden className="h-px flex-1 bg-line" />
        <span className="shrink-0 text-2xs font-medium uppercase tracking-caption text-faint">
          {label}
        </span>
        <span aria-hidden className="h-px flex-1 bg-line" />
      </div>
    )
  }

  return (
    <div
      // `presentation` rather than no role at all: an element with no role is
      // still a `div`, which a reader may announce as a group when it carries
      // other attributes. This says outright that there is nothing here.
      role={decorative ? 'presentation' : 'separator'}
      // Only on the one that has a role to orient. A presentational element
      // carrying an aria attribute is itself a violation - the attribute
      // describes a role the element has just disclaimed.
      aria-orientation={decorative ? undefined : orientation}
      className={cn(dividerVariants({ orientation, spacing }), className)}
      {...props}
    />
  )
}

export interface SectionHeaderProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  title: ReactNode
  description?: ReactNode
  /** Buttons belonging to this section rather than to the screen - Add,
   * Collapse, a link out. */
  actions?: ReactNode
}

/**
 * The heading over a part of a screen, with what belongs to that part at the
 * far end of the same row.
 *
 * An `h2`: `PageHeader` holds the screen's `h1`, and a section is one level
 * inside it, so a reader moving by heading walks the screen's actual
 * structure. It is the between-size heading the products kept writing by
 * hand, above `SectionLabel`'s uppercase caption and below the page's title.
 */
export function SectionHeader({
  title,
  description,
  actions,
  className,
  ...props
}: SectionHeaderProps) {
  return (
    <div
      className={cn('mb-3 flex flex-wrap items-start justify-between gap-x-4 gap-y-1', className)}
      {...props}
    >
      <div className="flex min-w-0 flex-col gap-0.5">
        <h2 className="text-base font-semibold text-text">{title}</h2>
        {description === undefined ? null : <p className="text-sm text-dim">{description}</p>}
      </div>
      {actions === undefined ? null : (
        <div className="flex shrink-0 items-center gap-2">{actions}</div>
      )}
    </div>
  )
}

import { Drawer as Base } from '@base-ui/react/drawer'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Drawer.
 *
 * A panel that slides in from an edge and holds the screen while it is there -
 * a filter sheet, a detail pane, a form too long to centre. Modal like Dialog,
 * placed like nothing else.
 *
 * Base UI positions none of it. Unlike Popover there is no Positioner and no
 * anchor to measure against; the edge it comes from is entirely CSS, which is
 * what the `side` variant is. It drives three things at once and they have to
 * agree: where the Viewport pushes the panel, which border it grows against,
 * and which way it is translated while opening and closing.
 *
 * `swipeDirection` is the other half and cannot be inferred here: it lives on
 * the root, while `side` lives on the popup, so the two are set together by
 * hand - `side="right"` with `swipeDirection="right"`, `side="bottom"` with
 * `down`, which is Base UI's default. Left unmatched, the drawer slides in
 * from one edge and is flicked away towards another.
 *
 * The transitions key off `data-starting-style` and `data-ending-style` rather
 * than `data-closed`. That is Base UI's own convention for the drawer, and the
 * reason is that a drawer is dragged as well as animated: the popup carries a
 * live `--drawer-swipe-movement-*` while a finger is on it, and the transform
 * has to compose with that rather than replace it.
 */

/** The Viewport: fixed to the whole window, pushing the popup to one edge.
 *
 * It is separate from the popup because a drawer that is its own positioner
 * cannot be scrolled independently of where it sits - and the panel needs to
 * scroll while the edge it is pinned to does not move. */
const drawerViewportVariants = cva('fixed inset-0 flex', {
  variants: {
    side: {
      right: 'justify-end',
      left: 'justify-start',
      bottom: 'items-end',
    },
  },
  defaultVariants: { side: 'right' },
})

export const drawerPopupVariants = cva(
  [
    'flex flex-col overflow-y-auto overscroll-contain',
    'border-line bg-raise p-5 text-text shadow-float',
    'focus-visible:outline-none',
    // Composed with the live swipe offset rather than replacing it, so a
    // half-dragged drawer animates from where the finger left it.
    '[transition:transform_var(--duration-base)_var(--ease-out)]',
    'will-change-transform',
  ],
  {
    variants: {
      /* Where it comes from. The three the products of the line reach for:
       * a right-hand pane, its mirror, and a bottom sheet. */
      side: {
        right: [
          'h-full w-[min(24rem,calc(100vw-3rem))] border-l',
          '[transform:translateX(var(--drawer-swipe-movement-x))]',
          'data-[starting-style]:[transform:translateX(100%)]',
          'data-[ending-style]:[transform:translateX(100%)]',
        ],
        left: [
          'h-full w-[min(24rem,calc(100vw-3rem))] border-r',
          '[transform:translateX(var(--drawer-swipe-movement-x))]',
          'data-[starting-style]:[transform:translateX(-100%)]',
          'data-[ending-style]:[transform:translateX(-100%)]',
        ],
        bottom: [
          'max-h-[80vh] w-full rounded-t-xl border-t',
          '[transform:translateY(var(--drawer-swipe-movement-y))]',
          'data-[starting-style]:[transform:translateY(100%)]',
          'data-[ending-style]:[transform:translateY(100%)]',
        ],
      },
    },
    defaultVariants: { side: 'right' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `DrawerTrigger`. */
export const Drawer = Base.Root

/** What opens it. Give it `render` to use your own button. */
export const DrawerTrigger = Base.Trigger

/** What closes it - the same, for a cancel button or an X. */
export const DrawerClose = Base.Close

/** The scrim. Dark because a drawer is modal: what is behind it is out of
 * reach, and saying so with contrast is the only thing that reads at a
 * glance. */
export function DrawerBackdrop({ className, ...props }: Base.Backdrop.Props) {
  return (
    <Base.Backdrop
      className={cn(
        'fixed inset-0 bg-black/50 backdrop-blur-[2px]',
        '[z-index:var(--z-overlay)]',
        '[transition:opacity_var(--duration-base)_var(--ease-out)]',
        'data-[closed]:opacity-0 data-[starting-style]:opacity-0',
        className,
      )}
      {...props}
    />
  )
}

export interface DrawerPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof drawerPopupVariants> {
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by an ancestor. Pass an element to put it
   * somewhere else - inside an overlay that is already open, or into a
   * container being screenshotted. */
  container?: Base.Portal.Props['container']
  /** Whether to draw the scrim. On by default, and it should stay on for
   * anything a person actually uses: the dim is what says the page behind is
   * out of reach. Turn it off where the popup is shown alongside other things
   * on purpose - a component gallery, a screenshot - because a scrim is
   * `position: fixed` and covers everything, not only its own container. */
  backdrop?: boolean
}

/** The panel. Portalled, and wrapped in its own viewport so the edge it is
 * pinned to holds still while the contents scroll. */
export function DrawerPopup({
  container,
  backdrop = true,
  side,
  className,
  children,
  ...props
}: DrawerPopupProps) {
  return (
    <Base.Portal container={container}>
      {backdrop && <DrawerBackdrop />}
      <div className={cn(drawerViewportVariants({ side }), '[z-index:var(--z-modal)]')}>
        <Base.Viewport className="flex w-full">
          <Base.Popup
            className={cn(drawerPopupVariants({ side }), className)}
            {...props}
          >
            {children}
          </Base.Popup>
        </Base.Viewport>
      </div>
    </Base.Portal>
  )
}

/** The heading. Base UI points the popup's `aria-labelledby` at it, so a
 * drawer with one is named for a screen reader without anyone arranging it. */
export function DrawerTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-base font-semibold', className)} {...props} />
}

/** The line under the heading, and the popup's `aria-describedby`. */
export function DrawerDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-1 text-sm text-dim', className)} {...props} />
}

/** Where the actions go. Pushed to the bottom of the panel rather than sitting
 * under the content, because a drawer is tall and its buttons should not
 * wander up the page when there is little in it. */
export function DrawerActions({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mt-auto flex justify-end gap-2 pt-5', className)} {...props} />
}

import { useState, type Ref } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * DurationField - a length of time, typed the way people say it.
 *
 * The alternative is what products keep building: two number boxes labelled
 * "hours" and "minutes", which means two tab stops, two validations, and a
 * reader who has to divide 90 minutes in their head before typing. Here they
 * write `1h 30m`, or `90m`, or `1.5h`, and it means the same thing.
 *
 * The value is **minutes**, a plain number. Not a string, not a Duration
 * object: the products of this line store durations as minutes already, and
 * a field whose value has to be parsed by its caller has moved the problem
 * rather than solved it.
 *
 * Parsing is deliberately generous and formatting is strict. Anything a
 * person plausibly types is accepted - `2h`, `2 h`, `2:30`, `150`, `2h30`,
 * with or without spaces - and what comes back on blur is always the one
 * canonical spelling. That asymmetry is the whole design: being strict on
 * input means rejecting people, being loose on output means the column of
 * values never lines up.
 *
 * Empty is `null`, like NumberField: "no duration" and "zero minutes" are
 * different answers, and a task with no estimate is not a task estimated at
 * nothing.
 */

/** Minutes from whatever was typed, or `null` for empty, or `undefined` when
 * it cannot be read as a duration at all.
 *
 * Exported because the parsing *is* the component - a test that goes through
 * the DOM checks React's state handling, and what needs checking is this. */
export function parseDuration(text: string): number | null | undefined {
  const input = text.trim().toLowerCase()
  if (input === '') return null

  // `2:30` - the clock spelling, which is unambiguous and worth taking.
  const clock = /^(\d+):([0-5]?\d)$/.exec(input)
  if (clock) return Number(clock[1]) * 60 + Number(clock[2])

  // A bare number is minutes. `90` is an hour and a half, not ninety hours:
  // the field is most often used for something that takes minutes, and a
  // reader typing hours writes the `h`.
  if (/^\d+(?:[.,]\d+)?$/.test(input)) return Math.round(Number(input.replace(',', '.')))

  /* The general form: any number of `<number><unit>` pairs. A decimal is
   * allowed on the hours (`1.5h`) because people write it, and a comma counts
   * as a decimal point because half the world uses one. */
  const pattern = /(\d+(?:[.,]\d+)?)\s*([hm])/g
  let total = 0
  let matched = false
  let consumed = 0

  for (const match of input.matchAll(pattern)) {
    matched = true
    consumed += match[0].length
    const amount = Number(match[1]!.replace(',', '.'))
    total += match[2] === 'h' ? amount * 60 : amount
  }

  // Everything that is not whitespace has to have been part of a pair -
  // otherwise `1h banana` would quietly parse as an hour.
  if (!matched || consumed !== input.replace(/\s+/g, '').length) return undefined

  return Math.round(total)
}

/** The one spelling a duration is written back as: `1h 30m`, `45m`, `2h`.
 *
 * Zero is `0m` rather than blank, because a duration of zero is an answer -
 * blank is what `null` renders as. */
export function formatDuration(minutes: number): string {
  const whole = Math.max(0, Math.round(minutes))
  const hours = Math.floor(whole / 60)
  const rest = whole % 60
  if (hours === 0) return `${rest}m`
  if (rest === 0) return `${hours}h`
  return `${hours}h ${rest}m`
}

export interface DurationFieldProps {
  /** Minutes, or `null` for empty. */
  value: number | null
  onValueChange: (value: number | null) => void
  /** What a reader sees before they type. A duration in the canonical
   * spelling is the best hint there is, so this is the product's to give. */
  placeholder?: string
  disabled?: boolean
  readOnly?: boolean
  required?: boolean
  name?: string
  id?: string
  ref?: Ref<HTMLInputElement>
  'aria-label'?: string
  'aria-describedby'?: string
  className?: string
}

export function DurationField({
  value,
  onValueChange,
  className,
  ref,
  ...props
}: DurationFieldProps) {
  /* The field holds text while it is being typed and a number the rest of the
   * time. Without the local copy, typing `1h 3` would reformat under the
   * cursor after every keystroke - the classic controlled-input-with-parsing
   * bug, where the field fights the person using it. */
  const [text, setText] = useState(() => (value === null ? '' : formatDuration(value)))
  const [editing, setEditing] = useState(false)

  /* The `value` this box last saw from outside, adjusted during render rather
   * than in an effect - React's own pattern for a state that has to follow a
   * prop, and the one the `set-state-in-effect` rule points at.
   *
   * The comparison has to be against what was last *seen*, not against
   * `value`. After a commit the two differ in exactly the case that must be
   * left alone: `commit` writes `1h 30m` and tells the parent, the parent
   * still holds `null` for a tick, and comparing with `value` would clear the
   * box under the reader. Asking "has the outside changed?" answers it. */
  const [seen, setSeen] = useState<number | null>(value)

  if (value !== seen) {
    setSeen(value)
    // A value that changed while someone is typing is remembered, not shown:
    // reformatting under the cursor is the bug the local copy exists for.
    if (!editing) setText(value === null ? '' : formatDuration(value))
  }

  const commit = () => {
    setEditing(false)
    const parsed = parseDuration(text)
    if (parsed === undefined) {
      // Unreadable: put back what the value actually is rather than leaving
      // the box saying something the form does not believe.
      setText(value === null ? '' : formatDuration(value))
      return
    }
    setText(parsed === null ? '' : formatDuration(parsed))
    if (parsed !== value) onValueChange(parsed)
  }

  return (
    <input
      {...props}
      ref={ref}
      type="text"
      inputMode="text"
      value={text}
      onFocus={() => setEditing(true)}
      onChange={(event) => setText(event.target.value)}
      onBlur={commit}
      onKeyDown={(event) => {
        if (event.key === 'Enter') {
          event.preventDefault()
          commit()
        }
      }}
      className={cn(fieldClasses, 'h-control tabular-nums', className)}
    />
  )
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * What a screen says when there is nothing on it.
 *
 * Three kinds of nothing, and a product that draws the same panel for all
 * three is telling the reader the wrong thing twice:
 *
 *   **empty** - there is nothing here yet, and that is normal. The panel says
 *   what would be here and offers the one action that makes it appear.
 *
 *   **filtered** - there is plenty here, just none of it matching. The way out
 *   is to widen the filter, not to create anything.
 *
 *   **error** - it could not be fetched. Nothing is missing; something failed,
 *   and the way out is to try again.
 *
 * They differ in what the reader should do next, which is exactly what an
 * empty screen is for, so they are a variant rather than three components.
 *
 * `action` is the whole point of the component: **an empty screen with no way
 * out is a dead end.** It is optional in the type because a panel inside a
 * larger screen can borrow the way out from its surroundings - but a full-page
 * empty state without one is a bug the reader cannot report.
 *
 * The mark is the line's hexagon, drawn in the current text colour rather than
 * a product's accent. A full-strength logo in an empty panel shouts; this is a
 * watermark, and it is `aria-hidden` because it says nothing a reader needs.
 */

export const emptyStateVariants = cva(
  'flex flex-col items-center justify-center gap-3 rounded-xl p-8 text-center',
  {
    variants: {
      variant: {
        empty: 'border border-dashed border-line-2',
        filtered: 'border border-dashed border-line-2',
        // Solid rather than dashed: a dashed border reads as a placeholder for
        // something that belongs there, and a failure is not that.
        error: 'border border-bad/40 bg-bad-soft/30',
      },
    },
    defaultVariants: { variant: 'empty' },
  },
)

/** The line's hexagon, at whatever size the caller asks for.
 *
 * Inlined rather than fetched: it is decorative, so it should not cost a
 * request, and it has to take the theme's colour - a file could not. */
export function EmptyMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 100 100" aria-hidden className={cn('size-14', className)}>
      <polygon
        points="50,5 89,27.5 89,72.5 50,95 11,72.5 11,27.5"
        fill="none"
        stroke="currentColor"
        strokeWidth={6}
        strokeLinejoin="round"
      />
    </svg>
  )
}

/** The same hexagon, cut by a slash. For a filter that matched nothing: the
 * shape is there, the contents are not. */
export function FilteredMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 100 100" aria-hidden className={cn('size-14', className)}>
      <polygon
        points="50,5 89,27.5 89,72.5 50,95 11,72.5 11,27.5"
        fill="none"
        stroke="currentColor"
        strokeWidth={6}
        strokeLinejoin="round"
      />
      <line x1="22" y1="78" x2="78" y2="22" stroke="currentColor" strokeWidth={6} strokeLinecap="round" />
    </svg>
  )
}

/** A hexagon with a corner broken out of it. For something that failed. */
export function ErrorMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 100 100" aria-hidden className={cn('size-14', className)}>
      <polyline
        points="50,5 89,27.5 89,72.5 50,95 11,72.5 11,27.5 50,5"
        fill="none"
        stroke="currentColor"
        strokeWidth={6}
        strokeLinejoin="round"
        strokeLinecap="round"
        // The gap is the break: the outline is drawn as a line rather than a
        // closed shape so one edge can be missing.
        strokeDasharray="150 34"
      />
    </svg>
  )
}

export interface EmptyStateProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'title'>,
    VariantProps<typeof emptyStateVariants> {
  /** What is not here, in the product's words. */
  title: ReactNode
  /** Why, or what to do about it. */
  body?: ReactNode
  /** The one thing worth doing here. An empty screen with no way out is a
   * dead end. */
  action?: ReactNode
  /** Something other than the default mark - a product's own illustration. */
  mark?: ReactNode
}

export function EmptyState({
  variant = 'empty',
  title,
  body,
  action,
  mark,
  className,
  ...props
}: EmptyStateProps) {
  const defaultMark =
    variant === 'error' ? (
      <ErrorMark className="text-bad/60" />
    ) : variant === 'filtered' ? (
      <FilteredMark className="text-line-2" />
    ) : (
      <EmptyMark className="text-line-2" />
    )

  return (
    <div className={cn(emptyStateVariants({ variant }), className)} {...props}>
      {mark ?? defaultMark}
      <div>
        <p className={cn('font-medium', variant === 'error' && 'text-bad')}>{title}</p>
        {body !== undefined && <p className="mt-1 text-sm text-dim">{body}</p>}
      </div>
      {action}
    </div>
  )
}

import { Component, type ErrorInfo, type ReactNode } from 'react'
import { Button } from './button'
import { EmptyState } from './empty-state'

/*
 * The screen that appears instead of a crash.
 *
 * A class component, and the only one in the set - not a style choice: React
 * gives no hook for catching a render error, and `componentDidCatch` exists
 * nowhere else. Anything that claims otherwise catches events, not renders.
 *
 * What it is for is narrow and worth stating, because products reach for it as
 * a general error handler and it is not one: it catches errors **thrown while
 * rendering**, below itself. A failed fetch is not that - it is a value the
 * component receives and shows, which is `QueryState`. An error in an event
 * handler is not that either; nothing catches those but the handler.
 *
 * So this is the last line: something that should never have thrown did, and
 * the alternative is a white page with the product's own name at the top.
 *
 * The fallback is deliberately plain and deliberately says the message. The
 * reader cannot fix it, but the reader is who files it - and a screen that
 * hides the one string worth quoting turns a bug report into a guess. It is
 * folded away behind a summary, because it is evidence rather than an
 * instruction.
 */

export interface ErrorBoundaryProps {
  children: ReactNode
  /** Draw something else instead of the default screen.
   *
   * Given the error and a way to clear it, because a fallback that cannot
   * retry is a dead end with extra steps. */
  fallback?: (error: Error, reset: () => void) => ReactNode
  /** Change this to clear the error - a route, usually.
   *
   * Without it a boundary that has caught once stays caught: the reader
   * navigates away from the broken screen and the crash follows them, because
   * nothing told the boundary the reason had gone. */
  resetKey?: unknown
  /** Somewhere to send it. The product owns whether that is a log, a file or a
   * service - the boundary only knows it happened. */
  onError?: (error: Error, info: ErrorInfo) => void
  /** The words on the default screen. Required, and not defaulted: they are
   * the only text here, and English inside a primitive is text no product can
   * translate. */
  labels: ErrorBoundaryLabels
}

export interface ErrorBoundaryLabels {
  /** "Something went wrong." */
  title: string
  /** What the reader can do about it. */
  body: string
  /** The summary that unfolds the message, e.g. "Details". */
  details: string
  /** The retry button, e.g. "Try again". */
  retry: string
}

interface State {
  error: Error | null
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, State> {
  state: State = { error: null }

  static getDerivedStateFromError(error: Error): State {
    return { error }
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    this.props.onError?.(error, info)
  }

  componentDidUpdate(previous: ErrorBoundaryProps): void {
    // Clearing on a changed key, rather than on any re-render: a boundary that
    // resets whenever its parent renders re-runs the throwing child
    // immediately, and the screen flickers between the crash and the fallback
    // for as long as the cause is there.
    if (this.state.error !== null && previous.resetKey !== this.props.resetKey) {
      this.setState({ error: null })
    }
  }

  private reset = (): void => {
    this.setState({ error: null })
  }

  render(): ReactNode {
    const { error } = this.state
    if (error === null) return this.props.children

    const { fallback, labels } = this.props
    if (fallback) return fallback(error, this.reset)

    return (
      <EmptyState
        variant="error"
        title={labels.title}
        body={labels.body}
        action={
          <div className="flex w-full flex-col items-center gap-3">
            <details className="w-full text-left">
              <summary className="cursor-pointer text-xs text-faint">{labels.details}</summary>
              {/* Selectable and monospaced, because its job is to be copied
                * into a bug report verbatim. */}
              <pre className="mt-2 max-h-40 overflow-auto rounded-md bg-softer p-3 font-mono text-xs text-dim">
                {error.message}
              </pre>
            </details>
            <Button variant="primary" onClick={this.reset}>
              {labels.retry}
            </Button>
          </div>
        }
      />
    )
  }
}

import type { ReactElement, ReactNode } from 'react'
import { Field as Base } from '@base-ui/react/field'
import { cn } from 'dowel-ui'

/*
 * Field - the label, the control, and what the form has to say about it.
 *
 * Every form is the same four parts repeated: a name for the control, the
 * control, sometimes a hint, and sometimes an error. Written by hand each
 * time, they drift - the label loses its `htmlFor`, the hint is a `<div>` no
 * screen reader mentions, the error appears in red and is announced by
 * nothing at all. This is that arrangement, once.
 *
 * The wiring is the point, and Base UI does it: the label points at the
 * control, the description and the error are named by `aria-describedby`, and
 * the control is marked invalid while an error is showing. None of that is
 * visible when it works, which is exactly why a product stops doing it.
 *
 * `error` is a string this is given, not a rule this enforces. dowel has no
 * opinion about where the string came from - Base UI's own `validate`, a
 * schema, react-hook-form, or a server that just said no - because a design
 * system that picked a form library would be choosing for products that
 * already chose. The one thing it insists on is that an error, once it
 * exists, is announced and points at the field it belongs to.
 *
 * The label is always rendered. A field whose name is only a placeholder
 * loses that name the moment someone types, and a placeholder is not a label
 * to anything that reads the page aloud; `labelHidden` takes it off the
 * screen and leaves it in the accessibility tree.
 */

export interface FieldProps {
  /** What the control is called. Always rendered; `labelHidden` only takes it
   * off the screen. */
  label: ReactNode
  /** The control itself - Input, Textarea, Select, Checkbox, anything.
   *
   * A single element rather than arbitrary nodes, because it is handed to
   * Base UI to carry the field's id and its `aria-*` wiring. Two children, or
   * a bare string, would leave the label naming nothing. */
  children: ReactElement
  /** A hint under the control. Hidden while an error is showing: two lines of
   * small print under one field is one line too many, and the error is the
   * one that matters. */
  help?: ReactNode
  /** What is wrong, if anything. Its presence is what marks the control
   * invalid - there is no separate `invalid` prop to keep in step. */
  error?: ReactNode
  /** Keep the label for screen readers but take it off the screen. For a
   * field whose meaning is obvious in context - a search box in a toolbar. */
  labelHidden?: boolean
  className?: string
  /** Marks the field required, which is a statement about the form rather
   * than about validation: the label gets the mark a reader looks for. */
  required?: boolean
  /** The control's `name`, forwarded so a `Form` can attach a server error to
   * this field by name. */
  name?: string
  disabled?: boolean
}

export function Field({
  label,
  children,
  help,
  error,
  labelHidden = false,
  className,
  required = false,
  name,
  disabled = false,
}: FieldProps) {
  const invalid = error !== undefined && error !== null && error !== false

  return (
    <Base.Root
      name={name}
      disabled={disabled}
      // Base UI marks the control invalid from its own validity state; this
      // says so for an error that arrived from anywhere else.
      invalid={invalid || undefined}
      className={cn('flex flex-col gap-1.5', className)}
    >
      <Base.Label
        className={cn(
          'text-2xs font-medium uppercase tracking-caption text-faint',
          // Off the screen, still in the accessibility tree. Not
          // `display: none`, which would take it out of both.
          labelHidden && 'sr-only',
        )}
      >
        {label}
        {required && (
          <span aria-hidden className="ml-0.5 text-bad">
            *
          </span>
        )}
      </Base.Label>

      {/* The control is handed to Base UI rather than merely nested inside
        * it. This is the whole component: a plain child renders a label whose
        * `for` points at an id nothing carries, so the label looks wired and
        * names nothing - which is exactly the bug this exists to prevent, and
        * it is invisible in a screenshot. `render` gives the child the id,
        * `aria-labelledby` and `aria-describedby` instead. */}
      <Base.Control render={children} />

      {/* The error wins the one line under the control. `match` is not used:
        * the string is already the decision - this renders whatever it was
        * handed rather than asking the browser what is wrong. */}
      {invalid ? (
        <Base.Error className="text-xs text-bad" match>
          {error}
        </Base.Error>
      ) : (
        help !== undefined && <Base.Description className="text-xs text-dim">{help}</Base.Description>
      )}
    </Base.Root>
  )
}

import { useCallback, useId, useRef, useState, type DragEvent, type ReactNode } from 'react'
import { cn } from 'dowel-ui'

/*
 * FileDrop.
 *
 * A place to put files: drag them onto it, or press it and pick them. It takes
 * files and hands them over - it does not upload them. Where they go, with
 * which credentials, retried how - that is the product's transport, and a
 * primitive that owned it would be wrong for every product whose upload does
 * not look like the one it guessed.
 *
 * The boundary is the same one `Field` draws around validation: the component
 * knows the shape of the interaction, the product knows what the interaction
 * means.
 *
 * The parts that are easy to get wrong, and are therefore here:
 *
 * - **A real `<input type="file">` underneath.** Not a div with a click
 *   handler. The native input is what makes the keyboard work, what the
 *   operating system's file picker attaches to, and what a screen reader
 *   announces as a file field. It is visually hidden, not `display: none` -
 *   hidden that way it is unfocusable, and the label stops reaching it.
 * - **The drag counter.** `dragleave` fires when the pointer crosses onto a
 *   *child* of the drop zone, so a zone that toggles on leave flickers as the
 *   pointer moves over its own text. Counting enters and leaves is the fix,
 *   and it is the single commonest defect in hand-written drop zones.
 * - **`dragover` must be prevented.** Without it the browser navigates to the
 *   file instead of dropping it - the drop appears to do nothing, and the page
 *   is replaced by a PDF.
 * - **Rejected files are reported, not swallowed.** A file dropped and
 *   silently ignored looks like a broken page. What is wrong with it is the
 *   product's word, so `onReject` hands back the file and the reason.
 */

/** Why a file was not accepted. The product turns this into a sentence. */
export type FileRejection = {
  file: File
  reason: 'type' | 'size' | 'count'
}

export interface FileDropProps {
  /** Called with the files that passed the filters. */
  onFiles: (files: File[]) => void
  /** Called with the ones that did not, so the product can say why. */
  onReject?: (rejections: FileRejection[]) => void
  /** What to take, in the form `<input accept>` uses: `image/*`, `.pdf,.docx`. */
  accept?: string
  /** Largest file, in bytes. */
  maxSize?: number
  /** How many at once. Without it, any number. */
  maxFiles?: number
  /** Whether several may be chosen in the picker. */
  multiple?: boolean
  disabled?: boolean
  /** What the zone says. The product's words, in the product's language. */
  children?: ReactNode
  className?: string
  id?: string
  /** Names the field for a screen reader, when there is no visible label. */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-describedby'?: string
}

/** Whether a file matches an `accept` list. Handles the three forms the
 * attribute takes: an extension, a full type, and a wildcard type. */
function matchesAccept(file: File, accept: string | undefined): boolean {
  if (!accept) return true
  return accept
    .split(',')
    .map((entry) => entry.trim().toLowerCase())
    .filter(Boolean)
    .some((entry) => {
      if (entry.startsWith('.')) return file.name.toLowerCase().endsWith(entry)
      if (entry.endsWith('/*')) return file.type.toLowerCase().startsWith(entry.slice(0, -1))
      return file.type.toLowerCase() === entry
    })
}

export function FileDrop({
  onFiles,
  onReject,
  accept,
  maxSize,
  maxFiles,
  multiple,
  disabled,
  children,
  className,
  id,
  ...aria
}: FileDropProps) {
  const inputRef = useRef<HTMLInputElement>(null)
  const generatedId = useId()
  const inputId = id ?? generatedId

  /* Nested elements each fire their own enter and leave as the pointer crosses
   * them, so a boolean would flicker while the pointer moves across the zone's
   * own label. The depth counter is what makes "still inside" answerable. */
  const [depth, setDepth] = useState(0)
  const over = depth > 0

  const take = useCallback(
    (list: FileList | null) => {
      if (!list) return
      const incoming = Array.from(list)
      const accepted: File[] = []
      const rejected: FileRejection[] = []

      for (const file of incoming) {
        if (!matchesAccept(file, accept)) rejected.push({ file, reason: 'type' })
        else if (maxSize !== undefined && file.size > maxSize) rejected.push({ file, reason: 'size' })
        else if (maxFiles !== undefined && accepted.length >= maxFiles)
          rejected.push({ file, reason: 'count' })
        else accepted.push(file)
      }

      if (accepted.length) onFiles(accepted)
      if (rejected.length) onReject?.(rejected)
    },
    [accept, maxFiles, maxSize, onFiles, onReject],
  )

  const onDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    setDepth(0)
    if (disabled) return
    take(event.dataTransfer.files)
  }

  return (
    <div
      onDragEnter={(event) => {
        event.preventDefault()
        setDepth((d) => d + 1)
      }}
      onDragLeave={(event) => {
        event.preventDefault()
        setDepth((d) => Math.max(0, d - 1))
      }}
      // Without preventing this, the browser opens the dropped file instead,
      // and the page the reader was filling in is simply gone.
      onDragOver={(event) => event.preventDefault()}
      onDrop={onDrop}
      // Presentational: the input inside is the control, and wrapping it in a
      // second interactive element would give a screen reader two.
      className={cn(
        'rounded-lg border border-dashed border-line bg-raise p-6 text-center transition-colors',
        over && !disabled && 'border-accent bg-accent-soft',
        disabled && 'pointer-events-none opacity-50',
        className,
      )}
    >
      <label htmlFor={inputId} className={cn('block', !disabled && 'cursor-pointer')}>
        {children}
      </label>
      <input
        ref={inputRef}
        id={inputId}
        type="file"
        accept={accept}
        multiple={multiple}
        disabled={disabled}
        {...aria}
        onChange={(event) => {
          take(event.target.files)
          // Cleared so that choosing the same file twice in a row still fires
          // a change - otherwise the second attempt silently does nothing.
          event.target.value = ''
        }}
        /* Visually hidden, not `hidden`: it stays focusable, keeps its place
         * in the tab order, and the label above still points at a real
         * control. `display: none` would take all three away. */
        className="sr-only"
      />
    </div>
  )
}

import {
  useLayoutEffect,
  useRef,
  useState,
  type HTMLAttributes,
  type ImgHTMLAttributes,
  type ReactNode,
} from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * AspectRatio and Image.
 *
 * The layout jump a loading picture leaves behind is not a styling defect,
 * it is a missing number: the browser has nowhere to put the box until the
 * file arrives and tells it the pixel size, so everything below the picture
 * slides down and back up. `AspectRatio` is that number, given up front by
 * the caller rather than discovered by the browser - a plain box on CSS
 * `aspect-ratio` that reserves its space the instant it is in the tree, and
 * lets any child (an `<img>`, a map, a video) fill it with `size-full`.
 *
 * `Image` is what goes inside one. It carries its own three-state life, the
 * same shape `Avatar` already uses for its picture - loading, loaded, and
 * failed - because a face and a photograph fail to load for the same
 * reasons and should not fail differently:
 *
 * - **Loading** shows a placeholder in the exact box the ratio already
 *   reserved, built from `Skeleton`'s own look (`animate-pulse bg-soft`)
 *   rather than a new grey rectangle invented for this one component - one
 *   loading language for the set, not two that drift apart over time.
 * - **Loaded** fades the picture in over `--duration-base` rather than
 *   popping it in, because a sudden picture reads as a flash the eye has to
 *   catch; the theme's own reduced-motion media query cuts every duration to
 *   near zero for a reader who asked for that, so nothing extra is wired up
 *   here for it. The `<img>` itself is always in the DOM - hidden with
 *   opacity and `aria-hidden`, not unmounted - so the load event has
 *   something to fire on the first render rather than never.
 * - **Failed** shows `fallback` instead of the browser's own broken-image
 *   glyph, which looks like the product forgot the picture rather than that
 *   the network did.
 *
 * The state a naive version gets wrong is the fourth one: a picture already
 * in the browser's cache is already `complete` the instant the `<img>` mounts,
 * and no `load` event follows - there is nothing left to load. Without the
 * check in the effect below, that picture's placeholder would sit forever,
 * because the one event this component was waiting for already happened
 * before it started listening. The same effect is what makes navigating back
 * to an already-seen picture look instant instead of re-showing a skeleton
 * for a picture that is sitting in memory.
 *
 * Base UI has no image-loading primitive of its own to reach for here - its
 * `Avatar` component is a separate package this workspace does not install,
 * and this line's own `Avatar` already reimplements the same loaded/failed
 * state by hand for the same reason: a picture is common enough, and small
 * enough, that a dependency would cost more than the `useState` it replaces.
 * `Image` follows that precedent rather than inventing a second one.
 */

export const aspectRatioVariants = cva('relative w-full overflow-hidden bg-soft', {
  variants: {
    /** How the box is shaped. `square` and `video` are named because those
     * are the two ratios a product reaches for by name; anything else is a
     * plain number on `ratio`. */
    ratio: {
      square: 'aspect-square',
      video: 'aspect-video',
    },
  },
})

/* `ratio` carries both the named steps and a raw number, which `cva`'s own
 * variant type cannot express - its keys are strings, not numbers. The prop
 * is widened here and split apart in the component instead. */
type AspectRatioVariant = VariantProps<typeof aspectRatioVariants>['ratio'] | number

export interface AspectRatioProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /** The box's shape: `square`, `video`, or a raw number as width / height -
   * `4 / 3`, `21 / 9` - for anything the named steps do not cover. */
  ratio?: AspectRatioVariant
  children?: ReactNode
}

/** A box that keeps its shape before, during and after whatever fills it
 * loads. `size-full` on the child is the contract: this component reserves
 * the rectangle, the child covers it. */
export function AspectRatio({ ratio, className, children, style, ...props }: AspectRatioProps) {
  const named = typeof ratio === 'number' ? undefined : ratio
  const numeric = typeof ratio === 'number' ? ratio : undefined

  return (
    <div
      className={cn(aspectRatioVariants({ ratio: named }), className)}
      style={numeric ? { aspectRatio: numeric, ...style } : style}
      {...props}
    >
      {children}
    </div>
  )
}

export const imageVariants = cva('size-full', {
  variants: {
    /** How the picture fills a box that is not its own shape. `cover` for a
     * photo standing in for the whole box; `contain` for a logo or a
     * diagram where cropping would cut off the point of it. */
    fit: {
      cover: 'object-cover',
      contain: 'object-contain',
    },
  },
  defaultVariants: { fit: 'cover' },
})

export interface ImageProps
  extends Omit<ImgHTMLAttributes<HTMLImageElement>, 'onLoad' | 'onError' | 'placeholder'>,
    VariantProps<typeof imageVariants> {
  /** Required, with no default: a decorative picture says so explicitly with
   * `alt=""` rather than by omission, which is indistinguishable from a
   * picture nobody described yet. */
  alt: string
  /** What stands in the box when the picture fails to load - the product's
   * text or icon, not a default this component would have to write in some
   * one language. */
  fallback?: ReactNode
}

/** A picture that reserves its box, shows `Skeleton`'s placeholder while it
 * loads, fades in once it has, and shows `fallback` instead of a broken-image
 * glyph if it can't be loaded at all. */
export function Image({ fallback, fit, className, src, alt, ...props }: ImageProps) {
  const [status, setStatus] = useState<'loading' | 'loaded' | 'failed'>('loading')
  const ref = useRef<HTMLImageElement>(null)

  // A picture already in the browser's cache is already `complete` the
  // instant this mounts, and fires no `load` event of its own - there is
  // nothing left to load. Without this check the placeholder above it would
  // never be told to leave. `useLayoutEffect` rather than `useEffect`, so a
  // cached picture never paints its placeholder for even one frame - only
  // the layout-timed effect runs before the browser has painted.
  useLayoutEffect(() => {
    const img = ref.current
    setStatus(img && img.complete && img.naturalWidth > 0 ? 'loaded' : 'loading')
  }, [src])

  return (
    <span className="relative block size-full overflow-hidden">
      {status !== 'failed' && (
        <img
          {...props}
          ref={ref}
          src={src}
          alt={alt}
          onLoad={() => setStatus('loaded')}
          onError={() => setStatus('failed')}
          className={cn(
            imageVariants({ fit }),
            'absolute inset-0 transition-opacity duration-base ease-out',
            status === 'loaded' ? 'opacity-100' : 'opacity-0',
            className,
          )}
          // Hidden from a reader until there is a picture to announce - an
          // `alt` describing content that is not there yet, or never
          // arrives, is worse than saying nothing.
          aria-hidden={status !== 'loaded'}
        />
      )}
      {status === 'loading' && (
        <span aria-hidden className="absolute inset-0 animate-pulse rounded-md bg-soft" />
      )}
      {status === 'failed' && fallback && (
        <span className="absolute inset-0 flex items-center justify-center text-dim">{fallback}</span>
      )}
    </span>
  )
}

import type { InputHTMLAttributes, Ref } from 'react'
import { cn } from 'dowel-ui'

/*
 * Input.
 *
 * A single-line field. It is a plain `<input>` with the line's clothes on, so
 * everything a browser gives an input for free - autofill, spellcheck, the
 * right keyboard on a phone, `type="email"` validation - still works.
 *
 * The focus ring is the accent, drawn outside the border rather than replacing
 * it: a field that only changes colour on focus is invisible to anyone who
 * cannot distinguish those two colours.
 */
export const fieldClasses = cn(
  'w-full rounded-md border border-line bg-transparent px-2.5 py-1.5',
  'text-sm text-text placeholder:text-faint',
  'transition-colors hover:border-line-2',
  'focus-visible:outline-2 focus-visible:outline-offset-0 focus-visible:outline-accent',
  // A field nobody can type in should look like one.
  'disabled:cursor-not-allowed disabled:opacity-50',
  // `aria-invalid` rather than a prop: the attribute is what a screen reader
  // reads, so making it the source of the colour keeps the two in step.
  'aria-invalid:border-bad aria-invalid:focus-visible:outline-bad',
)

export interface InputProps extends InputHTMLAttributes<HTMLInputElement> {
  /** React 19 passes `ref` as a plain prop; it is declared so callers can
   * reach the element to focus it or read its selection. */
  ref?: Ref<HTMLInputElement>
}

export function Input({ className, ref, ...props }: InputProps) {
  return <input ref={ref} className={cn(fieldClasses, 'h-control', className)} {...props} />
}

/*
 * What a JSON value looks like as a list of rows, with no React in it.
 *
 * The sibling of `tree-rows`, built the same way and for the same reason: a
 * product that wants to count the rows before drawing any of them - to put a
 * viewer inside a VirtualList, to say "1,204 entries" - imports this and never
 * the component.
 *
 * Flattening is also what makes the keyboard simple. Down is the next row of
 * this list and Up the previous, whatever the nesting; a recursive walk at
 * every keystroke asks the same question and answers it differently at each
 * depth.
 */

/** What a value is, for drawing and for deciding whether it opens.
 *
 * `null` is its own kind rather than an absence: in JSON it is a value
 * somebody wrote, and a viewer that shows it as an empty cell says the key is
 * missing when it is present and null - a distinction that decides bugs. */
export type JsonKind = 'object' | 'array' | 'string' | 'number' | 'boolean' | 'null'

/** Any value `JSON.parse` can return. */
export type JsonValue = null | boolean | number | string | JsonValue[] | { [key: string]: JsonValue }

export interface JsonRow {
  /**
   * Where this sits, in JSONPath: `$.items[3].name`.
   *
   * The identity of a row, and deliberately not its index: a row's index
   * changes when a branch above it opens, and anything remembered by index -
   * which rows are open, which is selected - would jump to a different value
   * the moment something above it moved. It is also what a reader copies when
   * they want to point at this value from somewhere else.
   */
  path: string
  /** The key, or the index as written in the path. `null` only for the root. */
  key: string | null
  /** True when the key is an array index rather than an object's name - drawn
   * differently, because `0` as a name and `0` as a position are not the same
   * thing. */
  index: boolean
  kind: JsonKind
  /** The value itself, for a leaf. A branch has none: what it holds is in the
   * rows below it. */
  value?: string | number | boolean | null
  depth: number
  /** How many entries a branch holds, so a closed one can say so without being
   * opened. */
  size?: number
  /** The path of the branch this row sits in, if any. What Left uses to get
   * out of a deep branch in one press. */
  parent?: string
}

export function kindOf(value: JsonValue): JsonKind {
  if (value === null) return 'null'
  if (Array.isArray(value)) return 'array'
  return typeof value as JsonKind
}

export function isBranch(kind: JsonKind): boolean {
  return kind === 'object' || kind === 'array'
}

/*
 * A key as it appears in a path.
 *
 * Dot notation where the key is an ordinary identifier, brackets otherwise -
 * which is not decoration. `$.user name` is not a path anything can resolve,
 * and a key containing a dot (`$.a.b` for the single key `"a.b"`) is a path
 * that resolves to the WRONG value silently. Both are common in real data:
 * configuration files and anything exported from a spreadsheet.
 */
function step(key: string): string {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key)
    ? `.${key}`
    : `[${JSON.stringify(key)}]`
}

/**
 * The rows a value shows, in the order the eye and the keyboard travel.
 *
 * Only what is visible: a closed branch contributes its own row and nothing
 * below it. That is what keeps a viewer of a large document cheap - a
 * thousand-entry array that nobody opened costs one row.
 */
export function visibleRows(
  value: JsonValue,
  open: ReadonlySet<string>,
  { root = '$' }: { root?: string } = {},
): JsonRow[] {
  const rows: JsonRow[] = []

  const walk = (
    node: JsonValue,
    path: string,
    key: string | null,
    index: boolean,
    depth: number,
    parent?: string,
  ): void => {
    const kind = kindOf(node)

    if (!isBranch(kind)) {
      rows.push({ path, key, index, kind, value: node as string | number | boolean | null, depth, parent })
      return
    }

    const entries: [string, JsonValue][] = Array.isArray(node)
      ? node.map((item, at) => [String(at), item])
      : Object.entries(node as { [key: string]: JsonValue })

    rows.push({ path, key, index, kind, depth, size: entries.length, parent })

    if (!open.has(path)) return

    for (const [childKey, child] of entries) {
      walk(
        child,
        Array.isArray(node) ? `${path}[${childKey}]` : `${path}${step(childKey)}`,
        childKey,
        Array.isArray(node),
        depth + 1,
        path,
      )
    }
  }

  walk(value, root, null, false, 0)
  return rows
}

/**
 * The paths to open so a document arrives readable.
 *
 * Bounded twice, by depth AND by size, and the second bound is the one that
 * does the work. A depth bound alone reads as sufficient and is not: the cost
 * of opening is measured in ROWS, while depth counts LEVELS, and those track
 * each other only while the branches are small - which is the case nobody
 * needed protecting from.
 *
 * Measured, not reasoned: a payload holding `assets: [1204 entries]` at its
 * top level rendered 1216 rows and 24,000 pixels of scroll on arrival under a
 * depth-2 bound, because the array sits AT depth 2. That is exactly the freeze
 * the bound exists to prevent, produced by the bound itself. The shape that
 * hurts is one huge branch near the surface, and a level count is blindest to
 * precisely that shape.
 *
 * So a branch opens when it is shallow enough AND holds fewer than `size`
 * entries. A branch left shut is not descended through either - what is inside
 * something the reader cannot see does not need deciding about.
 */
export function branchPaths(
  value: JsonValue,
  {
    root = '$',
    depth = 2,
    /** How many entries a branch may hold and still open by itself. Twenty is
     * about a screen: enough that a settings file arrives open, few enough
     * that a list of records arrives as a list of records. */
    size = 20,
  }: { root?: string; depth?: number; size?: number } = {},
): Set<string> {
  const paths = new Set<string>()

  const walk = (node: JsonValue, path: string, level: number): void => {
    const kind = kindOf(node)
    if (!isBranch(kind) || level > depth) return

    const entries: [string, JsonValue][] = Array.isArray(node)
      ? node.map((item, at) => [String(at), item])
      : Object.entries(node as { [key: string]: JsonValue })

    // Too big to open, so it stays shut - and nothing below it is considered:
    // those rows are not going to be drawn either way.
    if (entries.length > size) return

    paths.add(path)

    for (const [key, child] of entries) {
      walk(child, Array.isArray(node) ? `${path}[${key}]` : `${path}${step(key)}`, level + 1)
    }
  }

  walk(value, root, 1)
  return paths
}

/**
 * What a closed branch says about itself: `{ 4 }` or `[ 1204 ]`.
 *
 * The count rather than a preview of the contents. A preview of the first
 * entries reads as though those are all of them, which is the one thing a
 * closed branch must not imply.
 */
export function summarise(row: JsonRow): string {
  if (row.kind === 'array') return `[ ${row.size ?? 0} ]`
  return `{ ${row.size ?? 0} }`
}

import { useMemo, useState, type KeyboardEvent } from 'react'
import { cn } from 'dowel-ui'
import {
  branchPaths,
  isBranch,
  summarise,
  visibleRows,
  type JsonRow,
  type JsonValue,
} from './json-rows'

/*
 * A JSON value, read rather than parsed by eye.
 *
 * What a product reaches for when it has to show a response, a settings file,
 * a webhook payload - data the reader needs to understand, not edit. The
 * alternative it replaces is `JSON.stringify(value, null, 2)` inside a `<pre>`,
 * which is fine for twenty lines and useless for two hundred: nothing folds,
 * nothing is findable, and the shape of the document is somewhere inside the
 * indentation.
 *
 * It is a TREE, and it deliberately does not reuse TreeView. A row here is a
 * key AND a value, and TreeView's row is one `ReactNode` label - pouring JSON
 * into it means the component can no longer colour a value by its type, tell
 * an array index from a name, or offer the two things a reader actually wants
 * (the value at this row, the path to it). What is genuinely shared is the
 * arithmetic of which rows are visible, and that is shared: `json-rows` is the
 * sibling of `tree-rows`, both with no React in them.
 *
 * The keyboard is the ARIA tree pattern, for the reason TreeView states it:
 *
 *   **One tab stop, not one per row.** A document of four hundred rows with a
 *   `tabIndex` on each is four hundred stops between whatever is above it and
 *   whatever is below.
 *
 *   **Right and Left do different things depending on where the cursor is.**
 *   Right opens a closed branch, steps into an open one, does nothing on a
 *   leaf; Left closes an open branch and otherwise jumps to the parent, which
 *   is how a reader gets out of a deep branch without walking back up through
 *   every sibling.
 *
 * Values are coloured with `--syntax-*`, the same tokens a CodeBlock uses, so
 * a string is the same green in both. Colour is never the only signal: a
 * string is quoted, a branch says how many it holds, and null is the word.
 */

export interface JsonViewerProps {
  value: JsonValue
  /** Which branches are open, by path. Uncontrolled if omitted, starting with
   * the top two levels open - the shape of an answer rather than the whole
   * document. */
  open?: ReadonlySet<string>
  onOpenChange?: (open: Set<string>) => void
  /** Told which row was activated, with its path and its value. What a product
   * hangs "copy this" or "go to this setting" on. */
  onActivate?: (row: JsonRow) => void
  /** What a screen reader calls it. Required, and without a default: a string
   * this component invents is a string the product cannot translate. */
  label: string
  /** The path the document starts at, for a viewer showing one field of a
   * larger record. Paths are then written so they still mean something in that
   * record. */
  root?: string
  className?: string
}

export function JsonViewer({
  value,
  open: openProp,
  onOpenChange,
  onActivate,
  label,
  root = '$',
  className,
}: JsonViewerProps) {
  const [openState, setOpenState] = useState(() => branchPaths(value, { root }))
  const open = openProp ?? openState

  const rows = useMemo(() => visibleRows(value, open, { root }), [value, open, root])

  /* The cursor is a path, not an index. An index would point at a different
   * value the moment a branch above it opened - the cursor would appear to
   * jump on its own. */
  const [cursor, setCursor] = useState<string>(root)
  const at = Math.max(
    0,
    rows.findIndex((row) => row.path === cursor),
  )

  const setOpen = (next: Set<string>) => {
    if (openProp === undefined) setOpenState(next)
    onOpenChange?.(next)
  }

  const toggle = (path: string) => {
    const next = new Set(open)
    if (next.has(path)) next.delete(path)
    else next.add(path)
    setOpen(next)
  }

  const move = (to: number) => {
    const row = rows[Math.min(Math.max(to, 0), rows.length - 1)]
    if (row !== undefined) setCursor(row.path)
  }

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const row = rows[at]
    if (row === undefined) return

    switch (event.key) {
      case 'ArrowDown':
        move(at + 1)
        break
      case 'ArrowUp':
        move(at - 1)
        break
      case 'ArrowRight':
        // Open a closed branch; step into an open one. On a leaf, nothing -
        // rather than falling through to the next row, which would make Right
        // a second Down and lose the reader their place in the nesting.
        if (isBranch(row.kind) && !open.has(row.path)) toggle(row.path)
        else if (isBranch(row.kind)) move(at + 1)
        else return
        break
      case 'ArrowLeft':
        // Close what is open; otherwise leave the branch. The second half is
        // what makes a deep document navigable at all.
        if (isBranch(row.kind) && open.has(row.path)) toggle(row.path)
        else if (row.parent !== undefined) setCursor(row.parent)
        else return
        break
      case 'Home':
        move(0)
        break
      case 'End':
        move(rows.length - 1)
        break
      case 'Enter':
      case ' ':
        if (isBranch(row.kind)) toggle(row.path)
        onActivate?.(row)
        break
      default:
        return
    }
    // Only for a key this component handled: swallowing every keystroke would
    // take Tab and the browser's own shortcuts with it.
    event.preventDefault()
  }

  return (
    <div
      role="tree"
      aria-label={label}
      // The one tab stop. The arrows move a cursor inside it - the arrangement
      // a radio group has, and for the same reason.
      tabIndex={0}
      onKeyDown={onKeyDown}
      className={cn(
        'overflow-auto rounded-md border border-line bg-soft py-1 font-mono text-xs leading-relaxed',
        // A desktop shell turns selection off; this is data someone came to
        // take away.
        'select-text',
        'focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent',
        className,
      )}
    >
      {rows.map((row) => {
        const branch = isBranch(row.kind)
        const expanded = branch ? open.has(row.path) : undefined

        return (
          <div
            key={row.path}
            role="treeitem"
            aria-level={row.depth + 1}
            aria-expanded={expanded}
            aria-selected={row.path === cursor}
            onClick={() => {
              setCursor(row.path)
              if (branch) toggle(row.path)
              onActivate?.(row)
            }}
            className={cn(
              'flex cursor-default items-baseline gap-1.5 px-2 py-px',
              'hover:bg-softer',
              row.path === cursor && 'bg-accent-soft',
            )}
            // Indentation as padding rather than nested elements: a row four
            // levels down is still a sibling of every other row, which is what
            // lets the whole list be windowed.
            style={{ paddingLeft: `${row.depth * 0.9 + 0.5}rem` }}
          >
            {/* The twisty. A fixed-width slot even on a leaf, so the keys of a
              * branch and a leaf at the same level line up - without it the
              * eye reads the indentation wrong. */}
            <span className={cn('w-2 shrink-0 text-faint', !branch && 'invisible')} aria-hidden>
              {expanded === true ? '▾' : '▸'}
            </span>

            {row.key !== null && (
              <>
                <span className={row.index ? 'text-faint tabular-nums' : 'text-syntax-name'}>
                  {row.index ? row.key : `"${row.key}"`}
                </span>
                <span className="text-syntax-punctuation" aria-hidden>
                  :
                </span>
              </>
            )}

            {branch ? (
              /* A closed branch says how many it holds; an open one says it
               * too, because the count is still the fastest answer to "how big
               * is this" once the reader has scrolled past the first entries. */
              <span className="text-faint">{summarise(row)}</span>
            ) : (
              <Leaf row={row} />
            )}
          </div>
        )
      })}
    </div>
  )
}

/*
 * A value, drawn as what it is.
 *
 * Quotes on a string are not decoration: `"1"` and `1` are different values,
 * and a viewer that draws them alike hides the commonest bug in any JSON
 * payload - a number that arrived as a string. Colour says the same thing
 * faster for those who see it; the quotes say it to everyone.
 */
function Leaf({ row }: { row: JsonRow }) {
  if (row.kind === 'string') {
    return (
      <span className="min-w-0 break-all text-syntax-string">{`"${String(row.value)}"`}</span>
    )
  }
  if (row.kind === 'number') {
    return <span className="text-syntax-number tabular-nums">{String(row.value)}</span>
  }
  if (row.kind === 'boolean') {
    return <span className="text-syntax-keyword">{String(row.value)}</span>
  }
  // `null` in the same colour as a comment: present, and nothing there. Drawn
  // as the word rather than as an empty cell, which would read as a key with
  // no value at all.
  return <span className="text-syntax-comment">null</span>
}

import type { HTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * Kbd.
 *
 * A key, as printed in a menu or a hint: `Ctrl` `K`. It is a `<kbd>` element
 * because that is what the element is for - a screen reader announces it as
 * keyboard input rather than reading a stray capital letter.
 *
 * The platform substitution is the useful part. A shortcut written `Ctrl+K` is
 * wrong on a Mac, where the same shortcut is `⌘K`, and every product either
 * hard-codes one of them or writes the branch again.
 */

/** Whether this machine writes shortcuts the Apple way. */
function isApplePlatform(): boolean {
  if (typeof navigator === 'undefined') return false
  return /mac|iphone|ipad|ipod/i.test(navigator.platform || navigator.userAgent)
}

/** What a key is called here. `Mod` is the one that differs: command on Apple
 * platforms, control everywhere else. */
export function keyLabel(key: string, apple: boolean = isApplePlatform()): string {
  const shared: Record<string, string> = {
    Enter: '↵',
    Escape: 'Esc',
    ArrowUp: '↑',
    ArrowDown: '↓',
    ArrowLeft: '←',
    ArrowRight: '→',
    Backspace: '⌫',
    Tab: '⇥',
    Space: '␣',
  }
  const perPlatform: Record<string, [apple: string, other: string]> = {
    Mod: ['⌘', 'Ctrl'],
    Alt: ['⌥', 'Alt'],
    Shift: ['⇧', 'Shift'],
  }

  const platform = perPlatform[key]
  if (platform) return apple ? platform[0] : platform[1]
  return shared[key] ?? key
}

export interface KbdProps extends HTMLAttributes<HTMLElement> {
  /** Keys of a shortcut, in order: `['Mod', 'K']`. Given this, the component
   * writes the separators and the platform's own names. */
  keys?: string[]
}

export function Kbd({ keys, className, children, ...props }: KbdProps) {
  const cap = cn(
    'inline-flex min-w-5 items-center justify-center rounded-sm border border-line bg-soft',
    'px-1 py-0.5 font-mono text-2xs leading-none text-dim',
  )

  if (!keys) {
    return (
      <kbd className={cn(cap, className)} {...props}>
        {children}
      </kbd>
    )
  }

  return (
    <span className={cn('inline-flex items-center gap-0.5', className)} {...props}>
      {keys.map((key) => (
        <kbd key={key} className={cap}>
          {keyLabel(key)}
        </kbd>
      ))}
    </span>
  )
}

import { createContext, useContext, type HTMLAttributes, type ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * A list of facts: a name, and what it is.
 *
 * The shape every product builds out of two `<div>`s in a flex row, and the
 * reason it is worth having once: it is a `<dl>`, and the pairing is what a
 * screen reader announces. Two divs read as four unrelated pieces of text -
 * "Created", "2 hours ago", "Owner", "Ines" - and nothing says which value
 * belongs to which name. The right element says it for free.
 *
 * Two layouts, and both exist because the same list sits in two places: beside
 * something (a panel of properties, names in one column) and under a heading
 * (a card, name above value). A product moving a panel should not have to
 * change component.
 *
 * The layouts need *different markup*, and that is why the row reads the
 * layout from context rather than taking a prop:
 *
 *   **rows** puts `<dt>`/`<dd>` directly in the grid, so every value lines up
 *   in one column. Wrap each pair in a `<div>` and each pair becomes its own
 *   box - the values then sit at a different place on every line, which is
 *   exactly the ragged look this component exists to stop.
 *
 *   **stacked** wraps each pair, because without a wrapper the column gaps
 *   fall between `dt` and `dd` as readily as between pairs, and a list of six
 *   facts reads as twelve unrelated lines.
 *
 * Both are valid `<dl>`: the spec allows `dt`/`dd` as direct children, and
 * allows a `<div>` per pair. What it does not allow is any other element
 * between them, which is why the pair is a component rather than something the
 * caller assembles.
 */

export const keyValueVariants = cva('text-sm', {
  variants: {
    layout: {
      rows: 'grid grid-cols-[minmax(0,auto)_minmax(0,1fr)] items-baseline gap-x-4 gap-y-2',
      stacked: 'flex flex-col gap-3',
    },
  },
  defaultVariants: { layout: 'rows' },
})

type Layout = NonNullable<VariantProps<typeof keyValueVariants>['layout']>

/* The row has to know the layout to know whether to wrap. Context rather than
 * a prop on every row: a list whose rows disagree with it is not a thing
 * anyone wants, and repeating the value at each row is how they come to. */
const LayoutContext = createContext<Layout>('rows')

export interface KeyValueProps
  extends HTMLAttributes<HTMLDListElement>,
    VariantProps<typeof keyValueVariants> {}

export function KeyValue({ layout, className, ...props }: KeyValueProps) {
  return (
    <LayoutContext.Provider value={layout ?? 'rows'}>
      <dl className={cn(keyValueVariants({ layout }), className)} {...props} />
    </LayoutContext.Provider>
  )
}

export interface KeyValueRowProps {
  /** The name of the fact. */
  label: ReactNode
  /** What it is. A node rather than a string: half the values in a real panel
   * are a Badge, a RelativeTime or a link. */
  children: ReactNode
  className?: string
}

/** One pair. */
export function KeyValueRow({ label, children, className }: KeyValueRowProps) {
  const layout = useContext(LayoutContext)

  const value = <dd className="min-w-0 text-text">{children}</dd>

  // Wrapped, so the column's gap falls between pairs rather than inside one,
  // and the caller's class dresses the pair as a whole.
  if (layout === 'stacked') {
    return (
      <div className={cn('flex flex-col gap-0.5', className)}>
        <dt className="text-dim">{label}</dt>
        {value}
      </div>
    )
  }

  /* Directly in the grid, so every value shares one column - there is no
   * wrapper here to carry the caller's class, so it dresses the term. That is
   * the half a caller styles: the value's own appearance comes from whatever
   * it renders. */
  return (
    <>
      <dt className={cn('text-dim', className)}>{label}</dt>
      {value}
    </>
  )
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { boundsOf, pathOf, runs, ticksFor, yOf, type Bounds, type Point } from './line-scale'

/*
 * A quantity over time, where it continues between the readings.
 *
 * The distinction against its neighbours is the data's, not the drawing's. A
 * column says each period is its own sum - hours worked in a week, and there
 * is no Wednesday-afternoon figure between two weeks. A line says the value
 * existed the whole time and was sampled: an account balance, a price, a
 * temperature. Drawing a sum as a line claims readings nobody took; drawing a
 * level as columns throws away the thing being watched.
 *
 * Sparkline is the same shape with the axes taken away, for beside a figure.
 * This one has them, because a balance without a scale is a squiggle.
 *
 * **A hole breaks the line.** Interpolating across invents a reading; closing
 * the gap up moves every later point and makes the axis lie about when things
 * happened. Both are quieter than the truth, which is why the truth has to be
 * drawn deliberately.
 *
 * **The floor is not zero unless the caller says so**, and that is a departure
 * from BarChart on purpose. A bar's length is the quantity, so its baseline
 * has to be zero. A line's subject is change, and a balance between 4,900 and
 * 5,100 on a zero-based axis is a flat rule. The ticks are what keep this
 * honest: they say where the bottom is.
 *
 * The plot owns its height in pixels, for the reason BarChart does - a
 * percentage against a parent with no height of its own resolves to zero, and
 * the chart disappears without failing.
 */

export const lineChartVariants = cva('relative w-full', {
  variants: {
    size: {
      sm: '[--plot:96px]',
      md: '[--plot:160px]',
    },
    /* Room on the right for the tick labels. Drawn inside the plot they sit on
     * top of whatever the line is doing there - found by looking, with `$5,200`
     * crossed out by its own series. A gutter costs a little width and cannot
     * collide. */
    gutter: {
      true: 'pr-12',
      false: '',
    },
  },
  defaultVariants: { size: 'md', gutter: true },
})

export const lineVariants = cva('fill-none', {
  variants: {
    tone: {
      accent: 'stroke-accent',
      series: 'stroke-series-1',
      good: 'stroke-good',
      bad: 'stroke-bad',
      muted: 'stroke-dim',
    },
  },
  defaultVariants: { tone: 'accent' },
})

export interface LineChartProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>,
    VariantProps<typeof lineChartVariants>,
    VariantProps<typeof lineVariants> {
  /** The readings, in order. `value: null` is a measurement not taken. */
  points: Point[]
  /** Override any edge of the plot. `min: 0` for a count, where zero is the
   * truth rather than a flattening. */
  bounds?: Partial<Bounds>
  /** What the chart as a whole says, for a reader who cannot see it. */
  label: string
  /** How many value ticks to aim for. They land on round numbers, so the count
   * is a wish rather than a promise. `0` draws none. */
  ticks?: number
  /** Turns a tick into its label. Without it the number is drawn as it is -
   * which is right for a count and wrong for money or a duration. */
  formatTick?: (value: number) => string
  /** The labels under the axis - usually the first and last reading. Two or
   * three, not one per point: the axis is not a place for a list. */
  footer?: ReactNode
}

export function LineChart({
  points,
  bounds: stated,
  label,
  ticks = 4,
  formatTick,
  footer,
  tone,
  size,
  className,
  ...props
}: LineChartProps) {
  const bounds = boundsOf(points, stated)

  /* Nothing measured is not a chart of zeroes: an empty plot with its axis is
   * the honest drawing, and the caller says so in words beside it. */
  if (bounds === null) {
    return (
      <div
        className={cn(lineChartVariants({ size, gutter: false }), className)}
        role="img"
        aria-label={label}
        {...props}
      >
        <div className="h-[var(--plot)] w-full border-b border-chart-axis" />
      </div>
    )
  }

  const drawn = runs(points, bounds)
  const rules = ticks > 0 ? ticksFor(bounds, ticks) : []

  return (
    <div
      className={cn(lineChartVariants({ size, gutter: rules.length > 0 }), className)}
      role="img"
      aria-label={label}
      {...props}
    >
      <div className="relative h-[var(--plot)] w-full border-b border-chart-axis">
        {rules.map((tick) => {
          const y = yOf(tick, bounds)
          if (y === null) return null
          return (
            <div key={tick} className="pointer-events-none absolute inset-x-0" style={{ top: `${y}%` }}>
              {/* Solid hairline: a dashed rule reads as a threshold or a
                * projection, and this is neither. */}
              <div className="h-px w-full bg-chart-grid" />
              {/* Outside the plot, in the gutter the variant reserves: a label
                * drawn over the series is a label crossed out by it. */}
              <span className="absolute -top-1.5 left-full pl-1.5 text-[10px] leading-none text-faint tabular-nums">
                {formatTick ? formatTick(tick) : tick}
              </span>
            </div>
          )
        })}

        {/* `preserveAspectRatio="none"` is what lets the plot be a box of the
          * caller's shape while the maths stays in percentages: x and y scale
          * independently, which would bend a shape but cannot bend a line
          * whose every segment is straight. The stroke is drawn in absolute
          * units so it does not stretch with the box. */}
        <svg
          viewBox="0 0 100 100"
          preserveAspectRatio="none"
          className="absolute inset-0 h-full w-full overflow-visible"
          aria-hidden
        >
          {drawn.map((run) => (
            <path
              key={run[0]!.at}
              d={pathOf(run)}
              vectorEffect="non-scaling-stroke"
              strokeWidth={2}
              strokeLinecap="round"
              strokeLinejoin="round"
              className={cn(lineVariants({ tone }))}
            />
          ))}
        </svg>
      </div>

      {footer !== undefined && (
        <div className="mt-1 flex justify-between text-[10px] text-faint tabular-nums">{footer}</div>
      )}
    </div>
  )
}

/*
 * The arithmetic behind LineChart, with no React in it.
 *
 * Split out like `track-segments` and `activity-weeks`: a product labelling
 * its own points, or checking its own domain sums, should not import a
 * component to get at the numbers.
 *
 * Two things live here and neither is obvious. Turning a series with holes in
 * it into drawable runs, and choosing the ticks on an axis - which is a
 * question about what reads as a round number, not about dividing a range into
 * equal parts.
 */

/** One reading. `value: null` is a measurement that was not taken - which is
 * not a reading of zero, and not a reason to move the ones after it. */
export interface Point {
  /** Position along the axis. Same units throughout: a timestamp, an index. */
  at: number
  value: number | null
}

export interface Bounds {
  /** The value the left edge stands for. */
  from: number
  /** The right edge. */
  to: number
  /** The bottom of the plot. */
  min: number
  /** The top. */
  max: number
}

/** A point placed in the box, in percentages: x from the left, y from the top
 * (SVG's own direction, so a larger value has a smaller y). */
export interface Placed {
  x: number
  y: number
  at: number
  value: number
}

/**
 * The bounds a series is drawn against.
 *
 * The y range does NOT start at zero by default, and that is a deliberate
 * departure from the bar's rule. A bar's length *is* the quantity, so its
 * baseline has to be zero or the length lies. A line's job is the shape of a
 * change, and a balance moving between 4,900 and 5,100 flattens into a
 * horizontal rule on a zero-based axis - the very thing the reader opened the
 * chart to see. What keeps it honest is that the axis is labelled: the ticks
 * say where the bottom is, so nobody reads the floor as nothing.
 *
 * A caller who wants zero states it, and for a quantity that is a count rather
 * than a level - requests, errors - they should.
 */
export function boundsOf(points: Point[], stated: Partial<Bounds> = {}): Bounds | null {
  const drawn = points.filter((point): point is Point & { value: number } => point.value !== null)
  if (drawn.length === 0) return null

  const values = drawn.map((point) => point.value)
  const positions = points.map((point) => point.at)

  const from = stated.from ?? Math.min(...positions)
  const to = stated.to ?? Math.max(...positions)

  let min = stated.min ?? Math.min(...values)
  let max = stated.max ?? Math.max(...values)

  /* A flat series has no range to scale against, and dividing by it would put
   * every point at the same y - or at NaN. Given a band around the value, the
   * line sits in the middle of the plot and reads as what it is: unchanging. */
  if (!(max > min)) {
    const pad = Math.abs(max) > 0 ? Math.abs(max) * 0.1 : 1
    min = max - pad
    max = max + pad
  }

  return { from, to, min, max }
}

/**
 * The series as runs of consecutive readings.
 *
 * A hole breaks the line rather than being drawn through or closed up, and the
 * three options are worth naming because two of them lie:
 *
 *   **Interpolating across** invents a reading nobody took - the one thing a
 *   chart of measurements must never do.
 *
 *   **Dropping the point** keeps the line whole and moves every later reading
 *   to the left, so the axis stops matching the data: a chart that says the
 *   value was 40 in March when it was 40 in April.
 *
 *   **Breaking the line** leaves the gap visible, keeps every other point
 *   where it belongs, and invents nothing. So that is what happens here.
 *
 * A run of one point is kept: it has no line, but it has a dot, and dropping
 * it would hide a reading that exists.
 */
export function runs(points: Point[], bounds: Bounds): Placed[][] {
  const span = bounds.to - bounds.from
  const height = bounds.max - bounds.min
  if (!(span > 0) || !(height > 0)) return []

  const out: Placed[][] = []
  let run: Placed[] = []

  for (const point of points) {
    if (point.value === null) {
      if (run.length > 0) out.push(run)
      run = []
      continue
    }

    const clamped = Math.min(Math.max(point.value, bounds.min), bounds.max)
    run.push({
      x: ((point.at - bounds.from) / span) * 100,
      // SVG's y grows downward, so the largest value sits at the top.
      y: ((bounds.max - clamped) / height) * 100,
      at: point.at,
      value: point.value,
    })
  }

  if (run.length > 0) out.push(run)
  return out
}

/** A run as an SVG path, in the same percentages.
 *
 * Straight segments rather than a curve: a spline through measured points
 * overshoots between them, inventing highs and lows that were never recorded -
 * the same lie as interpolating across a gap, drawn more prettily. */
export function pathOf(run: Placed[]): string {
  return run
    .map((point, index) => `${index === 0 ? 'M' : 'L'}${point.x.toFixed(2)} ${point.y.toFixed(2)}`)
    .join(' ')
}

/**
 * Ticks for the value axis, on round numbers.
 *
 * Not the range cut into equal parts: 4,900 to 5,100 in four gives 4,950 and
 * 5,050, which nobody reads as a landmark. A tick's job is to be recognised
 * instantly, so the step is the nearest 1, 2, 5 or 10 above what the range
 * needs, and the ticks are the multiples of it inside the range.
 *
 * Returns nothing when a step would not fit - a range too narrow for a round
 * number is better with no ticks than with invented ones.
 */
export function ticksFor(bounds: Bounds, wanted = 4): number[] {
  const height = bounds.max - bounds.min
  if (!(height > 0) || wanted < 1) return []

  const rough = height / wanted
  const magnitude = 10 ** Math.floor(Math.log10(rough))
  const step = [1, 2, 5, 10].map((n) => n * magnitude).find((candidate) => candidate >= rough)
  if (step === undefined) return []

  const ticks: number[] = []
  for (let tick = Math.ceil(bounds.min / step) * step; tick <= bounds.max; tick += step) {
    // Floating point leaves 0.30000000000000004 where 0.3 was meant; the step
    // is what decides how many decimals are real.
    const decimals = Math.max(0, -Math.floor(Math.log10(step)))
    ticks.push(Number(tick.toFixed(decimals)))
  }

  return ticks
}

/** Where a value sits in the plot, as a percentage from the top - for a tick's
 * rule, or a threshold drawn across the line. */
export function yOf(value: number, bounds: Bounds): number | null {
  const height = bounds.max - bounds.min
  if (!(height > 0)) return null
  if (value < bounds.min || value > bounds.max) return null
  return ((bounds.max - value) / height) * 100
}

import {
  useCallback,
  useMemo,
  type ChangeEvent,
  type CSSProperties,
  type ReactNode,
  type Ref,
  type TextareaHTMLAttributes,
} from 'react'
import { cn } from 'dowel-ui'

/*
 * Text with marks on it - read, or typed into.
 *
 * A textarea cannot colour a word. The way round it is older than React: draw
 * the same text twice, once as marked-up HTML underneath and once as the
 * textarea on top with its own text transparent, so the caret and the
 * selection are the browser's and the colours are ours. The two have to agree
 * on every metric - font, size, line height, padding, wrapping - or the marks
 * slide off the words they mark. So both take ONE class list, given by the
 * caller, and the textarea adds only what makes it invisible.
 *
 * The mirror is also what sizes the box. It sits in the flow and the textarea
 * is stretched over it, which means the field grows with its text without a
 * `scrollHeight` measurement and never scrolls inside itself - the box around
 * it scrolls, and the marks scroll with the words. A trailing space on the
 * last line keeps a final newline from being a line the mirror forgot.
 *
 * Two kinds of mark: a span of characters (a repeated word, a misspelling)
 * and a whole line (a line that is new since the other version). Lines are
 * drawn as blocks rather than separated by newlines so a line mark can paint
 * the full width; a block per line wraps exactly as the textarea's line does,
 * since it is the same text in the same width with the same font.
 */

/** A span of characters, as offsets into the whole text. */
export interface Mark {
  start: number
  end: number
  className?: string
  style?: CSSProperties
}

/** A whole line. */
export interface LineMark {
  /** Zero-based line index. */
  line: number
  className?: string
}

export interface MarkedLinesProps {
  text: string
  marks?: readonly Mark[]
  lineMarks?: readonly LineMark[]
  /** Transparent text: the textarea above shows the letters. */
  ghost?: boolean
}

/** One line cut into runs, each run under at most one mark. */
function runs(line: string, offset: number, marks: readonly Mark[]): ReactNode[] {
  const out: ReactNode[] = []
  let at = 0
  for (const mark of marks) {
    const start = Math.max(mark.start - offset, 0)
    const end = Math.min(mark.end - offset, line.length)
    if (end <= at || start >= line.length) continue
    if (start > at) out.push(line.slice(at, start))
    out.push(
      <mark
        key={offset + start}
        // `<mark>` for the semantics; the browser's yellow is dropped so the
        // caller's class is the colour, in whichever tone the mark means.
        className={cn('rounded-sm bg-transparent text-inherit', mark.className)}
        style={mark.style}
      >
        {line.slice(start, end)}
      </mark>,
    )
    at = end
  }
  if (at < line.length) out.push(line.slice(at))
  return out
}

/** The marked-up text, line by line. The layer both the readable and the
 * typeable form are made of. */
export function MarkedLines({ text, marks = [], lineMarks = [], ghost = false }: MarkedLinesProps) {
  // Each line with where it starts in the text, so a mark given as an offset
  // into the whole can be cut to the line it falls on.
  const lines = useMemo(() => {
    const out: { line: string; start: number }[] = []
    let offset = 0
    for (const line of text.split('\n')) {
      out.push({ line, start: offset })
      offset += line.length + 1
    }
    return out
  }, [text])
  const byLine = useMemo(() => {
    const map = new Map<number, string | undefined>()
    for (const mark of lineMarks) map.set(mark.line, mark.className)
    return map
  }, [lineMarks])

  return (
    <>
      {lines.map(({ line, start }, index) => {
        // Only the marks that touch this line, in order; a text has few marks
        // and few lines, so a filter per line is cheaper than an index.
        const own = marks.filter((mark) => mark.end > start && mark.start < start + line.length)
        return (
          <div
            key={index}
            data-line={index}
            className={cn(
              'min-h-[1lh] whitespace-pre-wrap [overflow-wrap:anywhere]',
              ghost && 'text-transparent',
              byLine.get(index),
            )}
          >
            {/* A blank line still needs its height, and a trailing line needs
                a character to exist at all. */}
            {line === '' ? ' ' : runs(line, start, own)}
            {index === lines.length - 1 && ' '}
          </div>
        )
      })}
    </>
  )
}

export interface MarkedTextProps extends MarkedLinesProps {
  className?: string
}

/** Marked text to read. */
export function MarkedText({ className, ...lines }: MarkedTextProps) {
  return (
    <div className={cn('select-text', className)}>
      <MarkedLines {...lines} />
    </div>
  )
}

export interface MarkedTextareaProps
  extends Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, 'value' | 'onChange' | 'className'> {
  ref?: Ref<HTMLTextAreaElement>
  value: string
  /** The new value, not the event: the event is the textarea's business. */
  onChange: (value: string) => void
  marks?: readonly Mark[]
  lineMarks?: readonly LineMark[]
  /** The metrics both layers share: font, size, line height, padding. */
  className?: string
}

/** Marked text to type into. */
export function MarkedTextarea({
  value,
  onChange,
  marks,
  lineMarks,
  className,
  ref,
  ...props
}: MarkedTextareaProps) {
  const change = useCallback(
    (event: ChangeEvent<HTMLTextAreaElement>) => onChange(event.target.value),
    [onChange],
  )

  return (
    <div className="relative">
      <div aria-hidden data-mirror className={cn('pointer-events-none', className)}>
        <MarkedLines text={value} marks={marks} lineMarks={lineMarks} ghost />
      </div>
      <textarea
        ref={ref}
        value={value}
        onChange={change}
        spellCheck={false}
        className={cn(
          // The same metrics, and nothing that would draw: the letters, the
          // caret and the selection are what this layer is for.
          'absolute inset-0 h-full w-full resize-none overflow-hidden text-text outline-none',
          '[overflow-wrap:anywhere] whitespace-pre-wrap',
          className,
          // After the caller's classes, on purpose. A background in the
          // metrics is meant for the box and lands on both layers; on this
          // one it would paint over every mark. The mirror keeps it, the
          // field never does.
          'bg-transparent',
        )}
        {...props}
      />
    </div>
  )
}

import { Menu as Base } from '@base-ui/react/menu'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Menu.
 *
 * A list of actions that opens from a button - the row menu, the overflow
 * menu, the one behind the three dots. The products all wrote this by hand,
 * and all of them wrote the same three hundred lines: a click-outside
 * listener, an Escape handler, and a `stopPropagation` on every item so that
 * choosing an action does not also open the row underneath.
 *
 * None of that is what makes a menu hard. What makes it hard is the keyboard:
 * arrows that wrap, Home and End, type-ahead that finds an item by its first
 * letters, a submenu that opens on the right key and closes when the pointer
 * leaves diagonally. Base UI has all of it.
 *
 * The items are exposed rather than taken as an array of `{ label, onSelect }`.
 * An array is enough until the first separator, the first checkbox item and
 * the first submenu - and each of those arrives as another field on the object
 * rather than as the JSX it obviously is.
 */

export const menuPopupVariants = cva(
  [
    'min-w-40 rounded-md border border-line bg-raise p-1 text-text shadow-raise',
    'focus-visible:outline-none',
    '[transition:opacity_var(--duration-quick)_var(--ease-out),transform_var(--duration-quick)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        sm: 'min-w-32',
        md: 'min-w-40',
        lg: 'min-w-56',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** One row of the menu. `danger` draws the destructive one apart from the
 * rest - in the colour of something that cannot be undone. */
export const menuItemVariants = cva(
  [
    'flex cursor-pointer select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm',
    'outline-none transition-colors',
    // Base UI marks the item under the pointer or the keyboard the same way,
    // so one rule covers both and they cannot disagree.
    'data-[highlighted]:bg-soft data-[highlighted]:text-text',
    'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
    '[&_svg]:size-3.5 [&_svg]:shrink-0',
  ],
  {
    variants: {
      tone: {
        default: 'text-dim data-[highlighted]:text-text',
        danger: 'text-bad data-[highlighted]:bg-bad-soft data-[highlighted]:text-bad',
      },
    },
    defaultVariants: { tone: 'default' },
  },
)

/** The root. Uncontrolled by default; `open` and `onOpenChange` make it
 * controlled. */
export const Menu = Base.Root

/** What opens it. Give it `render` to use your own button. */
export const MenuTrigger = Base.Trigger

/** A labelled group of items, for a menu long enough to need headings. */
export const MenuGroup = Base.Group

/** A submenu, opened from a `MenuSubTrigger` inside the parent. */
export const MenuSub = Base.SubmenuRoot

export interface MenuPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof menuPopupVariants> {
  /** Preferred side of the trigger. Base UI flips it when it does not fit. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. */
  align?: Base.Positioner.Props['align']
  /** Distance from the trigger, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /** Where to portal to. Defaults to the document body, which keeps the menu
   * from being clipped by a row with `overflow: hidden` - which is where most
   * hand-written ones go to die. */
  container?: Base.Portal.Props['container']
}

/** The panel. Portalled and positioned against the trigger. */
export function MenuPopup({
  size,
  side,
  align,
  sideOffset = 4,
  container,
  className,
  children,
  ...props
}: MenuPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        className="[z-index:var(--z-menu)]"
      >
        <Base.Popup className={cn(menuPopupVariants({ size }), className)} {...props}>
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

export interface MenuItemProps extends Base.Item.Props, VariantProps<typeof menuItemVariants> {}

/** An action. Closing the menu afterwards is Base UI's default, which is
 * almost always right - `closeOnClick={false}` is for the one that is not. */
export function MenuItem({ tone, className, ...props }: MenuItemProps) {
  return <Base.Item className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** An item that opens a submenu. Drawn like any other, because it is one. */
export function MenuSubTrigger({ tone, className, ...props }: MenuItemProps) {
  return <Base.SubmenuTrigger className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** An item that carries a tick. The state is the caller's - a menu does not
 * remember anything. */
export function MenuCheckboxItem({ tone, className, ...props }: MenuItemProps) {
  return <Base.CheckboxItem className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** The tick itself, drawn only when the item is checked. */
export const MenuCheckboxIndicator = Base.CheckboxItemIndicator

/** A line between groups of items. Decorative, and marked as such: a screen
 * reader announcing "separator" between every pair of actions is noise. */
export function MenuSeparator({ className, ...props }: Base.Separator.Props) {
  return <Base.Separator className={cn('-mx-1 my-1 h-px bg-line', className)} {...props} />
}

/** The caption above a group. */
export function MenuGroupLabel({ className, ...props }: Base.GroupLabel.Props) {
  return (
    <Base.GroupLabel
      className={cn('px-2 py-1.5 text-2xs uppercase tracking-caption text-faint', className)}
      {...props}
    />
  )
}

import type { HTMLAttributes, ReactNode } from 'react'
import { useRender } from '@base-ui/react/use-render'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * NavRail.
 *
 * The product's own destinations: the screens it has, drawn as a column down
 * the left, a row of tabs in a header, or a bar along the bottom of a phone.
 * One list, three shapes, because they are the same list - and when they were
 * three components in two products they drew the current entry three
 * different ways.
 *
 * The entries are the product's links, not this component's. `render` takes
 * an item and answers with the element to draw it as - a router's `NavLink`,
 * a plain `<a>`, whatever the product navigates with - and the rail puts the
 * clothes, the icon and the `aria-current` on it. That keeps the router out
 * of the registry entirely: a set that imported `react-router` would install
 * one in a product that had chosen another, and there is no version of that
 * which is the design system's business.
 *
 * `NavGroup` is the small uppercase caption between runs of entries, and
 * `NavSpacer` pushes what follows to the far end - the settings, the theme
 * switch, the profile, which every rail in the line keeps at its foot.
 */

export const navRailVariants = cva('flex', {
  variants: {
    /*
     * Which of the three shapes this is.
     *
     * Not a guess from the width: a rail that changed shape when its
     * container narrowed would change shape in the middle of a drag.
     */
    layout: {
      /* Down the left, the desktop shape. `h-full` so the rail runs the
       * height of the window and its foot sits at the bottom because the nav
       * reaches it, not because the content does. */
      column: 'h-full flex-col gap-0.5 overflow-y-auto border-r border-line px-2.5 pt-2.5 pb-3',
      /* A row of tabs, in a header beside the product's name. */
      row: 'flex-row items-center gap-1',
      /* Along the bottom, where a thumb already is. The safe-area inset is
       * the phone's home indicator: without it the last row of entries sits
       * under it with no way to scroll out. */
      bar: 'flex-row border-t border-line bg-raise pb-[env(safe-area-inset-bottom)]',
    },
  },
  defaultVariants: { layout: 'column' },
})

export interface NavRailItem {
  id: string
  label: ReactNode
  icon?: ReactNode
  /** A count, a dot, a version chip - whatever sits at the end of the row.
   * Drawn only in `column`, where there is width for it. */
  end?: ReactNode
  /** A destination that exists on the roadmap but not in the build. It is
   * drawn greyed and is not a link: the point is to say the screen is coming,
   * which an entry that navigates nowhere would say by doing nothing. */
  soon?: boolean
}

export interface NavRailProps
  extends Omit<HTMLAttributes<HTMLElement>, 'children' | 'onSelect'>,
    VariantProps<typeof navRailVariants> {
  /** What this set of destinations is called. Not drawn - it names the
   * landmark, so a reader meeting two navs on one page can tell which is
   * which. A product with a rail AND a bottom bar has exactly that. */
  label: string
  items: readonly NavRailItem[]
  /** Which destination is the open screen. */
  activeId?: string
  /** The element an entry is drawn as - `render={(item) => <NavLink to={…} />}`. */
  render?: (item: NavRailItem) => useRender.RenderProp
  /** Pressed, whatever the entry is drawn as. */
  onSelect?: (id: string) => void
}

export function NavRail({
  layout,
  label,
  items,
  activeId,
  render,
  onSelect,
  className,
  ...props
}: NavRailProps) {
  return (
    <nav aria-label={label} className={cn(navRailVariants({ layout }), className)} {...props}>
      {items.map((item) => (
        <NavRailEntry
          key={item.id}
          item={item}
          layout={layout ?? 'column'}
          active={item.id === activeId}
          render={item.soon === true ? undefined : render?.(item)}
          onSelect={onSelect}
        />
      ))}
    </nav>
  )
}

/** The clothes of one entry, by shape.
 *
 * `target-min` on the two narrow shapes rather than on all three: a column
 * entry is already taller than the floor, and the utility establishes a
 * containing block, which is not free on every row of a list. */
const entryClasses = {
  column:
    'flex w-full items-center gap-2.5 rounded-md px-2.5 py-1.5 text-left text-sm no-underline transition-colors',
  /* `flex` here for the same reason as the other two, and it was missing: a
   * tab is an icon beside a word, and without it the entry is a block, the
   * icon and the label stack, and the header grows to twice its height. The
   * class-list tests did not see it - they read the string, not the layout -
   * and the stand did, in the first screenshot. */
  row: 'target-min flex items-center gap-2 rounded-md px-2.5 py-1 text-sm no-underline transition-colors',
  bar: 'target-min flex min-h-14 min-w-0 flex-1 flex-col items-center justify-center gap-1 px-1 py-2 text-2xs no-underline transition-colors',
} as const

function NavRailEntry({
  item,
  layout,
  active,
  render,
  onSelect,
}: {
  item: NavRailItem
  layout: NonNullable<NavRailProps['layout']>
  active: boolean
  render?: useRender.RenderProp
  onSelect?: (id: string) => void
}) {
  const soon = item.soon === true

  return useRender({
    render,
    // A destination is a link when the product gives it one and a button when
    // it does not; one that is not built yet is neither, and `span` says so -
    // a disabled button is still in the tab order on some browsers, and
    // tabbing onto a screen that does not exist is a dead end.
    defaultTagName: soon ? 'span' : 'button',
    props: {
      ...(render === undefined && !soon ? { type: 'button' } : {}),
      // Named as the current page, which is how a reader learns which of six
      // identical links is where they stand. Colour alone says it to nobody
      // who cannot see it.
      'aria-current': active ? 'page' : undefined,
      ...(soon ? { 'aria-disabled': true } : {}),
      onClick: soon ? undefined : () => onSelect?.(item.id),
      className: cn(
        entryClasses[layout],
        '[&_svg]:size-4 [&_svg]:shrink-0',
        'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
        soon
          ? 'cursor-default text-faint'
          : cn(
              'cursor-pointer text-dim hover:bg-soft hover:text-text',
              // The bottom bar tints the entry itself rather than filling the
              // cell: a filled cell in a four-across bar reads as a pressed
              // button, and it is a location, not an action.
              active &&
                (layout === 'bar'
                  ? 'text-accent-2 hover:bg-transparent'
                  : 'bg-accent-soft text-text [&_svg]:text-accent'),
            ),
      ),
      children: (
        <>
          {item.icon === undefined ? null : (
            <span aria-hidden className="contents">
              {item.icon}
            </span>
          )}
          {/* Truncated, in one line. A rail is a fixed-width column, and a
              label that wraps onto a second line makes the row taller than
              every other - which in a two-language product happens to one
              entry and not the rest. `min-w-0` because a flex child refuses
              to shrink below its content without it. */}
          <span className={cn('min-w-0 truncate', layout === 'bar' ? 'w-full text-center' : 'flex-1')}>
            {item.label}
          </span>
          {item.end === undefined || layout !== 'column' ? null : (
            <span className="ml-auto shrink-0 text-2xs text-faint">{item.end}</span>
          )}
        </>
      ),
    },
  })
}

/** The caption over a run of entries: Library, Team, Admin.
 *
 * A `div` rather than a heading: a rail's groups are not the page's outline,
 * and six `h3`s inside a nav put six entries into a reader's document map
 * that lead nowhere. */
export function NavGroup({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        'px-2.5 pt-3 pb-1 text-2xs font-medium uppercase tracking-caption text-faint',
        className,
      )}
      {...props}
    />
  )
}

/** Pushes everything after it to the far end of the rail. */
export function NavSpacer({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mt-auto flex flex-col gap-0.5', className)} {...props} />
}

import { Children, useState, type ReactNode } from 'react'
import { cn } from 'dowel-ui'
import { Button } from './button'
import { Popover, PopoverPopup, PopoverTrigger } from './popover'

/*
 * The bell in the title bar, lit by what asks to be looked at.
 *
 * A bell that is always lit is a bell nobody reads, so the count is the
 * product's decision and this draws it: nothing at zero, the number past
 * that, `9+` past nine. Pressing it does not leave the screen - the last few
 * entries open under it and the whole history is one more click, which is
 * the shape every product converged on once the first one tried a page.
 *
 * What is in the list is the product's: the rows are `children`, because a
 * journal entry, a failed upload and a comment are three different lines and
 * one component cannot draw them. What is shared is the frame around them -
 * the trigger with its badge, the heading with the button that clears the
 * count, the empty line, and the footer that leads to everything.
 *
 * Built on Popover and Button rather than on a `<div>` of its own, so the
 * panel opens, positions and closes the way every other panel does.
 */

export interface NotificationBellProps {
  /** How many things ask to be looked at. Nothing is drawn at zero. */
  count: number
  /** What the bell is called, for a screen reader and the tooltip. */
  label: string
  /** The heading of the panel. */
  title: string
  /** Open, controlled. Left out, the bell manages itself. */
  open?: boolean
  onOpenChange?: (open: boolean) => void
  /** The button that clears the count, shown only while there is one. */
  markAllLabel?: string
  onMarkAll?: () => void
  /** The footer button, which closes the panel and hands over. */
  seeAllLabel?: string
  onSeeAll?: () => void
  /** What the list says when there are no rows. */
  emptyLabel: string
  /** The rows. */
  children?: ReactNode
  /** While the product is clearing the count: the button waits. */
  busy?: boolean
  className?: string
}

export function NotificationBell({
  count,
  label,
  title,
  open,
  onOpenChange,
  markAllLabel,
  onMarkAll,
  seeAllLabel,
  onSeeAll,
  emptyLabel,
  children,
  busy = false,
  className,
}: NotificationBellProps) {
  const [own, setOwn] = useState(false)
  const isOpen = open ?? own
  const setOpen = (next: boolean) => {
    setOwn(next)
    onOpenChange?.(next)
  }
  const empty = Children.count(children) === 0

  return (
    <Popover open={isOpen} onOpenChange={setOpen}>
      <PopoverTrigger
        render={
          <Button variant="icon" size="icon-sm" className={cn('relative', className)} title={label} aria-label={label} />
        }
      >
        <Bell />
        {count > 0 ? (
          <span
            data-badge
            className={cn(
              'absolute -right-0.5 -top-0.5 min-w-3.5 rounded-full bg-warn px-1',
              'text-center font-mono text-[9px] leading-[14px] text-on-warn',
            )}
          >
            {count > 9 ? '9+' : count}
          </span>
        ) : null}
      </PopoverTrigger>
      <PopoverPopup align="end" arrow={false} size="lg" className="p-0">
        <header className="flex items-center gap-2 border-b border-line px-3 py-2">
          <h3 className="text-sm font-semibold">{title}</h3>
          {count > 0 && markAllLabel ? (
            <Button variant="ghost" size="sm" className="ml-auto" disabled={busy} onClick={onMarkAll}>
              {markAllLabel}
            </Button>
          ) : null}
        </header>
        <div className="max-h-80 overflow-y-auto px-3">
          {empty ? <p className="py-3 text-sm text-dim">{emptyLabel}</p> : children}
        </div>
        {seeAllLabel ? (
          <footer className="border-t border-line p-2">
            <Button
              variant="ghost"
              size="sm"
              className="w-full"
              onClick={() => {
                setOpen(false)
                onSeeAll?.()
              }}
            >
              {seeAllLabel}
            </Button>
          </footer>
        ) : null}
      </PopoverPopup>
    </Popover>
  )
}

function Bell() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" aria-hidden>
      <path d="M4 11V7.5a4 4 0 0 1 8 0V11l1 1.5H3z" strokeLinejoin="round" />
      <path d="M6.5 13.5a1.5 1.5 0 0 0 3 0" strokeLinecap="round" />
    </svg>
  )
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * PageHeader.
 *
 * What a screen says it is, and the buttons that act on the whole of it: a
 * title, a line under it, and the actions at the far end of the same row.
 * Every screen in the line opens with these three and every one of them set
 * the title in a different size, because `text-lg font-semibold` is the kind
 * of thing nobody looks up.
 *
 * The title is an `h1`. It is the one heading a screen is entitled to: the
 * shell's bar names the application and the rail names the destinations, so
 * this is the top of the content's outline, and a reader jumping by heading
 * lands here. `Container` below is the other half - the measure the content
 * under it is read at.
 */

export interface PageHeaderProps extends Omit<HTMLAttributes<HTMLElement>, 'title'> {
  title: ReactNode
  /** The line under the title. One sentence: this is the screen's subtitle,
   * not its documentation. */
  description?: ReactNode
  /** Buttons that act on the screen as a whole - New, Export, a filter. They
   * sit at the far end of the title's row and wrap under it when there is no
   * width left, rather than squeezing the title into two words. */
  actions?: ReactNode
  /** A trail, a status, a tab strip: whatever belongs between the heading and
   * the content. Drawn under the whole row. */
  children?: ReactNode
}

export function PageHeader({
  title,
  description,
  actions,
  className,
  children,
  ...props
}: PageHeaderProps) {
  return (
    <header className={cn('mb-4 flex flex-col gap-3', className)} {...props}>
      {/* `flex-wrap` and `items-start`: the actions drop to their own line on
          a narrow screen instead of the title truncating. A title is what the
          screen is; a button can wait a row. */}
      <div className="flex flex-wrap items-start justify-between gap-x-4 gap-y-2">
        <div className="flex min-w-0 flex-col gap-1">
          <h1 className="text-xl font-semibold tracking-tight text-text">{title}</h1>
          {description === undefined ? null : (
            <p className="text-sm text-dim">{description}</p>
          )}
        </div>
        {actions === undefined ? null : (
          <div className="flex shrink-0 flex-wrap items-center gap-2">{actions}</div>
        )}
      </div>
      {children}
    </header>
  )
}

export const containerVariants = cva('mx-auto w-full min-w-0', {
  variants: {
    /*
     * How wide the content is allowed to get.
     *
     * A measure rather than a taste: text at more than about ninety
     * characters a line loses the reader on the way back to the left margin,
     * and a form whose fields run the width of a 32-inch monitor asks the eye
     * to travel between a label and its input.
     */
    width: {
      /* Reading and forms: settings, an article, a dialog's worth of fields
       * given a whole screen. */
      prose: 'max-w-[68ch]',
      /* The usual screen: a list, a card, a dashboard's columns. */
      default: 'max-w-5xl',
      /* Tables and boards, which are read by scanning down a column rather
       * than across a line, and are the worse for being penned in. */
      wide: 'max-w-7xl',
      /* No ceiling. For a screen that IS the window - a canvas, a map, a
       * timeline that earns every pixel it is given. */
      full: '',
    },
  },
  defaultVariants: { width: 'default' },
})

export interface ContainerProps
  extends HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof containerVariants> {}

/**
 * The measure the screen's content is read at.
 *
 * Width only, and deliberately: the padding belongs to `Screen`, which knows
 * whether it is scrolling and therefore whether a scrollbar is about to take
 * ten pixels off the right. A container that also padded would double it.
 */
export function Container({ width, className, ...props }: ContainerProps) {
  return <div className={cn(containerVariants({ width }), className)} {...props} />
}

import type { ReactNode } from 'react'
import { cn } from 'dowel-ui'
import { Select, SelectItem, SelectPopup, SelectTrigger, SelectValue } from './select'

/*
 * How many rows to a page.
 *
 * Its own file rather than a part of `Pagination`, because the two are needed
 * apart often enough: a list that scrolls for ever wants "how many to load at
 * a time" and no page buttons, and a table with a fixed page size wants the
 * buttons and no choice. Together they were also over the size gate, which
 * asked the right question.
 *
 * A `Select`, because the line has no native `<select>` anywhere - and this is
 * the control most likely to reintroduce one, since it is three numbers in a
 * box and looks like the case where it would not matter.
 */

export interface PageSizeProps {
  pageSize: number
  options?: number[]
  onPageSizeChange: (pageSize: number) => void
  /** Names the control for a screen reader, e.g. "Rows per page". */
  label: string
  /** The visible label, when there is room for one. */
  children?: ReactNode
  className?: string
}

export function PageSize({
  pageSize,
  options = [10, 25, 50, 100],
  onPageSizeChange,
  label,
  children,
  className,
}: PageSizeProps) {
  return (
    <div className={cn('flex items-center gap-2 text-sm text-dim', className)}>
      {children}
      <Select
        value={String(pageSize)}
        onValueChange={(value: unknown) => onPageSizeChange(Number(value))}
      >
        <SelectTrigger aria-label={label} className="w-auto min-w-16">
          <SelectValue />
        </SelectTrigger>
        <SelectPopup>
          {options.map((option) => (
            <SelectItem key={option} value={String(option)}>
              {option}
            </SelectItem>
          ))}
        </SelectPopup>
      </Select>
    </div>
  )
}

import { cn } from 'dowel-ui'
import { Button } from './button'

/*
 * Paging through a list, and choosing how much of it to see at once.
 *
 * The arithmetic is exported separately from the component for the same reason
 * `table-sort` is a file of its own: a product that pages on the server needs
 * the page numbers and not the buttons, and computing them a second time in a
 * different place is how the two disagree about where the last page ends.
 *
 * Two things this deliberately does not do.
 *
 * It does not fetch, and it does not slice. It is told the page and the total
 * and it says which page was asked for - because whether paging means an
 * `OFFSET` or an `Array.prototype.slice` is the product's business, and a
 * component that guesses gets it wrong for the other one.
 *
 * It does not show every page number. A list of forty pages drawn in full is a
 * row of forty targets nobody aims at; `pageWindow` gives first, last, the
 * neighbourhood of the current page, and a gap where the rest were.
 *
 * How many rows to a page is next door, in `PageSize`. They are two controls
 * that usually sit together and are needed apart often enough to be separate:
 * a list that scrolls for ever wants "how many to load at a time" and no page
 * buttons, and a table with a fixed page size wants the buttons and no choice.
 */

/** A step in the row of pages: a page to go to, or the gap where pages were
 * left out. The gap is not a page and is never clickable - rendering it as a
 * disabled button gives a keyboard three stops that lead nowhere. */
export type PageStep = number | 'gap'

/** How many pages a list of this size has. At least one: a list with nothing
 * in it is on page 1 of 1, not page 1 of 0, and the second reads as broken. */
export function pageCount(total: number, pageSize: number): number {
  if (pageSize <= 0) return 1
  return Math.max(1, Math.ceil(total / pageSize))
}

/** The row of pages to draw: first, last, the current page and its
 * neighbours, with a gap standing in for the rest.
 *
 * `around` is how many pages sit either side of the current one. The row keeps
 * a steady width as the reader pages through it, because a row that grows and
 * shrinks moves the buttons under the pointer.
 */
export function pageWindow(page: number, pages: number, around = 1): PageStep[] {
  const total = Math.max(1, pages)
  const current = Math.min(Math.max(1, page), total)

  // How many places the row has: first, last, a gap at each end, and the
  // neighbourhood between them. This is the number the row always fills.
  const width = around * 2 + 5
  if (total <= width) {
    return Array.from({ length: total }, (_, index) => index + 1)
  }

  /* The row is built to a fixed number of places, and that is the whole
   * difficulty. A window of a fixed number of *pages* looks right in the
   * middle and comes up short at the ends, where one of the gaps is not
   * needed: the row loses a place, and the "next" button moves as you use it.
   *
   * So the run of middle pages is grown to whatever fills the row - which
   * depends on how many gaps there are, which depends on where the run sits.
   * Rather than iterate towards that (it oscillates on the pages either side
   * of an end, where dropping a gap moves the run and moving the run brings
   * the gap back), each possible number of gaps is tried and the one that
   * describes itself is kept.
   */
  for (const gaps of [2, 1, 0]) {
    // Places for pages: the row, less the two ends, less the gaps.
    const run = width - 2 - gaps
    if (run > total - 2) continue
    // Centre the run on the current page, then slide it inside the ends. The
    // clamp is what pushes the neighbourhood away from an edge rather than
    // clipping it there.
    let from = Math.min(Math.max(2, current - Math.floor((run - 1) / 2)), total - run)

    // A gap that stands for a single page is a lie that costs a click: `1 … 3`
    // hides only page 2, which the row had room for. The fix is to slide the
    // run onto the end rather than to drop the page: leaving it out silently
    // is worse than the gap, because then the row says 1 is followed by 3 and
    // gives no sign that anything is missing.
    if (from === 3) from = 2
    if (from + run - 1 === total - 2) from += 1
    const to = from + run - 1

    const before = from > 2
    const after = to < total - 1
    if (Number(before) + Number(after) !== gaps) continue

    const steps: PageStep[] = [1]
    if (before) steps.push('gap')
    for (let page = from; page <= to; page += 1) steps.push(page)
    if (after) steps.push('gap')
    steps.push(total)
    return steps
  }

  // Unreachable for `total > width`: with no gaps the run covers every middle
  // page, which is the case handled above. Kept so the function has an answer
  // for every input rather than an implicit `undefined`.
  return Array.from({ length: total }, (_, index) => index + 1)
}

/** Which rows this page holds: `[from, to]`, counting from one, for the "1-20
 * of 97" a reader is shown. `to` is clamped to the total, so the last page
 * says what it actually holds rather than what a full page would. */
export function pageRange(page: number, pageSize: number, total: number): [number, number] {
  if (total <= 0) return [0, 0]
  const from = (page - 1) * pageSize + 1
  return [from, Math.min(page * pageSize, total)]
}

export interface PaginationProps {
  page: number
  pageSize: number
  total: number
  onPageChange: (page: number) => void
  /** How many pages either side of the current one. */
  around?: number
  /** What a screen reader hears for the region and its buttons. Required
   * rather than defaulted: a default here would be English shipped inside a
   * primitive, and these are the only words the control has. */
  labels: PaginationLabels
  className?: string
}

export interface PaginationLabels {
  /** Names the whole control, e.g. "Pages". */
  region: string
  previous: string
  next: string
  /** Names one page button. Given the number, because "Page 3" is a sentence
   * only the product's language can build. */
  page: (page: number) => string
}

export function Pagination({
  page,
  pageSize,
  total,
  onPageChange,
  around = 1,
  labels,
  className,
}: PaginationProps) {
  const pages = pageCount(total, pageSize)
  const current = Math.min(Math.max(1, page), pages)
  const steps = pageWindow(current, pages, around)

  return (
    <nav aria-label={labels.region} className={cn('flex items-center gap-1', className)}>
      <Button
        variant="ghost"
        size="sm"
        aria-label={labels.previous}
        disabled={current <= 1}
        onClick={() => onPageChange(current - 1)}
      >
        ‹
      </Button>

      {steps.map((step, index) =>
        step === 'gap' ? (
          // Not a button, and not `aria-hidden` either: the gap is real
          // information - there are pages here that are not shown - and a
          // reader that skips it hears a jump from 2 to 40 with no reason.
          <span
            // The index is the key on purpose: two gaps in a row are
            // indistinguishable, and there is never more than one at each end.
            key={`gap-${index}`}
            className="px-1 text-dim select-none"
          >
            …
          </span>
        ) : (
          <Button
            key={step}
            variant={step === current ? 'primary' : 'ghost'}
            size="sm"
            // The current page is announced, not only coloured. `aria-current`
            // rather than `aria-selected`, which belongs to a listbox.
            aria-current={step === current ? 'page' : undefined}
            aria-label={labels.page(step)}
            onClick={() => onPageChange(step)}
            className="tabular-nums"
          >
            {step}
          </Button>
        ),
      )}

      <Button
        variant="ghost"
        size="sm"
        aria-label={labels.next}
        disabled={current >= pages}
        onClick={() => onPageChange(current + 1)}
      >
        ›
      </Button>
    </nav>
  )
}

import type { HTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Panel.
 *
 * The raised surface everything else sits on. It is the one place a screen
 * gets its structure from, so it stays deliberately plain: a ground, a
 * hairline, a corner.
 *
 * The two products it came from disagreed about that corner - one used 16px,
 * the other 12px, for the component with the same name and the same purpose.
 * It is `lg` here, and `SectionLabel` is included because a panel almost
 * always has one and every product wrote its own.
 */
export const panelVariants = cva('bg-raise', {
  variants: {
    variant: {
      /* The default: a surface that sits on the page. */
      raised: 'rounded-lg border border-line',
      /* For something that has left the page - a menu, a popover. The shadow
       * is what says how far away it is. */
      floating: 'rounded-lg border border-line shadow-raise',
      /* Inside another panel, where a second border would be a box in a box. */
      inset: 'rounded-inner bg-soft',
    },
  },
  defaultVariants: { variant: 'raised' },
})

export interface PanelProps
  extends HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof panelVariants> {}

export function Panel({ variant, className, ...props }: PanelProps) {
  return <div className={cn(panelVariants({ variant }), className)} {...props} />
}

/**
 * The small uppercase caption above a block of content.
 *
 * Its tracking is the one the products argued about - 0.08em in six files and
 * 0.09em in three - and it is a token now, so the argument cannot recur.
 */
export function SectionLabel({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        'flex items-center gap-2 text-2xs font-medium uppercase tracking-caption text-faint',
        className,
      )}
      {...props}
    />
  )
}

import { useId, useState, type Ref } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * PasswordField - a password, and the button that shows it.
 *
 * The reveal is the whole component, and it is not a convenience. A masked
 * field is the only one in a form where a typo cannot be seen, so people
 * either paste (fine) or type slowly and get it wrong anyway; the toggle is
 * what turns an unverifiable field into a checkable one, and it is why long
 * passphrases became usable at all.
 *
 * What it costs is a moment where the password is on the screen, so the
 * component states its two rules rather than leaving them to each product:
 *
 *   - it always starts masked, and there is no prop to start it revealed;
 *   - revealing is the reader's own action, never a default and never
 *     something a form can turn on for them.
 *
 * The button is a real button with a real name, and the name changes with the
 * state - "Show password" / "Hide password". That is what a screen reader
 * announces, and it is the one place the component needs words, so they are
 * required props. A default here would ship English inside a primitive.
 *
 * `autoComplete` is not defaulted either. The right value is the product's
 * to know: `current-password` on a login, `new-password` on a sign-up, and
 * getting it wrong is how a password manager fills the wrong box.
 */

export interface PasswordFieldProps {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** What the reveal button is called while the password is hidden. */
  showLabel: string
  /** ...and while it is showing. */
  hideLabel: string
  /** `current-password` for a login, `new-password` for a sign-up. */
  autoComplete?: string
  placeholder?: string
  disabled?: boolean
  readOnly?: boolean
  required?: boolean
  name?: string
  id?: string
  ref?: Ref<HTMLInputElement>
  'aria-label'?: string
  'aria-describedby'?: string
  className?: string
}

export function PasswordField({
  value,
  defaultValue,
  onValueChange,
  showLabel,
  hideLabel,
  className,
  disabled,
  ref,
  ...props
}: PasswordFieldProps) {
  /* Always false to begin with. Deliberately local state with no prop to set
   * it: a password that arrives on screen without the reader asking is the
   * one failure this component must not have. */
  const [revealed, setRevealed] = useState(false)
  const inputId = useId()

  return (
    <div
      className={cn(
        fieldClasses,
        'flex h-control items-stretch overflow-hidden p-0',
        'focus-within:outline-2 focus-within:outline-offset-0 focus-within:outline-accent',
        className,
      )}
    >
      <input
        {...props}
        ref={ref}
        id={props.id ?? inputId}
        type={revealed ? 'text' : 'password'}
        value={value}
        defaultValue={defaultValue}
        disabled={disabled}
        onChange={(event) => onValueChange?.(event.target.value)}
        className={cn(
          'w-full min-w-0 bg-transparent px-2.5 text-sm text-text placeholder:text-faint',
          'outline-none disabled:cursor-not-allowed',
        )}
      />

      <button
        type="button"
        // Not a submit button, and not in the tab order ahead of the field it
        // belongs to - it sits after the input, which is where Tab reaches it.
        onClick={() => setRevealed((was) => !was)}
        disabled={disabled}
        aria-label={revealed ? hideLabel : showLabel}
        aria-pressed={revealed}
        aria-controls={props.id ?? inputId}
        className={cn(
          'flex w-9 shrink-0 items-center justify-center text-dim',
          'transition-colors hover:bg-soft hover:text-text',
          'focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent',
          'disabled:pointer-events-none disabled:opacity-50',
        )}
      >
        {revealed ? (
          /* An eye with a stroke through it: hiding is the action offered
           * while the password is visible. */
          <svg viewBox="0 0 20 20" className="size-4" fill="none" aria-hidden>
            <path
              d="M4 4l12 12M8.5 8.7a2 2 0 002.8 2.8M6.3 6.4C4.4 7.5 3 9.2 2.5 10c1.2 2.2 4 5 7.5 5 1.3 0 2.5-.4 3.5-1M9 5.1c.3 0 .7-.1 1-.1 3.5 0 6.3 2.8 7.5 5-.3.5-.8 1.3-1.6 2.1"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          </svg>
        ) : (
          <svg viewBox="0 0 20 20" className="size-4" fill="none" aria-hidden>
            <path
              d="M2.5 10C3.7 7.8 6.5 5 10 5s6.3 2.8 7.5 5c-1.2 2.2-4 5-7.5 5s-6.3-2.8-7.5-5z"
              stroke="currentColor"
              strokeWidth="1.5"
            />
            <circle cx="10" cy="10" r="2.2" stroke="currentColor" strokeWidth="1.5" />
          </svg>
        )}
      </button>
    </div>
  )
}

import { Popover as Base } from '@base-ui/react/popover'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Popover.
 *
 * A panel anchored to the thing that opened it, for content that belongs
 * beside a control rather than in the middle of the screen: a filter, a small
 * form, a menu of settings that is not a menu.
 *
 * Where Dialog is centred and covers the page, this one is placed, and the
 * placing is the part that is easy to get wrong. It goes through a Positioner
 * between the Portal and the Popup - Base UI measures the trigger, measures
 * the popup, and flips or shifts it when the preferred side does not fit. So
 * `side` and `align` are a preference, not an instruction, and a popover near
 * the bottom of the window will come out above its trigger. That is the
 * behaviour worth having; a popover that stays where it was told is a popover
 * half off the screen.
 *
 * `sideOffset` is a distance from the anchor and belongs to the Positioner,
 * not the Popup, so it is taken here and passed inward. The Arrow is optional
 * and sits inside the Popup, where Base UI rotates it to whichever side the
 * popup actually landed on.
 *
 * It is not modal. The page underneath stays live, and focus is not trapped -
 * which is right for a panel beside a control and wrong for a decision.
 */

export const popoverPopupVariants = cva(
  [
    'rounded-lg border border-line bg-raise p-4 text-text shadow-raise',
    'focus-visible:outline-none',
    // The enter and the leave. `duration-*` reads the token directly because
    // Tailwind's own utility takes a literal number.
    '[transition:opacity_var(--duration-quick)_var(--ease-out),transform_var(--duration-quick)_var(--ease-out)]',
    'data-[closed]:scale-[0.97] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.97] data-[starting-style]:opacity-0',
    // Grow out of the edge it is anchored to rather than out of its own
    // middle, so the motion points back at the trigger.
    'origin-[var(--transform-origin)]',
  ],
  {
    variants: {
      size: {
        sm: 'w-[min(16rem,calc(100vw-2rem))]',
        md: 'w-[min(20rem,calc(100vw-2rem))]',
        lg: 'w-[min(28rem,calc(100vw-2rem))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `PopoverTrigger`. */
export const Popover = Base.Root

/** What opens it, and what the popup is measured against. */
export const PopoverTrigger = Base.Trigger

/** What closes it, for a button inside the panel. */
export const PopoverClose = Base.Close

export interface PopoverPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof popoverPopupVariants> {
  /** Preferred side of the trigger. Base UI flips it when it does not fit,
   * and defaults it to the bottom. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. Base UI centres it by default. */
  align?: Base.Positioner.Props['align']
  /** Distance from the trigger, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /** Whether to draw the arrow pointing back at the trigger. */
  arrow?: boolean
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by an ancestor. Pass an element to put it
   * somewhere else - inside an overlay that is already open, or into a
   * container being screenshotted. */
  container?: Base.Portal.Props['container']
}

/** The panel. Portalled and positioned, so it is not clipped by an ancestor
 * with `overflow: hidden` - which is where most anchored popups go to die.
 *
 * `side` and `align` are passed straight through rather than defaulted here:
 * Base UI's own defaults are already bottom and centre, and writing them out
 * again would be one more place for the two to disagree. */
export function PopoverPopup({
  size,
  side,
  align,
  sideOffset = 8,
  arrow = true,
  container,
  className,
  children,
  ...props
}: PopoverPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        className="[z-index:var(--z-floating)]"
      >
        <Base.Popup className={cn(popoverPopupVariants({ size }), className)} {...props}>
          {arrow ? <PopoverArrow /> : null}
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

/** The notch pointing back at the trigger. Base UI rotates it to whatever side
 * the popup landed on, which is why the rotation is keyed off `data-side`
 * rather than off the `side` that was asked for. */
export function PopoverArrow({ className, ...props }: Base.Arrow.Props) {
  return (
    <Base.Arrow
      className={cn(
        'h-2 w-2 rotate-45 border border-line bg-raise',
        'data-[side=bottom]:-top-1 data-[side=bottom]:border-r-0 data-[side=bottom]:border-b-0',
        'data-[side=top]:-bottom-1 data-[side=top]:border-t-0 data-[side=top]:border-l-0',
        'data-[side=left]:-right-1 data-[side=left]:border-b-0 data-[side=left]:border-l-0',
        'data-[side=right]:-left-1 data-[side=right]:border-r-0 data-[side=right]:border-t-0',
        className,
      )}
      {...props}
    />
  )
}

/** The heading. Base UI points the popup's `aria-labelledby` at it, so a
 * popover with one is named for a screen reader without anyone arranging it. */
export function PopoverTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-sm font-semibold', className)} {...props} />
}

/** The line under the heading, and the popup's `aria-describedby`. */
export function PopoverDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-1 text-sm text-dim', className)} {...props} />
}

import { PreviewCard as Base } from '@base-ui/react/preview-card'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * PreviewCard.
 *
 * The card that appears when a link is hovered: who the author is, what the
 * issue says, what is behind the URL. Rich content - an avatar, a few lines,
 * a figure or two - rather than the phrase a Tooltip holds.
 *
 * Positioned the same way a Popover is, through a Positioner between the
 * Portal and the Popup, so it flips and shifts to stay on screen. What differs
 * is how it opens: hovering the trigger, after a delay, and it stays open
 * while the pointer travels from the link to the card. That last part is the
 * whole trick - a card that vanishes when the pointer leaves the link cannot
 * be read, let alone clicked into.
 *
 * Same warning as Tooltip, and for the same reason. Base UI treats this as a
 * visual enhancement for sighted mouse and keyboard users: it is not reachable
 * on a touch screen and not announced by a screen reader. So NOTHING IN THE
 * CARD MAY BE THE ONLY PLACE IT APPEARS. Everything in it has to also be on
 * the page the link goes to - the card is a shortcut for people who can see
 * it, never the delivery mechanism for the information itself.
 *
 * If the content has to be reachable by everyone, this is the wrong component;
 * a Popover opened from a real button is the right one.
 */

export const previewCardPopupVariants = cva(
  [
    'rounded-lg border border-line bg-raise p-4 text-sm text-text shadow-raise',
    'focus-visible:outline-none',
    // The enter and the leave. `duration-*` reads the token directly because
    // Tailwind's own utility takes a literal number.
    '[transition:opacity_var(--duration-base)_var(--ease-out),transform_var(--duration-base)_var(--ease-out)]',
    'data-[closed]:scale-[0.97] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.97] data-[starting-style]:opacity-0',
    // Grow out of the edge it is anchored to rather than out of its own
    // middle, so the motion points back at the link.
    'origin-[var(--transform-origin)]',
  ],
  {
    variants: {
      size: {
        sm: 'w-[min(18rem,calc(100vw-2rem))]',
        md: 'w-[min(22rem,calc(100vw-2rem))]',
        lg: 'w-[min(28rem,calc(100vw-2rem))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `PreviewCardTrigger`. */
export const PreviewCard = Base.Root

/** The link the card previews. Usually rendered as the anchor itself, so it
 * stays a real link: it navigates, it opens in a new tab, and a screen reader
 * announces it as one - which is what the card cannot do. Takes `delay`. */
export const PreviewCardTrigger = Base.Trigger

export interface PreviewCardPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof previewCardPopupVariants> {
  /** Preferred side of the link. Base UI flips it when it does not fit, and
   * defaults it to the bottom. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. Base UI centres it by default. */
  align?: Base.Positioner.Props['align']
  /** Distance from the link, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /** Whether to draw the arrow pointing back at the link. */
  arrow?: boolean
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by an ancestor. Pass an element to put it
   * somewhere else - inside an overlay that is already open, or into a
   * container being screenshotted. */
  container?: Base.Portal.Props['container']
}

/** The card. Portalled and positioned, so it is not clipped by the paragraph
 * the link sits in. */
export function PreviewCardPopup({
  size,
  side,
  align,
  sideOffset = 8,
  arrow = true,
  container,
  className,
  children,
  ...props
}: PreviewCardPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        className="[z-index:var(--z-floating)]"
      >
        <Base.Popup className={cn(previewCardPopupVariants({ size }), className)} {...props}>
          {arrow ? <PreviewCardArrow /> : null}
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

/** The notch pointing back at the link. Base UI rotates it to whatever side
 * the card landed on, which is why the placement is keyed off `data-side`
 * rather than off the `side` that was asked for. */
export function PreviewCardArrow({ className, ...props }: Base.Arrow.Props) {
  return (
    <Base.Arrow
      className={cn(
        'h-2 w-2 rotate-45 border border-line bg-raise',
        'data-[side=bottom]:-top-1 data-[side=bottom]:border-r-0 data-[side=bottom]:border-b-0',
        'data-[side=top]:-bottom-1 data-[side=top]:border-t-0 data-[side=top]:border-l-0',
        'data-[side=left]:-right-1 data-[side=left]:border-b-0 data-[side=left]:border-l-0',
        'data-[side=right]:-left-1 data-[side=right]:border-r-0 data-[side=right]:border-t-0',
        className,
      )}
      {...props}
    />
  )
}

import { useId } from 'react'
import { cn } from 'dowel-ui'
import { markLevel, marks, type MarkName } from 'dowel-ui/marks'

/*
 * ProductMark - a product's mark from the lacodda line, drawn at the level its
 * size calls for.
 *
 * Every product of the line has one mark, a hexagonal tile with a two-letter
 * code, in three levels that are a rule rather than options: from 64px it
 * carries the product's metaphor under the code, from 28px it is the code
 * alone and larger, and at 27px and under it is the tile filled with the
 * product's colour and a heavy code - a metaphor at sixteen pixels is noise,
 * and a thin outline disappears. A product that drew its own mark picked one
 * level and used it at every size, so the same mark was a smudge in the tab
 * strip and a bare tile on the About screen. Here the size is the only input,
 * and the level follows.
 *
 * The masters are the line's, drawn by its mark generator and shipped in the
 * package (`dowel-ui/marks`); nothing is redrawn here. The tile is dark in
 * both themes, as the line draws it everywhere - the mark is the product's
 * signature, not part of the screen's palette.
 *
 * A mark beside the product's name is decoration and is hidden from a reader,
 * who already has the name. Given `label`, it becomes an image with that name,
 * for the places where the mark stands alone.
 */

export interface ProductMarkProps {
  /** Which mark: a product of the line, or `lacodda` for the line itself. */
  product: MarkName
  /** Its width and height in CSS pixels, which also choose its level. */
  size?: number
  /** Its name, when nothing next to it says which product it is. */
  label?: string
  className?: string
}

export function ProductMark({ product, size = 24, label, className }: ProductMarkProps) {
  // SVG ids are global to the document, and a two-colour mark names its
  // gradient: two such marks on one screen would share the first one's. The
  // id React makes is unique, but carries characters an `url(#...)` reference
  // does not tolerate everywhere.
  const id = `mark-${useId().replace(/[^a-zA-Z0-9_-]/g, '')}`
  const markup = marks[product][markLevel(size)].replaceAll('{{id}}', id)

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 100 100"
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      data-mark={product}
      data-level={markLevel(size)}
      className={cn('shrink-0', className)}
      dangerouslySetInnerHTML={{ __html: markup }}
    />
  )
}

/** The line's own mark - λ on a graphite tile - for the places that say a
 * product belongs to the lacodda line. */
export function LineMark(props: Omit<ProductMarkProps, 'product'>) {
  return <ProductMark product="lacodda" {...props} />
}

import { cn } from 'dowel-ui'
import type { MarkName } from 'dowel-ui/marks'
import { Menu, MenuItem, MenuPopup, MenuTrigger } from './menu'
import { ProductMark } from './product-mark'

/*
 * ProductSwitcher - the way from one product of the line to the next.
 *
 * The line's products are meant to be used together: kasl-server reads what
 * kasl records, rigger plans what furca commits, a note in scheda cites a
 * track in lyrid. A person moving between them was typing addresses from
 * memory. This is the one place that knows where the others are - the current
 * product's small tile and name on the trigger, and the others in a menu, each
 * with its own tile, so the colour a person already knows the product by is
 * what they look for.
 *
 * The component knows nothing about where a product lives: the list, its
 * order and every address come from the caller, because which products a
 * person has, and on which host, is the deployment's to say. An entry with
 * `href` is a link - it opens with a middle click in a new tab, which a person
 * moving between web products expects - and one with `onSelect` is an action,
 * for a desktop product that opens another by launching it.
 *
 * The current product is not in the menu. It is on the trigger; listing it
 * again offers a choice that changes nothing.
 */

export interface SwitcherProduct {
  product: MarkName
  /** The name, as the product writes it. */
  name: string
  /** A few words on what it is, under the name. */
  description?: string
  /** Where it lives. */
  href?: string
  /** What choosing it does, when it is not a place to go. */
  onSelect?: () => void
}

export interface ProductSwitcherProps {
  /** The product this is. */
  current: MarkName
  /** Its name, shown on the trigger. */
  currentName: string
  /** The others, in the order to offer them. */
  products: SwitcherProduct[]
  /** What the trigger does, for a reader: "Switch product". */
  label: string
  className?: string
}

export function ProductSwitcher({ current, currentName, products, label, className }: ProductSwitcherProps) {
  return (
    <Menu>
      <MenuTrigger
        className={cn(
          'inline-flex h-8 cursor-default items-center gap-2 rounded-md px-2 text-sm font-semibold text-text',
          'transition-colors duration-quick hover:bg-soft data-[popup-open]:bg-soft',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
          className,
        )}
      >
        <ProductMark product={current} size={18} />
        <span>{currentName}</span>
        {/* The name a reader hears is the visible one and then what the
            button does; a space of its own keeps the two words apart. */}
        {' '}
        <span className="sr-only">{label}</span>
        <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.2" aria-hidden className="text-faint">
          <path d="M2 3.5l3 3 3-3" />
        </svg>
      </MenuTrigger>
      <MenuPopup align="start" className="min-w-60">
        {products
          .filter((entry) => entry.product !== current)
          .map((entry) => (
            <MenuItem
              key={entry.product}
              onClick={entry.onSelect}
              render={entry.href ? <a href={entry.href} /> : undefined}
              className="gap-2.5 py-1.5"
            >
              <ProductMark product={entry.product} size={20} />
              <span className="flex min-w-0 flex-col">
                <span className="truncate text-text">{entry.name}</span>
                {entry.description && <span className="truncate text-xs text-dim">{entry.description}</span>}
              </span>
            </MenuItem>
          ))}
      </MenuPopup>
    </Menu>
  )
}

import { Progress as Base } from '@base-ui/react/progress'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * How far along something is.
 *
 * The distinction the component is built on, and the one products collapse:
 *
 *   **determinate** - the fraction is known. The bar fills to it, and a reader
 *   can tell how long is left.
 *
 *   **indeterminate** - something is happening and nobody knows how much is
 *   left. The bar says exactly that, by moving without filling.
 *
 * Collapsing them means picking a number that is not true - a bar that creeps
 * to 90% and waits there is the commonest version, and it is a lie the reader
 * learns to distrust, after which no progress bar in the product means
 * anything. `value={undefined}` is the honest answer, and it is the default.
 *
 * Base UI carries the role, the announcement and the value clamping. What is
 * here is the clothes, and the rule about which of the two states is drawn.
 *
 * Not a Spinner. A spinner says "working" in a corner; this says "working, and
 * here is the shape of it" across a width. Where the shape of what is coming
 * is known, a Skeleton says more than either.
 */

export const progressVariants = cva('w-full overflow-hidden rounded-full bg-soft', {
  variants: {
    size: {
      sm: 'h-1',
      md: 'h-2',
    },
    tone: {
      accent: '',
      good: '',
      warn: '',
      bad: '',
    },
  },
  defaultVariants: { size: 'md', tone: 'accent' },
})

const fillVariants = cva('h-full rounded-full transition-[width] duration-base', {
  variants: {
    tone: {
      accent: 'bg-accent',
      good: 'bg-good',
      warn: 'bg-warn',
      bad: 'bg-bad',
    },
  },
  defaultVariants: { tone: 'accent' },
})

/* The stripes take their colour from `currentColor`, so the tone arrives as a
 * text colour rather than a background - the same four names, said the other
 * way round. */
const stripeVariants = cva('h-full w-full rounded-full opacity-40', {
  variants: {
    tone: {
      accent: 'text-accent',
      good: 'text-good',
      warn: 'text-warn',
      bad: 'text-bad',
    },
  },
  defaultVariants: { tone: 'accent' },
})

export interface ProgressProps
  extends Omit<Base.Root.Props, 'className' | 'value'>,
    VariantProps<typeof progressVariants> {
  /** The fraction done, 0 to `max`. Leave it out when it is not known - that
   * is not a missing value but a different, honest state. */
  value?: number | null
  max?: number
  /** What is progressing, for a screen reader. Required: a bar with no name is
   * announced as a percentage of nothing, and the word belongs to the product. */
  label: string
  className?: string
  /** A visible label beside the bar, when there is room. */
  children?: React.ReactNode
}

export function Progress({
  value,
  max = 100,
  size,
  tone,
  label,
  className,
  children,
  ...props
}: ProgressProps) {
  const indeterminate = value === undefined || value === null

  return (
    <Base.Root
      value={indeterminate ? null : value}
      max={max}
      aria-label={label}
      className={cn('flex w-full flex-col gap-1.5', className)}
      {...props}
    >
      {children !== undefined && (
        <div className="flex items-baseline justify-between text-xs text-dim">
          {children}
          {/* The number only where there is one. Showing "0%" for an unknown
            * amount is the same lie as a bar that creeps to 90%. */}
          {!indeterminate && (
            <span className="tabular-nums">{Math.round((value / max) * 100)}%</span>
          )}
        </div>
      )}

      <Base.Track className={cn(progressVariants({ size, tone }))}>
        {indeterminate ? (
          /* Stripes across the whole track, not a filled bar.
           *
           * A full-width fill was the first version and it was wrong in the
           * one way that matters: measured on the stand, it drew 384px of a
           * 384px track - a reader glancing at it sees "done", which is the
           * opposite of what the state means. Pulsing did not rescue it, and
           * under `prefers-reduced-motion` the pulse stops and a solid,
           * complete-looking bar is all that remains.
           *
           * Stripes cannot be read as a fraction at all: there is no edge to
           * take for a boundary. They are drawn with a gradient rather than a
           * `@keyframes` of their own, because a name in the theme is a
           * contract the line carries forever - and this needs no animation to
           * say what it says. */
          <div
            className={cn(stripeVariants({ tone }))}
            style={{
              backgroundImage:
                'repeating-linear-gradient(45deg, currentColor 0 6px, transparent 6px 12px)',
            }}
          />
        ) : (
          <Base.Indicator className={cn(fillVariants({ tone }))} />
        )}
      </Base.Track>
    </Base.Root>
  )
}

import type { ReactNode } from 'react'
import { EmptyState } from './empty-state'
import { SkeletonList } from './skeleton'

/*
 * The three screens between asking for data and showing it.
 *
 * Every list in every product writes the same ladder - loading, then failed,
 * then nothing found, then the content - and writes it slightly differently
 * each time. What differs is never deliberate: one screen forgets the empty
 * case, another shows a spinner where the shape was known, a third prints the
 * raw error object. This is that ladder, once.
 *
 * **It takes values, not a query.** `useQuery` from TanStack Query hands back
 * `isPending` and `error`, and those are ordinary values - so this component
 * asks for them rather than for the query result, and works the same with SWR,
 * with a reducer, or with two `useState` calls. Taking the result object would
 * put a library in the registry and therefore in every product that installs
 * this primitive, to save one line at the call site:
 *
 *     const works = useQuery({ queryKey, queryFn })
 *     <QueryState pending={works.isPending} error={works.error} empty={!works.data?.length} …>
 *
 * **The order of the cases is the component**, and it is the part that goes
 * wrong by hand: pending first, because a refetch that already has data should
 * not blank the screen; then error, because an error with stale data is still
 * an error; then empty, which is only knowable once something arrived.
 *
 * What it deliberately does not do is fetch, retry or cache. Those belong to
 * whatever owns the data - and a component that guessed at them would be
 * wrong for the product that owns them differently.
 */

export interface QueryStateProps {
  /** Nothing has arrived yet. */
  pending?: boolean
  /** It failed. Anything with a `message`, which is what every error library
   * agrees on - or a string, for a product that carries its own. */
  error?: { message: string } | string | null
  /** Something arrived, and it was nothing. Computed by the caller, because
   * only the caller knows whether empty means `[]`, `null` or a count of
   * zero. */
  empty?: boolean
  /** What stands in while pending. A shape, ideally - the default is a list,
   * because most screens are waiting for one, but a screen waiting for a card
   * should say so. */
  skeleton?: ReactNode
  /** What is shown when nothing came back. */
  emptyState?: ReactNode
  /** What is shown when it failed. Given the message, so a product can put it
   * where it likes - or ignore it. */
  errorState?: (message: string) => ReactNode
  /** The words on the default error screen. Required only in the sense that
   * the default screen needs them; pass `errorState` instead and they are
   * never read. */
  errorLabels?: { title: string; body?: string }
  children: ReactNode
}

export function QueryState({
  pending = false,
  error = null,
  empty = false,
  skeleton,
  emptyState,
  errorState,
  errorLabels,
  children,
}: QueryStateProps) {
  /* `aria-busy` on the wrapper, in every state.
   *
   * This is what tells a screen reader that the region is working, and it is
   * why the Skeletons themselves are `aria-hidden`: the fact belongs to the
   * region, said once, rather than to a dozen empty boxes announced as
   * content. */
  const wrap = (content: ReactNode) => <div aria-busy={pending || undefined}>{content}</div>

  // Pending first: a refetch that still holds data should not blank the screen
  // it is refreshing, and the caller decides that by passing `pending` only
  // when there is nothing to show.
  if (pending) return wrap(skeleton ?? <SkeletonList />)

  if (error) {
    const message = typeof error === 'string' ? error : error.message
    if (errorState) return wrap(errorState(message))
    return wrap(
      <EmptyState
        variant="error"
        title={errorLabels?.title ?? message}
        // The message is shown as the body when there is a title above it, and
        // as the title when there is not - so it is never lost, and never
        // printed twice.
        body={errorLabels?.title ? (errorLabels.body ?? message) : errorLabels?.body}
      />,
    )
  }

  // Empty last of the three: it is the only one that cannot be known until
  // something has arrived.
  if (empty && emptyState) return wrap(emptyState)

  return wrap(children)
}

import type { ReactNode } from 'react'
import { Radio as Base } from '@base-ui/react/radio'
import { RadioGroup as BaseGroup } from '@base-ui/react/radio-group'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * RadioGroup - one of a few, all of them visible.
 *
 * The rule for reaching for this rather than a Select is whether the options
 * are worth the space: a handful of short choices read faster laid out than
 * hidden behind a trigger, and each one becomes a target rather than a step.
 * Past about five, or when the labels are long, a Select is the honest
 * choice - this is not a Select with more pixels.
 *
 * The group is the control, not the button. That is what the arrow keys
 * follow, what a screen reader announces as one thing with a position in it,
 * and why `Radio` on its own is not exported: a radio outside a group is a
 * checkbox that cannot be unchecked.
 *
 * The dot is drawn rather than native, for the same reason as the tick in
 * Checkbox: a real `<input type=radio>` cannot be styled without
 * `appearance: none`, and after that the dot has to be drawn anyway.
 */

export interface RadioGroupProps {
  children: ReactNode
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  disabled?: boolean
  readOnly?: boolean
  required?: boolean
  name?: string
  /** Lay the options out in a row. For two or three short ones; a column is
   * the default because it stays readable as labels grow. */
  orientation?: VariantProps<typeof radioGroupVariants>['orientation']
  'aria-label'?: string
  className?: string
}

/* The layout lives in `cva` rather than in a destructured default, which is
 * how every other primitive here states one. It also keeps the word out of
 * the component's signature: a string default in a props list is how a
 * primitive ends up shipping English, and the gate that watches for that
 * cannot tell an enum value from a label. */
export const radioGroupVariants = cva('flex', {
  variants: {
    orientation: {
      vertical: 'flex-col gap-2',
      horizontal: 'flex-row flex-wrap gap-4',
    },
  },
  defaultVariants: { orientation: 'vertical' },
})

export function RadioGroup({ children, orientation, className, ...props }: RadioGroupProps) {
  return (
    <BaseGroup className={cn(radioGroupVariants({ orientation }), className)} {...props}>
      {children}
    </BaseGroup>
  )
}

export interface RadioProps {
  value: string
  /** The words next to the dot. */
  children?: ReactNode
  disabled?: boolean
  className?: string
}

export function Radio({ value, children, disabled, className }: RadioProps) {
  const dot = (
    <Base.Root
      value={value}
      disabled={disabled}
      className={cn(
        'flex size-4 shrink-0 items-center justify-center rounded-full border border-line-2 bg-transparent',
        'transition-colors',
        'hover:border-accent',
        'data-[checked]:border-accent',
        'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        'disabled:cursor-not-allowed disabled:opacity-50',
        children === undefined && className,
      )}
    >
      <Base.Indicator className="size-2 rounded-full bg-accent" render={<span />} />
    </Base.Root>
  )

  if (children === undefined) return dot

  return (
    <label
      className={cn(
        'flex cursor-pointer items-center gap-2 text-sm text-text',
        'has-[:disabled]:cursor-not-allowed has-[:disabled]:opacity-50',
        className,
      )}
    >
      {dot}
      {children}
    </label>
  )
}

import { useId, type KeyboardEvent } from 'react'
import { cn } from 'dowel-ui'

/*
 * RatingScale - a judgement on a short scale, and the absence of one.
 *
 * Generalised from kilna, where it is how a work is scored on each of its
 * axes. The shape is a row of marks rather than stars: stars carry a meaning
 * of their own - a review, a public verdict - and this is as often "how hard
 * was this" or "how finished is it" as it is "how good".
 *
 * The part worth keeping from the donor, and the reason this is not a Slider
 * with a small range: **not judged yet is a state, not a zero.** "I have not
 * scored this" and "I scored it nothing" are different facts, and a control
 * that collapses them makes the difference unrecoverable the moment it is
 * saved. So `value` is `number | undefined`, clicking the current mark clears
 * it, and Backspace does the same from the keyboard.
 *
 * One tab stop, arrows within it - the arrangement a radio group has. The
 * marks are not buttons: the container is the control, and a `<button>` inside
 * an element with `role="slider"` is a nested interactive control - axe calls
 * it out, and it is right, because assistive technology is not promised to
 * announce or reach the inner one. The donor had them as `aria-hidden`
 * buttons, which hides them from a reader without making them stop being
 * controls.
 *
 * So a mark is a plain element that happens to accept a click. Everything
 * that makes the control usable - the tab stop, the keyboard, the announced
 * value - belongs to the container, and the pointer is served by the marks.
 */

export interface RatingScaleProps {
  /** How many marks. */
  scale: number
  /** The score, or `undefined` for not judged yet. */
  value: number | undefined
  onValueChange: (value: number | undefined) => void
  /** What is being judged. Required: a bare row of marks names nothing, and
   * this is the only thing a screen reader has to go on. */
  label: string
  /** What a screen reader hears in place of a number when nothing is chosen.
   * Required rather than defaulted, because a default here would be English
   * shipped inside a primitive. */
  emptyLabel: string
  disabled?: boolean
  className?: string
}

export function RatingScale({
  scale,
  value,
  onValueChange,
  label,
  emptyLabel,
  disabled = false,
  className,
}: RatingScaleProps) {
  const id = useId()
  const marks = Math.max(1, Math.round(scale))

  const clamp = (next: number) => Math.min(Math.max(next, 0), marks)

  const step = (delta: number) => {
    if (disabled) return
    // From nothing, a step forward lands on the first mark and a step back on
    // the last - so either arrow starts scoring rather than doing nothing.
    const next = value === undefined ? (delta > 0 ? 1 : marks) : value + delta
    onValueChange(clamp(next))
  }

  const onKeyDown = (event: KeyboardEvent) => {
    if (disabled) return
    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowUp':
        event.preventDefault()
        step(1)
        break
      case 'ArrowLeft':
      case 'ArrowDown':
        event.preventDefault()
        step(-1)
        break
      case 'Home':
        event.preventDefault()
        onValueChange(0)
        break
      case 'End':
        event.preventDefault()
        onValueChange(marks)
        break
      case 'Backspace':
      case 'Delete':
        // The keyboard's way back to not judged. Without it the state is
        // reachable only by clicking the mark that is already chosen.
        event.preventDefault()
        onValueChange(undefined)
        break
      default:
        break
    }
  }

  return (
    <div
      id={id}
      role="slider"
      tabIndex={disabled ? -1 : 0}
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={marks}
      aria-valuenow={value}
      aria-valuetext={value === undefined ? emptyLabel : String(value)}
      aria-disabled={disabled || undefined}
      onKeyDown={onKeyDown}
      className={cn(
        'flex gap-hair rounded-md',
        'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        disabled && 'cursor-not-allowed opacity-50',
        className,
      )}
    >
      {Array.from({ length: marks }, (_, index) => {
        const mark = index + 1
        const filled = value !== undefined && mark <= value
        return (
          <span
            key={mark}
            // Deliberately not a button. The container is the control; a
            // nested one would be a second interactive element inside a
            // `slider`, which assistive technology is not promised to handle.
            aria-hidden
            // Clicking the mark already chosen clears the score. That is the
            // pointer's way back to not judged, and it is why a rating is not
            // a five-option radio group.
            onClick={() => {
              if (disabled) return
              onValueChange(value === mark ? undefined : mark)
            }}
            className={cn(
              'h-5 flex-1 rounded-sm transition-colors',
              disabled ? 'cursor-not-allowed' : 'cursor-pointer',
              filled ? 'bg-accent' : 'bg-soft',
              !disabled && (filled ? 'hover:bg-accent-2' : 'hover:bg-line-2'),
            )}
          />
        )
      })}
    </div>
  )
}

import { useState, type TimeHTMLAttributes } from 'react'
import { cn, useLocale } from 'dowel-ui'

/*
 * "3 minutes ago", in the application's language, over a date they can still read.
 *
 * The rule the component is built on: **relative time is a convenience, never
 * the only copy of the fact.** "Last week" is quicker to read than a date and
 * useless the moment the reader needs to say when something actually happened
 * - and they cannot get it back, because the page has thrown it away. So the
 * element is a `<time dateTime=…>` with the exact moment in its `title`: the
 * machine-readable value stays, hovering shows the real date, and copying the
 * text still yields something a person can act on.
 *
 * `Intl.RelativeTimeFormat` writes the phrase, which is the whole reason there
 * is no date library here. "yesterday", "3 недели назад", "in 2 months" - the
 * plural rules and the special words for the nearest units are the part a
 * hand-written version gets wrong first, and it gets it wrong only in the
 * languages its author does not read.
 *
 * What `Intl` does not decide is which unit to use: it is told "3" and
 * "weeks". Choosing between them is `relativeParts` below, and it is the one
 * piece of arithmetic here.
 *
 * Deliberately not self-updating. A component that re-renders every second to
 * keep "2 minutes ago" honest costs a timer per instance - a table of fifty
 * rows is fifty timers - to correct a number nobody is watching change. A
 * product that needs it re-renders the list on its own schedule; the `now`
 * prop is there so it can, and so tests are not written against the clock.
 */

/** The thresholds, largest unit first: how many seconds it takes to earn one,
 * and the unit `Intl` should be handed.
 *
 * A month is 30 days and a year is 365. Both are approximations, and they are
 * the right ones: this is a phrase saying roughly how long ago, and a reader
 * who needs the exact interval is reading the date in the `title` instead. */
const UNITS: [seconds: number, unit: Intl.RelativeTimeFormatUnit][] = [
  [60 * 60 * 24 * 365, 'year'],
  [60 * 60 * 24 * 30, 'month'],
  [60 * 60 * 24 * 7, 'week'],
  [60 * 60 * 24, 'day'],
  [60 * 60, 'hour'],
  [60, 'minute'],
  [1, 'second'],
]

/** How long ago, as a count and a unit: what `Intl.RelativeTimeFormat` needs.
 *
 * The sign is the one `Intl` wants - negative for the past - and the count is
 * rounded towards zero. Rounding to nearest is the tempting alternative and
 * says "in 1 hour" 31 minutes before the meeting; truncating never claims more
 * time has passed than has. */
export function relativeParts(
  from: Date | number | string,
  now: Date | number = Date.now(),
): [value: number, unit: Intl.RelativeTimeFormatUnit] {
  const then = new Date(from).getTime()
  const seconds = (then - new Date(now).getTime()) / 1000
  const magnitude = Math.abs(seconds)

  for (const [size, unit] of UNITS) {
    if (magnitude >= size) return [Math.trunc(seconds / size), unit]
  }
  // Under a second either way. Zero seconds rather than the smallest unit,
  // because `Intl` turns that into "now" in every language it knows.
  return [0, 'second']
}

/** The phrase alone, for a `title`, an `aria-label` or a string. */
export function formatRelative(
  from: Date | number | string,
  locale: string,
  now: Date | number = Date.now(),
  options?: Intl.RelativeTimeFormatOptions,
): string {
  const [value, unit] = relativeParts(from, now)
  return new Intl.RelativeTimeFormat(locale, { numeric: 'auto', ...options }).format(value, unit)
}

export interface RelativeTimeProps extends Omit<TimeHTMLAttributes<HTMLTimeElement>, 'title'> {
  /** The moment being described. A `Date`, epoch milliseconds, or an ISO
   * string - whichever the data already holds. */
  value: Date | number | string
  /** What counts as now. Given rather than read from the clock so a list can
   * re-render on its own schedule, and so a test is not written against the
   * time it runs at. */
  now?: Date | number
  /** The application's language by default - see `useLocale`. */
  locale?: string
  /** `'auto'` by default, which is what produces "yesterday" rather than "1
   * day ago" where the language has a word for it. Pass `'always'` for a
   * column where every row should read the same way. */
  numeric?: Intl.RelativeTimeFormatOptions['numeric']
  /** How the exact moment is written in the `title`. The application's own format
   * by default. */
  titleOptions?: Intl.DateTimeFormatOptions
}

export function RelativeTime({
  value,
  now,
  locale,
  numeric = 'auto',
  titleOptions = { dateStyle: 'medium', timeStyle: 'short' },
  className,
  ...props
}: RelativeTimeProps) {
  /* Read once, at mount, rather than in a default argument.
   *
   * `now = Date.now()` in the parameter list is the obvious spelling and is
   * impure: it is evaluated on every render, so "now" moves whenever the
   * parent happens to re-render and the phrase changes for reasons that have
   * nothing to do with this component. Caught by `react-hooks/purity`, and
   * worth keeping caught - a component that deliberately does not update
   * itself must not update itself by accident either.
   *
   * With `now` given, the state is initialised and never read, which is what a
   * product paging a list wants: every row is measured from the same moment. */
  const [mountedAt] = useState(() => Date.now())
  const language = useLocale(locale)
  const moment = new Date(value)
  const invalid = Number.isNaN(moment.getTime())

  if (invalid) {
    // A date that is not a date renders as nothing rather than as "Invalid
    // Date", which is a string no reader can do anything with and which looks
    // like a value. The `<time>` element with no `dateTime` says the same to a
    // machine: there is no moment here.
    return <time className={className} {...props} />
  }

  return (
    <time
      dateTime={moment.toISOString()}
      // The fact itself, kept. The phrase above it is the convenience.
      title={new Intl.DateTimeFormat(language, titleOptions).format(moment)}
      className={cn('whitespace-nowrap', className)}
      {...props}
    >
      {formatRelative(moment, language, now ?? mountedAt, { numeric })}
    </time>
  )
}

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type HTMLAttributes,
  type PointerEvent as ReactPointerEvent,
} from 'react'
import { cn } from 'dowel-ui'

/*
 * Drag a row of a vertical list up or down to put it somewhere else.
 *
 * The columns in a column picker, the stops of a dial, the roles of a
 * profile. A hook and a grip rather than a list component: the rows are
 * already something else's - a menu's items, a form's fields - and a
 * component wrapping them would have to reproduce whatever that something
 * else does.
 *
 * Pointer events, not HTML5 drag-and-drop, for the reason given at
 * ColumnResizeHandle: a desktop shell that takes file drops never lets a
 * `dragstart` reach the page. The grip takes pointer capture on pointerdown,
 * so the rows underneath never see the drag and a menu's own highlighting
 * does not flicker down the list as the pointer crosses it.
 *
 * Nothing moves until the pointer is let go. Live reordering looks better
 * for a second and costs a write per crossed row - to a profile, that is a
 * request per row - and the row being dragged has already been picked up,
 * so the reader is watching the line that says where it lands. The hook
 * reports that line as `slot`, and the caller draws it.
 *
 * The keyboard's way is Alt with an arrow on the focused row. Plain arrows
 * are how a list is walked, and taking them for moving would leave no way
 * to walk it; the modifier is the one screen readers and editors already
 * use for "move this line".
 */

export interface ReorderOptions<K extends string> {
  /** The ids in their current order. Every row carries its id in
   * `data-reorder-id`, which `rowProps` sets. */
  order: readonly K[]
  /** Put `id` at index `to` of the resulting list. Called once per drop or
   * per keypress, never during a drag. */
  onMove: (id: K, to: number) => void
  disabled?: boolean
}

export interface Reorder<K extends string> {
  /** Spread on the element holding the rows: the rows are found under it.
   * A callback ref rather than a ref object, so that nothing ref-shaped is
   * handed back and the compiler does not take the whole result for one. */
  listProps: { ref: (element: HTMLElement | null) => void }
  /** The row being dragged, or null. */
  dragging: K | null
  /** Where a drop would go, as an insertion point: between the rows at
   * `slot - 1` and `slot`, in the order as it is. Null while nothing is
   * dragged, or while the drop would change nothing. */
  slot: number | null
  /** The insertion point's distance from the top of the list element, in
   * pixels, for drawing the line. */
  slotOffset: number | null
  /** Spread on the grip: the pointer path. */
  gripProps: (id: K) => (HTMLAttributes<HTMLElement>)
  /** Spread on the row: the id and the keyboard path. The `ref` is a
   * callback that returns its cleanup, as React 19 allows; a host that merges
   * refs and drops the cleanup leaves a listener on a node that is gone,
   * which is harmless. */
  rowProps: (id: K) => {
    'data-reorder-id': K
    ref: (row: HTMLElement | null) => void | (() => void)
  }
}

export function useReorder<K extends string>({ order, onMove, disabled }: ReorderOptions<K>): Reorder<K> {
  const listRef = useRef<HTMLElement | null>(null)
  const [dragging, setDragging] = useState<K | null>(null)
  // The slot and where to draw it, settled together in the move handler: the
  // boxes it is read from are refs, and refs are not for reading in render.
  const [drop, setDrop] = useState<{ slot: number; offset: number } | null>(null)
  // The rows' boxes as they were when the drag began; nothing moves during
  // it, so reading them once is reading them right.
  const boxes = useRef<{ top: number; bottom: number }[]>([])
  const listTop = useRef(0)

  // The slot under a pointer: how many rows have their middle above it.
  const slotAt = (y: number): number => {
    let count = 0
    for (const box of boxes.current) if ((box.top + box.bottom) / 2 < y) count += 1
    return count
  }

  // A slot is an insertion point in the list as drawn; the move wants the
  // index in the list as it will be, with the row gone from where it was.
  const destination = (from: number, at: number): number => (at > from ? at - 1 : at)

  const begin = (id: K, event: ReactPointerEvent<HTMLElement>) => {
    if (disabled || event.button !== 0) return
    const list = listRef.current
    if (list === null) return
    event.preventDefault()
    event.stopPropagation()

    listTop.current = list.getBoundingClientRect().top
    // By attribute rather than by selector, so an id needs no escaping.
    const rows = [...list.querySelectorAll<HTMLElement>('[data-reorder-id]')]
    boxes.current = order.map((rowId) => {
      const box = rows.find((row) => row.getAttribute('data-reorder-id') === rowId)?.getBoundingClientRect()
      return box ? { top: box.top, bottom: box.bottom } : { top: 0, bottom: 0 }
    })
    event.currentTarget.setPointerCapture(event.pointerId)
    setDragging(id)
    setDrop(null)
  }

  // The insertion point's distance from the top of the list: the top of the
  // row it goes before, or the bottom of the last row.
  const offsetOf = (at: number): number => {
    const rows = boxes.current
    const edge = at < rows.length ? rows[at]?.top : rows[rows.length - 1]?.bottom
    return (edge ?? 0) - listTop.current
  }

  const move = (id: K, event: ReactPointerEvent<HTMLElement>) => {
    if (dragging !== id) return
    const from = order.indexOf(id)
    const at = slotAt(event.clientY)
    // Dropping a row back where it is - the slot just above or just below
    // itself - is no move, and drawing a line there would promise one.
    setDrop(destination(from, at) === from ? null : { slot: at, offset: offsetOf(at) })
  }

  const end = (id: K, event: ReactPointerEvent<HTMLElement>) => {
    if (dragging !== id) return
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId)
    }
    const from = order.indexOf(id)
    const at = slotAt(event.clientY)
    const to = destination(from, at)
    setDragging(null)
    setDrop(null)
    if (event.type !== 'pointercancel' && to !== from) onMove(id, to)
  }

  // Rebuilt every render on purpose: they close over the drag state and the
  // order, and memoising them would mean listing both and getting one wrong.
  const gripProps = (id: K): HTMLAttributes<HTMLElement> => ({
    onPointerDown: (event) => begin(id, event),
    onPointerMove: (event) => move(id, event),
    onPointerUp: (event) => end(id, event),
    onPointerCancel: (event) => end(id, event),
    // The click the drop leaves behind must not reach the row: in a menu it
    // would toggle the item that was only meant to be moved.
    onClick: (event) => event.stopPropagation(),
  })

  // The keyboard path is a native listener on the row, not a React one. A
  // menu popup handles the arrow keys itself and stops them on the way up,
  // so a React `onKeyDown` on the item - dispatched from the root, above the
  // popup - never hears them; a listener on the row itself fires at the
  // target first, whatever the ancestors do afterwards. The listener reads
  // the row's id and the latest order off refs rather than closing over
  // them, so one stable callback serves every row and nothing is re-bound
  // on each render.
  const latest = useRef({ order, onMove, disabled })
  useEffect(() => {
    latest.current = { order, onMove, disabled }
  })

  const listen = useCallback((row: HTMLElement | null) => {
    if (row === null) return
    const onKeyDown = (event: KeyboardEvent) => {
      const { order: current, onMove: put, disabled: off } = latest.current
      if (off || !event.altKey) return
      const step = event.key === 'ArrowUp' ? -1 : event.key === 'ArrowDown' ? 1 : 0
      if (step === 0) return
      const id = row.getAttribute('data-reorder-id') as K | null
      if (id === null) return
      const to = current.indexOf(id) + step
      if (to < 0 || to >= current.length) return
      // Stopped here so the list's own arrow handling does not also walk the
      // focus off the row that was just moved.
      event.preventDefault()
      event.stopPropagation()
      put(id, to)
    }
    row.addEventListener('keydown', onKeyDown)
    return () => row.removeEventListener('keydown', onKeyDown)
  }, [])

  const rowProps = (id: K) => ({
    'data-reorder-id': id,
    ref: listen,
  })

  return {
    listProps: {
      ref: (element) => {
        listRef.current = element
      },
    },
    dragging,
    slot: drop?.slot ?? null,
    slotOffset: drop?.offset ?? null,
    gripProps,
    rowProps,
  }
}

/** The handle a row is picked up by. Decorative to a screen reader - the
 * keyboard path is on the row itself - so it carries no role and no label. */
export function ReorderGrip({ className, ...props }: HTMLAttributes<HTMLElement>) {
  return (
    <span
      aria-hidden
      data-reorder-grip
      className={cn(
        'inline-flex shrink-0 cursor-grab touch-none select-none text-faint',
        'active:cursor-grabbing [&_svg]:size-3.5',
        className,
      )}
      {...props}
    >
      <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden>
        <circle cx="6" cy="3.5" r="1.2" />
        <circle cx="10" cy="3.5" r="1.2" />
        <circle cx="6" cy="8" r="1.2" />
        <circle cx="10" cy="8" r="1.2" />
        <circle cx="6" cy="12.5" r="1.2" />
        <circle cx="10" cy="12.5" r="1.2" />
      </svg>
    </span>
  )
}

/** The line where a dragged row would land. Positioned by the caller from
 * `slotOffset`, inside the element `listProps` is on - which has to be
 * positioned itself. */
export function ReorderIndicator({ offset, className }: { offset: number | null; className?: string }) {
  if (offset === null) return null
  return (
    <div
      aria-hidden
      data-reorder-indicator
      className={cn('pointer-events-none absolute inset-x-1 h-0.5 -translate-y-px rounded-full bg-accent', className)}
      style={{ top: offset }}
    />
  )
}

import { useEffect, useState, type ReactNode } from 'react'
import { cn } from 'dowel-ui'
import { spinnerVariants } from './spinner'

/*
 * SaveState.
 *
 * The quiet line beside a field that saves itself: "saving…", then a tick that
 * fades. It exists because a form without a Save button has to say what it did
 * anyway - otherwise the reader is left guessing whether their edit survived,
 * and the usual answer to that guess is to press Ctrl+S at a page that has no
 * such thing.
 *
 * Taken from kilna, where it has been in production, with the two things a
 * primitive may not keep: its words (they came from the product's i18n, and a
 * component with a string of its own cannot be translated) and its icons.
 *
 * The rules it already got right, and which are the whole reason not to write
 * this fresh:
 *
 * - **The tick decays.** One that never leaves stops meaning "just now" and
 *   becomes furniture.
 * - **Only a real save earns one.** Mounting next to an idle mutation must not
 *   flash a tick for a save that happened before the reader arrived.
 * - **A failure is not a save.** It is announced elsewhere - a toast, an error
 *   on the field - and saying "saved" underneath that is worse than silence.
 * - **The width is held.** The line sits next to a field; if it grew and shrank
 *   with its own text, the layout would twitch on every keystroke's worth of
 *   saving.
 */

/** What the indicator is showing. `idle` is invisible but still occupies its
 * width. */
export type SaveStatus = 'idle' | 'saving' | 'saved'

/**
 * Turns "is a mutation in flight" into the three states this shows.
 *
 * Only the tick is state: `saving` is read straight off the mutation, and the
 * tick decays on its own.
 *
 * @param isPending whether the save is in flight right now
 * @param isError whether the save that just finished failed
 * @param linger how long the tick stays, in milliseconds
 */
export function useSaveStatus(isPending: boolean, isError = false, linger = 2000): SaveStatus {
  const [justSaved, setJustSaved] = useState(false)
  // The falling edge of a real save is the only thing worth a tick. Without
  // this, mounting beside an idle mutation would show one immediately, for a
  // save the reader was not there for.
  const [wasPending, setWasPending] = useState(isPending)

  // Adjusted during render rather than in an effect: this is state that
  // follows a prop, and `react-hooks/set-state-in-effect` is right to say so.
  if (wasPending !== isPending) {
    setWasPending(isPending)
    setJustSaved(!isPending && !isError)
  }

  useEffect(() => {
    if (!justSaved) return
    const timer = setTimeout(() => setJustSaved(false), linger)
    return () => clearTimeout(timer)
  }, [justSaved, linger])

  if (isPending) return 'saving'
  return justSaved ? 'saved' : 'idle'
}

export interface SaveStateProps {
  /** What to show. Usually from `useSaveStatus`. */
  status: SaveStatus
  /** What to say while saving. The product's word, in the product's language. */
  savingLabel?: ReactNode
  /** What to say once it is saved. */
  savedLabel?: ReactNode
  className?: string
}

/**
 * The indicator itself.
 *
 * `aria-live="polite"` rather than `assertive`: this is a background fact, and
 * interrupting someone mid-sentence to tell them a field saved is precisely
 * the kind of announcement that makes people turn a screen reader's verbosity
 * down.
 */
export function SaveState({ status, savingLabel, savedLabel, className }: SaveStateProps) {
  return (
    <span
      aria-live="polite"
      className={cn(
        'inline-flex min-w-16 items-center gap-1 text-xs text-faint transition-opacity',
        // Kept in the layout when idle, so the row does not reflow around it.
        status === 'idle' && 'opacity-0',
        className,
      )}
    >
      {status === 'saving' && (
        <>
          {/* The ring, not `Spinner`.
            *
            * `Spinner` carries its own `role="status"` and `aria-live`, which
            * is right when it stands alone and wrong inside this: nesting one
            * live region in another gives a screen reader two things to
            * announce for one event. So the visual is reused through the
            * variants and the announcing is left to the span around it. */}
          <span aria-hidden className={cn(spinnerVariants({ size: 'sm', tone: 'current' }), 'border-r-transparent')} />
          {savingLabel}
        </>
      )}
      {status === 'saved' && (
        <>
          {/* The tick is the only place this component names a colour, and it
              names the token for "this went well" rather than a green. */}
          <svg
            viewBox="0 0 16 16"
            aria-hidden="true"
            className="size-3 text-good"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M3 8.5 6.5 12 13 4.5" />
          </svg>
          {savedLabel}
        </>
      )}
    </span>
  )
}

import { useCallback, useRef, type InputHTMLAttributes, type Ref } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'
import { Kbd } from './kbd'
import { useShortcut } from './shortcut'

/*
 * SearchField.
 *
 * An Input that knows it is a search box, which is three small things the
 * products kept not doing:
 *
 *   - a magnifier, so the field is recognisable before it is read;
 *   - a way to clear it that is not "select all and delete" - and one that a
 *     keyboard can reach, which a decorative `<span>` cannot;
 *   - the shortcut that focuses it, shown in the field rather than learned.
 *
 * `type="search"` is deliberate: it is what tells a browser to offer previous
 * queries, and what makes Escape clear the field on the platforms where that
 * is the convention. The browser's own clear button is hidden, because it is
 * drawn in the operating system's chrome and cannot be made to match - the
 * same reason the line does not use a native `<select>`.
 */

export interface SearchFieldProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'value' | 'onChange'> {
  /** The query. Controlled, because a search box that owns its own text
   * cannot be cleared by the thing that owns the results. */
  value: string
  /** Told the new query on every keystroke. */
  onValueChange: (value: string) => void
  /**
   * What the clear button is called, for a screen reader. No default: a word
   * the component invents is a word the product cannot translate.
   *
   * Leave it out and no clear button is drawn - which is the right shape for a
   * field that filters as you type and is cleared by other means.
   */
  clearLabel?: string
  /**
   * The shortcut that focuses the field, as `['Mod', 'K']`. Shown at the right
   * of the field, and bound: pressing it focuses and selects, from anywhere
   * that is not already a field.
   */
  shortcut?: string[]
  ref?: Ref<HTMLInputElement>
}

export function SearchField({
  value,
  onValueChange,
  clearLabel,
  shortcut,
  className,
  ref,
  ...props
}: SearchFieldProps) {
  const own = useRef<HTMLInputElement>(null)

  const setRefs = useCallback(
    (element: HTMLInputElement | null) => {
      own.current = element
      if (typeof ref === 'function') ref(element)
      else if (ref) ref.current = element
    },
    [ref],
  )

  // Focus and select, so the shortcut replaces a stale query rather than
  // appending to it. Not while someone is typing elsewhere - that is
  // `useShortcut`'s default, and it is the half of this people forget.
  const focusAndSelect = useCallback(() => {
    own.current?.focus()
    own.current?.select()
  }, [])
  useShortcut(shortcut ?? [], focusAndSelect, { enabled: shortcut !== undefined })

  const showClear = clearLabel !== undefined && value !== ''

  return (
    <div className={cn('relative', className)}>
      <MagnifierIcon />

      <input
        ref={setRefs}
        type="search"
        value={value}
        onChange={(event) => onValueChange(event.target.value)}
        className={cn(
          fieldClasses,
          'h-control pl-8',
          // Room on the right for whatever sits there, and none when nothing
          // does - a field with a permanent gap looks broken.
          showClear && 'pr-8',
          !showClear && shortcut && 'pr-14',
          // The browser's own clear affordance, in the operating system's
          // chrome. Ours is below.
          '[&::-webkit-search-cancel-button]:appearance-none',
        )}
        {...props}
      />

      {showClear && (
        <button
          type="button"
          aria-label={clearLabel}
          onClick={() => {
            onValueChange('')
            own.current?.focus()
          }}
          className={cn(
            'absolute right-1.5 top-1/2 grid size-6 -translate-y-1/2 place-items-center',
            'rounded-sm text-faint transition-colors hover:bg-soft hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
          )}
        >
          <CrossIcon />
        </button>
      )}

      {!showClear && shortcut && (
        // Decorative: the shortcut works whether or not it is read out, and a
        // screen reader announcing "Control K" inside a search box is noise.
        <Kbd
          keys={shortcut}
          aria-hidden
          className="pointer-events-none absolute right-2 top-1/2 -translate-y-1/2"
        />
      )}
    </div>
  )
}

function MagnifierIcon() {
  return (
    <svg
      viewBox="0 0 16 16"
      width="14"
      height="14"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.6"
      aria-hidden
      className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-faint"
    >
      <circle cx="7" cy="7" r="4.5" />
      <path d="M10.5 10.5L14 14" strokeLinecap="round" />
    </svg>
  )
}

function CrossIcon() {
  return (
    <svg viewBox="0 0 16 16" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
      <path d="M4 4l8 8M12 4l-8 8" strokeLinecap="round" />
    </svg>
  )
}

import { useId, type HTMLAttributes, type ReactNode } from 'react'
import { useRender } from '@base-ui/react/use-render'
import { cn } from 'dowel-ui'

/*
 * The left-hand list of a screen with sections, and the heading each opens.
 *
 * A settings screen is the usual case: five or six sections, each its own
 * address so it can be linked to and the back button walks between them,
 * listed down the left with the current one tinted. Every product draws the
 * same column, and every product draws the active row a little differently -
 * which is exactly the drift a shared list exists to stop.
 *
 * The rows are the product's links, not the component's. `render` takes the
 * item and answers with the element to draw it as - a router's `NavLink`, an
 * `<a>`, whatever the product navigates with - and the component puts the
 * row's clothes, its icon and its `aria-current` on it. Without `render` a
 * row is a button and `onSelect` says which one was pressed, for a screen
 * whose sections are state rather than routes.
 *
 * `SectionHeading` is the other half: the title and the one-line hint above
 * a section's body, so the column and the page it opens are set in the same
 * type.
 */

export interface SectionNavItem {
  id: string
  label: ReactNode
  icon?: ReactNode
}

export interface SectionNavProps extends Omit<HTMLAttributes<HTMLElement>, 'children' | 'onSelect'> {
  /** What the list is called: the caption above it, and the name a screen
   * reader gives the landmark. */
  label: string
  items: readonly SectionNavItem[]
  /** Which item is the current page. */
  activeId?: string
  /** The element a row is drawn as - `render={(item) => <NavLink to={…} />}`.
   * The row's props are merged onto it, the way Button takes a `render`. */
  render?: (item: SectionNavItem) => useRender.RenderProp
  /** Pressed, whatever the row is drawn as. */
  onSelect?: (id: string) => void
}

export function SectionNav({ label, items, activeId, render, onSelect, className, ...props }: SectionNavProps) {
  const captionId = useId()
  return (
    <nav aria-labelledby={captionId} className={cn('flex flex-col gap-0.5', className)} {...props}>
      <h2 id={captionId} className="px-2.5 pb-2 text-2xs font-medium uppercase tracking-caption text-faint">
        {label}
      </h2>
      {items.map((item) => (
        <SectionNavRow
          key={item.id}
          item={item}
          active={item.id === activeId}
          render={render?.(item)}
          onSelect={onSelect}
        />
      ))}
    </nav>
  )
}

function SectionNavRow({
  item,
  active,
  render,
  onSelect,
}: {
  item: SectionNavItem
  active: boolean
  render?: useRender.RenderProp
  onSelect?: (id: string) => void
}) {
  return useRender({
    render,
    defaultTagName: 'button',
    props: {
      ...(render === undefined ? { type: 'button' } : {}),
      // Named as the current page for a screen reader, which cannot see that
      // it is the tinted one.
      'aria-current': active ? 'page' : undefined,
      onClick: () => onSelect?.(item.id),
      className: cn(
        'flex w-full items-center gap-2.5 rounded-md px-2.5 py-1.5 text-left text-sm text-dim no-underline transition-colors',
        'hover:bg-soft hover:text-text [&_svg]:size-4 [&_svg]:shrink-0',
        'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
        active && 'bg-accent-soft text-text [&_svg]:text-accent',
      ),
      children: (
        <>
          {item.icon ? <span aria-hidden className="contents">{item.icon}</span> : null}
          {/* One line, truncated, like a NavRail entry. A section column is a
              fixed width, and a label that wraps makes one row taller than
              every other - which in a two-language product happens to one
              section and not the rest, so the column reads as ragged and the
              line height stops meaning anything. `min-w-0` because a flex
              child will not shrink below its content without it. */}
          <span className="min-w-0 flex-1 truncate">{item.label}</span>
        </>
      ),
    },
  })
}

export interface SectionHeadingProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  title: ReactNode
  description?: ReactNode
}

/** The title of the open section and the line under it. */
export function SectionHeading({ title, description, className, ...props }: SectionHeadingProps) {
  return (
    <div className={cn('mb-4 flex flex-col gap-1', className)} {...props}>
      <h2 className="text-base font-semibold text-text">{title}</h2>
      {description ? <p className="text-sm text-dim">{description}</p> : null}
    </div>
  )
}

import { Select as Base } from '@base-ui/react/select'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * Select.
 *
 * The component the oldest rule in the line is about. A native `<select>`
 * cannot be dressed: the browser draws its popup itself, in the operating
 * system's chrome, and no CSS reaches inside. One native dropdown on a screen
 * of the product's own controls reads as a foreign object, and on Windows it
 * reads as a foreign object from 1998.
 *
 * So this renders `<button role="combobox">` and a portalled list of
 * `role="option"` - zero native elements, which is asserted in the test,
 * because it is the entire reason the component exists.
 *
 * What that costs is everything the browser was doing for free: the keyboard,
 * type-ahead, the announcement of the selected value, the scroll into view,
 * and on a phone the whole native picker. Base UI does all of it, which is
 * the only reason this trade is worth making - a hand-rolled dropdown is how
 * a product ships a control that a screen reader cannot see.
 *
 * The trigger wears Input's `fieldClasses`, imported rather than copied. A
 * select and a text field sit next to each other in every form there has ever
 * been, and two class lists that started the same drift within a release.
 *
 * `multiple` is a prop on the Root: it changes what `value` means - an array
 * rather than a single value - so it belongs where the value lives and not on
 * the trigger.
 */

export const selectTriggerVariants = cva([fieldClasses, 'flex items-center justify-between gap-2'], {
  variants: {
    size: {
      sm: 'h-control-sm text-xs',
      md: 'h-control',
      lg: 'h-control-lg text-base',
    },
  },
  defaultVariants: { size: 'md' },
})

export const selectPopupVariants = cva(
  [
    'max-h-[min(24rem,var(--available-height))] overflow-y-auto',
    'rounded-md border border-line bg-raise p-1 text-text shadow-raise',
    'focus-visible:outline-none',
    '[transition:opacity_var(--duration-quick)_var(--ease-out),transform_var(--duration-quick)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        // The popup matches the trigger's width by default, which is what a
        // dropdown should do; the sizes are a floor for a narrow one.
        sm: 'min-w-[max(8rem,var(--anchor-width))]',
        md: 'min-w-[max(10rem,var(--anchor-width))]',
        lg: 'min-w-[max(14rem,var(--anchor-width))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** One option. */
export const selectItemVariants = cva([
  'relative flex cursor-pointer select-none items-center gap-2 rounded-sm py-1.5 pl-2 pr-7 text-sm',
  'outline-none transition-colors',
  // Base UI marks the item under the pointer or the keyboard the same way,
  // so one rule covers both and they cannot disagree.
  'data-[highlighted]:bg-soft data-[highlighted]:text-text',
  // What is already chosen has to be visible in the list, and colour alone
  // will not do it: `text-text` on an item that is already `text-text` says
  // nothing. The tick below is the state; this is the emphasis that goes with
  // it, so the row reads as chosen at a glance and not only under the eye.
  'data-[selected]:font-medium data-[selected]:text-accent',
  'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
  '[&_svg]:size-3.5 [&_svg]:shrink-0',
])

/** The root. `multiple` turns `value` into an array; otherwise controlled with
 * `value` and `onValueChange`, or left to manage itself. */
export const Select = Base.Root

/** What the trigger shows: the selected item's label, and the `placeholder`
 * the product gives it until there is one.
 *
 * Two traps, both Base UI's and both quiet. Its `children` is a *function* of
 * the value, not a node - passing a node pins the trigger to that node
 * forever and the selection never appears, so the placeholder goes in
 * `placeholder`. And what it shows is the raw value, `plum` rather than
 * `Plum`, unless the root is given an `items` map to look the label up in.
 *
 * It truncates, and that matters most for `multiple`: nine chosen fruits are
 * one long string, and without this the trigger either grows into a paragraph
 * or spills its text past its own border. One line, an ellipsis, and the full
 * set is still in the list where the ticks are. */
export function SelectValue({ className, ...props }: Base.Value.Props) {
  return <Base.Value className={cn('min-w-0 flex-1 truncate text-left', className)} {...props} />
}

/** The chevron, or whatever the product puts there. Marked decorative by Base
 * UI, since the button is already named by its value. */
export const SelectIcon = Base.Icon

/** A labelled group of options. */
export const SelectGroup = Base.Group

/** The text of an option, which is what the trigger echoes when it is chosen. */
export const SelectItemText = Base.ItemText

/** The tick, drawn only on the chosen option. */
export const SelectItemIndicator = Base.ItemIndicator

export interface SelectTriggerProps
  extends Base.Trigger.Props,
    VariantProps<typeof selectTriggerVariants> {}

/** The control. A `<button role="combobox">` - never a `<select>`. */
export function SelectTrigger({ size, className, ...props }: SelectTriggerProps) {
  return <Base.Trigger className={cn(selectTriggerVariants({ size }), className)} {...props} />
}

export interface SelectPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof selectPopupVariants> {
  /** Preferred side of the trigger. Base UI flips it when it does not fit. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. */
  align?: Base.Positioner.Props['align']
  /** Distance from the trigger, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /** Where to portal to. Defaults to the document body, which keeps the list
   * from being clipped by a form with `overflow: hidden`. */
  container?: Base.Portal.Props['container']
}

/** The list. Portalled and positioned against the trigger.
 *
 * `alignItemWithTrigger` is off: Base UI's default lifts the popup so the
 * selected option sits over the button, which is the native macOS behaviour
 * and is disorienting in a web form - the list jumps to a different place
 * depending on what is already chosen. */
export function SelectPopup({
  size,
  side,
  align,
  sideOffset = 4,
  container,
  className,
  children,
  ...props
}: SelectPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        alignItemWithTrigger={false}
        className="[z-index:var(--z-menu)]"
      >
        <Base.Popup className={cn(selectPopupVariants({ size }), className)} {...props}>
          <Base.List>{children}</Base.List>
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

/** An option, with the tick that says it is the chosen one.
 *
 * The indicator is built in rather than left to the caller. The item already
 * reserves the room for it (`pr-7`), and a dropdown that does not show what is
 * currently selected is the commonest complaint about a styled select: it
 * opens, and the reader has to remember what they picked last time. Passing
 * `indicator={false}` turns it off for a list where the choice is obvious
 * some other way. */
export function SelectItem({
  indicator = true,
  className,
  children,
  ...props
}: Base.Item.Props & { indicator?: boolean }) {
  return (
    <Base.Item className={cn(selectItemVariants(), className)} {...props}>
      {children}
      {indicator && (
        <Base.ItemIndicator className="absolute right-2 flex text-accent">
          <svg viewBox="0 0 16 16" className="size-3.5" aria-hidden>
            <path
              d="M3.5 8.5l3 3 6-6.5"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </Base.ItemIndicator>
      )}
    </Base.Item>
  )
}

/** The caption above a group. */
export function SelectGroupLabel({ className, ...props }: Base.GroupLabel.Props) {
  return (
    <Base.GroupLabel
      className={cn('px-2 py-1.5 text-2xs uppercase tracking-caption text-faint', className)}
      {...props}
    />
  )
}

/** A line between groups of options. */
export function SelectSeparator({ className, ...props }: Base.Separator.Props) {
  return <Base.Separator className={cn('-mx-1 my-1 h-px bg-line', className)} {...props} />
}

import { useEffect } from 'react'

/*
 * Shortcut.
 *
 * Two things every product writes and half of them get subtly wrong: deciding
 * whether a keystroke is the shortcut, and deciding whether now is a moment to
 * act on it.
 *
 * The second is the one that bites. A shortcut that fires while someone is
 * typing in a field is a bug nobody can describe afterwards - `Mod+K` inside a
 * text editor means "delete to end of line", and a palette that opens on top
 * of it looks like the application misheard. So a keystroke aimed at an input,
 * a textarea or anything `contenteditable` belongs to that thing, always.
 *
 * A shortcut is written the way it is read: `['Mod', 'K']`. `Mod` is command
 * on Apple platforms and control everywhere else, which is the same rule Kbd
 * draws it by, so what is bound and what is shown cannot disagree.
 */

/** Whether the event landed somewhere that owns its own keys. */
export function isTypingTarget(target: EventTarget | null): boolean {
  const element = target as HTMLElement | null
  if (!element) return false
  const tag = element.tagName
  // Coerced: `isContentEditable` is computed from layout, and an engine that
  // does not lay out - jsdom, and any server render - leaves it `undefined`
  // rather than `false`. Truthiness is enough for the branch below, but a
  // function that says it returns a boolean has to.
  return tag === 'INPUT' || tag === 'TEXTAREA' || Boolean(element.isContentEditable)
}

/** Does this event match the shortcut? Exported because a product sometimes
 * has to ask the question inside a handler it already owns. */
export function matchesShortcut(event: KeyboardEvent, shortcut: string[]): boolean {
  const wants = new Set(shortcut.map((key) => key.toLowerCase()))
  const mod = wants.delete('mod')
  const shift = wants.delete('shift')
  const alt = wants.delete('alt')
  const [key] = [...wants]
  if (key === undefined) return false

  // An exact match on every modifier, in both directions: `Mod+K` must not
  // fire on `Mod+Shift+K`, which is usually a different command entirely.
  if (mod !== (event.metaKey || event.ctrlKey)) return false
  if (shift !== event.shiftKey) return false
  if (alt !== event.altKey) return false
  return event.key.toLowerCase() === key
}

export interface UseShortcutOptions {
  /** Bind it at all. For a shortcut that only exists on some screens. */
  enabled?: boolean
  /**
   * Fire even while someone is typing in a field.
   *
   * Off by default, and the default is the point. Turn it on for a shortcut
   * that belongs to the field itself - `Escape` closing the box it is typed
   * in - and never for one that takes the person somewhere else.
   */
  whileTyping?: boolean
}

/**
 * Run something when a shortcut is pressed.
 *
 * The handler is read from a ref, so a caller that writes it inline does not
 * rebind the listener on every render - which is how these end up firing twice.
 */
export function useShortcut(
  shortcut: string[],
  onPress: (event: KeyboardEvent) => void,
  { enabled = true, whileTyping = false }: UseShortcutOptions = {},
): void {
  useEffect(() => {
    if (!enabled) return

    const onKeyDown = (event: KeyboardEvent) => {
      if (!whileTyping && isTypingTarget(event.target)) return
      if (!matchesShortcut(event, shortcut)) return
      event.preventDefault()
      onPress(event)
    }

    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
    // `shortcut` is an array literal at most call sites, so it is joined
    // rather than compared by identity: otherwise every render rebinds.
  }, [shortcut.join('+'), onPress, enabled, whileTyping]) // eslint-disable-line react-hooks/exhaustive-deps
}

import { useCallback, useLayoutEffect, useRef, useState, type HTMLAttributes, type ReactNode } from 'react'
import { cn } from 'dowel-ui'

/*
 * SkeletonOf - a placeholder that remembers the shape instead of guessing it.
 *
 * `Skeleton` and its shapes solved half the problem: they gave a product a
 * list, a card and a grid to reach for instead of a spinner. The half left
 * over is the one that actually causes the jump, and it is a human one -
 * somebody has to look at the real thing, judge how many rows it has and how
 * tall they are, and type that in. The judgement is made once, the screen
 * changes a month later, and the placeholder goes on promising the old shape.
 * The line's own calendar is the recorded case: four short lines standing in
 * for a six-row month grid, and the skeleton was itself the jump it existed to
 * prevent.
 *
 * The rule is the same one `Skeleton` is built on:
 *
 *   **A skeleton of the wrong shape is worse than no skeleton.**
 *
 * What is new here is where the shape comes from. The content was on the
 * screen a moment ago; it measured itself, and nothing else knows its shape
 * better. So this keeps what was there - how many rows, how tall each one, how
 * tall the whole block - and draws that back while the next load is in flight.
 *
 * **Why measuring and not reading the source.** The obvious version of "derive
 * the skeleton from the markup" is to parse the component's JSX and emit
 * boxes from it. It cannot work, and the reason is worth writing down: the
 * shape on screen is not in the source. It is the source plus the data (five
 * rows or fifty), plus the viewport (one column or three), plus the theme's
 * own spacing. A generator reading `list.tsx` sees one `<li>` in a `map` and
 * knows nothing about any of that. Measuring the rendered thing sees all of it
 * at once, and it costs a `ResizeObserver` rather than a build step.
 *
 * **The first load has nothing to remember**, and that is the case a product
 * must still answer: `fallback` is what stands in until there is a measurement
 * to use. After that the fallback is never seen again on that screen.
 *
 * Everything drawn here is `aria-hidden`, like every other skeleton - the
 * loading fact belongs to the region and is said once, by whatever owns it.
 */

/** What was measured: the block's own height, and the rows inside it.
 *
 * Kept as plain numbers rather than as a copy of the DOM, because that is all
 * a placeholder needs and because a detached node would pin the whole tree in
 * memory for as long as the screen lives. */
export interface MeasuredShape {
  /** The block's height when it was last full, in pixels. */
  height: number
  /** The height of each row inside it. Empty when nothing matched the row
   * selector - a block with no repeating part is a single box. */
  rows: number[]
}

/**
 * Measure a node: its height, and the heights of the rows inside it.
 *
 * Exported because a product occasionally wants the measurement without the
 * component - to persist it between sessions, for instance, so that even the
 * first load of a screen already knows its shape.
 *
 * Rows are found by selector rather than by walking children, because the
 * repeating part is rarely a direct child: a table's rows are inside a
 * `<tbody>`, a list's inside a `<ul>` that may itself be inside a scroller.
 */
export function measureShape(node: HTMLElement, rowSelector?: string): MeasuredShape {
  const height = node.getBoundingClientRect().height
  const rows = rowSelector
    ? [...node.querySelectorAll(rowSelector)].map((row) => row.getBoundingClientRect().height)
    : []
  return { height, rows }
}

export interface SkeletonOfProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Whether the content is on its way. While false the children are shown and
   * measured; while true the remembered shape is drawn in their place. */
  pending: boolean
  /** The real thing. Rendered and measured when not pending. */
  children: ReactNode
  /**
   * What counts as a row - `'tr'`, `'li'`, `'[data-row]'`. Given, the
   * placeholder draws one box per row at the height that row had; omitted, it
   * draws a single box the height of the whole block.
   */
  rowSelector?: string
  /**
   * What to draw before anything has been measured - the first load of a
   * screen, where there is genuinely nothing to remember. A `SkeletonList` of
   * roughly the right size is the usual answer.
   */
  fallback?: ReactNode
  /**
   * A shape measured earlier - from `measureShape`, stored by the product
   * between sessions. Used until this instance measures something itself, so
   * even a first load can be honest.
   */
  shape?: MeasuredShape
  /** The gap between drawn rows, as a Tailwind class. Matches whatever the
   * real list uses; the rows' own heights come from the measurement. */
  gapClassName?: string
}

/**
 * Shows the children, remembers their shape, and draws that shape back while
 * the next load is in flight.
 *
 * The measurement is taken in a layout effect and on every resize, not once on
 * mount: a list that gains rows, a window that narrows, a font that loads late
 * all change the shape, and a placeholder built from the first measurement
 * would be wrong in exactly the way this component exists to prevent.
 */
export function SkeletonOf({
  pending,
  children,
  rowSelector,
  fallback,
  shape,
  gapClassName,
  className,
  ...props
}: SkeletonOfProps) {
  const [measured, setMeasured] = useState<MeasuredShape | undefined>(shape)
  const node = useRef<HTMLDivElement | null>(null)

  const remember = useCallback(() => {
    const element = node.current
    if (!element) return
    const next = measureShape(element, rowSelector)
    // A block of no height is a block that has not been laid out - a hidden
    // tab, a parent still collapsing. Remembering a zero would draw nothing
    // and claim it was the shape.
    if (next.height <= 0) return
    setMeasured((held) =>
      held && held.height === next.height && sameRows(held.rows, next.rows) ? held : next,
    )
  }, [rowSelector])

  useLayoutEffect(() => {
    // Only the branch that renders the content carries the ref, so while
    // pending there is nothing to measure and `remember` finds no node. That
    // is what keeps the memory from decaying: measuring the placeholder would
    // record the shape it had just drawn from memory, and each load would
    // remember a little less of what the content actually looked like.
    //
    // It is worth stating rather than relying on, because it rests on React
    // clearing a ref when the node it points at unmounts. The guard below is
    // that fact made explicit - if the component ever renders both branches,
    // this is the line that keeps the loop from closing.
    if (pending || !node.current) return
    remember()

    // jsdom has no ResizeObserver, and a product may run in one. The component
    // is still correct without it: it has the mount measurement, it just does
    // not follow later changes.
    if (typeof ResizeObserver === 'undefined') return
    const element = node.current
    if (!element) return
    const observer = new ResizeObserver(remember)
    observer.observe(element)
    return () => observer.disconnect()
  }, [pending, remember, children])

  if (!pending) {
    return (
      <div ref={node} className={className} {...props}>
        {children}
      </div>
    )
  }

  // Nothing measured yet, and nothing handed over: the first load of a screen
  // that did not say what it is waiting for. Saying nothing is better than
  // drawing a shape made up on the spot.
  if (!measured) return <>{fallback ?? null}</>

  return (
    <div aria-hidden className={cn('flex flex-col', gapClassName ?? 'gap-1', className)} {...props}>
      {measured.rows.length > 0 ? (
        measured.rows.map((height, row) => (
          <div
            key={row}
            style={{ height }}
            className="animate-pulse shrink-0 rounded-md bg-soft"
          />
        ))
      ) : (
        <div style={{ height: measured.height }} className="animate-pulse rounded-md bg-soft" />
      )}
    </div>
  )
}

/** Whether two row measurements are the same run of heights.
 *
 * Compared rather than replaced wholesale so that a resize that changes
 * nothing does not hand back a new object every frame - which would re-render
 * the subtree on every pixel of a window drag. */
function sameRows(left: number[], right: number[]): boolean {
  return left.length === right.length && left.every((height, index) => height === right[index])
}

import type { HTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * A placeholder shaped like the thing that is still loading.
 *
 * The rule the component is built on, and the reason it takes a shape rather
 * than filling the space:
 *
 *   **A skeleton of the wrong shape is worse than no skeleton.**
 *
 * It promises something the content does not keep, and the promise is paid for
 * in a jump: the page settles, the scrollbar appears, and whatever the reader
 * was about to click has moved. Measured rather than assumed - the line's own
 * calendar showed a list of four short lines where a six-row month grid was
 * about to land, and the skeleton was itself the jump it existed to prevent.
 *
 * So the useful thing here is not `<Skeleton />` - that is four lines anyone
 * can write - but the shapes: a list, a card, a grid. They are what a product
 * reaches for at the call site, and what keeps the placeholder honest.
 *
 * A spinner is the right answer when the shape is *not* known. A skeleton
 * claims to know; if it does not, say less rather than more.
 *
 * Everything here is `aria-hidden`. A screen reader is told the region is busy
 * by whatever owns the loading state - `QueryState` does it with `aria-busy` -
 * and announcing a dozen empty boxes as content would be noise on top of a
 * fact the reader already has.
 */

export type SkeletonProps = HTMLAttributes<HTMLDivElement>

/** One block. Size it with `className` - a skeleton is a shape, and the shape
 * belongs to whatever it stands in for. */
export function Skeleton({ className, ...props }: SkeletonProps) {
  return (
    <div
      aria-hidden
      className={cn('animate-pulse rounded-md bg-soft', className)}
      {...props}
    />
  )
}

export interface SkeletonTextProps extends HTMLAttributes<HTMLDivElement> {
  /** How many lines of text stand here. */
  lines?: number
}

/** A paragraph's worth of lines.
 *
 * The widths vary, and that is the whole point: a stack of equal bars reads as
 * a loading indicator, while ragged ones read as text. The last line is short,
 * because the last line of a paragraph is. */
export function SkeletonText({ lines = 3, className, ...props }: SkeletonTextProps) {
  const widths = ['w-full', 'w-11/12', 'w-4/5', 'w-full', 'w-3/4']
  return (
    <div aria-hidden className={cn('flex flex-col gap-2', className)} {...props}>
      {Array.from({ length: Math.max(1, lines) }, (_, line) => (
        <Skeleton
          key={line}
          className={cn(
            'h-3',
            line === lines - 1 ? 'w-1/2' : widths[line % widths.length],
          )}
        />
      ))}
    </div>
  )
}

export interface SkeletonListProps extends HTMLAttributes<HTMLDivElement> {
  rows?: number
  /** Draw a second, shorter line under each row - for a list whose rows carry
   * a title and something beneath it. */
  secondary?: boolean
}

/** Rows of a list, which is the shape most screens are waiting for. */
export function SkeletonList({
  rows = 5,
  secondary = true,
  className,
  ...props
}: SkeletonListProps) {
  // Three widths in rotation rather than random: a placeholder that differs
  // between renders is a placeholder that flickers when anything re-renders.
  const widths = ['w-2/3', 'w-4/5', 'w-1/2']
  return (
    <div aria-hidden className={cn('flex flex-col gap-1', className)} {...props}>
      {Array.from({ length: Math.max(1, rows) }, (_, row) => (
        <div key={row} className="flex flex-col gap-1.5 px-3 py-2">
          <Skeleton className={cn('h-3.5', widths[row % widths.length])} />
          {secondary && <Skeleton className="h-2.5 w-1/3" />}
        </div>
      ))}
    </div>
  )
}

export interface SkeletonGridProps extends HTMLAttributes<HTMLDivElement> {
  /** How many cells. */
  cells?: number
  /** How many per row. */
  columns?: number
  /** The aspect of one cell, as a Tailwind class - a gallery of covers is not
   * shaped like a grid of tiles. */
  cellClassName?: string
}

/** A grid of cells: a gallery, a board, a month.
 *
 * Given a cell count and a column count rather than a shape of its own,
 * because the grids a product waits for differ in both and agree in neither. */
export function SkeletonGrid({
  cells = 12,
  columns = 4,
  cellClassName = 'aspect-square',
  className,
  ...props
}: SkeletonGridProps) {
  return (
    <div
      aria-hidden
      // The column count is a style rather than a class, because a class would
      // have to be one of a fixed set - and Tailwind cannot generate
      // `grid-cols-${n}` from a value it never sees.
      style={{ gridTemplateColumns: `repeat(${Math.max(1, columns)}, minmax(0, 1fr))` }}
      className={cn('grid gap-2', className)}
      {...props}
    >
      {Array.from({ length: Math.max(1, cells) }, (_, cell) => (
        <Skeleton key={cell} className={cellClassName} />
      ))}
    </div>
  )
}

import type { SVGAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * A line small enough to sit beside the number it belongs to.
 *
 * The shape of a history, not a chart of it: no axes, no gridlines, no ticks.
 * "61 → 74 → 82" reads perfectly at three points and stops working at ten; a
 * line holds both, and the exact figures stay in the list underneath.
 *
 * Three things here are not free choices.
 *
 * **The box is drawn at the size it is shown at.** A `viewBox` wider than the
 * element scales x and y by different factors: the line bends away from the
 * data and the end dot stretches into a wedge. So the size is a variant rather
 * than a `className`, and each variant states the same numbers twice on
 * purpose - once for the geometry, once for the element - from one place. The
 * donor took a `size` object *and* a class, and every call site repeated
 * itself: `size={{ width: 52, height: 16 }} className="h-4 w-[52px]"`.
 *
 * **The scale comes from outside.** `max` is what the axis allows, not what
 * this line happens to reach, so two works can be compared by eye. Normalised
 * to itself, a line that moved 61 → 63 would climb the whole box and read as a
 * transformation.
 *
 * **The line does not judge.** The donor coloured it green when it ended
 * higher and red when it ended lower, which is a claim the component cannot
 * support: for time-to-answer or error rate, down is the good direction. So
 * the line is drawn in the de-emphasis tone and the newest point in the accent
 * - the eye goes to "where it is now", and what that means is said in words
 * next to it, usually by a StatTile's delta. `tone` is there for a caller who
 * genuinely knows the direction's meaning.
 *
 * Not interactive, and that is the form rather than an omission: a sparkline
 * has no room for a hover target that is not the whole of it. A reader who
 * needs the exact figures gets them from the table beside it.
 */

const GEOMETRY = {
  sm: { width: 52, height: 16, dot: 1.75, stroke: 1.25 },
  md: { width: 120, height: 28, dot: 2.5, stroke: 1.5 },
} as const

export type SparklineSize = keyof typeof GEOMETRY

export const sparklineVariants = cva('shrink-0 overflow-visible', {
  variants: {
    size: {
      /* Beside a figure in a row - an axis of a rubric, a cell in a table. */
      sm: 'h-4 w-[52px]',
      /* Beside a total, where the shape is meant to be read rather than
       * glanced at. */
      md: 'h-7 w-[120px]',
    },
  },
  defaultVariants: { size: 'md' },
})

export const sparklineLineVariants = cva('fill-none', {
  variants: {
    tone: {
      /* The default, and the one a caller should almost always leave alone:
       * the line is context for the number beside it. */
      muted: 'stroke-dim',
      /* For a line that IS the subject - one chart on a page, nothing else to
       * defer to. */
      accent: 'stroke-accent',
      /* Only where the caller knows what the direction means. A component
       * cannot: for time-to-answer, down is the good news. */
      good: 'stroke-good',
      bad: 'stroke-bad',
    },
  },
  defaultVariants: { tone: 'muted' },
})

export const sparklineDotVariants = cva('', {
  variants: {
    tone: {
      /* The newest point carries the accent even under the muted line: it is
       * the one the eye is looking for, and one dot of colour is enough to
       * find it without the line making a claim. */
      muted: 'fill-accent',
      accent: 'fill-accent',
      good: 'fill-good',
      bad: 'fill-bad',
    },
  },
  defaultVariants: { tone: 'muted' },
})

/** Breathing room, so the stroke and the end dot are not clipped by the box. */
const PAD = 3

export interface SparklineProps
  extends Omit<SVGAttributes<SVGSVGElement>, 'values'>,
    VariantProps<typeof sparklineLineVariants> {
  /** Oldest first. Fewer than two points is not a line, and draws nothing. */
  values: number[]
  /** The top of the scale, so two lines can be compared by eye. Defaults to
   * the highest value present, which makes the line self-scaled - fine for one
   * line alone, wrong for a column of them. */
  max?: number
  /** What the line says, for a reader who cannot see it. Required: an unlabelled
   * `img` is an unlabelled image, and this one carries information. */
  label: string
  size?: SparklineSize
}

export function Sparkline({ values, max, label, size, tone, className, ...props }: SparklineProps) {
  // One point is a dot with no direction and no point; zero is nothing at all.
  if (values.length < 2) return null

  /* The default lives in `sparklineVariants` like every other variant in the
   * library; this resolves the same word for the geometry, so the numbers and
   * the classes cannot disagree about which size is being drawn. */
  const { width, height, dot, stroke } = GEOMETRY[size ?? 'md']

  /* The ceiling never sits below the data: a value above `max` would otherwise
   * be drawn outside the box. Clamped rather than rejected, because a score
   * that overshoots its stated scale is the caller's problem to notice, not a
   * reason to draw nothing. */
  const top = Math.max(...values, max ?? 0)
  /* A flat line at zero, or a flat line anywhere with no stated scale, would
   * divide by zero. It is drawn along the bottom, which is where it belongs. */
  const span = width - PAD * 2
  const rise = height - PAD * 2

  const points = values.map((value, index) => {
    const x = PAD + (span * index) / (values.length - 1)
    // SVG's y grows downward, so a larger value has to sit higher up.
    const y = top === 0 ? PAD + rise : PAD + rise - (rise * value) / top
    return [x, y] as const
  })

  const path = points
    .map(([x, y], index) => `${index === 0 ? 'M' : 'L'}${x.toFixed(1)} ${y.toFixed(1)}`)
    .join(' ')
  const [lastX, lastY] = points.at(-1)!

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className={cn(sparklineVariants({ size }), className)}
      role="img"
      aria-label={label}
      {...props}
    >
      <path
        d={path}
        strokeWidth={stroke}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={cn(sparklineLineVariants({ tone }))}
      />
      <circle cx={lastX} cy={lastY} r={dot} className={cn(sparklineDotVariants({ tone }))} />
    </svg>
  )
}

import type { HTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Spinner.
 *
 * Something is happening and the answer has not arrived. It carries no text of
 * its own - what is loading is the product's word, not the system's - but it
 * does have to say *something* to a screen reader, or a page that is busy is
 * silently identical to a page that is empty.
 *
 * Under `prefers-reduced-motion` the theme stops the animation. That is not a
 * detail: for some readers a spinning thing is not decoration but a symptom.
 * A stopped spinner still says "busy" through `role`, which is the part that
 * carried the meaning all along.
 */
export const spinnerVariants = cva('inline-block animate-spin rounded-full border-2 border-current', {
  variants: {
    size: {
      sm: 'size-3.5 border-[1.5px]',
      md: 'size-4',
      lg: 'size-6',
    },
    tone: {
      /* Follows the text it sits in. */
      current: 'text-current',
      dim: 'text-dim',
      accent: 'text-accent',
    },
  },
  defaultVariants: { size: 'md', tone: 'current' },
})

export interface SpinnerProps
  extends HTMLAttributes<HTMLSpanElement>,
    VariantProps<typeof spinnerVariants> {
  /** What is being waited for, for a screen reader. The product's word. */
  label?: string
}

export function Spinner({ size, tone, label, className, ...props }: SpinnerProps) {
  return (
    <span role="status" aria-live="polite" className={cn('inline-flex items-center gap-2', className)} {...props}>
      <span
        // The gap in the ring is what makes the rotation visible.
        className={cn(spinnerVariants({ size, tone }), 'border-r-transparent')}
        aria-hidden
      />
      {label && <span className="sr-only">{label}</span>}
    </span>
  )
}

import {
  Children,
  createContext,
  isValidElement,
  useContext,
  useId,
  useRef,
  useState,
  type HTMLAttributes,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
  type RefObject,
} from 'react'
import { cva } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Panes side by side, or one above the other, with a handle between each two
 * that moves the boundary.
 *
 * Three parts - `Splitter`, `SplitterPane`, `SplitterHandle` - rather than a
 * component with a `first` and a `second`. A two-pane prop shape is the one
 * every product outgrows on the day it wants a third pane, and the rewrite is
 * every call site. Here a third pane is two more lines of markup. Each handle
 * moves only the boundary it sits on: the pane before it and the pane after
 * it trade size, and the others stay where they are, which is what a reader
 * dragging one edge expects.
 *
 * Sizes are percentages of the splitter, not pixels, so a window resized to
 * half its width keeps the sidebar at the same share of it instead of eating
 * the editor. A pane is laid out with its percentage as its flex grow and a
 * zero basis, which is what lets the one-pixel handles sit between them
 * without the percentages adding up to more than the box.
 *
 * The limits live on the panes (`min`, `max`, `collapsible`), because that is
 * where a reader of the markup looks for them, and the splitter reads them off
 * its children when it clamps. The price is that panes and handles must be
 * direct children - not wrapped in a fragment or a component of the product's
 * own - since that is how each learns its place in the row. The arithmetic is
 * exported as plain functions for the same reason `virtual-list`'s is: jsdom
 * has no layout, and a rule that can only be checked in a browser is a rule
 * that goes unchecked.
 *
 * The component keeps the sizes and never stores them. `onSizesChange` fires
 * when a change settles - a drag let go, a key pressed - and not on every
 * move, so a product persisting there writes once per gesture rather than
 * sixty times a second. What it saved comes back as `defaultSizes`.
 *
 * The handle is the ARIA window splitter: a focusable `separator` carrying the
 * size of the pane before it as its value, so a screen reader says how much
 * room that pane has and the arrows change it. Enter collapses a pane marked
 * `collapsible` and restores it to the size it had. The visible line is a
 * pixel; the hit area is `target-min`, the theme's named way of growing a
 * target past the floor without growing what is drawn. There is no drag by
 * HTML5 drag-and-drop, for the reason `column-resize-handle` gives: a desktop
 * shell that takes file drops never lets `dragstart` reach the page. Pointer
 * capture keeps the drag alive when the pointer runs ahead of the handle.
 */

/** What a pane allows, in percent of the splitter. */
export interface PaneLimits {
  /** Smallest size, 0 by default. */
  min?: number
  /** Largest size, 100 by default. */
  max?: number
  /** Whether the pane can shrink past `min` to `collapsedSize`. */
  collapsible?: boolean
  /** Its size when collapsed: 0 by default, a rail's width for a pane that
   * keeps its icons. */
  collapsedSize?: number
}

const floorOf = (limits: PaneLimits) => (limits.collapsible ? (limits.collapsedSize ?? 0) : (limits.min ?? 0))

/** The range the pane before handle `index` can take, given what both panes
 * beside the handle allow. */
export function boundsOf(sizes: number[], index: number, limits: PaneLimits[]): [number, number] {
  const before = limits[index] ?? {}
  const after = limits[index + 1] ?? {}
  const pair = sizes[index]! + sizes[index + 1]!
  return [Math.max(floorOf(before), pair - (after.max ?? 100)), Math.min(before.max ?? 100, pair - floorOf(after))]
}

/* A collapsible pane below its minimum is either collapsed or at its minimum,
 * never between. Dragging, it goes to whichever is nearer; by keyboard the
 * direction decides, or one press past the minimum would land on the minimum
 * again and the pane could never be collapsed by arrows. */
function snap(size: number, limits: PaneLimits, direction: number): number {
  const min = limits.min ?? 0
  const collapsed = limits.collapsedSize ?? 0
  if (!limits.collapsible || size >= min) return size
  return (direction === 0 ? size < (min + collapsed) / 2 : direction < 0) ? collapsed : min
}

/** New sizes after handle `index` asks for the pane before it to be `target`.
 * `direction` is the sign of a key press, or 0 for a drag. */
export function moveBoundary(
  sizes: number[],
  index: number,
  target: number,
  limits: PaneLimits[],
  direction = 0,
): number[] {
  const pair = sizes[index]! + sizes[index + 1]!
  const [low, high] = boundsOf(sizes, index, limits)
  let size = snap(target, limits[index] ?? {}, direction)
  size = pair - snap(pair - size, limits[index + 1] ?? {}, -direction)
  // Two decimals: finer than a pixel on any screen, and a persisted value
  // that reads as a number rather than as float noise.
  size = Math.round(Math.min(high, Math.max(low, size)) * 100) / 100
  const next = [...sizes]
  next[index] = size
  next[index + 1] = Math.round((pair - size) * 100) / 100
  return next
}

interface SplitterState {
  orientation: 'horizontal' | 'vertical'
  sizes: number[]
  limits: PaneLimits[]
  step: number
  paneId: (index: number) => string
  root: RefObject<HTMLDivElement | null>
  move: (index: number, target: number, direction: number, done: boolean) => void
}

const State = createContext<SplitterState | null>(null)
const Place = createContext(0)

function useSplitter() {
  const state = useContext(State)
  if (state === null) throw new Error('SplitterPane and SplitterHandle belong inside a Splitter')
  return state
}

export interface SplitterProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /** How the panes are laid out: `horizontal` is side by side, with upright
   * handles between them; `vertical` stacks them. */
  orientation?: 'horizontal' | 'vertical'
  /** One percentage per pane, summing to 100 - what was saved from
   * `onSizesChange`, or the product's opening layout. Equal shares without. */
  defaultSizes?: number[]
  /** Told the sizes when a change settles: persist them here. */
  onSizesChange?: (sizes: number[]) => void
  /** Percent moved by an arrow key; Shift moves five of these. */
  step?: number
  children: ReactNode
}

export function Splitter({
  orientation = 'horizontal',
  defaultSizes,
  onSizesChange,
  step = 2,
  className,
  children,
  ...props
}: SplitterProps) {
  const id = useId()
  const root = useRef<HTMLDivElement>(null)
  const limits: PaneLimits[] = []
  const placed = Children.toArray(children)
    .filter(isValidElement)
    .map((child) => {
      if (child.type === SplitterPane) limits.push(child.props as PaneLimits)
      // Counted after the push, so a pane's place is its own index and a
      // handle's is the index of the pane before it.
      return (
        <Place.Provider key={child.key} value={limits.length - 1}>
          {child}
        </Place.Provider>
      )
    })
  const even = () => limits.map(() => 100 / limits.length)
  const [kept, setKept] = useState<number[]>(() => defaultSizes ?? even())
  // A pane added or removed invalidates every share: start again from equal.
  const sizes = kept.length === limits.length ? kept : even()

  const move = (index: number, target: number, direction: number, done: boolean) => {
    const next = moveBoundary(sizes, index, target, limits, direction)
    setKept(next)
    if (done) onSizesChange?.(next)
  }

  return (
    <State.Provider
      value={{ orientation, sizes, limits, step, root, move, paneId: (index) => `${id}-pane-${index}` }}
    >
      <div
        ref={root}
        data-orientation={orientation}
        className={cn('flex size-full min-h-0 min-w-0', orientation === 'vertical' && 'flex-col', className)}
        {...props}
      >
        {placed}
      </div>
    </State.Provider>
  )
}

export interface SplitterPaneProps extends Omit<HTMLAttributes<HTMLDivElement>, 'id'>, PaneLimits {}

// `min` and `max` are taken out only so they do not land on the `div`: the
// splitter reads them off the element, and the pane has no use for them.
// eslint-disable-next-line @typescript-eslint/no-unused-vars
export function SplitterPane({ min, max, collapsible, collapsedSize = 0, className, style, ...props }: SplitterPaneProps) {
  const { sizes, paneId } = useSplitter()
  const index = useContext(Place)
  const size = sizes[index] ?? 0
  return (
    <div
      id={paneId(index)}
      data-collapsed={collapsible && size <= collapsedSize ? '' : undefined}
      // A pane collapsed to nothing still holds its content, and without
      // `inert` a Tab walks into controls nobody can see.
      inert={size === 0}
      style={{ flex: `${size} 1 0px`, ...style }}
      className={cn('min-h-0 min-w-0 overflow-hidden', className)}
      {...props}
    />
  )
}

export const splitterHandleVariants = cva(
  cn(
    'z-10 shrink-0 touch-none select-none bg-line target-min outline-none',
    '[transition:background-color_var(--duration-quick)_var(--ease-out)]',
    'hover:bg-accent data-[dragging]:bg-accent',
    'focus-visible:bg-accent focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
  ),
  {
    variants: {
      /* The splitter's orientation, so the handle's line runs across it. */
      orientation: {
        horizontal: 'w-px cursor-col-resize',
        vertical: 'h-px cursor-row-resize',
      },
    },
  },
)

export interface SplitterHandleProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Names what the handle resizes: "Resize the sidebar". No default - it is
   * the product's word. */
  label: string
}

export function SplitterHandle({ label, className, ...props }: SplitterHandleProps) {
  const { orientation, sizes, limits, step, paneId, root, move } = useSplitter()
  const index = useContext(Place)
  const origin = useRef<{ at: number; size: number; span: number } | null>(null)
  // The size a collapsed pane goes back to on the next Enter.
  const restore = useRef<number | undefined>(undefined)
  const [dragging, setDragging] = useState(false)
  const across = orientation === 'horizontal'
  const size = sizes[index] ?? 0
  const [low, high] = boundsOf(sizes, index, limits)

  const drag = (event: ReactPointerEvent<HTMLElement>, done: boolean) => {
    const from = origin.current
    if (from === null) return
    const travelled = (across ? event.clientX : event.clientY) - from.at
    move(index, from.size + (travelled / from.span) * 100, 0, done)
  }

  const begin = (event: ReactPointerEvent<HTMLElement>) => {
    // The primary button only: a right-click is the context menu's.
    if (event.button !== 0 || root.current === null) return
    const box = root.current.getBoundingClientRect()
    const span = across ? box.width : box.height
    if (span === 0) return
    event.preventDefault()
    origin.current = { at: across ? event.clientX : event.clientY, size, span }
    event.currentTarget.setPointerCapture(event.pointerId)
    setDragging(true)
  }

  const end = (event: ReactPointerEvent<HTMLElement>) => {
    drag(event, true)
    origin.current = null
    setDragging(false)
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId)
    }
  }

  // The pane before the handle collapses if it can, else the one after it: a
  // sidebar on the right is the second pane of its handle.
  const toggled = (): number | undefined => {
    const pane = limits[index]?.collapsible ? index : limits[index + 1]?.collapsible ? index + 1 : -1
    if (pane < 0) return undefined
    const own = sizes[pane]!
    const collapsed = limits[pane]!.collapsedSize ?? 0
    let next = collapsed
    if (own <= collapsed) next = restore.current ?? Math.max(limits[pane]!.min ?? 0, 100 / sizes.length)
    else restore.current = own
    return pane === index ? next : size + sizes[index + 1]! - next
  }

  const press = (event: KeyboardEvent<HTMLElement>) => {
    const by = event.shiftKey ? step * 5 : step
    const target = {
      [across ? 'ArrowLeft' : 'ArrowUp']: size - by,
      [across ? 'ArrowRight' : 'ArrowDown']: size + by,
      Home: low,
      End: high,
    }[event.key] ?? (event.key === 'Enter' ? toggled() : undefined)
    if (target === undefined) return
    event.preventDefault()
    move(index, target, Math.sign(target - size), true)
  }

  return (
    <div
      role="separator"
      tabIndex={0}
      aria-label={label}
      aria-controls={paneId(index)}
      // The line runs across the layout: panes side by side are split by an
      // upright separator.
      aria-orientation={across ? 'vertical' : 'horizontal'}
      aria-valuenow={Math.round(size)}
      aria-valuemin={Math.round(low)}
      aria-valuemax={Math.round(high)}
      data-dragging={dragging ? '' : undefined}
      onPointerDown={begin}
      onPointerMove={(event) => drag(event, false)}
      onPointerUp={end}
      onPointerCancel={end}
      onKeyDown={press}
      className={cn(splitterHandleVariants({ orientation }), className)}
      {...props}
    />
  )
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * One figure, and what it is a figure of.
 *
 * The smallest thing on a dashboard and the one every product writes itself:
 * a label above, a number below, sometimes a word about which way it moved.
 * It is here because the first consumer had written it twice - once on the
 * personal page, once on the team one - and the copies had already drifted:
 * one had grown a warning tone the other lacked, and the tone classes in it
 * were concatenated without a space, so a figure that was both accented and
 * warning would have emitted `text-accent-2text-warn` and been styled by
 * neither. Nothing had gone wrong on screen yet; the two flags were simply
 * never passed together.
 *
 * A `<dl>` rather than two divs, for the reason KeyValue is one: the pairing
 * is what a screen reader announces. Loose divs read as two unrelated pieces
 * of text and nothing says the number belongs to the label.
 *
 * Numbers are set in the mono face with tabular figures, so a column of tiles
 * lines up and a value that ticks does not shuffle its neighbours sideways.
 * That matters more than it sounds: a live figure redrawn every few seconds in
 * proportional digits makes the whole row twitch.
 *
 * The delta is a second, quieter line rather than a colour on the value. A
 * number that turns red is a number whose colour has to be explained, and the
 * explanation is never on the screen; a delta says "+12% vs last week" and
 * needs nothing. Its tone is stated by the caller rather than inferred from
 * the sign, because down is good for a figure like "time to first response",
 * and a component cannot know which figure it is holding.
 */

export const statTileVariants = cva('min-w-0', {
  variants: {
    size: {
      /* The dashboard default: a row of these under a heading. */
      md: '',
      /* For a tile that leads a page rather than sitting in a row of six. */
      lg: '',
    },
  },
  defaultVariants: { size: 'md' },
})

export const statTileValueVariants = cva('mt-1 font-mono tabular-nums', {
  variants: {
    size: {
      md: 'text-lg',
      lg: 'text-2xl',
    },
    tone: {
      /* The reading tone: what this figure is, not how it is doing. `accent`
       * marks the one figure a panel is really about; `warn` and `bad` are for
       * a figure that is itself a problem - people with no agent reporting,
       * a queue that is backing up. */
      default: 'text-text',
      accent: 'text-accent-2',
      warn: 'text-warn',
      bad: 'text-bad',
    },
  },
  defaultVariants: { size: 'md', tone: 'default' },
})

export const statTileDeltaVariants = cva('mt-1 text-xs', {
  variants: {
    tone: {
      /* Neutral by default, because most movement is just movement. */
      default: 'text-dim',
      good: 'text-good',
      bad: 'text-bad',
    },
  },
  defaultVariants: { tone: 'default' },
})

/*
 * A tone that is a judgement has to bring a mark with it.
 *
 * `warn` and `bad` say this figure is a problem, and on a dashboard that claim
 * is carried by colour alone - which is exactly where it fails. The line's own
 * accents sit close to the status hues: measured in OKLab, the first
 * consumer's gold is Delta-E 3.7 from `--warn`, hilvan's is 2.5 from `--bad`,
 * and four more products are inside 8.3. One tile accented and another warning
 * are, to a reader glancing down a row, the same colour.
 *
 * Neither side can move. The status hues are the line's shared language and
 * the accents come from the brand registry, so the fix is the rule the theme
 * already states in prose: meaning never rests on colour alone. Here it is
 * structure instead - the type will not let a judgement be drawn without a
 * mark beside it.
 *
 * The first consumer had already worked this out by hand, wrapping its value
 * in a flex row with a warning triangle. That is the proof the requirement is
 * real, and the reason it belongs in the primitive rather than in a guideline
 * nobody reads twice.
 */
type ToneWithMark =
  | {
      /** The reading tone. `default` and `accent` carry no judgement, so they
       * need no mark. */
      tone?: 'default' | 'accent'
      /** A glyph before the figure. Optional here. */
      icon?: ReactNode
    }
  | {
      /** A judgement: this figure is itself the problem. */
      tone: 'warn' | 'bad'
      /** Required with a judgement, and not decoration - it is what tells the
       * figure apart from an accented one for a reader who does not separate
       * the two hues, or is looking at a projector. */
      icon: ReactNode
    }

export type StatTileProps = Omit<HTMLAttributes<HTMLDListElement>, 'title'> &
  VariantProps<typeof statTileVariants> &
  ToneWithMark & {
    /** What the figure is. */
    label: ReactNode
    /** The figure. Already formatted - a duration, a count, a percentage: this
     * component decides how a number looks, never what it says. */
    value: ReactNode
    /** Which way it moved, in words the caller chooses: `+12% vs last week`,
     * `3 fewer than yesterday`. Omitted when there is nothing to compare to -
     * an empty line here reads as "unchanged", which is a claim. */
    delta?: ReactNode
    /** Whether that movement is good news. Stated rather than read off the
     * sign, because for a figure like time-to-answer a fall is the good
     * direction. */
    deltaTone?: NonNullable<VariantProps<typeof statTileDeltaVariants>['tone']>
  }

export function StatTile({
  label,
  value,
  tone,
  icon,
  delta,
  deltaTone,
  size,
  className,
  ...props
}: StatTileProps) {
  return (
    <dl className={cn(statTileVariants({ size }), className)} {...props}>
      <dt className="text-xs font-medium text-dim">{label}</dt>
      <dd className={cn(statTileValueVariants({ size, tone }), icon && 'flex items-center gap-1.5')}>
        {/* Hidden from the reader: the mark restates the tone, and the tone is
         * already in the words of the label. Announcing "warning" before the
         * number would be the screen reader saying twice what the sighted
         * reader sees once. */}
        {icon && <span className="shrink-0" aria-hidden>{icon}</span>}
        {value}
      </dd>
      {/* A second `dd` for the same term: the spec allows several, and this is
       * what they are for - one fact with two parts. A `<div>` here would end
       * the description list's pairing, and the delta would be read as loose
       * text next to the number rather than as part of it. */}
      {delta !== undefined && delta !== null && (
        <dd className={cn(statTileDeltaVariants({ tone: deltaTone }))}>{delta}</dd>
      )}
    </dl>
  )
}

/*
 * A row of tiles.
 *
 * Both donors wrote the identical container - `flex flex-wrap items-baseline
 * gap-x-8 gap-y-3` inside a Panel - and both had to get `items-baseline`
 * right, which is the part that is easy to miss: without it, a tile carrying a
 * delta is taller than its neighbours and the whole row's numbers stop sharing
 * a line.
 *
 * Wrapping rather than a grid, because the number of figures is decided at
 * runtime (one donor hides two of its five until there is something to say),
 * and a grid with a fixed column count leaves a hole where a hidden tile was.
 */
export type StatRowProps = HTMLAttributes<HTMLDivElement>

export function StatRow({ className, ...props }: StatRowProps) {
  return <div className={cn('flex flex-wrap items-baseline gap-x-8 gap-y-3', className)} {...props} />
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * StatusDot and StatusBadge.
 *
 * The smallest thing a screen can say about something's condition: a server is
 * up, a job failed, a person is away. Every product of the line drew its own
 * coloured circle, and every one of them drew it the same way - a `<span>` with
 * a background - which means the condition existed for exactly the readers who
 * could see it.
 *
 * The rule this pair is built on, and the reason a dot is not a component you
 * can call with a colour alone:
 *
 *   **Colour is emphasis. The word is the message.**
 *
 * That is not a preference. About one man in twelve does not separate red from
 * green, `--good` and `--bad` are the two hues most screens rest on, and a
 * printed or projected screen loses the distinction for everybody. The theme
 * already states the rule in prose; here it is structure: `StatusDot` will not
 * render without a label, and a label that is not shown is placed where a
 * screen reader will still read it.
 *
 * `StatusBadge` is the same fact when there is room to write it out. It exists
 * separately rather than as a variant because the choice between them is about
 * the space on the screen, not about the state - and a product that has the
 * room should be nudged to use the words.
 *
 * What neither does is carry a word of its own. "Online" is the product's
 * vocabulary in the product's language, and a primitive that shipped English
 * strings could not be translated.
 */

/** The conditions the line's vocabulary can name.
 *
 * `neutral` is not a fifth colour - it is the absence of a judgement, for the
 * states that are neither good nor bad: queued, archived, unknown. Drawing
 * those in one of the four would be a claim the product did not make. */
export type Status = 'good' | 'warn' | 'bad' | 'info' | 'neutral'

export const statusDotVariants = cva('inline-block shrink-0 rounded-full', {
  variants: {
    status: {
      good: 'bg-good',
      warn: 'bg-warn',
      bad: 'bg-bad',
      info: 'bg-info',
      neutral: 'bg-line-2',
    },
    size: {
      /* Beside `text-xs`, where a dot much larger than the x-height reads as a
       * bullet rather than as a state. */
      sm: 'size-1.5',
      md: 'size-2',
      lg: 'size-2.5',
    },
  },
  defaultVariants: { status: 'neutral', size: 'md' },
})

/** The status as ink rather than as a fill - what an icon standing in for the
 * dot is drawn in. Separate from the fill variants because the two are used in
 * different places and a single `cva` would have to undo one to get the
 * other. */
const statusInk: Record<Status, string> = {
  good: 'text-good',
  warn: 'text-warn',
  bad: 'text-bad',
  info: 'text-info',
  neutral: 'text-dim',
}

export interface StatusDotProps
  extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'>,
    VariantProps<typeof statusDotVariants> {
  /**
   * What this condition is called, in the product's words. Required, and not
   * for decoration: it is what the dot means to anyone who does not see the
   * colour.
   */
  label: string
  /**
   * Whether to print the label beside the dot.
   *
   * `false` keeps it for a screen reader only - the right answer inside a
   * dense table cell, where the column heading already says what is being
   * judged. It is never dropped.
   */
  showLabel?: boolean
  /**
   * A shape drawn inside the dot's place instead of the circle - a tick, a
   * cross, an exclamation. The second channel for a reader who sees the dot
   * but not its hue, and the reason `pulse` is not the only way to differ.
   */
  icon?: ReactNode
}

/**
 * A dot, and the word it stands for.
 *
 * The word is always in the accessibility tree. When it is not printed the dot
 * is not `aria-hidden` and not `role="presentation"` - it is a labelled image,
 * because a status nobody can read is the defect this component exists to
 * prevent.
 */
export function StatusDot({
  status,
  size,
  label,
  showLabel = false,
  icon,
  className,
  ...props
}: StatusDotProps) {
  const mark = icon ? (
    // The icon stands where the dot would, so it takes the status as its ink
    // rather than as a fill.
    <span
      className={cn('inline-flex shrink-0 items-center justify-center', statusInk[status ?? 'neutral'])}
      aria-hidden
    >
      {icon}
    </span>
  ) : (
    <span className={statusDotVariants({ status, size })} aria-hidden />
  )

  return (
    <span
      className={cn('inline-flex items-center gap-1.5 whitespace-nowrap', className)}
      // Announced as one thing. Without this the dot and the word are two
      // nodes and a reader hears the label twice - once from the image, once
      // from the text beside it.
      role="img"
      aria-label={label}
      {...props}
    >
      {mark}
      {showLabel && (
        <span className="text-xs text-dim" aria-hidden>
          {label}
        </span>
      )}
    </span>
  )
}

export const statusBadgeVariants = cva(
  'inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap',
  {
    variants: {
      status: {
        good: 'bg-good-soft text-good',
        warn: 'bg-warn-soft text-warn',
        bad: 'bg-bad-soft text-bad',
        info: 'bg-info-soft text-info',
        neutral: 'bg-soft text-dim',
      },
    },
    defaultVariants: { status: 'neutral' },
  },
)

export interface StatusBadgeProps
  extends HTMLAttributes<HTMLSpanElement>,
    VariantProps<typeof statusBadgeVariants> {
  /** A shape before the word - the second channel, where there is one. */
  icon?: ReactNode
  /** Draw the dot before the word. Off when an `icon` is given: two marks for
   * one state is noise. */
  dot?: boolean
}

/**
 * The state, written out, on a tinted ground.
 *
 * Distinct from `Badge`, which is a label of any kind: this one is about a
 * condition, takes the same `Status` vocabulary as the dot, and is what a
 * product should reach for when the answer is "failed" rather than "3".
 *
 * No `role="img"` here and no `aria-label`: the word is on the screen, and
 * naming the element as an image would replace the text a reader can already
 * hear with a duplicate of it.
 */
export function StatusBadge({
  status,
  icon,
  dot = true,
  className,
  children,
  ...props
}: StatusBadgeProps) {
  const showDot = dot && !icon
  return (
    <span className={cn(statusBadgeVariants({ status }), className)} {...props}>
      {icon && (
        <span className="inline-flex shrink-0 items-center justify-center" aria-hidden>
          {icon}
        </span>
      )}
      {showDot && (
        <span
          className={cn(
            'inline-block size-1.5 shrink-0 rounded-full',
            // `currentColor` rather than the status fill: inside the badge the
            // text already carries the hue, and a second token would drift
            // from it the first time either changed.
            'bg-current',
          )}
          aria-hidden
        />
      )}
      {children}
    </span>
  )
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Stepper.
 *
 * The steps of a task too long for one screen, and where you stand in them:
 * set up a workspace, import a library, configure a connection. It is a
 * picture of progress on its own, and the top of a Wizard when the steps are
 * a form - a product can show how far along something is without owning the
 * form that moves it, which is why the two are separate components. Base UI
 * has no stepper, so this one is written here rather than wrapped.
 *
 * An ordered list, like Breadcrumbs, because the order is the meaning: a
 * reader hears "list, 4 items" and then the steps in the order they are taken.
 * The step you are on carries `aria-current="step"`, which is what tells a
 * reader which of the four is the one in front of them rather than a list of
 * four equal names.
 *
 * **Meaning does not rest on colour.** A finished step draws a tick, a step
 * that failed its check draws an exclamation mark, the current one a filled
 * number and the ones ahead an outlined number - four shapes, so the stepper
 * reads in a greyscale screenshot and for the one man in twelve who does not
 * separate the accent from the error hue. The same states are written out for
 * a reader, in words the product gives (`stateLabels`): the component has no
 * strings of its own, because "Completed" is the product's vocabulary in the
 * product's language.
 *
 * **Narrow, it keeps the marks and drops the words.** A horizontal stepper in
 * a container narrower than `@xl` shows every step's mark but only the
 * current step's label; the others move off the screen and stay in the
 * accessibility tree. The marks still say how far along you are and which
 * steps are done, and `summary` - "Step 2 of 5", in the product's words - can
 * say it outright. Wrapping five labels onto three lines was the alternative,
 * and it turns a progress line into a paragraph. The breakpoint is the
 * container's, not the viewport's, since a wizard in a dialog is narrow on a
 * wide screen.
 *
 * **Going ahead is not a click away.** Steps are clickable only when the
 * product asks (`onStepSelect`), and even then only the steps already reached
 * - done, failed, or current. Clicking a step ahead is how a wizard's
 * validation is usually skipped: the user lands on step four with step two
 * half-filled and nothing ever checked it. `reach="any"` opens the steps ahead
 * too, and is named so that choosing it is a decision.
 */

/** Where a step stands. `error` is a step whose check failed - it is shown with
 * its own mark whether it is behind you or the one you are on. */
export type StepState = 'done' | 'current' | 'upcoming' | 'error'

export interface StepperStep {
  id: string
  label: ReactNode
  description?: ReactNode
  /**
   * What the step is, stated rather than inferred. Without it a step before
   * the current one is done and a step after it is upcoming; `done` marks a
   * step ahead that was already completed (the user went back), `error` a
   * step that failed its check.
   */
  status?: 'done' | 'error'
}

/** The words a reader hears for the states the marks draw. `current` has none:
 * `aria-current="step"` already says it, in the reader's own language. */
export interface StepStateLabels {
  done: string
  error: string
  /** Optional, because an unmarked step reads as not yet reached. */
  upcoming?: string
}

/** The mark in front of each label. Every state differs in shape as well as in
 * hue - a tick, a mark, a filled number, an outlined number - which is the
 * rule the whole component rests on. */
export const stepMarkerVariants = cva(
  [
    'inline-flex shrink-0 items-center justify-center rounded-full text-xs font-semibold tabular-nums',
    'transition-colors duration-(--duration-base) ease-(--ease-out)',
  ],
  {
    variants: {
      state: {
        done: 'bg-accent-soft text-accent',
        current: 'bg-accent text-on-accent',
        upcoming: 'border border-line-2 text-dim',
        error: 'bg-bad-soft text-bad',
      },
    },
    defaultVariants: { state: 'upcoming' },
  },
)

export interface StepperProps extends Omit<HTMLAttributes<HTMLElement>, 'children' | 'onSelect'> {
  /** What the list is called for a reader - "Setup steps". */
  label: string
  steps: readonly StepperStep[]
  /** The id of the step being shown. */
  current: string
  /** The words for the states, read by a screen reader beside each label. */
  stateLabels: StepStateLabels
  /**
   * The position in words - `(2, 5) => 'Step 2 of 5'`. Shown only when a
   * horizontal stepper is too narrow for its labels. A function of the two
   * numbers rather than a string, because the product says it in its own
   * language and grammar.
   */
  summary?: (position: number, total: number) => ReactNode
  /** Makes reachable steps buttons. Without it the stepper is a picture of
   * progress and nothing in it is a control. */
  onStepSelect?: (id: string) => void
  /**
   * Which steps can be clicked. `visited` - the default - is done, failed and
   * current ones; `any` also opens the ones ahead, which skips whatever check
   * stands between here and there. Only a product that has made the steps
   * independent should choose it.
   */
  reach?: 'visited' | 'any'
  /** A row across the top, or a column down the side. Only the row folds its
   * labels away when narrow; a column has the height to keep them. */
  orientation?: 'horizontal' | 'vertical'
}

/** A step's state from its place and from what the product said about it. */
export function stepState(step: StepperStep, index: number, currentIndex: number): StepState {
  if (step.status === 'error') return 'error'
  if (index === currentIndex) return 'current'
  if (step.status === 'done' || index < currentIndex) return 'done'
  return 'upcoming'
}

export function Stepper({
  label,
  steps,
  current,
  stateLabels,
  summary,
  onStepSelect,
  reach = 'visited',
  orientation = 'horizontal',
  className,
  ...props
}: StepperProps) {
  const horizontal = orientation === 'horizontal'
  const currentIndex = steps.findIndex((step) => step.id === current)

  const list = (
    <>
      {horizontal && summary && currentIndex >= 0 && (
        // Only in the narrow form, where the labels have gone and the position
        // needs saying. `hidden` rather than `sr-only` in the wide form: there
        // the list says it, and a reader hearing it twice is hearing noise.
        <p className="mb-2 text-xs text-dim @xl:hidden">{summary(currentIndex + 1, steps.length)}</p>
      )}
      <ol
        className={cn(
          'flex',
          horizontal ? 'items-center gap-2' : 'flex-col',
        )}
      >
        {steps.map((step, index) => {
          const state = stepState(step, index, currentIndex)
          const isCurrent = index === currentIndex
          const reachable = reach === 'any' || index <= currentIndex || state !== 'upcoming'
          return (
            <StepperItem
              key={step.id}
              step={step}
              index={index}
              state={state}
              isCurrent={isCurrent}
              last={index === steps.length - 1}
              horizontal={horizontal}
              stateLabels={stateLabels}
              onSelect={onStepSelect && reachable ? () => onStepSelect(step.id) : undefined}
            />
          )
        })}
      </ol>
    </>
  )

  // A landmark only when there is somewhere to go. A stepper nobody can click
  // is a progress picture, and announcing it as navigation would promise a
  // reader controls that are not there.
  return onStepSelect ? (
    <nav aria-label={label} className={cn('@container min-w-0', className)} {...props}>
      {list}
    </nav>
  ) : (
    <div
      role="group"
      aria-label={label}
      className={cn('@container min-w-0', className)}
      {...props}
    >
      {list}
    </div>
  )
}

function StepperItem({
  step,
  index,
  state,
  isCurrent,
  last,
  horizontal,
  stateLabels,
  onSelect,
}: {
  step: StepperStep
  index: number
  state: StepState
  isCurrent: boolean
  last: boolean
  horizontal: boolean
  stateLabels: StepStateLabels
  onSelect?: () => void
}) {
  const stateWord =
    state === 'done' ? stateLabels.done : state === 'error' ? stateLabels.error : state === 'upcoming' ? stateLabels.upcoming : undefined

  // Narrow and horizontal, only the current step keeps its words on the
  // screen. The others go to `sr-only`, not `hidden`: a reader still hears
  // every step.
  const collapsible = horizontal && !isCurrent
  const text = (
    <span className={cn('flex min-w-0 flex-col', collapsible && 'sr-only @xl:not-sr-only')}>
      <span
        className={cn(
          'truncate text-sm',
          isCurrent ? 'font-semibold text-text' : 'text-dim',
          state === 'error' && 'text-bad',
        )}
      >
        {step.label}
      </span>
      {step.description !== undefined && (
        <span className={cn('text-xs text-faint', horizontal && 'sr-only @xl:not-sr-only @xl:truncate')}>
          {step.description}
        </span>
      )}
      {stateWord && <span className="sr-only">{stateWord}</span>}
    </span>
  )

  const glyph =
    state === 'done' ? <Tick /> : state === 'error' ? <Mark /> : <span>{index + 1}</span>

  const itemClass = cn(
    'flex min-w-0 items-start gap-2 rounded-md text-left',
    horizontal ? 'items-center' : 'items-start',
  )

  const item = onSelect ? (
    <button
      type="button"
      aria-current={isCurrent ? 'step' : undefined}
      onClick={onSelect}
      className={cn(
        itemClass,
        'cursor-pointer py-1 pr-1 transition-colors duration-(--duration-quick) hover:bg-soft',
        'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
      )}
    >
      <span aria-hidden className={cn('size-6', stepMarkerVariants({ state }))}>
        {glyph}
      </span>
      {text}
    </button>
  ) : (
    <span aria-current={isCurrent ? 'step' : undefined} className={cn(itemClass, 'py-1')}>
      <span aria-hidden className={cn('size-6', stepMarkerVariants({ state }))}>
        {glyph}
      </span>
      {text}
    </span>
  )

  // The line joining a step to the next: accent once the step is behind you,
  // so the run of finished steps reads as one stroke. Drawing, not structure -
  // the list already says the steps are in order.
  const done = state === 'done'
  const connector = last ? null : (
    <span
      aria-hidden
      className={cn(
        'transition-colors duration-(--duration-base) ease-(--ease-out)',
        done ? 'bg-accent' : 'bg-line',
        horizontal ? 'h-px min-w-3 flex-1' : 'absolute top-8 bottom-0 left-3 w-px',
      )}
    />
  )

  return (
    <li
      className={cn(
        horizontal
          ? cn('flex min-w-0 items-center gap-2', last ? 'shrink-0' : 'flex-1', isCurrent && 'shrink')
          : cn('relative', !last && 'pb-4'),
      )}
    >
      {item}
      {connector}
    </li>
  )
}

function Tick() {
  return (
    <svg viewBox="0 0 16 16" width="14" height="14" fill="none" aria-hidden>
      <path d="M3.5 8.5l3 3 6-7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

function Mark() {
  return (
    <svg viewBox="0 0 16 16" width="14" height="14" fill="none" aria-hidden>
      <path d="M8 3.5v5.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <circle cx="8" cy="12.25" r="1.25" fill="currentColor" />
    </svg>
  )
}

/*
 * How a column is ordered, with no React in it.
 *
 * Split out of the Table for the reason `calendar-math` was split out of the
 * Calendar: these are the sums, and the component is the thing that draws
 * them. A product sorting its own rows - on the server, in a worker, before
 * the data ever reaches a component - imports this and nothing else.
 *
 * No table library, deliberately. The obvious choice here is TanStack Table,
 * and it would be the first dependency a product has to install beyond Base
 * UI. What it offers is a model of columns, pages and sorting state; what the
 * line's one real table needed was the rule below, which the model does not
 * have. So the model is the part that is written here, and it is small.
 *
 * The rule, and the reason this file exists at all:
 *
 *   **Absence sorts last, whichever way the column points.**
 *
 * A row with no value in this column is not the smallest - it is unknown, and
 * the two are different facts. Rank absence with the rest and flip the sign,
 * and a descending sort floats every empty row to the top: the reader asks for
 * "highest first" and is handed the rows that have no value at all. This is
 * measured rather than assumed - it is what the first version of the line's
 * catalogue did, and the fix is the shape below, where presence is settled
 * before the direction is applied.
 *
 * It is the same fact `RatingScale` is built on: not judged yet is a state,
 * not a zero. A table that sorts them together loses it on the first click.
 */

/** Which way a column points. */
export type SortDirection = 'asc' | 'desc'

/** A column, and which way it points. `column` is the caller's own key - the
 * id it gave the column, not an index, so reordering columns cannot silently
 * change what is sorted. */
export interface Sort<Column extends string = string> {
  column: Column
  direction: SortDirection
}

/** What can be compared. `null` and `undefined` both mean absent - a product
 * gets whichever its data uses, and having to normalise them before sorting
 * is the kind of step that gets forgotten in one branch of a switch. */
export type SortValue = string | number | boolean | null | undefined

/** Reads the value of a column out of a row.
 *
 * Given rather than inferred: a column id is not always a field name, and a
 * sortable column is often a computed one - a duration that is stored as two
 * timestamps, a name that sorts by surname. */
export type SortAccessor<Row, Column extends string = string> = (
  row: Row,
  column: Column,
) => SortValue

export interface SortOptions<Row> {
  /** The tiebreaker: what decides the order of rows that compare equal.
   *
   * Without one, `Array.prototype.sort` is stable and therefore leaves ties in
   * input order - which sounds fine until the input is re-fetched and arrives
   * in a different order, and a column of ties reshuffles under the reader
   * with no click. Pass the row's id. */
  tiebreak?: (row: Row) => SortValue
  /** The language text is compared in - the application's, from
   * `useLocale()`. Passed to `Intl.Collator`, so `ä` sorts where the reader
   * expects rather than after `z`. Required: left out, the collator used the
   * browser's language, which is not the one the table is written in. */
  locale: string
}

/** Order the rows. Returns a new array; the input is not touched, because a
 * component that sorts its own prop in place mutates the caller's state. */
export function sortRows<Row, Column extends string = string>(
  rows: readonly Row[],
  sort: Sort<Column>,
  accessor: SortAccessor<Row, Column>,
  options: SortOptions<Row>,
): Row[] {
  const sign = sort.direction === 'asc' ? 1 : -1
  // One collator for the whole sort rather than one `localeCompare` per
  // comparison: building it is the expensive half, and a sort of n rows asks
  // for it n log n times.
  const collator = new Intl.Collator(options.locale)

  return [...rows].sort((a, b) => {
    const left = accessor(a, sort.column)
    const right = accessor(b, sort.column)

    // Presence first, and outside the sign. This is the whole point of the
    // file: absence is last in both directions.
    const absent = presence(left, right)
    if (absent !== 0) return absent

    const ranked = compareValues(left, right, collator) * sign
    if (ranked !== 0) return ranked

    if (options.tiebreak) {
      const tied = compareValues(options.tiebreak(a), options.tiebreak(b), collator)
      // Deliberately not multiplied by the sign. The tiebreaker is there to
      // make the order stable, and an order that reverses with the column is
      // not stable - the rows that tie would swap places on every click.
      if (tied !== 0) return tied
    }
    return 0
  })
}

/** Whether a value counts as absent.
 *
 * Both spellings of nothing, and neither `0` nor `''` nor `false`, which are
 * values a row genuinely has.
 *
 * `NaN` counts too, and that is not tidiness. Subtraction with it returns
 * `NaN`, which `sort` reads as "these two are equal" - so a row whose number
 * is not a number takes whatever place the input happened to give it, and the
 * order changes when the data is re-fetched. A number that is not a number is
 * not a small number; it is unknown, which is what this file already has a
 * place for. */
export function isAbsent(value: SortValue): boolean {
  if (value === null || value === undefined) return true
  return typeof value === 'number' && Number.isNaN(value)
}

/** Which of the two lacks a value; absent sorts last, always. */
function presence(left: SortValue, right: SortValue): number {
  const leftHas = !isAbsent(left)
  const rightHas = !isAbsent(right)
  if (leftHas === rightHas) return 0
  return leftHas ? -1 : 1
}

/** Compare two present values of the same column.
 *
 * Numbers by subtraction, text by collator, and booleans as false-then-true.
 * A column whose values are of mixed type compares as text: that is a data
 * problem the table cannot fix, and ordering by `String` at least gives the
 * same answer twice. */
function compareValues(left: SortValue, right: SortValue, collator: Intl.Collator): number {
  if (isAbsent(left) || isAbsent(right)) return presence(left, right)

  // NaN never reaches here: `isAbsent` counts it as absent, so `presence`
  // settles it above, outside the sign.
  if (typeof left === 'number' && typeof right === 'number') return left - right
  if (typeof left === 'boolean' && typeof right === 'boolean') {
    return Number(left) - Number(right)
  }
  return collator.compare(String(left), String(right))
}

/** What clicking a column heading does.
 *
 * Three states rather than two, and the third is the reason this is a function
 * and not `direction === 'asc' ? 'desc' : 'asc'`: clicking a *different*
 * column starts it ascending rather than inheriting the direction of the one
 * before. Inheriting is what a two-state toggle does, and it means the first
 * click on a new column can hand back an order nobody asked for. */
export function toggleSort<Column extends string>(
  sort: Sort<Column>,
  column: Column,
): Sort<Column> {
  if (sort.column !== column) return { column, direction: 'asc' }
  return { column, direction: sort.direction === 'asc' ? 'desc' : 'asc' }
}

/** What a column heading announces: `ascending`, `descending`, or nothing.
 *
 * The value belongs in `aria-sort` on the `<th>`, and only on the one that is
 * sorted - `aria-sort="none"` on every other heading is allowed by the spec
 * and read out by some screen readers on every cell, which turns a table into
 * a recital. `undefined` removes the attribute. */
export function ariaSort(
  sort: Sort<string> | undefined,
  column: string,
): 'ascending' | 'descending' | undefined {
  if (!sort || sort.column !== column) return undefined
  return sort.direction === 'asc' ? 'ascending' : 'descending'
}

import type { HTMLAttributes, TdHTMLAttributes, ThHTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { ariaSort, type Sort } from './table-sort'

/*
 * A table of rows, and the heading that reorders them.
 *
 * Parts rather than a `columns` prop, and that is the decision worth stating:
 * a `<DataTable columns={…} rows={…} />` is quicker to write for the first
 * table and then owns every cell in the product forever. The moment one column
 * needs a Badge, another a link, and a third the row's own menu, the prop
 * grows a `render` for each - at which point it is JSX with extra steps, spelt
 * in a shape only this component understands.
 *
 * So the parts are the ones HTML already has, dressed: a caller writes
 * `<TableRow>` and `<TableCell>` and puts whatever it likes inside. What is
 * bought by having them here rather than in the product is that every table of
 * the line has the same row height, the same heading, the same hairline and
 * the same behaviour when a column is sorted - and that a heading that sorts
 * announces it, which is the part hand-rolled tables get wrong.
 *
 * The sorting arithmetic is next door in `table-sort`, with no React in it -
 * a product that sorts on the server imports that and never this.
 *
 * `<TableScroll>` exists because a table cannot scroll itself: `overflow` on a
 * `<table>` does nothing, so the wrapper is not decoration but the only place
 * a scrollbar can live. It is also what makes the sticky heading work, since
 * `position: sticky` needs a scroll container to stick inside.
 */

/*
 * Row height follows the density of the region, like every other control.
 *
 * This had a `density` prop of its own, with its own words - `base` and
 * `dense` - which made "density" mean two different things in one set: an
 * attribute on a container for fields, a prop on this one element for rows. A
 * product wanting a tight screen had to know both and set both, and a table
 * inside a compact form stayed comfortable unless somebody remembered.
 *
 * Now it reads `--row-cell`, so `data-density="compact"` on anything above it
 * tightens the rows with everything else. The font does not shrink with it:
 * shrinking the text too is how a dense table becomes an unreadable one.
 */
export const tableVariants = cva(
  'w-full border-collapse text-left text-sm [&_td]:py-row [&_th]:py-row',
)

export interface TableProps
  extends HTMLAttributes<HTMLTableElement>,
    VariantProps<typeof tableVariants> {}

export function Table({ className, ...props }: TableProps) {
  return <table className={cn(tableVariants(), className)} {...props} />
}

/** The scroll container a table needs, and the one a sticky heading sticks in.
 *
 * The scrollbar is the theme's - an overlay that takes no room in the layout,
 * so a table that grows past the fold does not shift the column beside it. */
export function TableScroll({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('w-full overflow-x-auto', className)} {...props} />
}

export interface TableHeadProps extends HTMLAttributes<HTMLTableSectionElement> {
  /** Keep the heading in view while the body scrolls under it.
   *
   * Off by default. A sticky heading needs a container with a height to stick
   * inside; switched on by default it would silently do nothing in the common
   * case - a table that scrolls with the page - and look broken in the other. */
  sticky?: boolean
}

export function TableHead({ sticky = false, className, ...props }: TableHeadProps) {
  return (
    <thead
      className={cn(
        'text-xs text-dim',
        // The heading needs its own ground when it is sticky: transparent, it
        // would have the body's rows sliding visibly beneath its text.
        sticky && 'sticky top-0 z-sticky bg-bg',
        className,
      )}
      {...props}
    />
  )
}

export function TableBody({ className, ...props }: HTMLAttributes<HTMLTableSectionElement>) {
  return <tbody className={cn('', className)} {...props} />
}

export interface TableRowProps extends HTMLAttributes<HTMLTableRowElement> {
  /** The row the reader has picked out - the one open in the panel beside the
   * table, the one a keyboard cursor is on. Not a hover state. */
  selected?: boolean
}

export function TableRow({ selected = false, className, ...props }: TableRowProps) {
  return (
    <tr
      // Announced rather than only drawn: a row picked out by colour alone is
      // a row nobody using a screen reader knows about.
      aria-selected={selected || undefined}
      className={cn(
        'border-b border-line transition-colors last:border-b-0',
        selected ? 'bg-accent-soft' : 'hover:bg-soft',
        className,
      )}
      {...props}
    />
  )
}

export interface TableCellProps extends TdHTMLAttributes<HTMLTableCellElement> {
  /** Right-align and use the lining figures. For a column of numbers, and the
   * reason it is a prop rather than a class the caller adds: a column of
   * numbers that is not aligned is the most common defect in a table, and the
   * one nobody files a bug about. */
  numeric?: boolean
}

export function TableCell({ numeric = false, className, ...props }: TableCellProps) {
  return (
    <td
      className={cn('px-3 align-middle', numeric && 'text-right tabular-nums', className)}
      {...props}
    />
  )
}

export interface TableHeaderProps extends ThHTMLAttributes<HTMLTableCellElement> {
  numeric?: boolean
}

/** A plain heading, for a column that does not sort. */
export function TableHeader({ numeric = false, className, ...props }: TableHeaderProps) {
  return (
    <th
      scope="col"
      className={cn(
        'px-3 font-medium',
        numeric && 'text-right tabular-nums',
        className,
      )}
      {...props}
    />
  )
}

export interface TableSortHeaderProps extends Omit<TableHeaderProps, 'onClick'> {
  /** This column's id - the key the accessor sorts by. */
  column: string
  /** What is sorted now, across the whole table. */
  sort: Sort | undefined
  onSortChange: (column: string) => void
}

/** A heading that reorders the table when clicked.
 *
 * A real `<button>` inside the `<th>`, not a click handler on the cell: the
 * cell is not focusable, gets no keyboard, and announces nothing. This is the
 * part a hand-rolled table almost always gets wrong, and it is invisible to
 * everyone who reorders with a mouse.
 *
 * The arrow is `aria-hidden`, because `aria-sort` on the cell already says
 * which way the column points - a reader would otherwise hear the direction
 * twice, once as a word and once as a character nobody meant to publish. */
export function TableSortHeader({
  column,
  sort,
  onSortChange,
  numeric = false,
  className,
  children,
  ...props
}: TableSortHeaderProps) {
  const active = sort?.column === column
  const direction = sort?.direction

  return (
    <th
      scope="col"
      // Only on the sorted column. `aria-sort="none"` on every other heading
      // is valid and gets announced by some readers on every cell.
      aria-sort={ariaSort(sort, column)}
      className={cn('px-3 font-medium', numeric && 'tabular-nums', className)}
      {...props}
    >
      <button
        type="button"
        onClick={() => onSortChange(column)}
        className={cn(
          'group -mx-1 inline-flex w-[calc(100%+0.5rem)] cursor-pointer items-center gap-1 rounded-sm px-1',
          'transition-colors hover:text-text',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
          active && 'text-text',
          numeric && 'justify-end',
        )}
      >
        {children}
        <span
          aria-hidden
          className={cn(
            'text-2xs transition-opacity',
            // The arrow of the unsorted column appears on hover rather than
            // never: a heading that gives no sign it can be clicked is one
            // nobody clicks. It stays out of the way until the pointer is on
            // it, so a table of eight columns is not a row of eight arrows.
            active ? 'opacity-100' : 'opacity-0 group-hover:opacity-40',
          )}
        >
          {direction === 'desc' && active ? '▼' : '▲'}
        </span>
      </button>
    </th>
  )
}

/** What the table says when it has no rows.
 *
 * A row spanning every column rather than a block below the table, so the
 * heading stays where it is and the table does not change shape between having
 * rows and not. `colSpan` is required: without it the message sits under the
 * first column and the rest of the header hangs over nothing. */
export interface TableEmptyProps extends TdHTMLAttributes<HTMLTableCellElement> {
  colSpan: number
}

export function TableEmpty({ colSpan, className, ...props }: TableEmptyProps) {
  return (
    <tr>
      <td
        colSpan={colSpan}
        className={cn('px-3 py-10 text-center text-sm text-dim', className)}
        {...props}
      />
    </tr>
  )
}

import { createContext, useContext, type KeyboardEvent, type MouseEvent, type ReactNode } from 'react'
import { Tabs as Base } from '@base-ui/react/tabs'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Tabs - one place on a screen showing one of several views, or a window
 * showing one of several open documents.
 *
 * Two shapes, because the line has two needs and they look nothing alike.
 * `line` is the familiar row of words over a panel, the active one underlined
 * in the accent: settings split into sections, a record's details and its
 * history. `bar` is the strip of open documents that lives *inside* a
 * frameless window's title bar - scheda's trade, where a separate tab row under
 * a system title bar cost about sixty pixels of every laptop screen. A bar tab
 * is as tall as the bar, the active one takes the page's ground so it reads as
 * joined to the document below, and a two-pixel accent rule on its top edge
 * marks it where an underline would sit against the window's edge.
 *
 * Behaviour is Base UI's: arrow keys move between tabs, Home and End go to
 * the ends, the list loops, and the panel is wired to its tab with the ids a
 * reader needs. Nothing here re-implements that.
 *
 * A document tab can close, and that is where the obvious markup is wrong.
 * A close button *inside* a `tab` is an interactive element nested in another,
 * which a screen reader flattens into one control and a keyboard cannot reach
 * separately. So the cross is a sibling drawn over the tab, for the pointer
 * only - taken out of the tab order and the reading - and the keyboard closes
 * the focused tab with Delete, which the tab announces through
 * `aria-keyshortcuts`. A middle click closes too, the way every tabbed thing
 * does. The cross is always drawn, faintly, rather than revealed on hover: a
 * button that appears under the pointer is one the pointer was not aiming for.
 *
 * A document with unsaved changes carries a dot in the accent. The dot is
 * drawing; the words `modifiedLabel` gives are what a reader hears, and the
 * type will not accept one without the other.
 */

export function Tabs({ className, ...props }: Base.Root.Props) {
  return <Base.Root className={cn('flex min-w-0 flex-col data-[orientation=vertical]:flex-row', className)} {...props} />
}

export const tabsListVariants = cva('relative flex min-w-0', {
  variants: {
    variant: {
      line: 'gap-1 border-b border-line data-[orientation=vertical]:flex-col data-[orientation=vertical]:border-r data-[orientation=vertical]:border-b-0',
      // The strip scrolls sideways rather than squeezing: a window with twenty
      // documents open keeps every name legible and lets the bar scroll. The
      // scrollbar itself stays out of a forty-pixel bar.
      bar: 'h-full items-stretch overflow-x-auto [scrollbar-width:none]',
    },
  },
  defaultVariants: { variant: 'line' },
})

export interface TabsListProps extends Base.List.Props, VariantProps<typeof tabsListVariants> {
  /** A name for the list, when nothing on the screen already says what the
   * tabs choose between. Documents in a window bar need one. */
  'aria-label'?: string
}

type Variant = NonNullable<TabsListProps['variant']>

/* The list tells its tabs which shape they are, through context rather than a
 * CSS ancestor selector: a panel of `line` tabs inside a `bar` document would
 * match the outer list's selector too. */
const VariantContext = createContext<Variant>('line')

export function TabsList({ variant, className, children, ...props }: TabsListProps) {
  const shape: Variant = variant ?? 'line'
  return (
    <Base.List className={cn(tabsListVariants({ variant: shape }), className)} {...props}>
      <VariantContext.Provider value={shape}>{children}</VariantContext.Provider>
      {shape === 'line' && (
        <Base.Indicator
          className={cn(
            // Base UI measures the active tab and hands its box over as CSS
            // variables, so the rule slides between tabs rather than jumping.
            'absolute bottom-0 left-(--active-tab-left) h-0.5 w-(--active-tab-width) translate-y-px bg-accent',
            'transition-[left,width] duration-quick ease-out',
            'data-[orientation=vertical]:top-(--active-tab-top) data-[orientation=vertical]:right-0 data-[orientation=vertical]:bottom-auto data-[orientation=vertical]:left-auto',
            'data-[orientation=vertical]:h-(--active-tab-height) data-[orientation=vertical]:w-0.5 data-[orientation=vertical]:translate-x-px data-[orientation=vertical]:translate-y-0',
            'data-[orientation=vertical]:transition-[top,height]',
          )}
        />
      )}
    </Base.List>
  )
}

const tabBase = cn(
  'flex cursor-default items-center gap-1.5 whitespace-nowrap text-dim outline-none select-none',
  'transition-colors duration-quick',
  'hover:text-text data-[active]:text-text',
  'focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50',
)

/** The shape of a tab, told by the list it sits in. */
const tabShape: Record<Variant, string> = {
  line: 'h-9 rounded-md px-3 text-sm',
  bar: cn(
    'h-full border-r border-line pl-3 text-xs',
    'hover:bg-soft data-[active]:bg-bg data-[active]:shadow-[inset_0_2px_0_var(--accent)]',
  ),
}

type Modified =
  | { modified?: false; modifiedLabel?: never }
  | {
      /** The document has changes that are not saved. */
      modified: true
      /** What a reader hears for the dot, e.g. "unsaved changes". */
      modifiedLabel: string
    }

type Closable =
  | { onClose?: never; closeLabel?: never }
  | {
      /** Closes the tab: from the cross, a middle click, or Delete. */
      onClose: () => void
      /** The cross's tooltip, e.g. "Close notes.md". */
      closeLabel: string
    }

export type TabsTabProps = Omit<Base.Tab.Props, 'children'> & {
  children: ReactNode
} & Modified &
  Closable

export function TabsTab({
  className,
  children,
  modified,
  modifiedLabel,
  onClose,
  closeLabel,
  onKeyDown,
  onAuxClick,
  ...props
}: TabsTabProps) {
  const variant = useContext(VariantContext)
  const tab = (
    <Base.Tab
      className={cn(tabBase, tabShape[variant], onClose && (variant === 'bar' ? 'pr-8' : 'pr-9'), className)}
      aria-keyshortcuts={onClose ? 'Delete' : undefined}
      onKeyDown={(event: KeyboardEvent<HTMLElement>) => {
        onKeyDown?.(event as Parameters<NonNullable<typeof onKeyDown>>[0])
        if (onClose && event.key === 'Delete' && !event.defaultPrevented) {
          event.preventDefault()
          onClose()
        }
      }}
      onAuxClick={(event: MouseEvent<HTMLElement>) => {
        onAuxClick?.(event as Parameters<NonNullable<typeof onAuxClick>>[0])
        if (onClose && event.button === 1) {
          event.preventDefault()
          onClose()
        }
      }}
      {...props}
    >
      <span className="min-w-0 max-w-56 truncate">{children}</span>
      {modified && (
        <>
          <span aria-hidden className="size-1.5 shrink-0 rounded-full bg-accent" />
          {/* A space of its own, outside the spans: name computation trims
              each element's text, so a space inside one is lost and the
              reader hears "plan.mdunsaved changes". */}
          {' '}
          <span className="sr-only">{modifiedLabel}</span>
        </>
      )}
    </Base.Tab>
  )

  if (!onClose) return tab

  return (
    <span className="relative flex shrink-0">
      {tab}
      <button
        type="button"
        tabIndex={-1}
        aria-hidden
        title={closeLabel}
        onClick={onClose}
        className={cn(
          'target-min absolute top-1/2 right-2 flex size-4 -translate-y-1/2 cursor-default items-center justify-center rounded-sm',
          'text-faint transition-colors duration-quick hover:bg-soft hover:text-text',
        )}
      >
        <svg width="8" height="8" viewBox="0 0 8 8" fill="none" stroke="currentColor" strokeWidth="1.2" aria-hidden>
          <path d="M0.5 0.5l7 7M7.5 0.5l-7 7" />
        </svg>
      </button>
    </span>
  )
}

export function TabsPanel({ className, ...props }: Base.Panel.Props) {
  return (
    <Base.Panel
      className={cn(
        'min-w-0 flex-1 outline-none focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent',
        className,
      )}
      {...props}
    />
  )
}

import { useCallback, useState, type KeyboardEvent, type ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'
import { Chip } from './chip'

/*
 * TagInput.
 *
 * Free text turned into a list: type a word, press Enter, it becomes a chip.
 * This is the field for labels, keywords, recipients - anywhere the set of
 * values is not known in advance, which is exactly what separates it from
 * `Combobox multiple`. Choosing from a list is that component's job; this one
 * is for values that do not exist until someone types them.
 *
 * Base UI has no part for this, and the reason is worth stating: its Combobox
 * chips are for values chosen from a collection, and "create the thing I just
 * typed" is a decision about the product's data, not about the widget. So the
 * behaviour here is written, and written narrowly.
 *
 * What it does, and why each one is not optional:
 *
 * - **Enter commits.** The obvious one, and the reason it is a field at all.
 * - **Backspace on an empty input removes the last tag.** Without it the only
 *   way back is the mouse, and a list built by typing should be unbuildable
 *   by typing too.
 * - **Blur commits what was typed.** A word left in the box when the reader
 *   clicks Save is a word they believe they entered. Losing it silently is
 *   the single commonest complaint about fields of this shape.
 * - **Duplicates are refused, not stacked.** A tag list is a set.
 * - **Whitespace is trimmed and empties dropped**, so Enter on a blank input
 *   does nothing rather than adding a tag nobody can see.
 *
 * What it deliberately does not do: validate. What makes a tag acceptable -
 * length, charset, whether it must already exist - is the product's rule, and
 * a component that guessed would be wrong in both directions. Reject a value
 * by not putting it in `value`.
 */

export const tagInputVariants = cva(
  cn(
    fieldClasses,
    'flex flex-wrap items-center gap-1 py-1',
    'focus-within:outline-2 focus-within:outline-offset-0 focus-within:outline-accent',
  ),
  {
    variants: {
      size: {
        sm: 'min-h-8 text-xs',
        md: 'min-h-9',
        lg: 'min-h-10 text-base',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/* The box inside the box.
 *
 * `min-h-*` on the container sets a floor; the input inside it has a height of
 * its own, and that is what a reader actually sees. A size that moved only the
 * container moved nothing - measured, `sm` and `md` both came out 38px tall,
 * because the input was `h-7` in all three and its padding decided the rest.
 *
 * `tailwind-merge` does not rescue this either: `h-7` and `min-h-8` are not
 * the same property, so both survive and the fixed height wins. The two have
 * to be declared together.
 */
const tagInputBoxVariants = cva(
  'w-auto min-w-24 flex-1 bg-transparent px-1 text-text outline-none placeholder:text-faint',
  {
    variants: {
      size: {
        sm: 'h-6 text-xs',
        md: 'h-7 text-sm',
        lg: 'h-8 text-base',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

export interface TagInputProps extends VariantProps<typeof tagInputVariants> {
  /** The tags. Controlled: the product owns the list. */
  value: string[]
  /** Called with the next list. */
  onValueChange: (value: string[]) => void
  /** Placeholder for the text box, shown when there is room for it. */
  placeholder?: string
  /** Names the field. Required - a box of chips with no label names nothing. */
  'aria-label'?: string
  /** Or points at a label element, when there is a visible one. */
  'aria-labelledby'?: string
  /** How a tag's remove button is named, for a screen reader. Takes the tag,
   * so the product can say "Remove documentation" in its own language.
   *
   * Required, like `Chip`'s own: a remove button exists only when there is a
   * word for it, and a word this component invented would ship in English to
   * every reader who does not read English. */
  removeLabel: (tag: string) => string
  /** Cap on how many tags may be added. */
  max?: number
  disabled?: boolean
  /** Drawn after the input, inside the box - a counter, a hint. */
  children?: ReactNode
  className?: string
  id?: string
}

export function TagInput({
  value,
  onValueChange,
  placeholder,
  removeLabel,
  max,
  disabled,
  size,
  children,
  className,
  id,
  ...aria
}: TagInputProps) {
  const [draft, setDraft] = useState('')

  const full = max !== undefined && value.length >= max

  const commit = useCallback(
    (raw: string) => {
      const tag = raw.trim()
      // Empty, duplicate, or past the cap: nothing to add. The draft is
      // cleared either way, so Enter always leaves the box ready for the next
      // word rather than leaving a rejected one sitting there.
      if (tag && !value.includes(tag) && !full) onValueChange([...value, tag])
      setDraft('')
    },
    [full, onValueChange, value],
  )

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      // Only when there is something to commit: otherwise Enter belongs to the
      // form around this, and swallowing it would break submitting by keyboard.
      if (draft.trim()) {
        event.preventDefault()
        commit(draft)
      }
      return
    }
    if (event.key === 'Backspace' && draft === '' && value.length > 0) {
      onValueChange(value.slice(0, -1))
    }
  }

  return (
    <div
      className={cn(tagInputVariants({ size }), disabled && 'pointer-events-none opacity-50', className)}
    >
      {value.map((tag) => (
        <Chip
          key={tag}
          removeLabel={removeLabel(tag)}
          onRemove={() => onValueChange(value.filter((entry) => entry !== tag))}
        >
          {tag}
        </Chip>
      ))}
      <input
        id={id}
        value={draft}
        disabled={disabled}
        // The list is the value; the box is how you add to it. Announcing the
        // box as the field would name the wrong thing, so the label goes here
        // where a screen reader meets it.
        {...aria}
        placeholder={full ? undefined : placeholder}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={onKeyDown}
        // A word typed and not committed is a word the reader thinks they
        // entered. Blur is where that belief meets the form's Save button.
        onBlur={() => commit(draft)}
        className={tagInputBoxVariants({ size })}
      />
      {children}
    </div>
  )
}

import { useCallback, useLayoutEffect, useRef, type Ref, type TextareaHTMLAttributes } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * Textarea.
 *
 * A multi-line field that can grow with what is typed into it, which is the
 * only interesting part: a fixed box makes someone scroll inside a scroll,
 * and a box that grows without limit pushes the button they are trying to
 * reach off the screen. `autoResize` grows it; `maxRows` says when to stop
 * and let it scroll after all.
 *
 * The measurement is the usual trick and worth stating: height is reset to
 * `auto` before reading `scrollHeight`, because a box already tall enough
 * reports its own height and never shrinks back.
 */
export interface TextareaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  ref?: Ref<HTMLTextAreaElement>
  /** Grow to fit the content instead of scrolling. */
  autoResize?: boolean
  /** Stop growing here, in lines, and scroll instead. */
  maxRows?: number
}

export function Textarea({
  className,
  ref,
  autoResize = false,
  maxRows,
  onChange,
  ...props
}: TextareaProps) {
  const own = useRef<HTMLTextAreaElement>(null)

  const resize = useCallback(() => {
    const element = own.current
    if (!element || !autoResize) return

    // Reset first: a box that is already tall enough reports its own height as
    // `scrollHeight` and would never shrink again.
    element.style.height = 'auto'

    const styles = getComputedStyle(element)
    const lineHeight = Number.parseFloat(styles.lineHeight) || 0
    const vertical =
      Number.parseFloat(styles.paddingTop) +
      Number.parseFloat(styles.paddingBottom) +
      Number.parseFloat(styles.borderTopWidth) +
      Number.parseFloat(styles.borderBottomWidth)

    const wanted = element.scrollHeight
    const ceiling = maxRows && lineHeight ? maxRows * lineHeight + vertical : Infinity

    element.style.height = `${Math.min(wanted, ceiling)}px`
    element.style.overflowY = wanted > ceiling ? 'auto' : 'hidden'
  }, [autoResize, maxRows])

  // Before paint, so the field never appears at the wrong height and then
  // jumps - including on the first render, when it may already have a value.
  useLayoutEffect(resize, [resize, props.value, props.defaultValue])

  return (
    <textarea
      ref={(element) => {
        own.current = element
        if (typeof ref === 'function') ref(element)
        else if (ref) ref.current = element
      }}
      onChange={(event) => {
        resize()
        onChange?.(event)
      }}
      className={cn(fieldClasses, autoResize ? 'resize-none' : 'resize-y', className)}
      {...props}
    />
  )
}

import type { HTMLAttributes, KeyboardEvent, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Tiers: the band a number falls in, the road of bands, and one axis of the
 * score that produced it.
 *
 * The shape comes from kilna, where a work is scored on several axes and the
 * total lands in a named band - "draft", "publishable", "a clip". Two more
 * products of the line grade things the same way (a health score, a review
 * verdict), which is what makes this a primitive rather than a screen.
 *
 * The three pieces answer three different questions and are separate for that
 * reason:
 *
 * - `TierBadge` - *which band is this in?* A verdict, in one word.
 * - `TierRuler` - *how far into it, and how far to the next?* The verdict
 *   stops being a pronouncement out of nowhere: "nearly a clip" is the thing
 *   someone wants to know while they are still moving marks around.
 * - `AxisBar` - *what did one axis contribute?* A row of segments read left to
 *   right, which a column of numerals is not.
 *
 * The defect corrected on the way in, and the reason not to copy the donor as
 * it stands: its ruler drew the bands to scale and then laid the labels out
 * with `justify-between`, which spaces them evenly. With bands at 0, 50, 78
 * and 90 the label "78" sat a fifth of the bar away from the boundary it
 * named. Here the labels are placed by the same arithmetic as the bands, so
 * the distance you read is the distance there is.
 */

/** A band: where it starts, and what it is called.
 *
 * `min` is on the same scale as the value - 0-100 in every consumer so far,
 * but the components do not require it: `TierRuler` takes the ends explicitly.
 * The band runs from its `min` to the next band's, and the last one runs to
 * the end. */
export interface Tier {
  /** Stable key, for React and for the caller's own lookups. */
  key: string
  /** What it is called, in the product's words. */
  label: string
  /** The lowest value in this band. */
  min: number
  /** How the band is coloured. `accent` is the default - a band is a position
   * on the product's own scale, not a judgement in the status vocabulary. A
   * product that means "this one is bad" says so. */
  status?: 'accent' | 'good' | 'warn' | 'bad' | 'info' | 'neutral'
}

/**
 * The bands in order, with the ones that cannot be drawn dropped.
 *
 * Exported because a product that has tiers usually needs them sorted
 * somewhere else too, and because sorting inside a render is the kind of thing
 * that quietly becomes three different sorts.
 */
export function orderedTiers(tiers: Tier[], min = 0, max = 100): Tier[] {
  return tiers
    .filter((tier) => Number.isFinite(tier.min) && tier.min >= min && tier.min <= max)
    .sort((left, right) => left.min - right.min)
}

/**
 * Which band a value is standing in.
 *
 * The highest band whose `min` the value has reached. Below every band - which
 * a caller can reach by scoring under the first `min` - the answer is
 * `undefined`, and that is a real state rather than a reason to clamp: a
 * product that shows a badge for a band nothing is in would be inventing one.
 */
export function tierAt(tiers: Tier[], value: number): Tier | undefined {
  const ordered = orderedTiers(tiers)
  let standing: Tier | undefined
  for (const tier of ordered) {
    if (value >= tier.min) standing = tier
    else break
  }
  return standing
}

const tierFill: Record<NonNullable<Tier['status']>, string> = {
  accent: 'bg-accent',
  good: 'bg-good',
  warn: 'bg-warn',
  bad: 'bg-bad',
  info: 'bg-info',
  neutral: 'bg-line-2',
}

/** The same bands at a quarter strength, for the stretch already passed.
 *
 * Written out rather than composed with an opacity utility, because a fill and
 * an opacity are two properties and a caller's `className` can only win
 * against one of them. */
const tierPassedFill: Record<NonNullable<Tier['status']>, string> = {
  accent: 'bg-accent/40',
  good: 'bg-good/40',
  warn: 'bg-warn/40',
  bad: 'bg-bad/40',
  info: 'bg-info/40',
  neutral: 'bg-line-2/40',
}

export const tierBadgeVariants = cva(
  'inline-flex items-center gap-1.5 rounded-md px-2 py-0.5 text-xs font-medium whitespace-nowrap',
  {
    variants: {
      status: {
        accent: 'bg-accent-soft text-accent',
        good: 'bg-good-soft text-good',
        warn: 'bg-warn-soft text-warn',
        bad: 'bg-bad-soft text-bad',
        info: 'bg-info-soft text-info',
        neutral: 'bg-soft text-dim',
      },
    },
    defaultVariants: { status: 'accent' },
  },
)

export interface TierBadgeProps
  extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'>,
    VariantProps<typeof tierBadgeVariants> {
  /** The band's name. */
  label: ReactNode
  /** The number behind the verdict, if the product shows it. Drawn quieter
   * than the name: the band is the answer and the score is the evidence. */
  value?: ReactNode
}

/**
 * The band, as a verdict.
 *
 * Square-cornered rather than a pill, which is what separates it from
 * `StatusBadge` at a glance: a tier is a position on a scale the product owns,
 * a status is a condition from the line's fixed vocabulary, and a screen that
 * shows both should not make the reader compare colours to tell which is
 * which.
 */
export function TierBadge({ label, value, status, className, ...props }: TierBadgeProps) {
  return (
    <span className={cn(tierBadgeVariants({ status }), className)} {...props}>
      {label}
      {value !== undefined && <span className="font-normal opacity-70">{value}</span>}
    </span>
  )
}

export interface TierRulerProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  tiers: Tier[]
  /** Where the thing stands now. */
  value: number
  /** The ends of the road. */
  min?: number
  max?: number
  /** What the ruler as a whole is called, for a screen reader, and what to say
   * the value is. The product's words - the ruler has none. */
  label: string
  /** The value spoken instead of the bare number: "7.8 out of 10, publishable"
   * is what a reader needs, and only the product can phrase it. */
  valueText?: string
  /** Print the band names under the road. */
  showLabels?: boolean
}

/**
 * The bands as a road, with the value standing somewhere along it.
 *
 * Drawn to scale, which is the whole point: a band that starts at 78 sits
 * nearly four fifths along, and the gap you are looking at is the gap you have
 * to close.
 *
 * Three states per band, not two - passed, standing in, still ahead. A flat
 * wash of "reached" over half the bar says only that the value is not at zero;
 * picking out the band being stood in is what carries the eye to where the
 * thing actually is.
 *
 * Reported as a `meter`: it is a measurement inside a known range, which is
 * exactly what that role is for, and it means a screen reader says the value
 * without the product building a sentence out of `aria-label`.
 */
export function TierRuler({
  tiers,
  value,
  min = 0,
  max = 100,
  label,
  valueText,
  showLabels = true,
  className,
  ...props
}: TierRulerProps) {
  const ordered = orderedTiers(tiers, min, max)
  const span = max - min

  // A road needs at least a start and one boundary on it; below that there is
  // nothing to show that a bare number would not say better.
  if (ordered.length < 2 || span <= 0) return null

  const at = Math.min(Math.max(value, min), max)
  /** Where a value falls along the road, as a percentage of its length. */
  const placeOf = (point: number) => ((point - min) / span) * 100

  return (
    <div className={cn('flex flex-col gap-1', className)} {...props}>
      <div
        role="meter"
        aria-label={label}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={at}
        aria-valuetext={valueText}
        className="relative h-1.5 w-full overflow-hidden rounded-full bg-soft"
      >
        {ordered.map((tier, index) => {
          const next = ordered[index + 1]
          const end = next === undefined ? max : next.min
          const width = placeOf(end) - placeOf(tier.min)
          if (width <= 0) return null

          const reached = value >= tier.min
          const standing = reached && (next === undefined || value < next.min)
          const status = tier.status ?? 'accent'

          return (
            <span
              key={tier.key}
              style={{ left: `${placeOf(tier.min)}%`, width: `${width}%` }}
              className={cn(
                'absolute top-0 h-full',
                standing ? tierFill[status] : reached ? tierPassedFill[status] : 'bg-line-2',
                // A hairline of the page's own ground, so two adjacent bands of
                // the same colour still read as two.
                index > 0 && 'border-l border-bg',
              )}
            />
          )
        })}

        {/* Where the value stands. A pale core inside a dark sheath, so the
            mark keeps its contrast over a filled band as well as over the
            empty road ahead. */}
        <span
          aria-hidden
          style={{ left: `${placeOf(at)}%` }}
          className="absolute top-1/2 h-2.5 w-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-bg ring-2 ring-text"
        />
      </div>

      {showLabels && (
        <div aria-hidden className="relative h-4">
          {ordered.map((tier, index) => {
            const place = placeOf(tier.min)
            return (
              <span
                key={tier.key}
                style={{
                  left: `${place}%`,
                  // The first label would hang off the left edge and the last
                  // off the right, so the ends align to their edge and
                  // everything between is centred on its boundary.
                  transform:
                    index === 0
                      ? 'none'
                      : index === ordered.length - 1 && place >= 100
                        ? 'translateX(-100%)'
                        : 'translateX(-50%)',
                }}
                className={cn(
                  'absolute top-0 text-2xs',
                  value >= tier.min ? 'font-medium text-dim' : 'text-faint',
                )}
              >
                {tier.label}
              </span>
            )
          })}
        </div>
      )}
    </div>
  )
}

export interface AxisBarProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  /** What this axis is called. */
  label: string
  /** The highest mark; one segment is drawn per whole point. */
  scale: number
  /** The mark, or `undefined` while the axis is unjudged. Not the same as
   * zero: zero is a verdict, and a blank axis is the absence of one. */
  value?: number
  /** Given, the row becomes a control. Omitted, it is a read-only reading of a
   * score someone else set. */
  onChange?: (value: number | undefined) => void
  /** The mark from which the total crosses into the next band, and what to
   * call it. Absent when no mark on this axis gets there - and then nothing is
   * drawn, because a line promising a band the axis cannot deliver is worse
   * than no line. */
  threshold?: { mark: number; label: string }
  /** What to say instead of the bare number - "unjudged", in the product's
   * word, when there is no mark. */
  valueText?: string
}

/**
 * One axis of a score, as a row of segments.
 *
 * Scoring is a judgement, not data entry: the useful question is "is this a
 * seven or an eight", and a row you click answers it in one movement where a
 * spin box asks you to read, aim and type. The filled length is also readable
 * down a column of axes, which numerals are not.
 *
 * When it takes `onChange` it reports itself as a slider rather than as a row
 * of buttons, so the arrow keys, Home and End work the way they do everywhere
 * else, and a reader hears one value in a range instead of ten unlabelled
 * buttons. The row owns the keyboard; the segments are pointer targets only,
 * or tabbing past one axis would take ten presses.
 *
 * Read-only, it is a `meter` and not a disabled slider: nothing here is
 * disabled, the number is simply a fact.
 */
export function AxisBar({
  label,
  scale,
  value,
  onChange,
  threshold,
  valueText,
  className,
  ...props
}: AxisBarProps) {
  const marks = Math.max(1, Math.round(scale))
  const interactive = onChange !== undefined

  const step = (delta: number) => {
    if (!onChange) return
    // An unjudged axis steps onto the first or last mark rather than through
    // zero: zero is a verdict of its own, and arrowing into it by accident
    // would be one.
    const next = value === undefined ? (delta > 0 ? 1 : marks) : value + delta
    onChange(Math.min(Math.max(next, 0), marks))
  }

  const onKeyDown = (event: KeyboardEvent) => {
    if (!onChange) return
    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowUp':
        event.preventDefault()
        step(1)
        break
      case 'ArrowLeft':
      case 'ArrowDown':
        event.preventDefault()
        step(-1)
        break
      case 'Home':
        event.preventDefault()
        onChange(0)
        break
      case 'End':
        event.preventDefault()
        onChange(marks)
        break
      // Back to unjudged, which no arrow key can reach - and which is not the
      // same as scoring the axis zero.
      case 'Backspace':
      case 'Delete':
        event.preventDefault()
        onChange(undefined)
        break
      default:
        break
    }
  }

  return (
    <div
      role={interactive ? 'slider' : 'meter'}
      tabIndex={interactive ? 0 : undefined}
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={marks}
      aria-valuenow={value}
      aria-valuetext={valueText}
      onKeyDown={interactive ? onKeyDown : undefined}
      className={cn(
        'flex gap-hair rounded-md focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        className,
      )}
      {...props}
    >
      {Array.from({ length: marks }, (_, index) => {
        const mark = index + 1
        const filled = value !== undefined && mark <= value
        // The first mark that would carry the total over. The ring goes around
        // the segment rather than on its leading edge: a rule beside the last
        // mark reads as the end of the scale, which is exactly when the
        // threshold matters most.
        const crosses = threshold !== undefined && threshold.mark === mark

        const shared = cn(
          'relative h-5 flex-1 rounded-sm transition-colors',
          filled ? 'bg-accent' : 'bg-soft',
          crosses && 'ring-2 ring-inset ring-good',
        )

        return interactive ? (
          // A `<span>` and not a `<button>`, which is what the donor used and
          // what the accessibility gate rejected: a focusable control inside a
          // `role="slider"` is a nested interactive element, and `tabindex=-1`
          // with `aria-hidden` does not undo that - assistive technology can
          // still land on it, and WCAG 4.1.2 says so.
          //
          // Nothing is lost. The row already owns the keyboard, so the segment
          // was never a keyboard target; it is a pointer target, which a span
          // with a click handler is.
          <span
            key={mark}
            aria-hidden
            // Clicking the mark already set clears the axis, which is the only
            // way back to unjudged with a pointer.
            onClick={() => onChange?.(value === mark ? undefined : mark)}
            title={crosses ? threshold.label : undefined}
            className={cn(shared, 'cursor-pointer', filled ? 'hover:bg-accent-2' : 'hover:bg-line-2')}
          />
        ) : (
          <span key={mark} aria-hidden className={shared} />
        )
      })}
    </div>
  )
}

import { useState, type Ref } from 'react'
import { cn, useLocale } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * TimeField - a time of day, typed the way people say it.
 *
 * No donor for this one: neither product of the line had a time field, so
 * this is written from the same shape as DurationField, and for the same
 * reason. Anything a person plausibly types is accepted - `9`, `9:30`, `930`,
 * `9.30`, `9pm`, `21:30` - and what comes back is always `HH:MM`.
 *
 * The value is `HH:MM` in twenty-four hours, always, no matter how it was
 * typed or how it is shown. That is what a database column holds and what
 * sorts correctly as a string; whether the reader sees `9:30 PM` or `21:30`
 * is a matter of where they live, and `Intl` answers it.
 *
 * Not `<input type="time">`, and the reason is the same as NumberField's: the
 * browser draws its own control, its own spinner and its own clock popup,
 * none of which a stylesheet reaches - so a form of the product's own fields
 * gets one that is visibly not.
 *
 * Empty is `null`, like the other fields here: no time is not midnight.
 */

/** Minutes since midnight from whatever was typed, or `null` for empty, or
 * `undefined` when it cannot be read as a time.
 *
 * Exported because the parsing is the component - a test that types into the
 * box checks React's state handling, and what has to be right is this. */
export function parseTime(text: string): string | null | undefined {
  const input = text.trim().toLowerCase().replace(/\s+/g, '')
  if (input === '') return null

  // `pm` means add twelve hours, `am` means midnight is 12. Stripped first so
  // the rest of the parsing does not have to know about them.
  const meridiem = /(am|pm)$/.exec(input)?.[1]
  const body = meridiem ? input.slice(0, -2) : input

  let hours: number
  let minutes: number

  const separated = /^(\d{1,2})[:.](\d{2})$/.exec(body)
  if (separated) {
    hours = Number(separated[1])
    minutes = Number(separated[2])
  } else if (/^\d{1,2}$/.test(body)) {
    // A bare number is an hour: `9` is nine o'clock, not nine minutes past
    // midnight - which is what someone typing a time means.
    hours = Number(body)
    minutes = 0
  } else if (/^\d{3,4}$/.test(body)) {
    // `930` and `0930`, which is how a time gets typed when the colon is a
    // reach on a phone keyboard.
    hours = Number(body.slice(0, body.length - 2))
    minutes = Number(body.slice(-2))
  } else {
    return undefined
  }

  if (minutes > 59) return undefined

  if (meridiem) {
    if (hours < 1 || hours > 12) return undefined
    if (meridiem === 'pm' && hours !== 12) hours += 12
    if (meridiem === 'am' && hours === 12) hours = 0
  } else if (hours > 23) {
    return undefined
  }

  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`
}

/** How a time reads here: `21:30` in most of the world, `9:30 PM` in some of
 * it. The stored value does not change - only what is shown. */
export function formatTime(time: string, locale: string): string {
  const [hours, minutes] = time.split(':').map(Number) as [number, number]
  return new Intl.DateTimeFormat(locale, { hour: 'numeric', minute: '2-digit' }).format(
    new Date(2024, 0, 1, hours, minutes),
  )
}

export interface TimeFieldProps {
  /** `HH:MM` in twenty-four hours, or `null` for empty. */
  value: string | null
  onValueChange: (value: string | null) => void
  /** How the time is shown while the field is not being typed into. The
   * application's language unless stated - see `useLocale`. */
  locale?: string
  placeholder?: string
  disabled?: boolean
  readOnly?: boolean
  required?: boolean
  name?: string
  id?: string
  ref?: Ref<HTMLInputElement>
  'aria-label'?: string
  'aria-describedby'?: string
  className?: string
}

export function TimeField({
  value,
  onValueChange,
  locale,
  className,
  ref,
  ...props
}: TimeFieldProps) {
  const language = useLocale(locale)
  const display = (time: string | null) => (time === null ? '' : formatTime(time, language))

  /* Text while it is being typed, a formatted time the rest of the time -
   * the same arrangement as DurationField, and for the same reason: a field
   * that reformats on every keystroke fights the person using it. */
  const [text, setText] = useState(() => display(value))
  const [editing, setEditing] = useState(false)

  /* The value this box last saw from outside, adjusted during render rather
   * than in an effect. Comparing against `value` would be wrong in exactly
   * the case that matters: after a commit the parent may still hold the old
   * one for a tick, and the box would clear itself under the reader. */
  const [seen, setSeen] = useState<string | null>(value)

  if (value !== seen) {
    setSeen(value)
    if (!editing) setText(display(value))
  }

  const commit = () => {
    setEditing(false)
    const parsed = parseTime(text)
    if (parsed === undefined) {
      // Unreadable: put back what the value actually is rather than leaving
      // the box saying something the form does not believe.
      setText(display(value))
      return
    }
    setText(display(parsed))
    if (parsed !== value) onValueChange(parsed)
  }

  return (
    <input
      {...props}
      ref={ref}
      type="text"
      inputMode="numeric"
      value={text}
      onFocus={() => setEditing(true)}
      onChange={(event) => setText(event.target.value)}
      onBlur={commit}
      onKeyDown={(event) => {
        if (event.key === 'Enter') {
          event.preventDefault()
          commit()
        }
      }}
      className={cn(fieldClasses, 'h-control tabular-nums', className)}
    />
  )
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Timeline.
 *
 * What happened, in the order it happened: a release history, an audit trail,
 * the steps a job went through. Four products of the line draw one, and all
 * four drew it the same way - a list with a border on the left and a dot
 * positioned over it by hand.
 *
 * Three things that version gets wrong, and which are the reason this is a
 * primitive:
 *
 * - **The rail runs past the last entry.** A border on the container ends
 *   where the container does, which is below the last dot - so the history
 *   trails off into a line going nowhere, and a reader cannot tell a finished
 *   list from one still loading. Here the rail is drawn per entry and the last
 *   one does not draw it.
 * - **It is a list, and says so.** A stack of `<div>`s is announced as nothing;
 *   an `<ol>` tells a reader how many entries there are and which one they are
 *   on, which is the whole navigational value of a history.
 * - **The state is a colour.** A red dot for a failed step is invisible to the
 *   reader it matters most to. The marker takes the same `Status` vocabulary as
 *   `StatusDot`, and the same rule applies: the colour is emphasis and the
 *   entry's own words are the message.
 *
 * The rail is drawn with a `<span>` rather than a border on the item, because
 * the segment has to start below the dot and run to the next one - a border
 * would start at the item's top edge and cut through the marker.
 */

export type TimelineStatus = 'good' | 'warn' | 'bad' | 'info' | 'neutral' | 'accent'

export const timelineMarkerVariants = cva(
  'relative z-1 flex shrink-0 items-center justify-center rounded-full',
  {
    variants: {
      status: {
        accent: 'bg-accent text-on-accent',
        good: 'bg-good text-on-good',
        warn: 'bg-warn text-on-warn',
        bad: 'bg-bad text-on-bad',
        info: 'bg-info text-on-info',
        neutral: 'bg-line-2 text-dim',
      },
      /** A step not taken yet: the ring of a dot with nothing in it, which is
       * how every other tool draws "not done" and is worth borrowing. */
      pending: {
        true: 'border-2 border-line-2 bg-bg',
        false: '',
      },
    },
    defaultVariants: { status: 'neutral', pending: false },
  },
)

export interface TimelineProps extends HTMLAttributes<HTMLOListElement> {
  /** Draw the rail and the markers on the right of the text, for a right-to-left
   * reading or a history beside a wider body of content. */
  side?: 'start' | 'end'
}

/**
 * The list itself.
 *
 * An ordered list, because the order is the content. A product that shows the
 * newest first hands them over in that order - the component does not sort,
 * since "newest first" and "the order it happened" are both right and only the
 * product knows which it means.
 */
export function Timeline({ side, className, children, ...props }: TimelineProps) {
  // Defaulted here rather than in the parameter list: a string default in the
  // props reads to the word gate as English shipped inside a primitive, and
  // the rule it enforces is worth more than the shorter spelling.
  const on = side ?? 'start'
  return (
    <ol
      className={cn('flex flex-col', on === 'end' && 'items-end', className)}
      data-side={on}
      {...props}
    >
      {children}
    </ol>
  )
}

export interface TimelineItemProps
  extends Omit<HTMLAttributes<HTMLLIElement>, 'title'>,
    VariantProps<typeof timelineMarkerVariants> {
  /** The headline of the entry - what happened. */
  title: ReactNode
  /** When it happened. Drawn quieter, and given as a node so the product can
   * pass its own `RelativeTime` rather than a string it formatted early. */
  time?: ReactNode
  /** A shape inside the marker - a tick, a cross, a number. The second
   * channel, for a reader who does not separate the hues. */
  icon?: ReactNode
  /** The last entry does not draw a rail below it. Set by the product, because
   * only it knows whether the history ends here or merely stops being shown. */
  last?: boolean
  /** Names the state in the product's words, for a reader who does not see the
   * colour. Required whenever `status` carries meaning the title does not
   * already say. */
  statusLabel?: string
}

/**
 * One entry: a marker, a rail down to the next, and what happened.
 *
 * The rail belongs to this entry rather than to the list, so a history can end
 * cleanly - and so an entry can be rendered on its own in a test or a preview
 * without a container to inherit a border from.
 */
export function TimelineItem({
  title,
  time,
  icon,
  status,
  pending,
  last = false,
  statusLabel,
  className,
  children,
  ...props
}: TimelineItemProps) {
  return (
    <li className={cn('flex gap-3', className)} {...props}>
      {/* The column runs the full height of the entry, gap included. The
          spacing between entries is on the text beside it rather than on the
          `<li>`, and that is not a detail of taste: with the padding on the
          item, the column stops above it and the rail stops with it - leaving
          a gap of exactly the padding between one rail and the next marker.
          Measured on the stand at 18-22px per entry, and invisible to a test
          that counts rails rather than asking where they reach. */}
      <div className="relative flex flex-col items-center self-stretch">
        <span
          className={cn(
            timelineMarkerVariants({ status, pending }),
            // Room for a glyph when there is one; a bare dot stays small
            // enough to read as a point on a line rather than as a bullet.
            icon ? 'mt-0.5 size-5 text-[10px]' : 'mt-1.5 size-2.5',
          )}
          // The marker is decorative when the state is not named. When it is,
          // the name is what a reader gets in place of the colour.
          role={statusLabel ? 'img' : undefined}
          aria-label={statusLabel}
          aria-hidden={statusLabel ? undefined : true}
        >
          {icon}
        </span>
        {!last && (
          // From just under the marker to the bottom of the entry, which is
          // where the next marker begins.
          <span aria-hidden className="mt-1 w-px flex-1 bg-line" />
        )}
      </div>

      <div className={cn('flex min-w-0 flex-1 flex-col gap-0.5', last ? 'pb-0.5' : 'pb-4')}>
        <div className="flex flex-wrap items-baseline gap-x-2 gap-y-0.5">
          <span className="text-sm text-text">{title}</span>
          {time && <span className="text-2xs text-faint">{time}</span>}
        </div>
        {children && <div className="text-xs text-dim">{children}</div>}
      </div>
    </li>
  )
}

import { Toast as Base } from '@base-ui/react/toast'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Toast.
 *
 * For something that already happened and needs no decision. Anything that
 * needs an answer is a dialog - a toast that asks a question is a question the
 * reader can miss by looking away.
 *
 * The tone is on the toast rather than in five separate components, because
 * the difference between "saved" and "could not save" is emphasis, never
 * meaning: the sentence says which it is, and a reader who cannot separate
 * green from red gets the same message. The stripe down the side exists for
 * the same reason a badge carries a word.
 *
 * `Toast.Root` is `role="dialog"` inside a `role="region"` viewport, and Base
 * UI drives the live region, the timers, the pause on hover and focus, and the
 * swipe. What is here is the clothes and the vocabulary.
 */

export const toastVariants = cva(
  [
    'relative w-[min(22rem,calc(100vw-2rem))] overflow-hidden',
    'rounded-lg border border-line bg-raise p-3 pl-4 text-text shadow-raise',
    // The stripe. `before` rather than a border, so the corner radius stays
    // the panel's own.
    'before:absolute before:inset-y-0 before:left-0 before:w-1',
    '[transition:opacity_var(--duration-base)_var(--ease-out),transform_var(--duration-base)_var(--ease-out)]',
    'data-[starting-style]:translate-x-4 data-[starting-style]:opacity-0',
    'data-[ending-style]:translate-x-4 data-[ending-style]:opacity-0',
  ],
  {
    variants: {
      tone: {
        neutral: 'before:bg-line-2',
        good: 'before:bg-good',
        warn: 'before:bg-warn',
        bad: 'before:bg-bad',
        info: 'before:bg-info',
      },
    },
    defaultVariants: { tone: 'neutral' },
  },
)

/** Wraps the part of the application that can raise a toast. One per screen;
 * nesting them gives a product two queues that do not know about each other. */
export const ToastProvider = Base.Provider

/** The manager: `add`, `update`, `close`, and `promise` for the common case of
 * "say this while it runs, that when it lands". */
export const useToastManager = Base.useToastManager

/** A toast raised outside React - from a store, an event handler, a worker.
 * Pass the result to `ToastProvider`'s `toastManager`. */
export const createToastManager = Base.createToastManager

/** The heading. Base UI points the toast's `aria-labelledby` at it. */
export function ToastTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-sm font-semibold', className)} {...props} />
}

/** The sentence under it, and the toast's `aria-describedby`. */
export function ToastDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-0.5 text-xs text-dim', className)} {...props} />
}

/** The one thing the reader can do about it: undo, or go and look. */
export function ToastAction({ className, ...props }: Base.Action.Props) {
  return (
    <Base.Action
      className={cn(
        'mt-2 inline-flex h-7 cursor-pointer items-center rounded-md px-2 text-xs font-medium',
        'bg-accent-soft text-accent transition-colors hover:bg-accent-soft/60',
        'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
        className,
      )}
      {...props}
    />
  )
}

/** The dismiss button. Needs a word - a bare cross is announced as nothing. */
