export interface ToastProps extends Base.Root.Props, VariantProps<typeof toastVariants> {}

/** One toast. The tone comes from the caller or from `toast.type`, so a
 * product that raises them through the manager gets the stripe for free. */
export function Toast({ tone, className, toast, ...props }: ToastProps) {
  const fromType = TONE_FOR_TYPE[toast.type ?? ''] ?? undefined
  return (
    <Base.Root
      toast={toast}
      className={cn(toastVariants({ tone: tone ?? fromType }), className)}
      {...props}
    />
  )
}

/** Base UI's own `type` values, mapped onto the vocabulary. A product calling
 * `manager.add({ type: 'success' })` should not also have to say which colour
 * that is. */
const TONE_FOR_TYPE: Record<string, 'good' | 'warn' | 'bad' | 'info' | undefined> = {
  success: 'good',
  warning: 'warn',
  error: 'bad',
  info: 'info',
  loading: 'info',
}

export interface ToastViewportProps extends Base.Viewport.Props {
  /** Where to portal to. Defaults to the document body, which is what keeps
   * toasts above everything regardless of where they were raised from. */
  container?: Base.Portal.Props['container']
}

/** Where they stack. Bottom right by default, which is the corner that does
 * not cover a form being filled in or a menu being read. */
export function ToastViewport({ container, className, ...props }: ToastViewportProps) {
  return (
    <Base.Portal container={container}>
      <Base.Viewport
        className={cn(
          'fixed bottom-4 right-4 flex w-[min(22rem,calc(100vw-2rem))] flex-col-reverse gap-2',
          '[z-index:var(--z-toast)]',
          className,
        )}
        {...props}
      />
    </Base.Portal>
  )
}

/*
 * The arithmetic behind Track, with no React in it.
 *
 * Split out for the reason `table-sort` and `tree-rows` are: a product that
 * needs the numbers - to label a segment, to test its own domain code, to draw
 * the same shape somewhere that is not the DOM - should not import a component
 * to get them.
 *
 * What lives here is only the geometry. Turning a day of work into segments,
 * or a set of tiers into them, is the product's own arithmetic and stays with
 * the product: this knows about spans and percentages and nothing else.
 */

/** A segment as the caller states it, in whatever units the caller counts in. */
export interface SegmentInput {
  /** Where it starts. Same units as `end` and as the track's span. */
  start: number
  /** Where it ends. A segment ending before it starts is empty, not backwards. */
  end: number
}

/** A segment as it is drawn: percentages of the track. */
export interface Placed {
  /** Distance from the left edge, 0-100. */
  left: number
  /** Width, 0-100. */
  width: number
  /** Whether the width is the real one, or the floor standing in for it.
   *
   * Worth knowing rather than hiding: a caller labelling segments may want to
   * say "under a minute" instead of a duration the bar is no longer drawing to
   * scale. */
  widened: boolean
}

/** The smallest a segment may be drawn, in percent.
 *
 * A ten-second pause in an eight-hour day is 0.03% of the track, which rounds
 * to no pixels at all: the segment is real, was measured, and would simply not
 * be there. The floor is the width at which a sliver is still visible on a
 * track a few hundred pixels wide. */
export const MIN_SEGMENT_WIDTH = 0.6

export interface PlaceOptions {
  /** The value the left edge stands for. Defaults to the first segment's start. */
  from?: number
  /** The value the right edge stands for. Defaults to the last segment's end. */
  to?: number
  /** Override the floor - `0` to draw every segment exactly to scale. */
  minWidth?: number
}

/**
 * Lay segments out along a track, as percentages.
 *
 * The scale is stated by `from` and `to` rather than inferred, because the two
 * readings differ and both are wanted: a day of work is read against itself
 * (an eight-hour day drawn across a third of the width wastes the space where
 * the breaks are), while a set of tiers is read against the whole 0-100 scale,
 * where the distance to the next tier is the distance you have to close.
 *
 * Widening a sliver to the floor is what makes this worth having once. It also
 * introduces the only subtlety here: a widened segment can run into the one
 * after it, and two segments drawn overlapping is a worse lie than a segment
 * drawn slightly too wide. So the pass is done in order, and each segment is
 * held back to where the next one starts - a floor is a request, not a
 * guarantee, and the last one may be trimmed by the end of the track.
 */
export function place(segments: SegmentInput[], options: PlaceOptions = {}): Placed[] {
  if (segments.length === 0) return []

  const from = options.from ?? Math.min(...segments.map((s) => s.start))
  const to = options.to ?? Math.max(...segments.map((s) => s.end))
  const span = to - from

  // A track with no span has nothing to scale against: every segment would be
  // at the same place with the same width, which is not a drawing of anything.
  if (!(span > 0)) return []

  const floor = options.minWidth ?? MIN_SEGMENT_WIDTH

  const raw = segments.map((segment) => {
    const start = Math.min(Math.max(segment.start, from), to)
    const end = Math.min(Math.max(segment.end, start), to)
    return { left: ((start - from) / span) * 100, width: ((end - start) / span) * 100 }
  })

  if (floor <= 0) return raw.map((segment) => ({ ...segment, widened: false }))

  /*
   * Widening is a layout pass, not a per-segment decision, and the first
   * version of this got it wrong in a way worth recording: it capped each
   * sliver at "where the next segment starts", which protects against overlap
   * and also means a segment that touches its neighbour can never grow at all.
   * Both shapes this component exists for are contiguous - work then break
   * then work, one tier after another - so the floor did nothing for either of
   * them, and the tests missed it because their crowded case had a gap.
   *
   * So a widened segment pushes what follows instead. That borrows room the
   * track does not have, and the debt is paid back at the end by the segments
   * wide enough to afford it - never by another sliver, which would undo the
   * widening we just did.
   */
  const widened: Placed[] = []
  let shift = 0

  for (const segment of raw) {
    const left = segment.left + shift
    if (segment.width >= floor) {
      widened.push({ left, width: segment.width, widened: false })
      continue
    }
    shift += floor - segment.width
    widened.push({ left, width: floor, widened: true })
  }

  if (shift === 0) return widened

  /* The debt is only owed if the track has actually overflowed. A sliver on an
   * otherwise empty track - one segment, or several with gaps between them -
   * grows into room nobody was using, and nothing needs to give way. */
  const end = widened.at(-1)!
  const overflow = end.left + end.width - 100
  if (overflow <= 0) return widened

  /* Who can pay: everything above the floor, by however much it has to spare.
   * Taken in proportion, so one long stretch is not singled out to absorb the
   * whole debt while its neighbour keeps its exact width. */
  const spare = widened.reduce((sum, s) => sum + (s.widened ? 0 : Math.max(0, s.width - floor)), 0)

  /* Nobody can pay: every segment is at or under the floor, and the track is
   * genuinely too crowded to draw honestly at this width. The floor loses -
   * a bar running off its own end is worse than slivers too thin to see. */
  if (spare <= 0) return raw.map((segment) => ({ ...segment, widened: false }))

  let paid = 0
  return widened.map((segment) => {
    const left = segment.left - paid
    if (segment.widened) return { ...segment, left }

    const contribution = (Math.max(0, segment.width - floor) / spare) * overflow
    paid += contribution
    return { left, width: segment.width - contribution, widened: false }
  })
}

/** Where a marker sits on the same scale, as a percentage, or `null` when it
 * falls outside the track.
 *
 * Outside rather than clamped: a marker pinned to the edge says "here, at the
 * very end", which is a different statement from "not on this track at all". */
export function markerAt(value: number, from: number, to: number): number | null {
  const span = to - from
  if (!(span > 0)) return null
  if (value < from || value > to) return null
  return ((value - from) / span) * 100
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { markerAt, place, type SegmentInput } from './track-segments'

/*
 * A bar divided into stretches, with something standing somewhere along it.
 *
 * Two products had written this independently and arrived at the same
 * construction - a rounded track, segments positioned absolutely by percent, a
 * floor under the segment width so a short one does not vanish - differing
 * only in what a segment meant. One drew the tiers of a rubric with the score
 * standing among them; the other drew a working day as alternating work and
 * breaks. Neither could be built from the other, and each knew something the
 * other did not: the tiers had the marker and the three-state reading of a
 * segment (passed, standing in, still ahead), the day had the minimum width
 * and the difference between an empty track and an unknown one.
 *
 * So it is one component, and the two are its two shapes:
 *
 *   **spans** - stretches of a whole, each meaning something in its own right:
 *   work and breaks, phases, occupancy. Adjacent or separated; gaps are the
 *   track showing through.
 *
 *   **thresholds** - a scale cut into bands, with a position on it. Here the
 *   segments are contiguous by construction and the point is not the bands but
 *   where you stand among them: "nearly a clip" is what the reader wants, and
 *   a badge saying which band you are in cannot say it.
 *
 * The arithmetic is in `track-segments`, importable without React.
 *
 * What this does NOT do is own its own height in pixels, and that is
 * deliberate: it is `h-1.5` in one donor and `h-2.5` in the other because the
 * bar carries different weight on the two screens. What it does own is the
 * geometry inside itself - percentages of its own box, never of a parent's -
 * which is the part that broke when a consumer put a percentage-height chart
 * inside a flex row and every bar resolved to zero.
 */

export const trackVariants = cva('relative w-full overflow-hidden rounded-full', {
  variants: {
    size: {
      /* Beside text, where the bar is a detail of a line. */
      sm: 'h-1.5',
      /* On its own row, where the bar is the thing being read. */
      md: 'h-2.5',
    },
  },
  defaultVariants: { size: 'md' },
})

export const trackSegmentVariants = cva('absolute top-0 h-full', {
  variants: {
    tone: {
      /* The subject: work done, the band you are standing in. */
      accent: 'bg-accent',
      /* Behind you, or secondary: a band already passed. Dimmed so the
       * current one carries the eye - a flat wash of "reached" over half the
       * bar says only that you are not at zero. */
      past: 'bg-accent/40',
      /* Ahead, or simply not the subject: a break, a band not yet reached. */
      idle: 'bg-line-2',
      /* Status, for a stretch that is itself a state rather than a quantity. */
      good: 'bg-good',
      warn: 'bg-warn',
      bad: 'bg-bad',
    },
  },
  defaultVariants: { tone: 'accent' },
})

export type TrackTone = NonNullable<VariantProps<typeof trackSegmentVariants>['tone']>

export interface TrackSegment extends SegmentInput {
  /** Distinguishes this segment from its neighbours in the DOM. */
  key: string
  tone?: TrackTone
  /** What this stretch is, in words. Shown on hover, and the only place the
   * segment's meaning exists for a reader who cannot see the colours. */
  label?: string
}

export interface TrackProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>,
    VariantProps<typeof trackVariants> {
  segments: TrackSegment[]
  /** The value the left edge stands for. Defaults to the earliest segment. */
  from?: number
  /** The value the right edge stands for. Defaults to the latest segment. */
  to?: number
  /** Where the position marker stands, on the same scale as the segments.
   * Omitted when there is no such thing - a day of work has no "you are here". */
  marker?: number
  /** What the whole bar says, for a reader who cannot see it. Required: the
   * segments are decoration to a screen reader, and their titles are not
   * announced in order. */
  label: string
  /** Override the floor under a segment's width - `0` draws everything exactly
   * to scale.
   *
   * The floor is right for a day of work, where a short break is a fact worth
   * seeing. It is wrong wherever the widths are being compared to each other,
   * because a widened segment is no longer to scale and a reader measuring by
   * eye would be measuring the floor. */
  minWidth?: number
  /** Separate adjacent segments with a hairline of the ground.
   *
   * On for thresholds, where the bands touch and the boundary between two
   * reached ones would otherwise be invisible. Off for spans, where a gap in
   * the data is meant to look different from a gap between two stretches. */
  divided?: boolean
}

export function Track({
  segments,
  from,
  to,
  marker,
  label,
  minWidth,
  divided = false,
  size,
  className,
  ...props
}: TrackProps) {
  const placed = place(segments, { from, to, minWidth })

  /* The marker rides the same scale as the segments, so it is resolved against
   * the same bounds rather than against its own reading of them. */
  const bounds = {
    from: from ?? Math.min(...segments.map((s) => s.start), Infinity),
    to: to ?? Math.max(...segments.map((s) => s.end), -Infinity),
  }
  const at = marker === undefined ? null : markerAt(marker, bounds.from, bounds.to)

  return (
    <div
      role="img"
      aria-label={label}
      className={cn(trackVariants({ size }), 'bg-soft', className)}
      {...props}
    >
      {placed.map((geometry, index) => {
        const segment = segments[index]!
        return (
          <span
            key={segment.key}
            title={segment.label}
            style={{ left: `${geometry.left}%`, width: `${geometry.width}%` }}
            className={cn(
              trackSegmentVariants({ tone: segment.tone }),
              // The hairline is drawn in the page's own ground rather than in
              // a border colour, so it reads as a cut between two fills
              // instead of a third colour of its own.
              divided && index > 0 && 'border-l border-bg',
            )}
          />
        )
      })}

      {at !== null && (
        /* A dark core inside a light sheath, so the mark keeps its contrast
         * over the accent band it usually stands on as well as over the empty
         * road ahead. Centred on its position rather than starting at it: the
         * mark says "here", and a mark whose left edge is the position reads
         * as half a step further along than it is. */
        <span
          style={{ left: `${at}%` }}
          className="absolute top-1/2 h-2.5 w-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-bg ring-2 ring-text"
        />
      )}
    </div>
  )
}

/*
 * The labels under a track.
 *
 * Separate from the track because the two donors disagreed about whether there
 * are any - the day had none, the tiers had one per band - and because a caller
 * with three bands and a narrow column will want to drop them without giving
 * up the bar.
 */
export interface TrackScaleProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode
}

export function TrackScale({ className, ...props }: TrackScaleProps) {
  return (
    <div
      className={cn('flex justify-between text-[10px] text-faint', className)}
      {...props}
    />
  )
}

import type { ReactNode } from 'react'

/*
 * What a tree shows, with no React in it.
 *
 * Split out of the TreeView for the reason `table-sort` and `calendar-math`
 * were split out of their components: these are the sums, and the component is
 * the thing that draws them. A product that windows a large tree needs to know
 * how many rows it has before rendering any of them - that is this file, and
 * it never touches the DOM.
 */

export interface TreeNode {
  /** Stable identity. Not the label: two folders can hold a file of the same
   * name, and keying by label collapses them into one. */
  id: string
  label: ReactNode
  /** Absent or empty means a leaf. An empty array is deliberately *not* an
   * empty folder - a folder with nothing in it still opens, and saying so
   * needs a real value rather than the absence of one. */
  children?: TreeNode[]
  /** An empty folder: opens, and shows nothing. */
  empty?: boolean
}

/** One visible row: the node, how deep it sits, and the branch it belongs to. */
export interface TreeRow {
  node: TreeNode
  depth: number
  /** The id of the folder this row is inside, if any. What Left uses to get
   * out of a deep branch in one press. */
  parent?: string
}

/** The rows a tree shows, in the order the eye and the keyboard travel.
 *
 * Flattening is what makes the keyboard simple: Down is the next row of this
 * list, Up the previous, and neither has to know about nesting. A recursive
 * walk at every keystroke would ask the same question - what is visually next
 * - and answer it differently at each depth.
 *
 * It is also the answer to "how many rows is this tree", which is what a
 * product needs to put a tree inside a VirtualList. */
export function visibleRows(
  nodes: readonly TreeNode[],
  open: ReadonlySet<string>,
  depth = 0,
  parent?: string,
): TreeRow[] {
  const rows: TreeRow[] = []
  for (const node of nodes) {
    rows.push({ node, depth, parent })
    if (node.children?.length && open.has(node.id)) {
      rows.push(...visibleRows(node.children, open, depth + 1, node.id))
    }
  }
  return rows
}

/** Whether this node is a folder - something that opens, even if empty. */
export function isBranch(node: TreeNode): boolean {
  return Boolean(node.empty) || Boolean(node.children?.length)
}

import { useMemo, useState, type KeyboardEvent } from 'react'
import { cn } from 'dowel-ui'
import { isBranch, visibleRows, type TreeNode } from './tree-rows'

/*
 * A tree: folders that open, one tab stop, arrows to move.
 *
 * The shape products reach for and then get wrong in the same place every
 * time. A tree is not a nest of lists with click handlers - it is one control
 * with a cursor in it, and the difference is the whole component:
 *
 *   **One tab stop, not one per node.** A tree of four hundred files with a
 *   `tabIndex` on each is four hundred stops between the sidebar and the
 *   editor. The container is what the keyboard reaches, and the arrows move a
 *   cursor inside it - the arrangement a `RadioGroup` has, for the same
 *   reason.
 *
 *   **Right and left do different things depending on where you are.** Right
 *   on a closed folder opens it; on an open one it steps into the first child;
 *   on a leaf it does nothing. Left closes an open folder, and on a leaf or a
 *   closed one it jumps to the parent - which is how a reader gets out of a
 *   deep branch without walking back up through every sibling.
 *
 * Both come from the ARIA tree pattern, and neither is guessable from looking
 * at a finished tree, which is why every hand-rolled one implements Up and
 * Down and stops there.
 *
 * The nodes are given, not discovered: a tree that loads its children when a
 * folder opens is a different component with a different problem (a spinner
 * per node, a request per open, an error state inside a row). This one is
 * handed everything and decides what to show.
 *
 * Which rows are visible is next door in `tree-rows`, with no React in it - a
 * product windowing a large tree imports that and never this.
 */

export interface TreeViewProps {
  nodes: readonly TreeNode[]
  /** Which folders are open. Uncontrolled if omitted. */
  open?: ReadonlySet<string>
  onOpenChange?: (open: Set<string>) => void
  /** Which row is chosen - the file being edited, not the one the cursor is
   * on. The two move apart: a reader walks the tree with arrows without
   * opening anything until Enter. */
  selected?: string
  onSelect?: (id: string) => void
  /** What a screen reader calls the tree. Required: a bare tree announces
   * "tree" and nothing else, and the word belongs to the product. */
  label: string
  className?: string
}

export function TreeView({
  nodes,
  open: openProp,
  onOpenChange,
  selected,
  onSelect,
  label,
  className,
}: TreeViewProps) {
  const [openState, setOpenState] = useState<ReadonlySet<string>>(() => new Set())
  const open = openProp ?? openState

  const setOpen = (next: Set<string>) => {
    if (openProp === undefined) setOpenState(next)
    onOpenChange?.(next)
  }

  const rows = useMemo(() => visibleRows(nodes, open), [nodes, open])

  /* Where the keyboard is, which is not where the selection is. The cursor
   * starts on the selected row when there is one, so arrowing into a tree
   * continues from what is open rather than from the top. */
  const [cursor, setCursor] = useState<string | undefined>(undefined)
  const active = rows.find((row) => row.node.id === cursor)
    ? cursor
    : (rows.find((row) => row.node.id === selected)?.node.id ?? rows[0]?.node.id)

  const index = rows.findIndex((row) => row.node.id === active)

  const move = (to: number) => {
    const row = rows[Math.min(Math.max(0, to), rows.length - 1)]
    if (row) setCursor(row.node.id)
  }

  const toggle = (id: string, next: boolean) => {
    const copy = new Set(open)
    if (next) copy.add(id)
    else copy.delete(id)
    setOpen(copy)
  }

  const onKeyDown = (event: KeyboardEvent) => {
    const current = rows[index]
    if (!current) return
    const branch = isBranch(current.node)
    const isOpen = open.has(current.node.id)

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault()
        move(index + 1)
        break
      case 'ArrowUp':
        event.preventDefault()
        move(index - 1)
        break
      case 'ArrowRight':
        event.preventDefault()
        // Open, then step in. Two presses rather than one that does both,
        // because opening a folder and moving into it are different intents -
        // and a reader who wanted only to look inside would have lost the row
        // they were on.
        if (branch && !isOpen) toggle(current.node.id, true)
        else if (branch && isOpen) move(index + 1)
        break
      case 'ArrowLeft': {
        event.preventDefault()
        if (branch && isOpen) {
          toggle(current.node.id, false)
          break
        }
        // Out of the branch rather than up one row. This is the escape from a
        // deep folder, and the part hand-rolled trees leave out: without it
        // the only way back to the parent is through every sibling below.
        const parent = current.parent
        if (parent) setCursor(parent)
        break
      }
      case 'Home':
        event.preventDefault()
        move(0)
        break
      case 'End':
        event.preventDefault()
        move(rows.length - 1)
        break
      case 'Enter':
      case ' ':
        event.preventDefault()
        if (branch) toggle(current.node.id, !isOpen)
        else onSelect?.(current.node.id)
        break
      default:
        break
    }
  }

  return (
    <div
      role="tree"
      aria-label={label}
      // One stop for the whole tree. A `tabIndex` per node is how a sidebar of
      // four hundred files becomes four hundred stops before the editor.
      tabIndex={0}
      onKeyDown={onKeyDown}
      // The cursor is published rather than only drawn: this is what a screen
      // reader follows, and what makes the tree one control instead of a
      // collection of rows.
      aria-activedescendant={active ? `tree-${active}` : undefined}
      className={cn(
        'text-sm',
        'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        className,
      )}
    >
      {rows.map(({ node, depth }) => {
        const branch = isBranch(node)
        const isOpen = open.has(node.id)
        return (
          <div
            key={node.id}
            id={`tree-${node.id}`}
            role="treeitem"
            // Only on folders. On a leaf it would announce "collapsed" for
            // something that never opens.
            aria-expanded={branch ? isOpen : undefined}
            aria-selected={node.id === selected || undefined}
            // One-based, and the level a reader is told - the indent is the
            // sighted half of the same fact.
            aria-level={depth + 1}
            onClick={() => {
              setCursor(node.id)
              if (branch) toggle(node.id, !isOpen)
              else onSelect?.(node.id)
            }}
            className={cn(
              'flex cursor-pointer items-center gap-1 rounded-sm py-1 pr-2 transition-colors',
              node.id === selected ? 'bg-accent-soft text-text' : 'hover:bg-soft',
              node.id === active && node.id !== selected && 'bg-softer',
            )}
            // Indent by depth. A padding rather than a nested box, because the
            // rows are one flat list - which is what lets the keyboard treat
            // Down as "the next row" without knowing about nesting.
            style={{ paddingLeft: `${depth * 16 + 8}px` }}
          >
            <span aria-hidden className={cn('w-3 shrink-0 text-2xs text-dim', !branch && 'opacity-0')}>
              {isOpen ? '▾' : '▸'}
            </span>
            <span className="truncate">{node.label}</span>
          </div>
        )
      })}
    </div>
  )
}

import type { HTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * Truncate.
 *
 * Text that does not fit, cut with an ellipsis - and, importantly, still
 * readable in full: the element carries its own text as a `title`, so hovering
 * shows what was cut. Every product wrote the one-line version of this and
 * none of them remembered the title.
 *
 * `lines` truncates after that many instead of one, which needs a different
 * mechanism (`line-clamp`) rather than a different value.
 */
export interface TruncateProps extends HTMLAttributes<HTMLSpanElement> {
  /** The text. A string, because the component has to be able to put it in a
   * `title` - arbitrary children could not be. */
  children: string
  /** Cut after this many lines. One by default. */
  lines?: number
  /** Say what the full text is on hover. On by default; turn it off where the
   * text is already visible elsewhere, or the tooltip is noise. */
  title?: string | undefined
}

export function Truncate({ children, lines = 1, className, title, ...props }: TruncateProps) {
  return (
    <span
      // The browser shows this only when the text is actually cut, so it costs
      // nothing when everything fits.
      title={title ?? children}
      className={cn(
        lines === 1 ? 'block truncate' : 'block overflow-hidden',
        className,
      )}
      style={
        lines > 1
          ? { display: '-webkit-box', WebkitLineClamp: lines, WebkitBoxOrient: 'vertical' }
          : undefined
      }
      {...props}
    >
      {children}
    </span>
  )
}

import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react'
import { cn } from 'dowel-ui'

/*
 * A list of a hundred thousand rows that puts a screenful in the DOM.
 *
 * The browser is fine with long lists until it is not: a hundred thousand
 * `<div>`s is a layout the machine recomputes on every change, and the page
 * stops responding while it does. What is drawn instead is the window the
 * reader can actually see, held in place by a tall spacer, so the scrollbar
 * still says how much there is.
 *
 * No virtualisation library. `react-window`, `react-virtuoso` and
 * `@tanstack/react-virtual` all solve the general problem - variable heights
 * measured at runtime, horizontal windows, grids - and the general problem is
 * not the one a design system has: every long list in a product is a column of
 * rows of one height. That case is the arithmetic below, and it is small
 * enough to read.
 *
 * The arithmetic is exported separately, and that is the part worth stating.
 * A window computed inside an effect can only be tested by a browser, and
 * jsdom gives every element a height of zero - so a test would assert against
 * a list that believes it is invisible, and pass whatever the code did. As
 * plain functions the rules are checkable: given a scroll offset and a height,
 * these rows are drawn.
 *
 * Variable row heights are deliberately not supported. Measuring them means
 * rendering to find out, which means a second pass, a cache, and a scrollbar
 * that changes length as the reader travels. When a product needs that, it
 * needs a library rather than a bigger version of this.
 */

export interface Window {
  /** Index of the first row to render. */
  start: number
  /** Index one past the last row to render. */
  end: number
  /** The height of the whole list, drawn or not - what makes the scrollbar
   * honest. */
  totalHeight: number
  /** How far down the first drawn row sits. Applied as a translation rather
   * than as a top margin, so the rows are not re-laid-out on every scroll. */
  offsetTop: number
}

export interface WindowInput {
  /** How many rows there are in total. */
  count: number
  /** How tall one row is, in pixels. One height for every row. */
  rowHeight: number
  /** How tall the scrolling box is. */
  viewportHeight: number
  /** How far the box is scrolled. */
  scrollTop: number
  /** How many extra rows to draw beyond each edge.
   *
   * Not decoration: without it a fast scroll paints blank where rows have not
   * been drawn yet, because the scroll event arrives after the pixels. Three
   * rows is enough to cover a frame at ordinary speeds and cheap enough not to
   * matter. */
  overscan?: number
}

/** Which rows to draw. Pure arithmetic, so it can be checked without a browser.
 *
 * Every edge case here is one that shows as a blank list rather than as an
 * error: a viewport of zero (the box has not been measured yet), a scroll
 * position past the end (the list shrank under the reader), a negative one
 * (elastic scrolling on a trackpad). */
export function windowFor({
  count,
  rowHeight,
  viewportHeight,
  scrollTop,
  overscan = 3,
}: WindowInput): Window {
  const rows = Math.max(0, Math.floor(count))
  const height = Math.max(1, rowHeight)
  const totalHeight = rows * height

  if (rows === 0) return { start: 0, end: 0, totalHeight: 0, offsetTop: 0 }

  // Clamped rather than trusted. A negative scrollTop is what a trackpad hands
  // over at the top of an elastic scroll, and `Math.floor` of it walks the
  // start index backwards into rows that do not exist.
  const top = Math.min(Math.max(0, scrollTop), Math.max(0, totalHeight - 1))

  const first = Math.floor(top / height)
  /* One more row than fits, so the row cut by the bottom edge is drawn rather
   * than appearing as the reader scrolls into it.
   *
   * The `+ 1` is also what keeps the first frame from being empty: before the
   * effect measures the box, `viewportHeight` is 0 and this is 1. A
   * `Math.max(1, ...)` around it looks like the guard for that and is dead
   * code - the expression cannot reach zero. Mutation found it: removing the
   * floor changed nothing at all. */
  const visible = Math.ceil(Math.max(0, viewportHeight) / height) + 1

  const start = Math.max(0, first - overscan)
  const end = Math.min(rows, first + visible + overscan)

  return { start, end, totalHeight, offsetTop: start * height }
}

export interface VirtualListProps<Row> {
  rows: readonly Row[]
  /** How tall one row is. Fixed, and the component enforces it - a row that
   * grows past this height overlaps its neighbour, which is why the value is
   * required rather than measured. */
  rowHeight: number
  children: (row: Row, index: number) => ReactNode
  /** A stable identity per row. Without it React keys by index, and a list
   * that is sorted or filtered reuses the wrong DOM node - the row moves but
   * its input keeps the text that was typed into a different row. */
  rowKey: (row: Row, index: number) => string | number
  overscan?: number
  /** What a screen reader calls the list. Required: a scrolling box of rows
   * with no name is announced as "list" and nothing else, and the word is the
   * product's to give. */
  label: string
  className?: string
}

export function VirtualList<Row>({
  rows,
  rowHeight,
  children,
  rowKey,
  overscan = 3,
  label,
  className,
}: VirtualListProps<Row>) {
  const viewport = useRef<HTMLDivElement>(null)
  const [scrollTop, setScrollTop] = useState(0)
  const [viewportHeight, setViewportHeight] = useState(0)

  const measure = useCallback(() => {
    const element = viewport.current
    if (!element) return
    setViewportHeight(element.clientHeight)
    setScrollTop(element.scrollTop)
  }, [])

  useEffect(() => {
    const element = viewport.current
    if (!element) return
    measure()

    /* The height is watched, not read once. A list inside a panel that opens,
     * a window the reader resizes, a font that loads late - all change the
     * viewport after mount, and a list that measured once draws the wrong
     * number of rows until something scrolls. */
    if (typeof ResizeObserver === 'undefined') return
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    return () => observer.disconnect()
  }, [measure])

  const { start, end, totalHeight, offsetTop } = windowFor({
    count: rows.length,
    rowHeight,
    viewportHeight,
    scrollTop,
    overscan,
  })

  return (
    <div
      ref={viewport}
      onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
      // `tabIndex` because a box that scrolls has to be reachable: a keyboard
      // user with no focusable row inside cannot otherwise page through it.
      tabIndex={0}
      role="list"
      aria-label={label}
      className={cn(
        'relative overflow-y-auto',
        'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        className,
      )}
    >
      {/* The spacer is what the scrollbar measures. Without it the box is only
        * as tall as the rows drawn, and the reader can never scroll past the
        * first screenful. */}
      <div style={{ height: totalHeight }} className="relative">
        <div
          // Translated rather than positioned with `top`: a transform is
          // composited, while changing `top` re-lays-out the subtree on every
          // scroll event.
          style={{ transform: `translateY(${offsetTop}px)` }}
          className="absolute inset-x-0 top-0"
        >
          {rows.slice(start, end).map((row, offset) => {
            const index = start + offset
            return (
              <div
                key={rowKey(row, index)}
                role="listitem"
                /* The pair that makes a window honest to a screen reader.
                 *
                 * Without them the reader counts the rows it can see and says
                 * "3 of 20" in a list of a hundred thousand - the rows in the
                 * DOM are a screenful, and that is exactly what a virtual list
                 * hides. `aria-setsize` is the real total, `aria-posinset` the
                 * real position.
                 *
                 * Deliberately not `aria-rowcount`/`aria-rowindex`, which were
                 * the obvious names and are wrong: those belong to `grid`,
                 * `table` and `treegrid`. On a `list` they are unsupported -
                 * axe rejects them, and a reader would simply ignore them,
                 * which is the worse half: the markup would look like it said
                 * something. */
                aria-setsize={rows.length}
                aria-posinset={index + 1}
                style={{ height: rowHeight }}
              >
                {children(row, index)}
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}

import {
  useCallback,
  useEffect,
  useState,
  type CSSProperties,
  type MouseEvent,
  type PointerEvent,
  type ReactNode,
} from 'react'
import { getCurrentWindow } from '@tauri-apps/api/window'
import { cn } from 'dowel-ui'

/** The eight compass names Tauri resizes by. Read off the method rather than
 * imported: the package declares the type without exporting it. */
type ResizeDirection = Parameters<ReturnType<typeof getCurrentWindow>['startResizeDragging']>[0]

/*
 * The window's own frame, for a window that has no system frame.
 *
 * With `decorations: false` the system draws nothing, so everything it used
 * to do is the page's: dragging the window by its title bar, double-click to
 * maximise, the three buttons, and the edges you grab to resize. Each is
 * small; the reason to take them on at all is that a system title bar over an
 * application title bar costs a strip of every laptop screen for nothing.
 * scheda made the trade first and kilna copied it, which is the second
 * consumer the line asks for before anything becomes shared.
 *
 * `TitleBar` is the bar itself, assembled: the product's mark, whatever the
 * window shows at the top (its open documents as `Tabs variant="bar"`, or a
 * trail), a stretch that exists only to be grabbed, the product's own actions,
 * and the three buttons. `ResizeEdges` goes once at the root beside it. The
 * parts are exported too - `WindowButtons`, `useTitleBarGestures()` spread on
 * a bar of your own, and `useMaximized()` for anything else that changes shape
 * with the window - for a bar the assembled one does not fit.
 *
 * Outside Tauri - a browser, a test, the stand - there is no window to drive.
 * Every call goes through `currentWindow()`, which answers null when the
 * Tauri bridge is absent, so the chrome renders and does nothing rather than
 * throwing on the first click. A product's own storybook runs in a browser
 * too, and a title bar that crashes it is a title bar nobody previews.
 */

/** The Tauri window, or null where there is none to drive. The bridge is what
 * `getCurrentWindow` reads its label from, so its absence is the test. */
function currentWindow() {
  return '__TAURI_INTERNALS__' in window ? getCurrentWindow() : null
}

/** Whether the window is maximised, kept current as the window changes.
 *
 * The window can be maximised without our buttons - a drag to the top edge,
 * the keyboard, a snap layout - so the answer follows the window rather than
 * our own last click. */
export function useMaximized(): boolean {
  const [maximized, setMaximized] = useState(false)

  useEffect(() => {
    const target = currentWindow()
    if (!target) return
    const read = () => {
      target.isMaximized().then(setMaximized).catch(() => undefined)
    }
    read()
    const unlisten = target.onResized(read)
    return () => {
      unlisten.then((stop) => stop()).catch(() => undefined)
    }
  }, [])

  return maximized
}

export interface WindowButtonsProps {
  /** What each button is called. Required, and deliberately without a
   * default: a string this component invents is a string the product cannot
   * translate. `restore` replaces `maximize` while the window is maximised. */
  labels: { minimize: string; maximize: string; restore: string; close: string }
  className?: string
}

type Control = keyof WindowButtonsProps['labels']

/** The four glyphs, drawn in one stroke on a ten-pixel grid - the size the
 * system's own were, so the bar reads as the window's and not as a toolbar. */
const GLYPH: Record<Control, ReactNode> = {
  minimize: <path d="M0 5h10" />,
  maximize: <rect x="0.5" y="0.5" width="9" height="9" />,
  restore: <path d="M2.5 2.5V0.5h7v7h-2M0.5 2.5h7v7h-7z" />,
  close: <path d="M0 0l10 10M10 0L0 10" />,
}

/** The window controls, in the order Windows puts them.
 *
 * Close asks rather than closes: Tauri's `close()` emits `closeRequested`
 * before anything happens, so a product's unsaved-work guard listening for
 * that request sees this button exactly as it sees the system's own close.
 * scheda once took an `onClose` of its own to get that; it was never needed,
 * and a second way to close is a second place for the guard to be missed. */
export function WindowButtons({ labels, className }: WindowButtonsProps) {
  const maximized = useMaximized()
  const controls: [Control, () => unknown][] = [
    ['minimize', () => currentWindow()?.minimize()],
    [maximized ? 'restore' : 'maximize', () => currentWindow()?.toggleMaximize()],
    ['close', () => currentWindow()?.close()],
  ]

  return (
    <div className={cn('flex h-full shrink-0 items-stretch', className)}>
      {controls.map(([name, act]) => (
        <button
          key={name}
          type="button"
          aria-label={labels[name]}
          title={labels[name]}
          onClick={() => void act()}
          className={cn(
            'flex h-full w-window-button cursor-default items-center justify-center text-dim transition-colors',
            'hover:bg-soft hover:text-text',
            // The close button is the one that must not be mistaken for its
            // neighbours: it goes red under the pointer, as on every desktop.
            name === 'close' && 'hover:bg-bad hover:text-on-bad',
          )}
        >
          <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1" aria-hidden>
            {GLYPH[name]}
          </svg>
        </button>
      ))}
    </div>
  )
}

/** A press on a control has already been handled by the control. */
const shouldHandle = (target: EventTarget | null) =>
  !(target as HTMLElement | null)?.closest(
    'button, a, input, textarea, [role="menu"], [role="menuitem"], [role="tab"], [role="dialog"]',
  )

/** How far the pointer moves before a press becomes a drag, in pixels. */
const THRESHOLD = 4

/** Makes an element behave like a title bar: drag to move, double-click to
 * maximise. Both are what the system used to do for free. Spread the result
 * on the bar: `<header {...useTitleBarGestures()}>`.
 *
 * Two handlers rather than one. A `pointerdown` cannot recognise a double
 * click: its `detail` counts clicks of the *mouse* event sequence, and the
 * second press still arrives as 1 - reading it there fired `startDragging`
 * three times over a double click and toggled nothing. So the press starts a
 * drag, and `dblclick`, which the browser is the one qualified to detect,
 * maximises.
 *
 * Dragging starts on the first movement, not on the press. `startDragging`
 * hands the window over to the system - which is what keeps snap layouts and
 * drag-to-edge working - but from that moment the webview stops seeing the
 * mouse. Calling it on `pointerdown` ate the second click of every double
 * click, and maximising never happened. */
export function useTitleBarGestures() {
  const onPointerDown = useCallback((event: PointerEvent) => {
    if (event.button !== 0 || !shouldHandle(event.target)) return

    const start = { x: event.clientX, y: event.clientY }
    const onMove = (move: globalThis.PointerEvent) => {
      if (Math.abs(move.clientX - start.x) < THRESHOLD && Math.abs(move.clientY - start.y) < THRESHOLD) {
        return
      }
      stop()
      void currentWindow()?.startDragging()
    }
    const stop = () => {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', stop)
      window.removeEventListener('pointercancel', stop)
    }

    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', stop)
    window.addEventListener('pointercancel', stop)
  }, [])

  const onDoubleClick = useCallback((event: MouseEvent) => {
    if (event.button !== 0 || !shouldHandle(event.target)) return
    void currentWindow()?.toggleMaximize()
  }, [])

  return { onPointerDown, onDoubleClick }
}

/** The eight edges and corners a frameless window still has to offer. */
const RESIZE_HANDLES: readonly ResizeDirection[] = [
  'North',
  'South',
  'East',
  'West',
  'NorthEast',
  'NorthWest',
  'SouthEast',
  'SouthWest',
]

/* The width of a strip and of a corner, as the theme states them. Read off
 * the tokens rather than written here: a window's chrome is shared with the
 * products that draw the rest of their own frame, and two numbers for one
 * edge is how the title bar ended up 40px in one product and 2.4rem in the
 * next. */
const EDGE = 'var(--spacing-resize-edge)'
const CORNER = 'var(--spacing-resize-corner)'

/** Where each strip sits and which cursor it shows. Inline styles rather than
 * classes: eight positions of a few pixels each are geometry, not design. */
const EDGE_STYLE: Record<ResizeDirection, CSSProperties> = {
  North: { top: 0, left: CORNER, right: CORNER, height: EDGE, cursor: 'ns-resize' },
  South: { bottom: 0, left: CORNER, right: CORNER, height: EDGE, cursor: 'ns-resize' },
  East: { top: CORNER, bottom: CORNER, right: 0, width: EDGE, cursor: 'ew-resize' },
  West: { top: CORNER, bottom: CORNER, left: 0, width: EDGE, cursor: 'ew-resize' },
  NorthEast: { top: 0, right: 0, width: CORNER, height: CORNER, cursor: 'nesw-resize' },
  NorthWest: { top: 0, left: 0, width: CORNER, height: CORNER, cursor: 'nwse-resize' },
  SouthEast: { bottom: 0, right: 0, width: CORNER, height: CORNER, cursor: 'nwse-resize' },
  SouthWest: { bottom: 0, left: 0, width: CORNER, height: CORNER, cursor: 'nesw-resize' },
}

export interface ResizeEdgesProps {
  /** Merged into every strip. `fixed` to the viewport by default, which is
   * where a window's edges are; `absolute` puts them on the nearest
   * positioned box instead, for a frame drawn inside a page. */
  className?: string
}

/** Invisible strips along the window's edges.
 *
 * A frameless window has no border to grab, so these put one back. They sit
 * outside the flow, above everything, and are only a few pixels wide -
 * enough to hit, not enough to steal a click meant for the text. A maximised
 * window has no edges to drag, and leaving the strips in place would mean
 * the top few pixels of the title bar stop taking clicks. */
export function ResizeEdges({ className }: ResizeEdgesProps) {
  const maximized = useMaximized()
  if (maximized) return null

  return (
    <>
      {RESIZE_HANDLES.map((direction) => (
        <div
          key={direction}
          aria-hidden
          data-resize-edge={direction}
          className={cn('fixed [z-index:var(--z-floating)]', className)}
          style={EDGE_STYLE[direction]}
          onPointerDown={(event) => {
            if (event.button !== 0) return
            event.preventDefault()
            void currentWindow()?.startResizeDragging(direction)
          }}
        />
      ))}
    </>
  )
}

export interface TitleBarProps {
  /** The window buttons' names; see `WindowButtons`. */
  labels: WindowButtonsProps['labels']
  /** The product's mark, at the left edge, where the system put the icon. */
  mark?: ReactNode
  /** What the window shows at the top: its open documents as
   * `<Tabs><TabsList variant="bar">`, a trail, or a title. */
  children?: ReactNode
  /** The product's own controls, between the handle and the window buttons. */
  actions?: ReactNode
  className?: string
}

/** A frameless window's title bar, assembled.
 *
 * Its height is `--spacing-titlebar`, and everything in it that is not a
 * control is a handle. The stretch between the content and the actions is
 * there for that alone: a window with twenty documents open would otherwise
 * have no bar left to drag by, so it never shrinks below a minimum, and the
 * content scrolls instead. */
export function TitleBar({ labels, mark, children, actions, className }: TitleBarProps) {
  const gestures = useTitleBarGestures()

  return (
    <header
      className={cn('flex h-titlebar shrink-0 items-stretch border-b border-line bg-raise select-none', className)}
      {...gestures}
    >
      {mark && <span className="flex shrink-0 items-center pr-2 pl-3">{mark}</span>}
      <div className="flex min-w-0 items-stretch">{children}</div>
      <div aria-hidden data-titlebar-handle className="min-w-4 flex-1" />
      {actions && <div className="flex shrink-0 items-center gap-1 px-1">{actions}</div>}
      <WindowButtons labels={labels} />
    </header>
  )
}

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type FormEvent,
  type HTMLAttributes,
  type ReactNode,
} from 'react'
import { cn } from 'dowel-ui'
import { Button } from './button'
import { Stepper, type StepStateLabels, type StepperStep } from './stepper'

/*
 * Wizard.
 *
 * A Stepper with the current step's content under it and the Back / Next /
 * Finish row that walks through the steps - checking each one before it lets
 * the user past. The Stepper alone shows progress; this is the form that
 * makes it, and a product that only needs the picture should not install the
 * form.
 *
 * Every way forward runs the same checks: Next, Enter in a field, and a click
 * on a completed step ahead in the stepper. The browser's own constraints on
 * the step's fields come first, then `canAdvance`, then the async `onNext`;
 * `false` or a throw keeps the user where they are and marks the step failed.
 * A wizard whose Enter key or stepper skipped the checks would have checks
 * that only the mouse on the Next button ever met.
 *
 * It is both controlled and uncontrolled, like every input in the set:
 * `defaultStep` for the common case where nothing outside cares which step is
 * showing, `step` + `onStepChange` for the case where something does - a step
 * in the URL, so the browser's Back button walks the wizard, or a product
 * that restores a half-finished setup. Either way the wizard runs the step's
 * checks before it asks to move forward; a controlled product decides whether
 * to move, never whether to validate.
 *
 * Its steps stay mounted once visited and are hidden rather than unmounted,
 * so going Back finds the fields as they were left - typed text, a picked
 * folder, a toggled switch - whether or not the product lifted that state
 * out. Losing a page of input to a Back button is the complaint every wizard
 * collects first, and the cost of keeping a handful of hidden panels in the
 * document is small against it.
 *
 * When the step changes, focus moves to the new step's heading, so a keyboard
 * or screen-reader user lands in the new content rather than on a Next button
 * at the bottom of a page they have not heard. All the words - the buttons,
 * the stepper's - are the product's, and required.
 */

/** What a step's check may return. `false` blocks; so does throwing. Anything
 * else lets the wizard go on. */
type CheckResult = boolean | void

export interface WizardStep extends Omit<StepperStep, 'status'> {
  /** The step itself - its fields, its choices. Stays mounted once visited. */
  content: ReactNode
  /** A synchronous check, run first. `false` keeps the user on the step. */
  canAdvance?: () => boolean
  /**
   * Run when the user asks to leave the step forward, after `canAdvance`. May
   * be async - a name checked against a server, a folder checked for write
   * access. Returning `false` or throwing keeps the user on the step; the
   * controls are disabled while it runs, so a second press does not run it
   * twice.
   */
  onNext?: () => CheckResult | Promise<CheckResult>
  /** Mark the step as failed from outside - a server rejected what it holds. */
  error?: boolean
}

export interface WizardProps extends Omit<HTMLAttributes<HTMLFormElement>, 'children' | 'onSubmit' | 'onError'> {
  steps: readonly WizardStep[]
  /** The step shown, for a controlled wizard. */
  step?: string
  /** The step shown first, for an uncontrolled one. The first step if omitted. */
  defaultStep?: string
  /** Called with the step to move to - after its checks have passed, when
   * moving forward. A controlled wizard moves when the product sets `step`. */
  onStepChange?: (id: string) => void
  /** Called when Finish is pressed on the last step and its checks pass. */
  onFinish: () => void | Promise<void>
  /** Called when a step's `onNext` throws. The step is blocked and marked
   * failed either way; without this the error is rethrown so it is not lost. */
  onError?: (error: unknown, stepId: string) => void
  /** The stepper's name for a reader. */
  stepperLabel: string
  stateLabels: StepStateLabels
  summary?: (position: number, total: number) => ReactNode
  /** The buttons' words. Required: the component has none of its own. */
  backLabel: ReactNode
  nextLabel: ReactNode
  finishLabel: ReactNode
  /** Stepper above the content, or beside it. */
  orientation?: 'horizontal' | 'vertical'
}

export function Wizard({
  steps,
  step: controlledStep,
  defaultStep,
  onStepChange,
  onFinish,
  onError,
  stepperLabel,
  stateLabels,
  summary,
  backLabel,
  nextLabel,
  finishLabel,
  orientation = 'horizontal',
  className,
  ...props
}: WizardProps) {
  const [ownStep, setOwnStep] = useState(defaultStep ?? steps[0]?.id ?? '')
  const current = controlledStep ?? ownStep
  const currentIndex = Math.max(
    0,
    steps.findIndex((step) => step.id === current),
  )
  const currentStep = steps[currentIndex]

  // Steps that were ever shown stay mounted, so Back finds them as they were.
  const [visited, setVisited] = useState<ReadonlySet<string>>(() => new Set([current]))
  // Steps whose checks passed when they were last left forward. A step ahead
  // of the current one is drawn as done only if it is in here.
  const [passed, setPassed] = useState<ReadonlySet<string>>(() => new Set())
  const [failed, setFailed] = useState<ReadonlySet<string>>(() => new Set())
  const [pending, setPending] = useState(false)
  // The guard against a second press while a check runs reads this rather
  // than `pending`: two presses inside one frame both see the state from
  // before either of them.
  const running = useRef(false)

  const panels = useRef(new Map<string, HTMLElement>())
  const heading = useRef<HTMLHeadingElement>(null)
  const baseId = useId()

  // `visited` is derived from `current` as it changes rather than set where
  // the move is made, because a controlled wizard moves when the product
  // says so and the move is not made here at all.
  if (!visited.has(current)) setVisited(new Set(visited).add(current))

  // The step changed: put the keyboard in its heading. Without this focus
  // stays on the Next button - now at the bottom of a different page - and a
  // screen reader says nothing about the new step at all. Not on the first
  // render: a wizard that steals focus when a screen opens moves the reader
  // away from wherever they were.
  const first = useRef(true)
  useEffect(() => {
    if (first.current) {
      first.current = false
      return
    }
    heading.current?.focus()
  }, [current])

  const goTo = useCallback(
    (id: string) => {
      if (controlledStep === undefined) setOwnStep(id)
      onStepChange?.(id)
    },
    [controlledStep, onStepChange],
  )

  const mark = (id: string, ok: boolean) => {
    setFailed((prev) => {
      if (prev.has(id) === !ok) return prev
      const next = new Set(prev)
      if (ok) next.delete(id)
      else next.add(id)
      return next
    })
    setPassed((prev) => {
      if (prev.has(id) === ok) return prev
      const next = new Set(prev)
      if (ok) next.add(id)
      else next.delete(id)
      return next
    })
  }

  /** Run one step's checks, in order: the browser's own constraints on its
   * fields (`required`, `pattern`), then `canAdvance`, then `onNext`. */
  const check = async (target: WizardStep): Promise<boolean> => {
    const panel = panels.current.get(target.id)
    if (panel) {
      // The form is `noValidate`, because the browser would otherwise check
      // every field in it - including the hidden ones of steps already left -
      // and refuse to submit over a field nobody can see. So the check is
      // made here, one step's fields at a time.
      const fields = panel.querySelectorAll<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>(
        'input, select, textarea',
      )
      for (const field of fields) {
        if (!field.checkValidity()) {
          if (target.id === current) field.reportValidity()
          return false
        }
      }
    }
    if (target.canAdvance && !target.canAdvance()) return false
    if (target.onNext) {
      try {
        const result = await target.onNext()
        if (result === false) return false
      } catch (error) {
        mark(target.id, false)
        if (onError) onError(error, target.id)
        else throw error
        return false
      }
    }
    return true
  }

  /** Move forward to `targetIndex`, checking every step on the way. A step
   * that fails stops the walk there and is the one shown, so the user lands
   * on the thing that needs fixing rather than past it. */
  const advance = async (targetIndex: number, finish: boolean) => {
    if (running.current) return
    running.current = true
    setPending(true)
    try {
      for (let index = currentIndex; index < targetIndex || (finish && index === currentIndex); index += 1) {
        const target = steps[index]!
        const ok = await check(target)
        mark(target.id, ok)
        if (!ok) {
          if (index !== currentIndex) goTo(target.id)
          return
        }
        if (finish) {
          await onFinish()
          return
        }
      }
      const target = steps[targetIndex]
      if (target) goTo(target.id)
    } finally {
      running.current = false
      setPending(false)
    }
  }

  const isLast = currentIndex === steps.length - 1

  const onSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    // Enter in a field is Next, through the same checks the button runs - a
    // wizard is a form and people press Enter in forms. On the last step it
    // does nothing: finishing sets something up, and that should take a
    // press of the button that says so, not a key pressed to leave a field.
    if (isLast) return
    void advance(currentIndex + 1, false)
  }

  const stepperSteps: StepperStep[] = steps.map((step, index) => ({
    id: step.id,
    label: step.label,
    description: step.description,
    status:
      step.error || failed.has(step.id)
        ? 'error'
        : index > currentIndex && passed.has(step.id)
          ? 'done'
          : undefined,
  }))

  const onStepSelect = (id: string) => {
    const index = steps.findIndex((step) => step.id === id)
    if (index < 0 || index === currentIndex || pending) return
    // Back is free; forward walks through every check in between.
    if (index < currentIndex) goTo(id)
    else void advance(index, false)
  }

  const vertical = orientation === 'vertical'

  return (
    <form
      noValidate
      aria-busy={pending || undefined}
      onSubmit={onSubmit}
      className={cn('flex gap-6', vertical ? 'flex-row' : 'flex-col', className)}
      {...props}
    >
      <Stepper
        label={stepperLabel}
        steps={stepperSteps}
        current={current}
        stateLabels={stateLabels}
        summary={summary}
        orientation={orientation}
        onStepSelect={onStepSelect}
        className={vertical ? 'w-56 shrink-0' : undefined}
      />

      <div className="flex min-w-0 flex-1 flex-col gap-4">
        {steps.map((step) => {
          if (!visited.has(step.id)) return null
          const shown = step.id === currentStep?.id
          const headingId = `${baseId}-${step.id}`
          return (
            <section
              key={step.id}
              hidden={!shown}
              aria-labelledby={headingId}
              ref={(node) => {
                if (node) panels.current.set(step.id, node)
                else panels.current.delete(step.id)
              }}
              className="flex flex-col gap-4"
            >
              <div>
                <h2
                  id={headingId}
                  ref={shown ? heading : undefined}
                  // Focusable by script only: it is where the wizard puts the
                  // reader on a step change, not a stop on the Tab order.
                  tabIndex={-1}
                  className="rounded-xs text-base font-semibold text-text focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent"
                >
                  {step.label}
                </h2>
                {step.description !== undefined && (
                  <p className="mt-1 text-sm text-dim">{step.description}</p>
                )}
              </div>
              {step.content}
            </section>
          )
        })}

        <div className="flex items-center justify-between gap-2 border-t border-line pt-4">
          {currentIndex > 0 ? (
            <Button
              variant="ghost"
              disabled={pending}
              onClick={() => goTo(steps[currentIndex - 1]!.id)}
            >
              {backLabel}
            </Button>
          ) : (
            // Holds Next to the right on the first step, where there is no
            // Back: a disabled Back would be a control that does nothing.
            <span />
          )}
          {isLast ? (
            <Button variant="primary" disabled={pending} onClick={() => void advance(currentIndex, true)}>
              {finishLabel}
            </Button>
          ) : (
            // `submit`, so Enter in a field is this button - and runs the
            // same checks.
            <Button type="submit" variant="primary" disabled={pending}>
              {nextLabel}
            </Button>
          )}
        </div>
      </div>
    </form>
  )
}
